// File: sqs.tf
provider "aws" {
  region = "ap-northeast-2"
}

data "aws_caller_identity" "current" {}

# Define the SQS queue
resource "aws_sqs_queue" "notification_queue" {
  name                       = "notificationQueue"
  delay_seconds              = 0
  max_message_size           = 2048
  message_retention_seconds  = 345600
  visibility_timeout_seconds = 30
}

resource "aws_sqs_queue_policy" "sqs_policy" {
  queue_url = aws_sqs_queue.notification_queue.id
  policy    = data.aws_iam_policy_document.sqs_policy_document.json
}

data "aws_iam_policy_document" "sqs_policy_document" {
  statement {
    sid    = "sqs_policy"
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions   = ["sqs:*"]
    resources = [aws_sqs_queue.notification_queue.arn]
  }
}

// File: main_gen.tf
# Copyright IBM Corp. 2014, 2026
# SPDX-License-Identifier: MPL-2.0

provider "null" {}

resource "aws_backup_framework" "test" {
  name        = var.rName
  description = var.rName

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    scope {
      compliance_resource_types = [
        "EBS"
      ]
    }
  }

  tags = {
    (var.unknownTagKey) = null_resource.test.id
  }
}

resource "null_resource" "test" {}

variable "rName" {
  description = "Name for resource"
  type        = string
  nullable    = false
  default     = "benchmark"
}

variable "unknownTagKey" {
  type     = string
  nullable = false
  default     = "BenchmarkTag"
}

// File: kms.tf
data "aws_caller_identity" "current" {}

resource "aws_kms_key" "foo_kms" {
  description              = "KMS key template"
  deletion_window_in_days  = 10
  customer_master_key_spec = "SYMMETRIC_DEFAULT" # Must be configured
  key_usage                = "ENCRYPT_DECRYPT"
  # SaC Testing - Severity: Critical - Set enable_key_rotation to false
  enable_key_rotation      = false
  is_enabled               = true
  policy = <<POLICY
  {
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "*"
      ],
      "Effect": "Allow",
      "Principal": {
        "AWS": [
          "*"
        ]
      },
      "Resource": [
        "*"
      ]
    }
  ]
}
POLICY
}

resource "aws_kms_alias" "foo_kms" {
  # All options # Must be configured
  name          = "alias/bar"
  target_key_id = aws_kms_key.foo_kms.id
}

// File: main.tf
# Security Groups ALB
resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Allow HTTP inbound traffic"

  ingress {
    description = "HTTP Inbound"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb"
  }
}

# Security Groups EC2
resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Allow ALB inbound traffic"

  ingress {
    description = "HTTP Inbound"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_alb"
  }
}

// File: output.tf
output "alb_sg_id" {
  value       = aws_security_group.alb.id
  description = "The Application Load Balance Security Group"
}

output "ec2_sg_id" {
  value       = aws_security_group.allow_alb.id
  description = "The EC2 Security Group"
}

// File: main.tf
resource "aws_iam_role" "iam_role_for_lambda" {
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json
}

data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    sid    = ""
    effect = "Allow"

    principals {
      identifiers = ["lambda.amazonaws.com"]
      type        = "Service"
    }

    actions = [
      "sts:AssumeRole"]
  }
}

data "aws_partition" "current" {}

data "aws_iam_policy" "AWSLambdaVPCAccessExecutionRole" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

data "aws_iam_policy" "AmazonElasticFileSystemClientFullAccess" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

resource "aws_iam_role_policy_attachment" "AWSLambdaVPCAccessExecutionRole-attach" {
  role       = aws_iam_role.iam_role_for_lambda.name
  policy_arn = data.aws_iam_policy.AWSLambdaVPCAccessExecutionRole.arn
}

resource "aws_iam_role_policy_attachment" "AmazonElasticFileSystemClientFullAccess-attach" {
  role       = aws_iam_role.iam_role_for_lambda.name
  policy_arn = data.aws_iam_policy.AmazonElasticFileSystemClientFullAccess.arn
}

// File: outputs.tf
output "iam_role_for_lambda" {
  value = aws_iam_role.iam_role_for_lambda
}

// File: main.tf
resource "aws_eip" "eip" {
  instance = var.aws_instance_id
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  #  depends_on = [aws_vpc.main]

}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  #  depends_on = [aws_vpc.main]
}

resource "aws_route_table" "public_rt" {
  vpc_id     = aws_vpc.main.id
  depends_on = [aws_vpc.main]
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "public_rt_assoc" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id
}

// File: outputs.tf
output "eip" {
  value = aws_eip.eip.public_ip
}

output "eip_id" {
  value = aws_eip.eip.id
}
output "vpc_id" {
  value = aws_vpc.main.id
}
output "vpc_subnet_id" {
  value = aws_subnet.public_subnet.id
}

