resource "aws_s3_account_public_access_block" "this" {
  block_public_acls   = false
  block_public_policy = false

  depends_on = [
    aws_s3_bucket_public_access_block.this,
  ]
}

// File: aws_s3_bucket.tf
variable "aws_profile" { default = "benchmark" }
variable "bucket_name" { default = "benchmark-bucket-tf5x" }
variable "bucket_force_destroy" { default = true }

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  tags = {
    Name = var.aws_profile
  }

  force_destroy = var.bucket_force_destroy

  # lifecycle {
  #   prevent_destroy = true
  # }
}

// File: aws_s3_bucket_public_access_block.tf
resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.bucket
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [
    aws_s3_bucket.this,
  ]
}

// File: aws_s3_bucket_server_side_encryption_configuration.tf
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.bucket
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

// File: main.tf
#--------------------------------------------------------------
# This module creates the S3 resource for Cloud trail
#--------------------------------------------------------------

variable "name" { default = "benchmark" }

variable "aws_region" { default = "us-east-1" }

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = "${var.name}-cloudtrail-${var.aws_region}"
  force_destroy = true
  policy        = "${data.aws_iam_policy_document.cloudtrail.json}"
}

data "aws_iam_policy_document" "cloudtrail" {
  statement {
    sid = "AWSCloudTrailAclCheck"

    actions = [
      "s3:GetBucketAcl",
    ]

    principals {
      type = "Service"

      identifiers = [
        "cloudtrail.amazonaws.com",
      ]
    }

    effect = "Allow"

    resources = [
      "arn:aws:s3:::${var.name}-cloudtrail-${var.aws_region}",
    ]
  }

  statement {
    sid = "AWSCloudTrailWrite"

    actions = [
      "s3:PutObject",
    ]

    effect = "Allow"

    resources = [
      "arn:aws:s3:::${var.name}-cloudtrail-${var.aws_region}/*",
    ]

    principals {
      type = "Service"

      identifiers = [
        "cloudtrail.amazonaws.com",
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"

      values = [
        "bucket-owner-full-control",
      ]
    }
  }
}

// File: output.tf
output "cloudtrail_bucket_id" {
  value = "${aws_s3_bucket.cloudtrail.id}"
}

// File: cw.tf
resource "aws_cloudwatch_log_group" "app" {
  name              = "cwlg-${local.slug}-app"
  retention_in_days = var.log_retention

  tags = merge(local.default_tags, {
    Name = "cwlg-${local.slug}-app"
  })
}

resource "aws_cloudwatch_log_group" "proxy" {
  name              = "cwlg-${local.slug}-proxy"
  retention_in_days = var.log_retention

  tags = merge(local.default_tags, {
    Name = "cwlg-${local.slug}-proxy"
  })
}

// File: data.tf
data "aws_region" "current" {}

// File: locals.tf
locals {
  default_tags = {
    App    = var.app
    Module = var.module
    Stage  = var.stage
  }
  slug = "${var.app}-${var.module}-${var.stage}"
}

// File: outputs.tf
output "log_group_region" {
  description = "Region of the log groups"
  value       = data.aws_region.current.name
}

output "app_log_group" {
  description = "CloudWatch log group for app"
  value       = aws_cloudwatch_log_group.app.name
}

output "proxy_log_group" {
  description = "CloudWatch log group for reverse proxy"
  value       = aws_cloudwatch_log_group.proxy.name
}

// File: variables.tf
variable "app_name" {
  description = "Name of this app"
  type        = string
