// File: main.tf
terraform {
  required_version = ">= 1.0.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-2"
}

# Create a KMS Customer Managed Key (CMK)
resource "aws_kms_key" "cmk" {
  policy = data.aws_iam_policy_document.cmk_admin_policy.json

  # We set a short deletion window, as these keys are only used
  # for testing/learning, and we want to minimize the AWS charges
  deletion_window_in_days = 7
}

# A simple policy that makes the current IAM user the admin
# of the CMK
data "aws_iam_policy_document" "cmk_admin_policy" {
  statement {
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:*"]
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.self.arn]
    }
  }
}

# Look up the details of the current user
data "aws_caller_identity" "self" {}

# Create an alias for the CMK
resource "aws_kms_alias" "cmk" {
  name          = "alias/${var.alias}"
  target_key_id = aws_kms_key.cmk.id
}

// File: outputs.tf
output "cmk_arn" {
  value       = aws_kms_key.cmk.arn
  description = "The ARN of the CMK"
}

output "cmk_alias" {
  value       = aws_kms_alias.cmk.name
  description = "The alias of the CMK"
}

// File: variables.tf
# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These parameters have reasonable defaults.
# ---------------------------------------------------------------------------------------------------------------------

variable "alias" {
  description = "The alias to use for the CMK"
  type        = string
  default     = "kms-cmk-example"
}

// File: 00_provider.tf
terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Define First AWS Provider (us-east-1)
provider "aws" {
  region = "us-east-1"
  alias  = "us-east-nv"

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

# Defining Second AWS Provider (ap-south-1)
provider "aws" {
  region = "ap-south-1"
  alias  = "ap-south-mumbai"

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "Mumbai"
    }
  }
}

// File: 01_vpc.tf
# Create VPC in different regions using different providers

# Create VPC in North-Virginia Region
resource "aws_vpc" "nv-vpc" {
  # meta argument provider is used to specify which provider to be used
  provider   = aws.us-east-nv
  cidr_block = "10.1.0.0/16"

  tags = {
    Name = "North-Virginia-VPC"
  }
}

# Create VPC in Mumbai Region
resource "aws_vpc" "mum-vpc" {
  # meta argument provider is used to specify which provider to be used
  provider   = aws.ap-south-mumbai
  cidr_block = "10.2.0.0/16"

  tags = {
    Name = "Mumbai-VPC"
  }
}

