// File: main.tf
variable "enable" {
  description = "Whether to create the resources in the module"
  type        = bool
  default     = true
}

variable "create_aws_key" {
  type    = bool
  default = false
}

resource "tls_private_key" "some_key" {
  count = var.enable ? 1 : 0

  algorithm   = "ECDSA"
  ecdsa_curve = "P384"
}

resource "local_file" "priv_key_on_disk" {
  count = var.enable ? 1 : 0

  filename          = "${local.ssh_dir}/priv-key.pem"
  sensitive_content = local.private_key
  file_permission   = "0400"
}

resource "local_file" "pub_key_on_disk" {
  count = var.enable ? 1 : 0

  filename          = "${local.ssh_dir}/pub-key.pem"
  sensitive_content = local.public_key
  file_permission   = "0600"
}

resource "aws_key_pair" "some_key_pair" {
  count = var.enable && var.create_aws_key ? 1 : 0

  key_name   = "some-key"
  public_key = local.public_key
}

output "fingerprint" {
  value = local.fingerprint
}

output "aws_key_id" {
  value = local.aws_key_id
}

locals {
  home_dir = pathexpand("~")
  ssh_dir  = "${local.home_dir}/.ssh"

  aws_key_id = join("", aws_key_pair.some_key_pair.*.id)

  public_key  = try(tls_private_key.some_key[0].public_key_pem, "NA")
  private_key = try(tls_private_key.some_key[0].private_key_pem, "NA")
  fingerprint = try(tls_private_key.some_key[0].public_key_fingerprint_md5, "NA")
}

// File: inputs.tf
variable "aws_profile" {
  description = "Name of AWS credentials profile trusted to provision resources as the Role ARN with the AWS Terraform Provider"
  type        = string
  default     = ""
}

variable "aws_region" {
  description = "Name of AWS region to use with the AWS Terraform Provider"
  type        = string
  default     = "us-east-1"
}

// File: main.tf
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# CREATE AN S3 BUCKET AND DYNAMODB TABLE TO USE AS A TERRAFORM BACKEND
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

# ----------------------------------------------------------------------------------------------------------------------
# REQUIRE A SPECIFIC TERRAFORM VERSION OR HIGHER
# This module has been updated with 0.12 syntax, which means it is no longer compatible with any versions below 0.12.
# This module is forked from https://github.com/gruntwork-io/intro-to-terraform/tree/master/s3-backend
# ----------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 0.12"
}

# ------------------------------------------------------------------------------
# CONFIGURE OUR AWS CONNECTION
# ------------------------------------------------------------------------------

provider "aws" {
  profile = var.aws_profile
  region  = var.aws_region
}

# ------------------------------------------------------------------------------
# CREATE THE S3 BUCKET
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
}

resource "aws_s3_bucket" "terraform_state" {
  # With account id, this S3 bucket names can be *globally* unique.
  bucket = "terraform-states-${local.account_id}-${local.region}"
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# CREATE THE DYNAMODB TABLE
# ------------------------------------------------------------------------------

resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}

// File: outputs.tf
output "s3_bucket_name" {
  value       = aws_s3_bucket.terraform_state.id
  description = "The NAME of the S3 bucket"
}

output "s3_bucket_arn" {
  value       = aws_s3_bucket.terraform_state.arn
  description = "The ARN of the S3 bucket"
}

output "s3_bucket_region" {
  value       = aws_s3_bucket.terraform_state.region
  description = "The REGION of the S3 bucket"
}

output "dynamodb_table_name" {
  value       = aws_dynamodb_table.terraform_lock.name
  description = "The ARN of the DynamoDB table"
}

output "dynamodb_table_arn" {
  value       = aws_dynamodb_table.terraform_lock.arn
  description = "The ARN of the DynamoDB table"
}

// File: athena_database.tf
#---------------------------------------------------
# AWS athena database
#---------------------------------------------------
resource "aws_athena_database" "athena_database" {
  count = var.enable_athena_database ? 1 : 0

  name   = var.athena_database_name != "" ? var.athena_database_name : "${lower(var.name)}-athena-db-${lower(var.environment)}"
  bucket = var.athena_database_bucket

  force_destroy = var.athena_database_force_destroy

  dynamic "encryption_configuration" {
    iterator = encryption_configuration
    for_each = var.athena_database_encryption_configuration

    content {
      encryption_option = lookup(encryption_configuration.value, "encryption_option", null)

      kms_key = lookup(encryption_configuration.value, "kms_key", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: athena_named_query.tf
#---------------------------------------------------
# AWS athena named query
#---------------------------------------------------
resource "aws_athena_named_query" "athena_named_query" {
  count = var.enable_athena_named_query ? 1 : 0

  name     = var.athena_named_query_name != "" ? lower(var.athena_named_query_name) : "${lower(var.name)}-athena-query-${lower(var.environment)}"
  database = var.athena_named_query_database != "" && !var.enable_athena_database ? var.athena_named_query_database : element(concat(aws_athena_database.athena_database.*.name, [""]), 0)
  query    = var.athena_named_query_query

  description = var.athena_named_query_description != "" ? var.athena_named_query_description : null
  workgroup   = var.athena_named_query_workgroup != "" && !var.enable_athena_workgroup ? var.athena_named_query_workgroup : element(concat(aws_athena_workgroup.athena_workgroup.*.id, [""]), 0)

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_athena_workgroup.athena_workgroup,
    aws_athena_database.athena_database
  ]
}

// File: athena_workgroup.tf
#---------------------------------------------------
# AWS athena workgroup
#---------------------------------------------------
resource "aws_athena_workgroup" "athena_workgroup" {
  count = var.enable_athena_workgroup ? 1 : 0

  name = var.athena_workgroup_name != "" ? lower(var.athena_workgroup_name) : "${lower(var.name)}-athena-workgroup-${lower(var.environment)}"

  description   = var.athena_workgroup_description
  state         = upper(var.athena_workgroup_state)
  force_destroy = var.athena_workgroup_force_destroy

  dynamic "configuration" {
    iterator = configuration
    for_each = var.athena_workgroup_configuration

    content {
      bytes_scanned_cutoff_per_query     = lookup(configuration.value, "bytes_scanned_cutoff_per_query", null)
      enforce_workgroup_configuration    = lookup(configuration.value, "enforce_workgroup_configuration", null)
      publish_cloudwatch_metrics_enabled = lookup(configuration.value, "publish_cloudwatch_metrics_enabled", null)

      dynamic "result_configuration" {
        iterator = result_configuration
        for_each = length(keys(lookup(configuration.value, "result_configuration", {}))) > 0 ? [lookup(configuration.value, "result_configuration", {})] : []

        content {
          output_location = lookup(result_configuration.value, "output_location", null)

          dynamic "encryption_configuration" {
            iterator = encryption_configuration
            for_each = length(keys(lookup(result_configuration.value, "encryption_configuration", {}))) > 0 ? [lookup(result_configuration.value, "encryption_configuration", {})] : []

            content {
              encryption_option = lookup(encryption_configuration.value, "encryption_option", null)
              kms_key_arn       = lookup(encryption_configuration.value, "kms_key_arn", null)
            }
          }
        }
      }
    }
  }

  tags = merge(
    {
      Name = var.athena_workgroup_name != "" ? lower(var.athena_workgroup_name) : "${lower(var.name)}-athena-workgroup-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: outputs.tf
