// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks. Each element should have keys named key, value, and propagate_at_launch."
  type        = map(string)
  default     = {}
}

#---------------------------------------------------
# ASW athena database
#---------------------------------------------------
variable "enable_athena_database" {
  description = "Enable athena DB usage"
  default     = false
}

variable "athena_database_name" {
  description = "Name of the database to create."
  default     = ""
}

variable "athena_database_bucket" {
  description = "(Required) Name of s3 bucket to save the results of the query execution."
  default     = ""
}

variable "athena_database_force_destroy" {
  description = "(Optional, Default: false) A boolean that indicates all tables should be deleted from the database so that the database can be destroyed without error. The tables are not recoverable."
  default     = false
}

variable "athena_database_encryption_configuration" {
  description = "(Optional) The encryption key block AWS Athena uses to decrypt the data in S3, such as an AWS Key Management Service (AWS KMS) key. An encryption_configuration block is documented below."
  default     = []
}

#---------------------------------------------------
# ASW athena named query
#---------------------------------------------------
variable "enable_athena_named_query" {
  description = "Enable athena named query usage"
  default     = false
}

variable "athena_named_query_name" {
  description = "The plain language name for the query. Maximum length of 128."
  default     = ""
}

variable "athena_named_query_workgroup" {
  description = "(Optional) The workgroup to which the query belongs. Defaults to primary"
  default     = "primary"
}

variable "athena_named_query_database" {
  description = "The database to which the query belongs."
  default     = ""
}

variable "athena_named_query_description" {
  description = "(Optional) A brief explanation of the query. Maximum length of 1024."
  default     = ""
}

variable "athena_named_query_query" {
  description = "(Required) The text of the query itself. In other words, all query statements. Maximum length of 262144."
  default     = ""
}

#---------------------------------------------------
# AWS athena workgroup
#---------------------------------------------------
variable "enable_athena_workgroup" {
  description = "Enable athena workgroup usage"
  default     = false
}

variable "athena_workgroup_name" {
  description = "Name of the workgroup."
  default     = ""
}

variable "athena_workgroup_description" {
  description = "(Optional) Description of the workgroup."
  default     = null
}

variable "athena_workgroup_state" {
  description = "(Optional) State of the workgroup. Valid values are DISABLED or ENABLED. Defaults to ENABLED."
  default     = null
}

variable "athena_workgroup_force_destroy" {
  description = "(Optional) The option to delete the workgroup and its contents even if the workgroup contains any named queries."
  default     = null
}

variable "athena_workgroup_configuration" {
  description = "(Optional) Configuration block with various settings for the workgroup."
  default     = []
}

// File: main.tf
/*

        Copyright (c) 2023 Dell, Inc or its subsidiaries.

        This Source Code Form is subject to the terms of the Mozilla Public
        License, v. 2.0. If a copy of the MPL was not distributed with this
        file, You can obtain one at https://mozilla.org/MPL/2.0/.

*/
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "powerscale_instance_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "powerscale_instance_policy" {
  statement {
    actions = [
      "ec2:AssignPrivateIpAddresses"
    ]
    resources = [for each_region in var.regions : "arn:aws:ec2:${each_region}:${data.aws_caller_identity.current.account_id}:network-interface/*"]
    effect    = "Allow"
  }
}

resource "aws_iam_policy" "powerscale_iam_instance_policy" {
  name        = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-policy"
  description = "powerscale IAM policy for create and destroy."
  path        = "/"
  policy      = data.aws_iam_policy_document.powerscale_instance_policy.json
}

resource "aws_iam_role" "powerscale_iam_role" {
  name               = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-role"
  assume_role_policy = data.aws_iam_policy_document.powerscale_instance_assume_role_policy.json
  description        = "powerscale IAM role for create and destroy."
}

resource "aws_iam_role_policy_attachment" "powerscale_iam_role_policy_attachment" {
  role       = aws_iam_role.powerscale_iam_role.name
  policy_arn = aws_iam_policy.powerscale_iam_instance_policy.arn
}

resource "aws_iam_instance_profile" "powerscale_iam_instance_profile" {
  name = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_iam_role.name
}

// File: outputs.tf
/*

        Copyright (c) 2023 Dell, Inc or its subsidiaries.

        This Source Code Form is subject to the terms of the Mozilla Public
        License, v. 2.0. If a copy of the MPL was not distributed with this
        file, You can obtain one at https://mozilla.org/MPL/2.0/.

*/
output "powerscale_iam_policy_arn" {
  value = aws_iam_policy.powerscale_iam_instance_policy.arn
}

output "powerscale_iam_role_arn" {
  value = aws_iam_role.powerscale_iam_role.arn
}

output "powerscale_iam_role_name" {
  value = aws_iam_role.powerscale_iam_role.name
}

output "powerscale_iam_instance_profile_arn" {
  value = aws_iam_instance_profile.powerscale_iam_instance_profile.arn
}

output "powerscale_iam_instance_profile_name" {
  value = aws_iam_instance_profile.powerscale_iam_instance_profile.name
}

// File: variables.tf
/*

        Copyright (c) 2023 Dell, Inc or its subsidiaries.

        This Source Code Form is subject to the terms of the Mozilla Public
        License, v. 2.0. If a copy of the MPL was not distributed with this
        file, You can obtain one at https://mozilla.org/MPL/2.0/.

*/
variable "regions" {
  default     = ["*"]
  description = <<EOT
    A comma separated list of AWS region(s) where the PowerScale cluster resources are deployed.
    Eg: ["us-east-1", "us-east-2"].
    To allow all regions, provide ["*"], which is also set as the default value.
  EOT
  type        = list(string)
}

// File: inputs.tf
# variable for region
variable region {
  type        = string
  default     = "us-west-2"
  description = "target region for creating resources"
}

# vpc range
variable vpc_cidr {
  type        = string
  default     = "192.168.0.0/16"
  description = "cidr range of vpc"
}

# Az's
variable availabilty_zones {
  type        = list(string)
  default     = ["a","b", "c", "a"]
  description = "az's"
}

variable subnet_tags {
  type        = list(string)
  default     = ["web", "app", "db", "mgmt"]
  description = "subnet tags"
}

variable vpctag {
  type        = string
  default     = "from terraform"
  description = "VPC Tag"
}

// File: main.tf
# VPC Section
resource "aws_vpc" "myvpc" {
    cidr_block              = var.vpc_cidr
    enable_dns_support      = true
    tags = {
        Name = var.vpctag
    }
}

# Web Subnet
resource "aws_subnet" "web" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,0)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[0])

    tags = {
        Name = var.subnet_tags[0]
    }

}

resource "aws_subnet" "app" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,1)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[1])

    tags = {
        Name = var.subnet_tags[1]
    }

}

resource "aws_subnet" "db" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,2)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[2])

    tags = {
        Name = var.subnet_tags[2]
    }

}

resource "aws_subnet" "mgmt" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,3)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[3])

    tags = {
        Name = var.subnet_tags[3]
    }

}

// File: providers.tf
provider "aws" {
    region = var.region
}

// File: data.tf
data "aws_partition" "current" {}

// File: main.tf
locals {
  name = "${var.name}-${var.environment_name}"
  path = var.workspace_name != "" ? "/${var.environment_name}/${var.workspace_name}/" : "/${var.environment_name}/"
}

// File: outputs.tf
output "instance_profile_arn" {
  value = aws_iam_instance_profile.instance_profile.arn
}

output "instance_profile_id" {
  value = aws_iam_instance_profile.instance_profile.id
}

output "role_arn" {
  value = aws_iam_role.role.arn
}

output "role_id" {
  value = aws_iam_role.role.id
}

// File: role.tf
data "aws_iam_policy_document" "assume_role-ec2" {
  statement {
    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = local.ec2_service_identifiers_by_partition[data.aws_partition.current.partition]
    }
  }
}

locals {
  ec2_service_identifiers_by_partition = {
    "aws" : [
      "ec2.amazonaws.com",
    ]
    "aws-cn" : [
      "ec2.amazonaws.com.cn",
    ]
  }
}

resource "aws_iam_instance_profile" "instance_profile" {
  name = local.name
  path = local.path
  role = aws_iam_role.role.id
}

resource "aws_iam_role" "role" {
  name               = local.name
  path               = local.path
  assume_role_policy = data.aws_iam_policy_document.assume_role-ec2.json
}

// File: role_policy.tf
locals {
  # Work around merge() breaking for_each.
  role_policy_document_keys = setunion(
    keys(var.role_policy_documents),
  )
  role_policy_documents = merge(
    var.role_policy_documents,
  )
}

resource "aws_iam_role_policy" "role_policy" {
  for_each = local.role_policy_document_keys

  name   = each.key
  policy = local.role_policy_documents[each.key]
  role   = aws_iam_role.role.id
}

// File: role_policy_attachment.tf
resource "aws_iam_role_policy_attachment" "role_policy_attachment" {
  for_each   = var.role_policy_attachment_arns
  policy_arn = each.value
  role       = aws_iam_role.role.id
}

// File: variables.tf
variable "environment_name" {
  type = string
  default     = "dev"
}

variable "name" {
  type = string
  default     = "benchmark"
}

variable "role_policy_attachment_arns" {
  default     = []
  description = "ARNs of additional managed policies to attach to the role."
  type        = set(string)
}

variable "role_policy_documents" {
  default     = {}
  description = "Additional IAM policy documents to attach to the role."
  type        = map(string)
}

variable "workspace_name" {
  type    = string
  default = ""
}

// File: main.tf
resource "aws_vpc" "this" {
  cidr_block = var.vpc_cidr_block

  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-vpc"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-private-subnet-${var.availability_zones[count.index]}"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnets)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-public-subnet-${var.availability_zones[count.index]}"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-igw"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = var.all_ips
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-public-rt"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnets)

  route_table_id = aws_route_table.public.id
  subnet_id      = aws_subnet.public[count.index].id
}

// File: outputs.tf
output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.this.id
}

output "private_subnet_ids" {
  description = "ID of the private subnets of this VPC"
  value       = aws_subnet.private[*].id
}

output "public_subnet_ids" {
  description = "ID of the public subnets of this VPC"
  value       = aws_subnet.public[*].id
}

// File: variables.tf
variable "cluster_name" {
  description = "Cluster name to identify all resources"
  type        = string
  default     = "Fast-App"
}

variable "aws_region" {
  description = "The AWS region things are created in"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "the environment we will be deploying for"
  type        = string
  default     = "dev"
}
variable "vpc_cidr_block" {
  description = "CIDR (Classless Inter-Domain Routing)"
  type        = string
  default     = "10.0.0.0/16"
}

variable "all_ips" {
  description = "CIDR (Classless Inter-Domain Routing) for all IP"
  type        = string
  default     = "0.0.0.0/0"
}

variable "availability_zones" {
  description = "Subnet Availability Zones"
  type = list(string)
  default = ["us-east-1a", "us-east-1b"]
}

variable "private_subnets" {
  description = "CIDR ranges for private subnets"
  type = list(string)
  default = ["10.0.0.0/19", "10.0.32.0/19"]
}

variable "public_subnets" {
  description = "CIDR ranges for public subnets"
  type = list(string)
  default = ["10.0.64.0/19", "10.0.96.0/19"]
}

// File: main.tf
resource "aws_iam_role" "this" {
  assume_role_policy = data.aws_iam_policy_document.trust.json
  name               = var.name

  tags = merge(
    var.tags,
    { "grafana.workspace.${var.grafana_workspace_name}" = "true" }
  )
}

resource "aws_iam_role_policy_attachment" "grafana" {
  policy_arn = aws_iam_policy.grafana.arn
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "cloudwatch" {
  policy_arn = data.aws_iam_policy.cloudwatch.arn
  role       = aws_iam_role.this.name
}

resource "aws_iam_policy" "grafana" {
  name   = var.name
  policy = data.aws_iam_policy_document.grafana.json
  tags   = var.tags
}

data "aws_iam_policy_document" "grafana" {
  statement {
    sid       = "AllowPrometheus"
    resources = ["*"]

    actions = [
      "aps:DescribeWorkspace",
      "aps:GetAlertManagerStatus",
      "aps:GetLabels",
      "aps:GetMetricMetadata",
      "aps:GetSeries",
      "aps:ListAlertManagerAlertGroups",
      "aps:ListAlertManagerAlerts",
      "aps:ListAlertManagerSilences",
      "aps:ListWorkspaces",
      "aps:ListRules",
      "aps:QueryMetrics",
    ]
  }
}

data "aws_iam_policy_document" "trust" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type = "AWS"

      identifiers = [
        for account_id in local.monitoring_account_ids :
        "arn:aws:iam::${account_id}:root"
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "iam:ResourceTag/grafana.workspace.${var.grafana_workspace_name}"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy" "cloudwatch" {
  name = "AmazonGrafanaCloudWatchAccess"
}

data "aws_caller_identity" "this" {}

locals {
  monitoring_account_ids = coalesce(var.monitoring_account_ids, [data.aws_caller_identity.this.account_id])
}

// File: outputs.tf
output "arn" {
  description = "ARN of the created IAM role"
  value       = aws_iam_role.this.arn
}

// File: variables.tf
variable "grafana_workspace_name" {
  description = "Name of the AWS Managed Grafana workspace allowed to assume this role"
  type        = string
  default     = "Grafana"
}

variable "monitoring_account_ids" {
  description = "AWS account IDs in which Grafana will run"
  type        = list(string)
  default     = null
}

variable "name" {
  description = "Name of the IAM role for Grafana"
  type        = string
  default     = "grafana"
}

variable "tags" {
  description = "Tags to be applied to created resources"
  type        = map(string)
  default     = {}
}

// File: versions.tf
terraform {
  required_version = ">= 0.14.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

// File: main.tf
# Providing a reference to our default VPC
resource "aws_default_vpc" "vpc" {
}

#data
data "aws_availability_zones" "available" {
  state = "available"
}

# Providing a reference to our default subnets
resource "aws_default_subnet" "default_private_subnet_1" {
  availability_zone = element(data.aws_availability_zones.available.names, 0)
}

resource "aws_default_subnet" "default_private_subnet_2" {
  availability_zone = element(data.aws_availability_zones.available.names, 1)
}

locals {
  private_subnet_1_id = aws_default_subnet.default_private_subnet_1.id
  private_subnet_2_id = aws_default_subnet.default_private_subnet_2.id
  vpc_id              = aws_default_vpc.vpc.id
}

// File: outputs.tf
# Outputs
output "private_subnet_1_id" {
  description = "ID of Default Private Subnet 1"
  value       = aws_default_subnet.default_private_subnet_1.id
}

output "private_subnet_2_id" {
  description = "ID of Default Private Subnet 2"
  value       = aws_default_subnet.default_private_subnet_2.id
}

output "vpc_id" {
  description = "ID of Default VPC"
  value       = aws_default_vpc.vpc.id
}

output "private_subnet_1_cidr" {
  description = "CIDR block of Default Private Subnet 1"
  value       = aws_default_subnet.default_private_subnet_1.cidr_block
}

output "private_subnet_2_cidr" {
  description = "CIDR block of Default Private Subnet 2"
  value       = aws_default_subnet.default_private_subnet_2.cidr_block
}

#FAKE used only for testing
output "public_subnet_1_id" {
  description = "ID of Default Pubrlic Subnet 1"
  value       = aws_default_subnet.default_private_subnet_1.id
}

output "public_subnet_2_id" {
  description = "ID of Default Pubrlic Subnet 2"
  value       = aws_default_subnet.default_private_subnet_2.id
}

output "public_subnet_1_cidr" {
  description = "CIDR block of Default Public Subnet 1"
  value       = aws_default_subnet.default_private_subnet_1.cidr_block
}

output "public_subnet_2_cidr" {
  description = "CIDR block of Default Public Subnet 2"
  value       = aws_default_subnet.default_private_subnet_2.cidr_block
}

output "public_subnets" {
  description = "Private subnets list"
  value       = [aws_default_subnet.default_private_subnet_1.id, aws_default_subnet.default_private_subnet_2.id]
}

output "private_subnets" {
  description = "Private subnets list"
  value       = [aws_default_subnet.default_private_subnet_1.id, aws_default_subnet.default_private_subnet_2.id]
}

output "public_subnets_cidr" {
  description = "Private subnets cidr list"
  value       = [aws_default_subnet.default_private_subnet_1.cidr_block, aws_default_subnet.default_private_subnet_2.cidr_block]
}

output "private_subnets_cidr" {
  description = "Private subnets cidr list"
  value       = [aws_default_subnet.default_private_subnet_1.cidr_block, aws_default_subnet.default_private_subnet_2.cidr_block]
}

// File: data.tf
data "aws_region" "current" {}

// File: locals.tf
locals {
  region = data.aws_region.current.name
}

// File: outputs.tf
output "public_subnet_ids" {
  description = "A list of the VPC's public subnets."
  value       = module.vpc.public_subnets
}

output "private_subnet_ids" {
  description = "A list of the VPC's private subnets."
  value       = module.vpc.private_subnets
}

output "vpc_id" {
  description = "VPC ID"
  value       = module.vpc.vpc_id
}

output "private_subnets_cidr_blocks" {
  description = "A list of cidr_blocks of private subnets."
  value       = module.vpc.private_subnets_cidr_blocks
}

// File: security_groups.tf
resource "aws_security_group" "ssh" {
  name        = "allow-ssh"
  description = "Allow inbound SSH traffic"
  vpc_id      = module.vpc.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "allow_ssh" {
  security_group_id = aws_security_group.ssh.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
}

resource "aws_vpc_security_group_egress_rule" "allow_all_outbound" {
  security_group_id = aws_security_group.ssh.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

// File: versions.tf
terraform {
  required_version = ">= 1.8"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.3"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

// File: vpc.tf
module "vpc" {
  source = "github.com/terraform-aws-modules/terraform-aws-vpc?ref=v5.1.2"

  name = "trade-tariff-development-vpc"
  cidr = "10.0.0.0/16"

  azs = [
    "${local.region}d",
    "${local.region}f",
  ]

  private_subnets = [
    "10.0.4.0/24",
    "10.0.5.0/24",
    "10.0.6.0/24"
  ]

  public_subnets = [
    "10.0.104.0/24",
    "10.0.105.0/24",
    "10.0.106.0/24"
  ]

  enable_dns_hostnames = true
  enable_dns_support   = true

  enable_nat_gateway = true
  single_nat_gateway = true
}

// File: main.tf
resource "aws_ecr_repository" "this" {
  name                 = var.name
  image_tag_mutability = var.mutability

  encryption_configuration {
    encryption_type = var.kms_encryption == true ? "KMS" : "AES256"
    kms_key         = var.kms_encryption == true ? aws_kms_key.this[0].arn : null
  }
  force_delete = var.force_delete
  tags         = var.tags
}

data "aws_iam_policy_document" "this_policy" {
  count = var.allowed_principals != null ? 1 : 0
  statement {
    sid    = "AllowPull"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.allowed_principals
    }

    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability",
      "ecr:DescribeRepositories",
      "ecr:GetRepositoryPolicy",
      "ecr:ListImages",
    ]
  }
}

resource "aws_ecr_repository_policy" "this" {
  count      = var.allowed_principals != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.this_policy[0].json
}

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = jsonencode(var.lifecycle_policy)
}

resource "aws_kms_key" "this" {
  count               = var.kms_encryption == true ? 1 : 0
  enable_key_rotation = true
  tags                = var.tags
}

resource "aws_kms_alias" "this" {
  count         = var.kms_encryption == true ? 1 : 0
  name          = "alias/ecr/repository/${var.name}"
  target_key_id = aws_kms_key.this[0].key_id
}

// File: outputs.tf
output "arn" {
  value       = aws_ecr_repository.this.arn
  description = "Repository ARN"
}

output "repository_url" {
  value       = aws_ecr_repository.this.repository_url
  description = "Repository URL"
}

output "kms_key_id" {
  value       = aws_kms_key.this[*].key_id
  description = "KMS Key ID"
}

output "kms_key_arn" {
  value       = aws_kms_key.this[*].arn
  description = "KMS key ARN"
}

// File: provider.tf
terraform {
  required_version = ">= 1.4.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

// File: variables.tf
variable "name" {
  default     = "my-ecr-repo"
  type        = string
  description = "ECR Repo name"
}
variable "mutability" {
  default     = "MUTABLE"
  description = "MUTABLE or IMMUTABLE"
  type        = string
}
variable "kms_encryption" {
  default     = false
  description = "Enables KMS encryption for the repo. Default is AES256"
  type        = bool
}
variable "force_delete" {
  default     = false
  description = "When enabled, you can delete the repository when there are images inside."
  type        = bool
}
variable "tags" {
  default     = null
  description = "tags that are added to the repository (and KMS keys)"
  type        = map(any)
}

variable "allowed_principals" {
  default     = null
  description = "List of AWS account IDs or ARNs that are allowed to pull images"
  type        = list(any)
}

variable "lifecycle_policy" {
  default     = null
  description = "Lifecycle policy IAM document"
  type        = string
}

// File: context.tf
#
# ONLY EDIT THIS FILE IN github.com/cloudposse/terraform-null-label
# All other instances of this file should be a copy of that one
#
#
# Copy this file from https://github.com/cloudposse/terraform-null-label/blob/master/exports/context.tf
# and then place it in your Terraform module to automatically get
# Cloud Posse's standard configuration inputs suitable for passing
# to Cloud Posse modules.
#
# curl -sL https://raw.githubusercontent.com/cloudposse/terraform-null-label/master/exports/context.tf -o context.tf
#
# Modules should access the whole context as `module.this.context`
# to get the input variables with nulls for defaults,
# for example `context = module.this.context`,
# and access individual variables as `module.this.<var>`,
# with final values filled in.
#
# For example, when using defaults, `module.this.context.delimiter`
# will be null, and `module.this.delimiter` will be `-` (hyphen).
#

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0" # requires Terraform >= 0.13.0

  enabled             = var.enabled
  namespace           = var.namespace
  tenant              = var.tenant
  environment         = var.environment
  stage               = var.stage
  name                = var.name
  delimiter           = var.delimiter
  attributes          = var.attributes
  tags                = var.tags
  additional_tag_map  = var.additional_tag_map
  label_order         = var.label_order
  regex_replace_chars = var.regex_replace_chars
  id_length_limit     = var.id_length_limit
  label_key_case      = var.label_key_case
  label_value_case    = var.label_value_case
  descriptor_formats  = var.descriptor_formats
  labels_as_tags      = var.labels_as_tags

  context = var.context
}

# Copy contents of cloudposse/terraform-null-label/variables.tf here

variable "context" {
  type = any
  default = {
    enabled             = true
    namespace           = null
    tenant              = null
    environment         = null
    stage               = null
    name                = null
    delimiter           = null
    attributes          = []
    tags                = {}
    additional_tag_map  = {}
    regex_replace_chars = null
    label_order         = []
    id_length_limit     = null
    label_key_case      = null
    label_value_case    = null
    descriptor_formats  = {}
    # Note: we have to use [] instead of null for unset lists due to
    # https://github.com/hashicorp/terraform/issues/28137
    # which was not fixed until Terraform 1.0.0,
    # but we want the default to be all the labels in `label_order`
    # and we want users to be able to prevent all tag generation
    # by setting `labels_as_tags` to `[]`, so we need
    # a different sentinel to indicate "default"
    labels_as_tags = ["unset"]
  }
  description = <<-EOT
    Single object for setting entire context at once.
    See description of individual variables for details.
    Leave string and numeric variables as `null` to use default value.
    Individual variable settings (non-null) override settings in context object,
    except for attributes, tags, and additional_tag_map, which are merged.
  EOT

  validation {
    condition     = lookup(var.context, "label_key_case", null) == null ? true : contains(["lower", "title", "upper"], var.context["label_key_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }

  validation {
    condition     = lookup(var.context, "label_value_case", null) == null ? true : contains(["lower", "title", "upper", "none"], var.context["label_value_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "enabled" {
  type        = bool
  default     = null
  description = "Set to false to prevent the module from creating any resources"
}

variable "namespace" {
  type        = string
  default     = null
  description = "ID element. Usually an abbreviation of your organization name, e.g. 'eg' or 'cp', to help ensure generated IDs are globally unique"
}

variable "tenant" {
  type        = string
  default     = null
  description = "ID element _(Rarely used, not included by default)_. A customer identifier, indicating who this instance of a resource is for"
}

variable "environment" {
  type        = string
  default     = null
  description = "ID element. Usually used for region e.g. 'uw2', 'us-west-2', OR role 'prod', 'staging', 'dev', 'UAT'"
}

variable "stage" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate role, e.g. 'prod', 'staging', 'source', 'build', 'test', 'deploy', 'release'"
}

variable "name" {
  type        = string
  default     = null
  description = <<-EOT
    ID element. Usually the component or solution name, e.g. 'app' or 'jenkins'.
    This is the only ID element not also included as a `tag`.
    The "name" tag is set to the full `id` string. There is no tag with the value of the `name` input.
    EOT
}

variable "delimiter" {
  type        = string
  default     = null
  description = <<-EOT
    Delimiter to be used between ID elements.
    Defaults to `-` (hyphen). Set to `""` to use no delimiter at all.
  EOT
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = <<-EOT
    ID element. Additional attributes (e.g. `workers` or `cluster`) to add to `id`,
    in the order they appear in the list. New attributes are appended to the
    end of the list. The elements of the list are joined by the `delimiter`
    and treated as a single ID element.
    EOT
}

variable "labels_as_tags" {
  type        = set(string)
  default     = ["default"]
  description = <<-EOT
    Set of labels (ID elements) to include as tags in the `tags` output.
    Default is to include all labels.
    Tags with empty values will not be included in the `tags` output.
    Set to `[]` to suppress all generated tags.
    **Notes:**
      The value of the `name` tag, if included, will be the `id`, not the `name`.
      Unlike other `null-label` inputs, the initial setting of `labels_as_tags` cannot be
      changed in later chained modules. Attempts to change it will be silently ignored.
    EOT
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional tags (e.g. `{'BusinessUnit': 'XYZ'}`).
    Neither the tag keys nor the tag values will be modified by this module.
    EOT
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional key-value pairs to add to each map in `tags_as_list_of_maps`. Not added to `tags` or `id`.
    This is for some rare cases where resources want additional configuration of tags
    and therefore take a list of maps with tag key, value, and additional configuration.
    EOT
}

variable "label_order" {
  type        = list(string)
  default     = null
  description = <<-EOT
    The order in which the labels (ID elements) appear in the `id`.
    Defaults to ["namespace", "environment", "stage", "name", "attributes"].
    You can omit any of the 6 labels ("tenant" is the 6th), but at least one must be present.
    EOT
}

variable "regex_replace_chars" {
  type        = string
  default     = null
  description = <<-EOT
    Terraform regular expression (regex) string.
    Characters matching the regex will be removed from the ID elements.
    If not set, `"/[^a-zA-Z0-9-]/"` is used to remove all characters other than hyphens, letters and digits.
  EOT
}

variable "id_length_limit" {
  type        = number
  default     = null
  description = <<-EOT
    Limit `id` to this many characters (minimum 6).
    Set to `0` for unlimited length.
    Set to `null` for keep the existing setting, which defaults to `0`.
    Does not affect `id_full`.
  EOT
  validation {
    condition     = var.id_length_limit == null ? true : var.id_length_limit >= 6 || var.id_length_limit == 0
    error_message = "The id_length_limit must be >= 6 if supplied (not null), or 0 for unlimited length."
  }
}

variable "label_key_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of the `tags` keys (label names) for tags generated by this module.
    Does not affect keys of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper`.
    Default value: `title`.
  EOT

  validation {
    condition     = var.label_key_case == null ? true : contains(["lower", "title", "upper"], var.label_key_case)
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }
}

variable "label_value_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of ID elements (labels) as included in `id`,
    set as tag values, and output by this module individually.
    Does not affect values of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper` and `none` (no transformation).
    Set this to `title` and set `delimiter` to `""` to yield Pascal Case IDs.
    Default value: `lower`.
  EOT

  validation {
    condition     = var.label_value_case == null ? true : contains(["lower", "title", "upper", "none"], var.label_value_case)
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "descriptor_formats" {
  type        = any
  default     = {}
  description = <<-EOT
    Describe additional descriptors to be output in the `descriptors` output map.
    Map of maps. Keys are names of descriptors. Values are maps of the form
    `{
       format = string
       labels = list(string)
    }`
    (Type is `any` so the map values can later be enhanced to provide additional options.)
    `format` is a Terraform format string to be passed to the `format()` function.
    `labels` is a list of labels, in order, to pass to `format()` function.
    Label values will be normalized before being passed to `format()` so they will be
    identical to how they appear in `id`.
    Default is `{}` (`descriptors` output will be empty).
    EOT
}

#### End of copy of cloudposse/terraform-null-label/variables.tf

// File: main.tf
locals {
  enabled                 = module.this.enabled
  prebuilt_policy_enabled = local.enabled && var.prebuilt_policy.enabled
  name                    = var.fifo_queue_enabled ? format("%s.fifo", module.this.id) : module.this.id
  sqs_queue_arn           = one(aws_sqs_queue.default[*].arn)
  sqs_queue_url           = one(aws_sqs_queue.default[*].url)
}

resource "aws_sqs_queue" "default" {
  count = local.enabled ? 1 : 0

  name                              = local.name
  visibility_timeout_seconds        = var.visibility_timeout_seconds
  message_retention_seconds         = var.message_retention_seconds
  max_message_size                  = var.max_message_size
  delay_seconds                     = var.delay_seconds
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  policy                            = var.policy
  redrive_policy                    = var.redrive_policy
  fifo_queue                        = var.fifo_queue_enabled
  content_based_deduplication       = var.content_based_deduplication_enabled
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  deduplication_scope               = var.deduplication_scope
  fifo_throughput_limit             = var.fifo_throughput_limit
  tags                              = module.this.tags
}

data "aws_iam_policy_document" "default" {
  count = local.prebuilt_policy_enabled ? 1 : 0

  statement {
    sid     = var.prebuilt_policy.sid
    actions = var.prebuilt_policy.actions

    resources = [local.sqs_queue_arn]

    principals {
      type        = var.prebuilt_policy.principals.type
      identifiers = var.prebuilt_policy.principals.identifiers
    }

  }
}

resource "aws_sqs_queue_policy" "default" {
  count = local.prebuilt_policy_enabled ? 1 : 0

  queue_url = local.sqs_queue_url
  policy    = one(data.aws_iam_policy_document.default[*].json)
}

// File: outputs.tf
output "id" {
  value       = one(aws_sqs_queue.default[*].id)
  description = "The URL for the created Amazon SQS queue."
}

output "arn" {
  value       = local.sqs_queue_arn
  description = "The ARN of the SQS queue."
}

output "url" {
  value       = local.sqs_queue_url
  description = "The URL for the created Amazon SQS queue."
}

output "name" {
  value       = one(aws_sqs_queue.default[*].name)
  description = "The name of Amazon SQS queue."
}

// File: variables.tf
variable "visibility_timeout_seconds" {
  type        = number
  default     = 30
  description = "The visibility timeout for the queue. An integer from 0 to 43200 (12 hours)."
}

variable "message_retention_seconds" {
  type        = number
  default     = 345600
  description = "The number of seconds Amazon SQS retains a message. Integer representing seconds, from 60 (1 minute) to 1209600 (14 days)."
}

variable "max_message_size" {
  type        = number
  default     = 262144
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it. An integer from 1024 bytes (1 KiB) up to 262144 bytes (256 KiB)."
}

variable "delay_seconds" {
  type        = number
  default     = 0
  description = "The time in seconds that the delivery of all messages in the queue will be delayed. An integer from 0 to 900 (15 minutes)."
}

variable "receive_wait_time_seconds" {
  type        = number
  default     = 0
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling) before returning. An integer from 0 to 20 (seconds)."
}

variable "policy" {
  type        = string
  default     = null
  description = "The JSON policy for the SQS queue."
}

variable "redrive_policy" {
  type        = string
  default     = null
  description = "The JSON policy to set up the Dead Letter Queue."
}

variable "fifo_queue_enabled" {
  type        = bool
  default     = false
  description = "Boolean designating a FIFO queue."
}

variable "content_based_deduplication_enabled" {
  type        = bool
  default     = false
  description = "Enables content-based deduplication for FIFO queues."
}

variable "kms_master_key_id" {
  type        = string
  default     = null
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK."
}

variable "kms_data_key_reuse_period_seconds" {
  type        = number
  default     = 300
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again. An integer representing seconds, between 60 seconds (1 minute) and 86,400 seconds (24 hours)."
}

variable "deduplication_scope" {
  type        = string
  default     = null
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values are `messageGroup` and `queue`."

  validation {
    condition     = var.deduplication_scope == null ? true : contains(["messageGroup", "queue"], var.deduplication_scope)
    error_message = "Allowed values: `messageGroup`, `queue`."
  }
}

variable "fifo_throughput_limit" {
  type        = string
  default     = null
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values are `perQueue` and `perMessageGroupId`."

  validation {
    condition     = var.fifo_throughput_limit == null ? true : contains(["perQueue", "perMessageGroupId"], var.fifo_throughput_limit)
    error_message = "Allowed values: `perQueue`, `perMessageGroupId`."
  }
}

variable "prebuilt_policy" {
  type = object(
    {
      enabled = optional(bool, false)
      sid     = optional(string, "AllowSendMessage")
      actions = optional(list(string), ["sqs:SendMessage"])
      principals = optional(object(
        {
          type        = optional(string, "Service")
          identifiers = optional(list(string), ["events.amazonaws.com"])
        }
      ), {})
    }
  )
  default     = {}
  description = "A prebuilt AWS policy which will be assigned to SQS queue."
}

// File: versions.tf
terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.0"
    }
  }
}

// File: elastictranscoder_pipeline.tf
#---------------------------------------------------
# AWS elastictranscoder pipeline
#---------------------------------------------------
resource "aws_elastictranscoder_pipeline" "elastictranscoder_pipeline" {
  count = var.enable_elastictranscoder_pipeline ? 1 : 0

  input_bucket = var.elastictranscoder_pipeline_input_bucket
  role         = var.elastictranscoder_pipeline_role

  name            = var.elastictranscoder_pipeline_name != null ? lower(var.elastictranscoder_pipeline_name) : "${lower(var.name)}-elastictranscoder-pipeline-${lower(var.environment)}"
  output_bucket   = var.elastictranscoder_pipeline_output_bucket
  aws_kms_key_arn = var.elastictranscoder_pipeline_aws_kms_key_arn

  dynamic "content_config" {
    iterator = content_config
    for_each = var.elastictranscoder_pipeline_content_config

    content {
      bucket        = lookup(content_config.value, "bucket", null)
      storage_class = lookup(content_config.value, "storage_class", null)
    }
  }

  dynamic "content_config_permissions" {
    iterator = content_config_permissions
    for_each = var.elastictranscoder_pipeline_content_config_permissions

    content {
      access       = lookup(content_config_permissions.value, "access", null)
      grantee      = lookup(content_config_permissions.value, "grantee", null)
      grantee_type = lookup(content_config_permissions.value, "grantee_type", null)
    }
  }

  dynamic "notifications" {
    iterator = notifications
    for_each = var.elastictranscoder_pipeline_notifications

    content {
      completed   = lookup(notifications.value, "completed", null)
      error       = lookup(notifications.value, "error", null)
      progressing = lookup(notifications.value, "progressing", null)
      warning     = lookup(notifications.value, "warning", null)
    }
  }

  dynamic "thumbnail_config" {
    iterator = thumbnail_config
    for_each = var.elastictranscoder_pipeline_thumbnail_config

    content {
      bucket        = lookup(thumbnail_config.value, "bucket", null)
      storage_class = lookup(thumbnail_config.value, "storage_class", null)
    }
  }

  dynamic "thumbnail_config_permissions" {
    iterator = thumbnail_config_permissions
    for_each = var.elastictranscoder_pipeline_thumbnail_config_permissions

    content {
      access       = lookup(thumbnail_config_permissions.value, "access", null)
      grantee      = lookup(thumbnail_config_permissions.value, "grantee", null)
      grantee_type = lookup(thumbnail_config_permissions.value, "grantee_type", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: elastictranscoder_preset.tf
#---------------------------------------------------
# AWS elastictranscoder preset
#---------------------------------------------------
resource "aws_elastictranscoder_preset" "elastictranscoder_preset" {
  count = var.enable_elastictranscoder_preset ? 1 : 0

  container = lower(var.elastictranscoder_preset_container)

  name        = var.elastictranscoder_preset_name != null ? lower(var.elastictranscoder_preset_name) : "${lower(var.name)}-elastictranscoder-preset-${lower(var.environment)}"
  description = var.elastictranscoder_preset_description

  dynamic "audio" {
    iterator = audio
    for_each = var.elastictranscoder_preset_audio

    content {
      audio_packing_mode = lookup(audio.value, "audio_packing_mode", null)
      bit_rate           = lookup(audio.value, "bit_rate", null)
      channels           = lookup(audio.value, "channels", null)
      codec              = lookup(audio.value, "codec", null)
      sample_rate        = lookup(audio.value, "sample_rate", null)
    }
  }

  dynamic "audio_codec_options" {
    iterator = audio_codec_options
    for_each = var.elastictranscoder_preset_audio_codec_options

    content {
      profile   = lookup(audio_codec_options.value, "profile", null)
      bit_depth = lookup(audio_codec_options.value, "bit_depth", null)
      bit_order = lookup(audio_codec_options.value, "bit_order", null)
      signed    = lookup(audio_codec_options.value, "signed", null)
    }
  }

  dynamic "thumbnails" {
    iterator = thumbnails
    for_each = var.elastictranscoder_preset_thumbnails

    content {
      format         = lookup(thumbnails.value, "format", null)
      interval       = lookup(thumbnails.value, "interval", null)
      max_width      = lookup(thumbnails.value, "max_width", null)
      max_height     = lookup(thumbnails.value, "max_height", null)
      padding_policy = lookup(thumbnails.value, "padding_policy", null)
      sizing_policy  = lookup(thumbnails.value, "sizing_policy", null)
    }
  }

  dynamic "video" {
    iterator = video
    for_each = var.elastictranscoder_preset_video

    content {
      aspect_ratio         = lookup(video.value, "aspect_ratio", null)
      bit_rate             = lookup(video.value, "bit_rate", null)
      codec                = lookup(video.value, "codec", null)
      display_aspect_ratio = lookup(video.value, "display_aspect_ratio", null)
      fixed_gop            = lookup(video.value, "fixed_gop", null)
      frame_rate           = lookup(video.value, "frame_rate", null)
      keyframes_max_dist   = lookup(video.value, "keyframes_max_dist", null)
      max_frame_rate       = lookup(video.value, "max_frame_rate", null)
      max_height           = lookup(video.value, "max_height", null)
      max_width            = lookup(video.value, "max_width", null)
      padding_policy       = lookup(video.value, "padding_policy", null)
      resolution           = lookup(video.value, "resolution", null)
      sizing_policy        = lookup(video.value, "sizing_policy", null)
    }
  }

  dynamic "video_watermarks" {
    iterator = video_watermarks
    for_each = var.elastictranscoder_preset_video_watermarks

    content {
      id                = lookup(video_watermarks.value, "id", null)
      max_width         = lookup(video_watermarks.value, "max_width", null)
      max_height        = lookup(video_watermarks.value, "max_height", null)
      sizing_policy     = lookup(video_watermarks.value, "sizing_policy", null)
      horizontal_align  = lookup(video_watermarks.value, "horizontal_align", null)
      horizontal_offset = lookup(video_watermarks.value, "horizontal_offset", null)
      vertical_align    = lookup(video_watermarks.value, "vertical_align", null)
      vertical_offset   = lookup(video_watermarks.value, "vertical_offset", null)
      opacity           = lookup(video_watermarks.value, "opacity", null)
      target            = lookup(video_watermarks.value, "target", null)
    }
