// File: transfer_access.tf
#---------------------------------------------------
# AWS Transfer access
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/transfer_access

// File: transfer_server.tf
#---------------------------------------------------
# AWS Transfer server
#---------------------------------------------------
resource "aws_transfer_server" "transfer_server" {
  count = var.enable_transfer_server ? 1 : 0

  endpoint_type          = upper(var.transfer_server_endpoint_type)
  invocation_role        = var.transfer_server_invocation_role
  host_key               = var.transfer_server_host_key
  url                    = var.transfer_server_url
  identity_provider_type = var.transfer_server_identity_provider_type
  logging_role           = var.transfer_server_logging_role
  force_destroy          = var.transfer_server_force_destroy

  dynamic "endpoint_details" {
    iterator = endpoint_details
    for_each = var.transfer_server_endpoint_details

    content {
      vpc_endpoint_id = lookup(endpoint_details.value, "vpc_endpoint_id", null)
    }
  }

  tags = merge(
    {
      Name = var.transfer_server_name != "" ? lower(var.transfer_server_name) : "${lower(var.name)}-transfer-server-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: transfer_ssh_key.tf
#---------------------------------------------------
# AWS Transfer ssh key
#---------------------------------------------------
resource "aws_transfer_ssh_key" "transfer_ssh_key" {
  count = var.enable_transfer_ssh_key ? 1 : 0

  server_id = var.transfer_ssh_key_server_id != "" && !var.enable_transfer_server ? var.transfer_ssh_key_server_id : element(concat(aws_transfer_server.transfer_server.*.id, [""]), 0)
  user_name = var.transfer_ssh_key_user_name != "" && !var.enable_transfer_user ? var.transfer_ssh_key_user_name : element(concat(aws_transfer_user.transfer_user.*.user_name, [""]), 0)
  body      = var.transfer_ssh_key_body

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_transfer_server.transfer_server,
    aws_transfer_user.transfer_user
  ]
}

// File: transfer_user.tf
#---------------------------------------------------
# AWS Transfer user
#---------------------------------------------------
resource "aws_transfer_user" "transfer_user" {
  count = var.enable_transfer_user ? 1 : 0

  server_id = var.transfer_user_server_id != "" && !var.enable_transfer_server ? var.transfer_user_server_id : element(concat(aws_transfer_server.transfer_server.*.id, [""]), 0)
  user_name = var.transfer_user_name != "" ? lower(var.transfer_user_name) : "${lower(var.name)}-transfer-user-${lower(var.environment)}"
  role      = var.transfer_user_role

  home_directory = var.transfer_user_home_directory
  policy         = var.transfer_user_policy

  tags = merge(
    {
      Name = var.transfer_user_name != "" ? lower(var.transfer_user_name) : "${lower(var.name)}-transfer-user-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_transfer_server.transfer_server
  ]
}

