variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

// File: aggregate_metrics_table.tf
resource "aws_dynamodb_table" "aggregate_metrics" {

  name         = "aggregate_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  server_side_encryption {
    enabled = true
  }

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

}

// File: outputs.tf
output "raw_metrics_name" {
  value = aws_dynamodb_table.raw_metrics.id
}

output "raw_metrics_arn" {
  value = aws_dynamodb_table.raw_metrics.arn
}

output "raw_metrics_stream_arn" {
  value = aws_dynamodb_table.raw_metrics.stream_arn
}

output "aggregate_metrics_name" {
  value = aws_dynamodb_table.aggregate_metrics.id
}

output "aggregate_metrics_arn" {
  value = aws_dynamodb_table.aggregate_metrics.arn
}

// File: raw_metrics.table.tf
resource "aws_dynamodb_table" "raw_metrics" {
  # checkov:skip=CKV_AWS_28:RAW metrics are discarded after 24 hours (no backup required)
  name         = "raw_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  server_side_encryption {
    enabled = true
  }

  attribute {
    name = "uuid"
    type = "S"
  }

}

