  description = "(Optional) One or more pairs specifying the IP group rule (in CIDR format) from which web requests originate."
  default     = []
}

#---------------------------------------------------
# AWS Workspaces workspace
#---------------------------------------------------
variable "enable_workspaces_workspace" {
  description = "Enable workspaces workspace usage"
  default     = false
}

variable "workspaces_workspace_name" {
  description = "Set name for workplace"
  default     = ""
}

variable "workspaces_workspace_directory_id" {
  description = "The ID of the directory for the WorkSpace."
  default     = ""
}

variable "workspaces_workspace_bundle_id" {
  description = "(Required) The ID of the bundle for the WorkSpace."
  default     = null
}

variable "workspaces_workspace_user_name" {
  description = "(Required) The user name of the user for the WorkSpace. This user name must exist in the directory for the WorkSpace."
  default     = null
}

variable "workspaces_workspace_root_volume_encryption_enabled" {
  description = "(Optional) Indicates whether the data stored on the root volume is encrypted."
  default     = null
}

variable "workspaces_workspace_user_volume_encryption_enabled" {
  description = "(Optional) Indicates whether the data stored on the user volume is encrypted."
  default     = null
}

variable "workspaces_workspace_volume_encryption_key" {
  description = "(Optional) The symmetric AWS KMS customer master key (CMK) used to encrypt data stored on your WorkSpace. Amazon WorkSpaces does not support asymmetric CMKs."
  default     = null
}

variable "workspaces_workspace_workspace_properties" {
  description = "(Optional) The WorkSpace properties"
  default     = []
}

variable "workspaces_workspace_timeouts" {
  description = "Set timeouts for workspaces workspace"
  default     = {}
}

// File: workspaces_directory.tf
#---------------------------------------------------
# AWS Workspaces directory
#---------------------------------------------------
resource "aws_workspaces_directory" "workspaces_directory" {
  count = var.enable_workspaces_directory ? length(var.workspaces_directory_directory_ids) : 0

  directory_id = var.workspaces_directory_directory_ids[count.index]

  subnet_ids   = var.workspaces_directory_subnet_ids
  ip_group_ids = var.workspaces_directory_ip_group_ids

  dynamic "self_service_permissions" {
    iterator = self_service_permissions
    for_each = var.workspaces_directory_self_service_permissions

    content {
      change_compute_type  = lookup(self_service_permissions.value, "change_compute_type", false)
      increase_volume_size = lookup(self_service_permissions.value, "increase_volume_size", false)
      rebuild_workspace    = lookup(self_service_permissions.value, "rebuild_workspace", false)
      restart_workspace    = lookup(self_service_permissions.value, "restart_workspace", true)
      switch_running_mode  = lookup(self_service_permissions.value, "switch_running_mode", false)
    }
  }

  dynamic "workspace_access_properties" {
    iterator = workspace_access_properties
    for_each = var.workspaces_directory_workspace_access_properties

    content {
      device_type_android    = lookup(workspace_access_properties.value, "device_type_android", null)
      device_type_chromeos   = lookup(workspace_access_properties.value, "device_type_chromeos", null)
      device_type_ios        = lookup(workspace_access_properties.value, "device_type_ios", null)
      device_type_osx        = lookup(workspace_access_properties.value, "device_type_osx", null)
      device_type_web        = lookup(workspace_access_properties.value, "device_type_web", null)
      device_type_windows    = lookup(workspace_access_properties.value, "device_type_windows", null)
      device_type_zeroclient = lookup(workspace_access_properties.value, "device_type_zeroclient", null)
    }
  }

  dynamic "workspace_creation_properties" {
    iterator = workspace_creation_properties
    for_each = var.workspaces_directory_workspace_creation_properties

    content {
      custom_security_group_id            = lookup(workspace_creation_properties.value, "custom_security_group_id", null)
      default_ou                          = lookup(workspace_creation_properties.value, "default_ou", null)
      enable_internet_access              = lookup(workspace_creation_properties.value, "enable_internet_access", null)
      enable_maintenance_mode             = lookup(workspace_creation_properties.value, "enable_maintenance_mode", null)
      user_enabled_as_local_administrator = lookup(workspace_creation_properties.value, "user_enabled_as_local_administrator", null)
    }
  }

  tags = merge(
    {
      Name = var.workspaces_directory_name != "" ? lower(var.workspaces_directory_name) : "${lower(var.name)}-workspaces-directory-${lower(var.environment)}-${count.index + 1}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: workspaces_ip_group.tf
#---------------------------------------------------
# AWS Workspaces ip group
#---------------------------------------------------
resource "aws_workspaces_ip_group" "workspaces_ip_group" {
  count = var.enable_workspaces_ip_group ? 1 : 0

  name = var.workspaces_ip_group_name != "" ? var.workspaces_ip_group_name : "${lower(var.name)}-workspaces-ip-group-${lower(var.environment)}"

  description = var.workspaces_ip_group_description

  dynamic "rules" {
    iterator = rules
    for_each = var.workspaces_ip_group_rules

    content {
      source      = lookup(rules.value, "source", null)
      description = lookup(rules.value, "description", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: workspaces_workspace.tf
#---------------------------------------------------
# AWS Workspaces workspace
#---------------------------------------------------
resource "aws_workspaces_workspace" "workspaces_workspace" {
  count = var.enable_workspaces_workspace ? 1 : 0

  directory_id = var.workspaces_workspace_directory_id != "" ? var.workspaces_workspace_directory_id : (var.enable_workspaces_directory ? aws_workspaces_directory.workspaces_directory[count.index].id : null)
  bundle_id    = var.workspaces_workspace_bundle_id
  user_name    = var.workspaces_workspace_user_name

  root_volume_encryption_enabled = var.workspaces_workspace_root_volume_encryption_enabled
  user_volume_encryption_enabled = var.workspaces_workspace_user_volume_encryption_enabled
  volume_encryption_key          = var.workspaces_workspace_volume_encryption_key

  dynamic "workspace_properties" {
    iterator = workspace_properties
    for_each = var.workspaces_workspace_workspace_properties

    content {
      compute_type_name                         = lookup(workspace_properties.value, "compute_type_name", null)
      user_volume_size_gib                      = lookup(workspace_properties.value, "user_volume_size_gib", null)
      root_volume_size_gib                      = lookup(workspace_properties.value, "root_volume_size_gib", null)
      running_mode                              = lookup(workspace_properties.value, "running_mode", null)
      running_mode_auto_stop_timeout_in_minutes = lookup(workspace_properties.value, "running_mode_auto_stop_timeout_in_minutes", null)
    }
  }

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.workspaces_workspace_timeouts)) > 0 ? [var.workspaces_workspace_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
      update = lookup(timeouts.value, "update", null)
      delete = lookup(timeouts.value, "delete", null)
    }
  }

  tags = merge(
    {
      Name = var.workspaces_workspace_name != "" ? lower(var.workspaces_workspace_name) : "${lower(var.name)}-workspaces-workspace-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = false
    ignore_changes        = [volume_encryption_key]
  }

  depends_on = []
}

// File: main.tf
provider "aws" {
  region = "us-east-1"
}

resource "aws_sns_topic" "test" {
  name = "my-topic-with-policy"
}

resource "aws_sns_topic_policy" "default" {
  arn = aws_sns_topic.test.arn

  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic" "test2" {
  name = "my-topic-with-policy2"
}

resource "aws_sns_topic_policy" "default2" {
  arn = aws_sns_topic.test2.arn

  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

data "aws_iam_policy_document" "sns_topic_policy" {
  policy_id = "__default_policy_ID"

  statement {
    actions = [
      "SNS:Subscribe",
      "SNS:SetTopicAttributes",
      "SNS:RemovePermission",
      "SNS:Receive",
      "SNS:Publish",
      "SNS:ListSubscriptionsByTopic",
      "SNS:GetTopicAttributes",
      "SNS:DeleteTopic",
      "SNS:AddPermission",
    ]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values = []
    }

    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    resources = [
      aws_sns_topic.test.arn,
    ]

    sid = "__default_statement_ID"
  }
}

resource "aws_sns_topic" "user_updates" {
  name = "user-updates-topic"
  delivery_policy = <<EOF
{
  "http": {
    "defaultHealthyRetryPolicy": {
      "minDelayTarget": 20,
      "maxDelayTarget": 20,
      "numRetries": 3,
      "numMaxDelayRetries": 0,
      "numNoDelayRetries": 0,
      "numMinDelayRetries": 0,
      "backoffFunction": "linear"
    },
    "disableSubscriptionOverrides": false,
    "defaultThrottlePolicy": {
      "maxReceivesPerSecond": 1
    }
  }
}
EOF
}

// File: aws.tf
terraform {
  required_version = ">= 0.12"
  required_providers {
    aws = {
      source = "hashicorp/aws"
      #  Allow any 3.22+  version of the AWS provider
      version = "= 3.44"
    }
    null = {
      source  = "hashicorp/null"
      version = "= 3.1.0"
    }
    external = {
      source  = "hashicorp/external"
      version = "= 2.1.0"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "= 2.3.1"
    }

  }
}

provider "aws" {
  region                  = "eu-west-1"
  shared_credentials_file = "~/.aws/credentials"
  profile                 = "default"
}
provider "null" {}
provider "external" {}

// File: az.tf
data "aws_availability_zones" "az" {
  state = "available"
}

// File: my-eip.tf
resource "aws_eip" "my-eip" {
  public_ipv4_pool = "amazon"
  tags             = {}
  vpc              = true
  timeouts {}
}

