  value = aws_security_group.sg.id
}

output "namespace_id" {
  value = aws_service_discovery_private_dns_namespace.namespace.id
}

// File: variables.tf
variable "name" {
  description = "The name of the VPC"
  default     = "ecs-vpc"
}

// File: vpc.tf
data "aws_availability_zones" "available" {
  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "5.0.0"

  name = "${var.name}-vpc"

  cidr = "10.0.0.0/16"
  azs  = slice(data.aws_availability_zones.available.names, 0, 2)

  public_subnets  = ["10.0.4.0/24", "10.0.5.0/24"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24"]

  enable_nat_gateway   = true
  single_nat_gateway   = true
  enable_dns_hostnames = true
}

resource "aws_security_group" "sg" {
  name        = "${var.name}-sg"
  description = "Security group for ECS cluster"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Allow ssh traffic"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTP traffic"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTPS traffic"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTP traffic"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTP traffic"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_service_discovery_private_dns_namespace" "namespace" {
  name = "service.local"
  vpc  = module.vpc.vpc_id
}

// File: main.tf
data "aws_caller_identity" "current" {}

resource "aws_kms_key" "aws_backup_key" {
  description             = "AWS Backup KMS key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_backup_vault" "backup_vault" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.aws_backup_key.arn
}

resource "aws_backup_plan" "backup_plan" {
  name = "${var.vault_name}-backup-plan"

  rule {
    rule_name         = "${var.vault_name}-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    lifecycle {
      delete_after = var.backups_expire_days
    }
  }
}

resource "aws_backup_selection" "backup_plan_selection" {
  iam_role_arn = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/service-role/AWSBackupDefaultServiceRole"
  name         = "${var.vault_name}-backup-rule-tag-selection"
  plan_id      = aws_backup_plan.backup_plan.id
  resources    = ["*"]

  condition {
    string_equals {
      key   = "aws:ResourceTag/${var.backup_tag}"
      value = "true"
    }
  }
}

resource "aws_backup_vault_lock_configuration" "backup_vault_lock_configuration" {
  backup_vault_name   = aws_backup_vault.backup_vault.name

  changeable_for_days = 3  # This configuration makes the vault forever immutable after 3 days

  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
}

// File: variables.tf
variable "vault_name" {
  description = "The name of the AWS Backup vault"
  type        = string 
  default     = "benchmark-vault"
}

variable "schedule" {
  description = "Cron expression for when to run backup plan"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "start_window" {
  default     = 60
  description = "The start window in minutes for the backup plan"
  type        = number
}

variable "completion_window" {
  default     = 180
  description = "The completion window in minutes for the backup plan"
  type        = number
}

variable "backups_expire_days" {
  description = "Days after the backups are deleted"
  type        = number
  default     = 30
}

variable "min_retention_days" {
  description = "Minimum allowed retention days allowed by the vault lock."
  type        = number
  default     = 7
}

variable "max_retention_days" {
  description = "Maximum allowed retention days allowed by the vault lock."
  type        = number
  default     = 90
}

variable "backup_tag" {
  description = "The key of the tag to use on AWS resources that should be backed up."
  type        = string
  default     = "benchmark-backup"
}

// File: cloudformation_stack.tf
#---------------------------------------------------
# AWS cloudformation
#---------------------------------------------------
resource "aws_cloudformation_stack" "cloudformation_stack" {
  count = var.enable_cloudformation_stack ? 1 : 0

  name = var.cloudformation_stack_name != "" ? lower(var.cloudformation_stack_name) : "${lower(var.name)}-cloudformation-stack-${lower(var.environment)}"

  template_body      = var.cloudformation_stack_template_body
  template_url       = var.cloudformation_stack_template_url
  capabilities       = var.cloudformation_stack_capabilities
  disable_rollback   = var.cloudformation_stack_disable_rollback
  notification_arns  = var.cloudformation_stack_notification_arns
  on_failure         = var.cloudformation_stack_on_failure
  policy_body        = var.cloudformation_stack_policy_body
  policy_url         = var.cloudformation_stack_policy_url
  iam_role_arn       = var.cloudformation_stack_iam_role_arn
  timeout_in_minutes = var.cloudformation_stack_timeout_in_minutes

  parameters = var.cloudformation_stack_parameters

  tags = merge(
    {
      Name = var.cloudformation_stack_name != "" ? lower(var.cloudformation_stack_name) : "${lower(var.name)}-cloudformation-stack-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: cloudformation_stack_set.tf
#---------------------------------------------------
# AWS cloudformation stack set
#---------------------------------------------------
resource "aws_cloudformation_stack_set" "cloudformation_stack_set" {
  count = var.enable_cloudformation_stack_set ? 1 : 0

  name                    = var.cloudformation_stack_set_name != "" ? lower(var.cloudformation_stack_set_name) : "${lower(var.name)}-cloudformation-stack-set-${lower(var.environment)}"
  administration_role_arn = var.cloudformation_stack_set_administration_role_arn

  capabilities        = var.cloudformation_stack_set_capabilities
  description         = var.cloudformation_stack_set_description
  execution_role_name = var.cloudformation_stack_set_execution_role_name
  parameters          = var.cloudformation_stack_set_parameters
  template_body       = var.cloudformation_stack_set_template_body
  template_url        = var.cloudformation_stack_set_template_url

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.cloudformation_stack_set_timeouts)) > 0 ? [var.cloudformation_stack_set_timeouts] : []

    content {
      update = lookup(timeouts.value, "update", null)
    }
  }

  tags = merge(
    {
      Name = var.cloudformation_stack_set_name != "" ? lower(var.cloudformation_stack_set_name) : "${lower(var.name)}-cloudformation-stack-set-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: cloudformation_stack_set_instance.tf
#---------------------------------------------------
# AWS cloudformation stack set instance
#---------------------------------------------------
resource "aws_cloudformation_stack_set_instance" "cloudformation_stack_set_instance" {
  count = var.enable_cloudformation_stack_set_instance ? 1 : 0

  stack_set_name = var.cloudformation_stack_set_instance_stack_set_name != "" && !var.enable_cloudformation_stack_set ? var.cloudformation_stack_set_instance_stack_set_name : element(concat(aws_cloudformation_stack_set.cloudformation_stack_set.*.name, [""]), 0)

  account_id          = var.cloudformation_stack_set_instance_account_id
  parameter_overrides = var.cloudformation_stack_set_instance_parameter_overrides
  region              = var.region
  retain_stack        = var.cloudformation_stack_set_instance_retain_stack

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.cloudformation_stack_set_instance_timeouts)) > 0 ? [var.cloudformation_stack_set_instance_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
      update = lookup(timeouts.value, "update", null)
      delete = lookup(timeouts.value, "delete", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_cloudformation_stack_set.cloudformation_stack_set
  ]
}

