// File: backup_framework.tf
#---------------------------------------------------
# AWS Backup framework
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/backup_framework

// File: backup_global_settings.tf
#---------------------------------------------------
# AWS Backup global settings
#---------------------------------------------------
resource "aws_backup_global_settings" "backup_global_settings" {
  count = var.enable_backup_global_settings ? 1 : 0

  global_settings = var.backup_global_settings

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: backup_plan.tf
#---------------------------------------------------
# AWS Backup plan
#---------------------------------------------------
resource "aws_backup_plan" "backup_plan" {
  count = var.enable_backup_plan ? 1 : 0

  name = var.backup_plan_name != "" ? lower(var.backup_plan_name) : "${lower(var.name)}-backup-plan-${lower(var.environment)}"

  dynamic "rule" {
    iterator = rule
    for_each = var.backup_plan_rule

    content {
      rule_name         = lookup(rule.value, "rule_name", null)
      target_vault_name = lookup(rule.value, "target_vault_name", element(concat(aws_backup_vault.backup_vault.*.name, [""]), 0))

      schedule            = lookup(rule.value, "schedule", null)
      start_window        = lookup(rule.value, "start_window", null)
      completion_window   = lookup(rule.value, "completion_window", null)
      recovery_point_tags = lookup(rule.value, "recovery_point_tags", null)

      dynamic "lifecycle" {
        iterator = lifecycle
        for_each = length(keys(lookup(rule.value, "lifecycle", {}))) > 0 ? [lookup(rule.value, "lifecycle", {})] : []

        content {
          cold_storage_after = lookup(lifecycle.value, "cold_storage_after", null)
          delete_after       = lookup(lifecycle.value, "delete_after", null)
        }
      }

      dynamic "copy_action" {
        iterator = copy_action
        for_each = length(keys(lookup(rule.value, "copy_action", {}))) > 0 ? [lookup(rule.value, "copy_action", {})] : []

        content {
          destination_vault_arn = lookup(copy_action.value, "destination_vault_arn", null)

          dynamic "lifecycle" {
            iterator = lifecycle
            for_each = length(keys(lookup(copy_action.value, "lifecycle", {}))) > 0 ? [lookup(copy_action.value, "lifecycle", {})] : []

            content {
              cold_storage_after = lookup(lifecycle.value, "cold_storage_after", null)
              delete_after       = lookup(lifecycle.value, "delete_after", null)
            }
          }
        }
      }

    }
  }

  tags = merge(
    {
      Name = var.backup_plan_name != "" ? lower(var.backup_plan_name) : "${lower(var.name)}-backup-plan-${lower(var.environment)}"
    },
    var.tags,
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_backup_vault.backup_vault
  ]
}

// File: backup_region_settings.tf
#---------------------------------------------------
# AWS Backup region settings
#---------------------------------------------------
resource "aws_backup_region_settings" "backup_region_settings" {
  count = var.enable_backup_region_settings ? 1 : 0

  resource_type_opt_in_preference = var.backup_region_settings_resource_type_opt_in_preference

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: backup_report_plan.tf
#---------------------------------------------------
# AWS Backup report plan
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/backup_report_plan

// File: backup_selection.tf
#---------------------------------------------------
# AWS Backup selection
#---------------------------------------------------
resource "aws_backup_selection" "backup_selection" {
  count = var.enable_backup_selection ? 1 : 0

  name         = var.backup_selection_name != "" ? lower(var.backup_selection_name) : "${lower(var.name)}-backup-selection-${lower(var.environment)}"
  iam_role_arn = var.backup_selection_iam_role_arn
  plan_id      = var.backup_selection_plan_id != "" && !var.enable_backup_plan ? var.backup_selection_plan_id : element(concat(aws_backup_plan.backup_plan.*.id, [""]), 0)

  resources = var.backup_selection_resources

  dynamic "selection_tag" {
    iterator = selection_tag
    for_each = var.backup_selection_selection_tag

    content {
      type  = lookup(selection_tag.value, "type", null)
      key   = lookup(selection_tag.value, "key", null)
      value = lookup(selection_tag.value, "value", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_backup_plan.backup_plan
  ]
}

// File: backup_vault.tf
