// File: outputs.tf
#---------------------------------------------------
# SNS topic
#---------------------------------------------------
output "sns_topic_id" {
  description = "The ARN of the SNS topic"
  value       = element(concat(aws_sns_topic.sns_topic.*.id, [""]), 0)
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic, as a more obvious property (clone of id)"
  value       = element(concat(aws_sns_topic.sns_topic.*.arn, [""]), 0)
}

#---------------------------------------------------
# SNS topic policies
#---------------------------------------------------
output "sns_topic_policy_id" {
  description = "Get SNS topic policy ID"
  value       = element(concat(aws_sns_topic_subscription.sns_topic_subscription.*.id, [""]), 0)
}

#---------------------------------------------------
# SNS topic subscription
#---------------------------------------------------
output "sns_topic_subscription_id" {
  description = "The ARN of the subscription"
  value       = element(concat(aws_sns_topic_subscription.sns_topic_subscription.*.id, [""]), 0)
}

output "sns_topic_subscription_arn" {
  description = "The ARN of the subscription stored as a more user-friendly property"
  value       = element(concat(aws_sns_topic_subscription.sns_topic_subscription.*.arn, [""]), 0)
}

output "sns_topic_subscription_topic_arn" {
  description = "The ARN of the topic the subscription belongs to"
  value       = element(concat(aws_sns_topic_subscription.sns_topic_subscription.*.topic_arn, [""]), 0)
}

output "sns_topic_subscription_protocol" {
  description = "The protocol being used"
  value       = element(concat(aws_sns_topic_subscription.sns_topic_subscription.*.protocol, [""]), 0)
}

output "sns_topic_subscription_endpoint" {
  description = "The full endpoint to send data to (SQS ARN, HTTP(S) URL, Application ARN, SMS number, etc.)"
  value       = element(concat(aws_sns_topic_subscription.sns_topic_subscription.*.endpoint, [""]), 0)
}

// File: sns_platform_application.tf
#---------------------------------------------------
# AWS SNS platform application
#---------------------------------------------------
resource "aws_sns_platform_application" "sns_platform_application" {
  count = var.enable_sns_platform_application ? 1 : 0

  name                = var.sns_platform_application_name != "" ? var.sns_platform_application_name : "${lower(var.name)}-sns-plat-app-${lower(var.environment)}"
  platform            = var.sns_platform_application_platform
  platform_credential = var.sns_platform_application_platform_credential

  event_delivery_failure_topic_arn = var.sns_platform_application_event_delivery_failure_topic_arn
  event_endpoint_created_topic_arn = var.sns_platform_application_event_endpoint_created_topic_arn
  event_endpoint_deleted_topic_arn = var.sns_platform_application_event_endpoint_deleted_topic_arn
  event_endpoint_updated_topic_arn = var.sns_platform_application_event_endpoint_updated_topic_arn

  failure_feedback_role_arn    = var.sns_platform_application_failure_feedback_role_arn
  platform_principal           = var.sns_platform_application_platform_principal
  success_feedback_role_arn    = var.sns_platform_application_success_feedback_role_arn
  success_feedback_sample_rate = var.sns_platform_application_success_feedback_sample_rate

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: sns_sms_preferences.tf
#---------------------------------------------------
# AWS SNS sms preferences
#---------------------------------------------------
resource "aws_sns_sms_preferences" "sns_sms_preferences" {
  count = var.enable_sns_sms_preferences ? 1 : 0

  monthly_spend_limit                   = var.sns_sms_preferences_monthly_spend_limit
  delivery_status_iam_role_arn          = var.sns_sms_preferences_delivery_status_iam_role_arn
  delivery_status_success_sampling_rate = var.sns_sms_preferences_delivery_status_success_sampling_rate
  default_sender_id                     = var.sns_sms_preferences_default_sender_id
  default_sms_type                      = var.sns_sms_preferences_default_sms_type
  usage_report_s3_bucket                = var.sns_sms_preferences_usage_report_s3_bucket

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: sns_topic.tf
#---------------------------------------------------
# AWS SNS topic
#---------------------------------------------------
resource "aws_sns_topic" "sns_topic" {
  count = var.enable_sns_topic ? 1 : 0

  name            = var.sns_topic_name != "" && var.sns_topic_name_prefix == "" ? var.sns_topic_name : null
  name_prefix     = var.sns_topic_name_prefix != "" && var.sns_topic_name == "" ? var.sns_topic_name_prefix : null
  display_name    = var.sns_topic_display_name != "" ? var.sns_topic_display_name : "${lower(var.name)}-sns-${lower(var.environment)}"
  policy          = var.sns_topic_policy
  delivery_policy = var.sns_topic_delivery_policy

  application_success_feedback_role_arn    = var.sns_topic_application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.sns_topic_application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.sns_topic_application_failure_feedback_role_arn

  http_success_feedback_role_arn    = var.sns_topic_http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.sns_topic_http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.sns_topic_http_failure_feedback_role_arn

  kms_master_key_id = var.sns_topic_kms_master_key_id

  lambda_success_feedback_role_arn    = var.sns_topic_lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.sns_topic_lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.sns_topic_lambda_failure_feedback_role_arn

  sqs_success_feedback_role_arn    = var.sns_topic_sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sns_topic_sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sns_topic_sqs_failure_feedback_role_arn

  tags = merge(
    {
      Name = var.sns_topic_display_name != "" ? var.sns_topic_display_name : "${lower(var.name)}-sns-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: sns_topic_policy.tf
#---------------------------------------------------
# AWS SNS topic policies
#---------------------------------------------------
resource "aws_sns_topic_policy" "sns_topic_policy" {
  count = var.enable_sns_topic_policy ? 1 : 0

  arn    = var.sns_topic_policy_topic_arn != null ? var.sns_topic_policy_topic_arn : (var.enable_sns_topic ? element(concat(aws_sns_topic.sns_topic.*.arn, [""]), 0) : null)
  policy = var.sns_topic_policy_policy

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_sns_topic.sns_topic
  ]
}

// File: sns_topic_subscription.tf
#---------------------------------------------------
# AWS SNS topic subscription
#---------------------------------------------------
resource "aws_sns_topic_subscription" "sns_topic_subscription" {
  count = var.enable_sns_topic_subscription ? length(var.sns_topic_subscription_sns_endpoints) : 0

  topic_arn = var.sns_topic_subscription_topic_arn != "" ? var.sns_topic_subscription_topic_arn : element(concat(aws_sns_topic.sns_topic.*.arn, [""]), 0)

  confirmation_timeout_in_minutes = var.sns_topic_subscription_confirmation_timeout_in_minutes
  endpoint_auto_confirms          = var.sns_topic_subscription_endpoint_auto_confirms
  raw_message_delivery            = var.sns_topic_subscription_raw_message_delivery

  protocol = var.sns_topic_subscription_sns_protocol
  endpoint = var.sns_topic_subscription_sns_endpoints[count.index]

  filter_policy   = var.sns_topic_subscription_filter_policy
  delivery_policy = var.sns_topic_subscription_delivery_policy

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_sns_topic.sns_topic
  ]
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks. Each element should have keys named key, value, etc."
  type        = map(string)
  default     = {}
}

#-----------------------------------------------------------
# SNS topic
#-----------------------------------------------------------
variable "enable_sns_topic" {
  description = "Enable SNS topic usage"
  default     = false
}

variable "sns_topic_name" {
  description = "The friendly name for the SNS topic. By default generated by Terraform."
  default     = ""
}

variable "sns_topic_name_prefix" {
  description = "(Optional) The friendly name for the SNS topic. Conflicts with sns_topic_name."
  default     = ""
}

variable "sns_topic_display_name" {
  description = "(Optional) The display name for the SNS topic"
  default     = ""
}

variable "sns_topic_delivery_policy" {
  description = "(Optional) The SNS delivery policy."
  default     = ""
}

variable "sns_topic_policy" {
  description = "(Optional) The fully-formed AWS policy as JSON. For more information about building AWS IAM policy documents with Terraform"
  default     = null
}

variable "sns_application_success_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive success feedback for this topic"
  default     = null
}

variable "sns_application_success_feedback_sample_rate" {
  description = "(Optional) Percentage of success to sample"
  default     = null
}

variable "sns_application_failure_feedback_role_arn" {
  description = "(Optional) IAM role for failure feedback"
  default     = null
}

variable "sns_topic_http_success_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive success feedback for this topic"
