// File: codeartifact_domain.tf
#---------------------------------------------------
# AWS CodeArtifact domain
#---------------------------------------------------
resource "aws_codeartifact_domain" "codeartifact_domain" {
  count = var.enable_codeartifact_domain ? 1 : 0

  domain = var.codeartifact_domain != "" ? lower(var.codeartifact_domain) : "${lower(var.name)}-codeartifact-domain-${lower(var.environment)}"

  encryption_key = var.codeartifact_domain_encryption_key

  tags = merge(
    {
      Name = var.codeartifact_domain != "" ? lower(var.codeartifact_domain) : "${lower(var.name)}-codeartifact-domain-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: codeartifact_domain_permissions_policy.tf
#---------------------------------------------------
# AWS CodeArtifact domain permissions policy
#---------------------------------------------------
resource "aws_codeartifact_domain_permissions_policy" "codeartifact_domain_permissions_policy" {
  count = var.enable_codeartifact_domain_permissions_policy ? 1 : 0

  domain          = var.codeartifact_domain_permissions_policy_domain != "" ? var.codeartifact_domain_permissions_policy_domain : (var.enable_codeartifact_domain ? aws_codeartifact_domain.codeartifact_domain[0].domain : null)
  policy_document = var.codeartifact_domain_permissions_policy_document

  domain_owner    = var.codeartifact_domain_permissions_policy_domain_owner
  policy_revision = var.codeartifact_domain_permissions_policy_revision

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_codeartifact_domain.codeartifact_domain
  ]
}

// File: codeartifact_repository.tf
#---------------------------------------------------
# AWS CodeArtifact repository
#---------------------------------------------------
resource "aws_codeartifact_repository" "codeartifact_repository" {
  count = var.enable_codeartifact_repository ? 1 : 0

  repository = var.codeartifact_repository != "" ? lower(var.codeartifact_repository) : "${lower(var.name)}-codeartifact-repository-${lower(var.environment)}"
  domain     = var.codeartifact_repository_domain != "" ? var.codeartifact_repository_domain : (var.enable_codeartifact_domain ? aws_codeartifact_domain.codeartifact_domain[0].domain : null)

  description  = var.codeartifact_repository_description
  domain_owner = var.codeartifact_repository_domain_owner

  dynamic "upstream" {
    iterator = upstream
    for_each = var.codeartifact_repository_upstream

    content {
      repository_name = lookup(upstream.value, "repository_name", null)
    }
  }

  dynamic "external_connections" {
    iterator = external_connections
    for_each = var.codeartifact_repository_external_connections

    content {
      external_connection_name = lookup(external_connections.value, "external_connection_name", null)
    }
  }

  tags = merge(
    {
      Name = var.codeartifact_repository != "" ? lower(var.codeartifact_repository) : "${lower(var.name)}-codeartifact-repository-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_codeartifact_domain.codeartifact_domain
  ]
}

// File: codeartifact_repository_permissions_policy.tf
#---------------------------------------------------
# AWS CodeArtifact repository permissions policy
#---------------------------------------------------
resource "aws_codeartifact_repository_permissions_policy" "codeartifact_repository_permissions_policy" {
  count = var.enable_codeartifact_repository_permissions_policy ? 1 : 0

  repository      = var.codeartifact_repository_permissions_policy_repository != "" ? var.codeartifact_repository_permissions_policy_repository : (var.enable_codeartifact_repository ? aws_codeartifact_repository.codeartifact_repository[0].repository : null)
  domain          = var.codeartifact_repository_permissions_policy_domain != "" ? var.codeartifact_repository_permissions_policy_domain : (var.enable_codeartifact_domain ? aws_codeartifact_domain.codeartifact_domain[0].domain : null)
  policy_document = var.codeartifact_repository_permissions_policy_document

  domain_owner    = var.codeartifact_repository_permissions_policy_domain_owner
  policy_revision = var.codeartifact_repository_permissions_policy_policy_revision


  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_codeartifact_repository.codeartifact_repository,
    aws_codeartifact_domain.codeartifact_domain
  ]
}

