// File: lambda.tf
# Configure Lambda function
resource "aws_lambda_function" "lambda" {
  for_each = { for i in local.lambda : i.function_name => i }

  architectures           = each.value.architectures
  code_signing_config_arn = each.value.code_signing_config_arn
  description             = each.value.description
  function_name           = each.value.function_name
  filename                = each.value.source
  handler                 = each.value.handler
  source_code_hash        = filebase64(each.value.source)
  role                    = aws_iam_role.lambda[each.value.function_name].arn
  runtime                 = each.value.runtime
  memory_size             = each.value.memory
  timeout                 = each.value.timeout

  environment {
    variables = each.value.variables
  }

  # Dynamically assign VPC configuration only when such are present
  dynamic "vpc_config" {
    for_each = each.value.vpc
    content {
      security_group_ids = vpc_config.value.security_group_ids
      subnet_ids         = vpc_config.value.subnet_ids
    }

  }

  # Logging dependencies
  depends_on = [
    aws_iam_role_policy_attachment.lambda_logs,
    aws_cloudwatch_log_group.lambda,
  ]

  tags = local.tags
}

// File: locals.tf
locals {

  file_config = try(yamldecode(file(var.config))["config"], [])
  raw_config  = yamldecode(var.raw_config)["config"]
  # Overwrite configurations (if applicable)
  config = length(local.raw_config) > 0 ? local.raw_config : local.file_config

  # === LAMBDA CONFIG ===

  lambda = flatten([
    for config in local.config : {

      function_name           = config.name
      handler                 = config.handler
      runtime                 = config.runtime
      source                  = config.source
      architectures           = lookup(config, "architectures", ["x86_64"])
      code_signing_config_arn = lookup(config, "code_signing_config_arn", null)
      description             = lookup(config, "description", "")
      memory                  = lookup(config, "memory", 128)
      timeout                 = lookup(config, "timeout", 3)
      variables = {
        for i in local.variables : i.name => i.value if i.function_name == config.name
      }
      vpc = [
        for i in local.vpc_config : {
          subnet_ids         = i.subnet_ids
          security_group_ids = i.security_group_ids
        } if i.function_name == config.name
      ]
      permissions = [
        for i in local.permissions : {
          role   = i.role
          path   = i.path
          policy = i.policy
        }
      ]
      logs = [
        for i in local.logs : {
          group_name = i.group_name
          retention  = i.retention
        } if i.function_name == config.name
      ]
    }
  ])

  # === ENVRIONMENT VARIABLES ===

  variables = flatten([
    for config in local.config : [
      for variable in lookup(config, "variables", []) : {
        function_name = config.name
        name          = variable.name
        value         = variable.value
      }
    ]
  ])

  # === VPC CONFIG ===

  vpc_config = flatten([
    for config in local.config : {
      function_name      = config.name
      subnet_ids         = lookup(config.vpc, "subnet_ids", [])
      security_group_ids = lookup(config.vpc, "security_group_ids", [])
  }])

  # === PERMISSIONS CONFIG ===

  permissions = flatten([
    for config in local.config : {
      function_name = config.name
      role          = lookup(config.permissions, "role", config.name)
      path          = lookup(config.permissions, "path", "/terrabits/lambda/")
      policy        = lookup(config.permissions, "policy", "")
    }
  ])

  # === LOGS ===

  logs = flatten([
    for config in local.config : {
      function_name = config.name
      group_name    = lookup(config.logs, "group_name", "/aws/lambda/${config.name}")
      retention     = lookup(config.logs, "retention", 7)
    }
  ])

  tags = merge(var.shared_tags, {
    Terraformed = true
  })
}

// File: logs.tf
# Logs configuration for Lambda function
# This is to manage the CloudWatch Log Group for the Lambda Function.
# If skipping this resource configuration, also add "logs:CreateLogGroup" to the IAM policy below.
resource "aws_cloudwatch_log_group" "lambda" {
  for_each = { for i in local.lambda : i.function_name => i }

  name              = lookup(each.value.logs[0], "group_name", null)
  retention_in_days = lookup(each.value.logs[0], "retention", null)

  tags = local.tags
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:aws:logs:*:*:*"
    ]
  }
}

# See also the following AWS managed policy: AWSLambdaBasicExecutionRole
resource "aws_iam_policy" "lambda_logging" {
  for_each = { for i in local.lambda : i.function_name => i }

  name        = "${each.value.function_name}-logging"
  path        = lookup(each.value.permissions[0], "path", null)
  description = "IAM policy for logging from a lambda"

  policy = data.aws_iam_policy_document.lambda_logging.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  for_each = { for i in local.lambda : i.function_name => i }

  role       = aws_iam_role.lambda[each.value.function_name].name
  policy_arn = aws_iam_policy.lambda_logging[each.value.function_name].arn
}

// File: output.tf
output "lambda_arn" {
  description = "Amazon Resource Name (ARN)"
  value = [
    for i in aws_lambda_function.lambda : i.arn
  ]
}

output "lambda_invoke_arn" {
  description = "ARN to be used for invoking Lambda Function from API Gateway"
  value = [
    for i in aws_lambda_function.lambda : i.invoke_arn
  ]
}

output "lambda_id" {
  description = "Lambda function name"
  value = [
    for i in local.lambda : i.function_name
  ]
}

// File: permissions.tf
data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# A Lambda function may access to other AWS resources such as S3 bucket. So an
# IAM role needs to be defined.
resource "aws_iam_role" "lambda" {
  for_each = { for i in local.lambda : i.function_name => i }

  name = lookup(each.value.permissions[0], "role", null)
  path = lookup(each.value.permissions[0], "path", null)

  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json

  tags = local.tags
}

# Optional IAM policy, which is used to extend lambda permissions
resource "aws_iam_role_policy" "permissions" {
  for_each = { for i in local.lambda : i.function_name => i if length(lookup(i.permissions[0], "policy", "")) > 0 }

  name   = each.value.function_name
  role   = aws_iam_role.lambda[each.value.function_name].id
  policy = lookup(each.value.permissions[0], "policy", "")
}

// File: variables.tf
# === Required variables ===

variable "config" {
  type    = string
  default = "Path to the pipeline configuration file"
}

# === Optional variables ===

variable "raw_config" {
  type        = string
  description = "RAW Yaml configuration for the module. **IMPORTANT** Overwrites 'config' variable"
  default     = "\"config\": []"
}

variable "shared_tags" {
  type        = map(any)
  description = "Additional shared resource tags"
  default     = {}
}

// File: context.tf
#
# ONLY EDIT THIS FILE IN github.com/cloudposse/terraform-null-label
# All other instances of this file should be a copy of that one
#
#
# Copy this file from https://github.com/cloudposse/terraform-null-label/blob/master/exports/context.tf
# and then place it in your Terraform module to automatically get
# Cloud Posse's standard configuration inputs suitable for passing
# to Cloud Posse modules.
#
# curl -sL https://raw.githubusercontent.com/cloudposse/terraform-null-label/master/exports/context.tf -o context.tf
#
# Modules should access the whole context as `module.this.context`
# to get the input variables with nulls for defaults,
# for example `context = module.this.context`,
# and access individual variables as `module.this.<var>`,
# with final values filled in.
#
# For example, when using defaults, `module.this.context.delimiter`
# will be null, and `module.this.delimiter` will be `-` (hyphen).
#

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0" # requires Terraform >= 0.13.0

  enabled             = var.enabled
  namespace           = var.namespace
  tenant              = var.tenant
  environment         = var.environment
  stage               = var.stage
  name                = var.name
  delimiter           = var.delimiter
  attributes          = var.attributes
  tags                = var.tags
  additional_tag_map  = var.additional_tag_map
  label_order         = var.label_order
  regex_replace_chars = var.regex_replace_chars
  id_length_limit     = var.id_length_limit
  label_key_case      = var.label_key_case
  label_value_case    = var.label_value_case
  descriptor_formats  = var.descriptor_formats
  labels_as_tags      = var.labels_as_tags

  context = var.context
}

# Copy contents of cloudposse/terraform-null-label/variables.tf here

variable "context" {
  type = any
  default = {
    enabled             = true
    namespace           = null
    tenant              = null
    environment         = null
    stage               = null
    name                = null
    delimiter           = null
    attributes          = []
    tags                = {}
    additional_tag_map  = {}
    regex_replace_chars = null
    label_order         = []
    id_length_limit     = null
    label_key_case      = null
    label_value_case    = null
    descriptor_formats  = {}
    # Note: we have to use [] instead of null for unset lists due to
    # https://github.com/hashicorp/terraform/issues/28137
    # which was not fixed until Terraform 1.0.0,
    # but we want the default to be all the labels in `label_order`
    # and we want users to be able to prevent all tag generation
    # by setting `labels_as_tags` to `[]`, so we need
    # a different sentinel to indicate "default"
    labels_as_tags = ["unset"]
  }
  description = <<-EOT
    Single object for setting entire context at once.
    See description of individual variables for details.
    Leave string and numeric variables as `null` to use default value.
    Individual variable settings (non-null) override settings in context object,
    except for attributes, tags, and additional_tag_map, which are merged.
  EOT

  validation {
    condition     = lookup(var.context, "label_key_case", null) == null ? true : contains(["lower", "title", "upper"], var.context["label_key_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }

  validation {
    condition     = lookup(var.context, "label_value_case", null) == null ? true : contains(["lower", "title", "upper", "none"], var.context["label_value_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "enabled" {
  type        = bool
  default     = null
  description = "Set to false to prevent the module from creating any resources"
}

variable "namespace" {
  type        = string
  default     = null
  description = "ID element. Usually an abbreviation of your organization name, e.g. 'eg' or 'cp', to help ensure generated IDs are globally unique"
}

variable "tenant" {
  type        = string
  default     = null
  description = "ID element _(Rarely used, not included by default)_. A customer identifier, indicating who this instance of a resource is for"
}

variable "environment" {
  type        = string
  default     = null
  description = "ID element. Usually used for region e.g. 'uw2', 'us-west-2', OR role 'prod', 'staging', 'dev', 'UAT'"
}

variable "stage" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate role, e.g. 'prod', 'staging', 'source', 'build', 'test', 'deploy', 'release'"
}

variable "name" {
  type        = string
  default     = null
  description = <<-EOT
    ID element. Usually the component or solution name, e.g. 'app' or 'jenkins'.
    This is the only ID element not also included as a `tag`.
    The "name" tag is set to the full `id` string. There is no tag with the value of the `name` input.
    EOT
}

variable "delimiter" {
  type        = string
  default     = null
  description = <<-EOT
    Delimiter to be used between ID elements.
    Defaults to `-` (hyphen). Set to `""` to use no delimiter at all.
  EOT
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = <<-EOT
    ID element. Additional attributes (e.g. `workers` or `cluster`) to add to `id`,
    in the order they appear in the list. New attributes are appended to the
    end of the list. The elements of the list are joined by the `delimiter`
    and treated as a single ID element.
    EOT
}

variable "labels_as_tags" {
  type        = set(string)
  default     = ["default"]
  description = <<-EOT
    Set of labels (ID elements) to include as tags in the `tags` output.
    Default is to include all labels.
    Tags with empty values will not be included in the `tags` output.
    Set to `[]` to suppress all generated tags.
    **Notes:**
      The value of the `name` tag, if included, will be the `id`, not the `name`.
      Unlike other `null-label` inputs, the initial setting of `labels_as_tags` cannot be
      changed in later chained modules. Attempts to change it will be silently ignored.
    EOT
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional tags (e.g. `{'BusinessUnit': 'XYZ'}`).
    Neither the tag keys nor the tag values will be modified by this module.
    EOT
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional key-value pairs to add to each map in `tags_as_list_of_maps`. Not added to `tags` or `id`.
    This is for some rare cases where resources want additional configuration of tags
    and therefore take a list of maps with tag key, value, and additional configuration.
    EOT
}

variable "label_order" {
  type        = list(string)
  default     = null
  description = <<-EOT
    The order in which the labels (ID elements) appear in the `id`.
    Defaults to ["namespace", "environment", "stage", "name", "attributes"].
    You can omit any of the 6 labels ("tenant" is the 6th), but at least one must be present.
    EOT
}

variable "regex_replace_chars" {
  type        = string
  default     = null
  description = <<-EOT
    Terraform regular expression (regex) string.
    Characters matching the regex will be removed from the ID elements.
    If not set, `"/[^a-zA-Z0-9-]/"` is used to remove all characters other than hyphens, letters and digits.
  EOT
}

variable "id_length_limit" {
  type        = number
  default     = null
  description = <<-EOT
    Limit `id` to this many characters (minimum 6).
    Set to `0` for unlimited length.
    Set to `null` for keep the existing setting, which defaults to `0`.
    Does not affect `id_full`.
  EOT
  validation {
    condition     = var.id_length_limit == null ? true : var.id_length_limit >= 6 || var.id_length_limit == 0
    error_message = "The id_length_limit must be >= 6 if supplied (not null), or 0 for unlimited length."
  }
}

variable "label_key_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of the `tags` keys (label names) for tags generated by this module.
    Does not affect keys of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper`.
    Default value: `title`.
  EOT

  validation {
    condition     = var.label_key_case == null ? true : contains(["lower", "title", "upper"], var.label_key_case)
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }
}

variable "label_value_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of ID elements (labels) as included in `id`,
    set as tag values, and output by this module individually.
    Does not affect values of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper` and `none` (no transformation).
    Set this to `title` and set `delimiter` to `""` to yield Pascal Case IDs.
    Default value: `lower`.
  EOT

  validation {
    condition     = var.label_value_case == null ? true : contains(["lower", "title", "upper", "none"], var.label_value_case)
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "descriptor_formats" {
  type        = any
  default     = {}
  description = <<-EOT
    Describe additional descriptors to be output in the `descriptors` output map.
    Map of maps. Keys are names of descriptors. Values are maps of the form
    `{
       format = string
       labels = list(string)
    }`
    (Type is `any` so the map values can later be enhanced to provide additional options.)
    `format` is a Terraform format string to be passed to the `format()` function.
    `labels` is a list of labels, in order, to pass to `format()` function.
    Label values will be normalized before being passed to `format()` so they will be
    identical to how they appear in `id`.
    Default is `{}` (`descriptors` output will be empty).
    EOT
}

#### End of copy of cloudposse/terraform-null-label/variables.tf

// File: main.tf
data "aws_caller_identity" "current" {}

###############################
### R53 Hosted Zone ###
###############################

locals {
  zones              = var.zone_name == null ? [] : try(tolist(var.zone_name), [tostring(var.zone_name)], [])
  skip_zone_creation = (length(local.zones) == 0 || !var.create_phz)
}

resource "aws_route53_zone" "phz" {
  #checkov:skip=CKV2_AWS_39:Not enabling query logging for zones. Only internal resolvers.
  for_each = (length(local.zones) > 0 && var.create_phz) ? toset(local.zones) : []

  name          = each.value
  force_destroy = var.force_destroy

  dynamic "vpc" {
    for_each = { for id in var.vpc_ids : id => id }

    content {
      vpc_id = vpc.value
    }
  }

  lifecycle {
    ignore_changes = [vpc]
  }

  tags = merge(
    {
      Name = each.value
    },
    var.tags,
    var.terragrunt_tags
  )
}

resource "aws_kms_key" "this" {
  count = (length(local.zones) > 0 && var.create_phz && var.enable_dnssec && length(var.vpc_ids) == 0) ? 1 : 0

  customer_master_key_spec = "ECC_NIST_P256"
  deletion_window_in_days  = 7
  key_usage                = "SIGN_VERIFY"
  policy = jsonencode({
    Statement = [
      {
        Action = [
          "kms:DescribeKey",
          "kms:GetPublicKey",
          "kms:Sign",
          "kms:Verify",
        ],
        Effect = "Allow"
        Principal = {
          Service = "dnssec-route53.amazonaws.com"
        }
        Resource = "*"
        Sid      = "Allow Route 53 DNSSEC Service",
      },
      {
        Action = "kms:*"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Resource = "*"
        Sid      = "Enable IAM User Permissions"
      },
    ]
    Version = "2012-10-17"
  })
}

resource "aws_route53_key_signing_key" "this" {
  count = (length(local.zones) > 0 && var.create_phz && var.enable_dnssec && length(var.vpc_ids) == 0) ? 1 : 0

  hosted_zone_id             = aws_route53_zone.phz[var.zone_name].id
  key_management_service_arn = aws_kms_key.this[0].arn
  name                       = "${var.zone_name}-dnssec"
}

resource "aws_route53_hosted_zone_dnssec" "this" {
  count = (length(local.zones) > 0 && var.create_phz && var.enable_dnssec && length(var.vpc_ids) == 0) ? 1 : 0

  hosted_zone_id = aws_route53_key_signing_key.this[0].hosted_zone_id

  depends_on = [aws_route53_key_signing_key.this]
}

###################
### R53 Records ###
###################

locals {
  # prepare the records
  records_expanded = {
    for i, record in var.records : join("-", compact([
      lower(record.type),
      try(lower(record.set_identifier), ""),
      try(lower(record.failover), ""),
      try(lower(record.name), ""),
      ])) => {
      type = record.type
      name = try(record.name, "")
      ttl  = try(record.ttl, null)
      alias = {
        name                   = try(record.alias.name, null)
        zone_id                = try(record.alias.zone_id, null)
        evaluate_target_health = try(record.alias.evaluate_target_health, null)
      }
      allow_overwrite = try(record.allow_overwrite, var.allow_overwrite)
      health_check_id = try(record.health_check_id, null)
      idx             = i
      set_identifier  = try(record.set_identifier, null)
      weight          = try(record.weight, null)
      failover        = try(record.failover, null)
    }
  }

  records_by_name = {
    for product in setproduct(local.zones, keys(local.records_expanded)) : "${product[1]}-${product[0]}" => {
      zone_id         = try(aws_route53_zone.phz[product[0]].id, null)
      type            = local.records_expanded[product[1]].type
      name            = local.records_expanded[product[1]].name
      ttl             = local.records_expanded[product[1]].ttl
      alias           = local.records_expanded[product[1]].alias
      allow_overwrite = local.records_expanded[product[1]].allow_overwrite
      health_check_id = local.records_expanded[product[1]].health_check_id
      idx             = local.records_expanded[product[1]].idx
      set_identifier  = local.records_expanded[product[1]].set_identifier
      weight          = local.records_expanded[product[1]].weight
      failover        = local.records_expanded[product[1]].failover
    }
  }

  records_by_zone_id = {
    for id, record in local.records_expanded : id => {
      zone_id         = var.zone_id
      type            = record.type
      name            = record.name
      ttl             = record.ttl
      alias           = record.alias
      allow_overwrite = record.allow_overwrite
      health_check_id = record.health_check_id
      idx             = record.idx
      set_identifier  = record.set_identifier
      weight          = record.weight
      failover        = record.failover
    }
  }

  records = local.skip_zone_creation ? local.records_by_zone_id : local.records_by_name
}

resource "aws_route53_record" "record" {
  for_each = length(var.records) == 0 ? {} : local.records

  zone_id         = each.value.zone_id
  type            = each.value.type
  name            = each.value.name
  allow_overwrite = each.value.allow_overwrite
  health_check_id = each.value.health_check_id
  set_identifier  = each.value.set_identifier

  # only set default TTL when not set and not alias record
  ttl = each.value.ttl == null && each.value.alias.name == null ? var.default_ttl : each.value.ttl

  # split TXT records at 255 chars to support >255 char records
  records = (can(var.records[each.value.idx].records) && var.records[each.value.idx].records != null) ? [for r in var.records[each.value.idx].records :
    each.value.type == "TXT" && length(regexall("(\\\"\\\")", r)) == 0 ?
    join("\"\"", compact(split("{SPLITHERE}", replace(r, "/(.{255})/", "$1{SPLITHERE}")))) : r
  ] : null

  dynamic "weighted_routing_policy" {
    for_each = each.value.weight == null ? [] : [each.value.weight]

    content {
      weight = weighted_routing_policy.value
    }
  }

  dynamic "failover_routing_policy" {
    for_each = each.value.failover == null ? [] : [each.value.failover]

    content {
      type = failover_routing_policy.value
    }
  }

  dynamic "alias" {
    for_each = each.value.alias.name == null ? [] : [each.value.alias]

    content {
      name                   = alias.value.name
      zone_id                = alias.value.zone_id
      evaluate_target_health = alias.value.evaluate_target_health
    }
  }
}

// File: outputs.tf
output "zone" {
  description = "PHZ Object"
  value = (length(aws_route53_zone.phz) > 0) ? {
    name    = aws_route53_zone.phz[var.zone_name].name
    zone_id = aws_route53_zone.phz[var.zone_name].zone_id
    arn     = aws_route53_zone.phz[var.zone_name].arn
    vpc     = aws_route53_zone.phz[var.zone_name].vpc
  } : null
}

output "vpc_id" {
  description = "vpc id acting as primary associated vpc for private hosted zone"
  value       = try(var.vpc_ids, null)
}

output "route53_record_name" {
  description = "the name of the record"
  value       = { for k, v in aws_route53_record.record : k => v.name }
}

output "route53_record_fqdn" {
  description = "fqdn built using the zone domain and name"
  value       = { for k, v in aws_route53_record.record : k => v.fqdn }
}

// File: variables.tf
variable "zone_id" {
  description = "(Optional) A zone ID to create the records in"
  type        = string
  default     = null
}

variable "zone_name" {
  description = "(Required) The name of the hosted zone(s). To create multiple zones at once, pass a list of names [\"zone1\", \"zone2\"]."
  type        = any
  default     = null
}

variable "records" {
  description = "(Optional) A list of records to create in the Hosted Zone."
  type = list(object({
    name            = string
    type            = string
    ttl             = optional(number)       # required for non-alias records
    records         = optional(list(string)) # required for non-alias records
    zone_id         = optional(string)
    set_identifier  = optional(string)
    health_check_id = optional(string)

    alias = optional(object({
      name                   = string
      zone_id                = string
      evaluate_target_health = bool
    }))

    failover_routing_policy = optional(object({
      type = string
    }))

    geolocation_routing_policy = optional(object({
      continent   = optional(string)
      country     = optional(string)
      subdivision = optional(string)
    }))

    latency_routing_policy = optional(object({
      region = string
    }))

    weighted_routing_policy = optional(object({
      weight = number
    }))

    multivalue_answer_routing_policy = optional(bool)
  }))
  default = []
}

variable "allow_overwrite" {
  description = "(Optional) Default allow_overwrite value valid for all record sets."
  type        = bool
  default     = false
}

variable "default_ttl" {
  description = "(Optional) The default TTL ( Time to Live ) in seconds that will be used for all records that support the ttl parameter. Will be overwritten by the records ttl parameter if set."
  type        = number
  default     = 3600
}
variable "force_destroy" {
  description = "(Optional) Whether to force destroy all records (possibly managed outside of Terraform) in the zone when destroying the zone."
  type        = bool
  default     = false
}

variable "vpc_ids" {
  description = "(Optional) A list of IDs of VPCs to associate with a private hosted zone. Conflicts with the delegation_set_id."
  type        = list(string)
  default     = []
}

variable "terragrunt_tags" {
  description = "tags added by terragrunt automatically"
  type        = map(string)
  default     = {}
}

variable "create_phz" {
  description = "(Optional) Defines whether to create the PHZ or not. Useful in consul env's where resolver rule is preferred. (Default: False)"
  type        = bool
  default     = false
}

variable "enable_dnssec" {
  description = "(Optional) Defines whether to create the DNSSEC keys or not for public hosted zones. (Default: True)"
  type        = bool
  default     = true
}

// File: versions.tf
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.60"
    }
  }
}

// File: main.tf
locals {
  principals_readonly_access_non_empty = length(var.principals_readonly_access) > 0 ? true : false
  principals_full_access_non_empty     = length(var.principals_full_access) > 0 ? true : false
  ecr_need_policy                      = length(var.principals_full_access) + length(var.principals_readonly_access) > 0 ? true : false
}

################################################################################
# Private Repository
################################################################################
resource "aws_ecr_repository" "this" {
  count                = var.enable && var.enable_private_ecr ? 1 : 0
  name                 = var.repository_name
  tags                 = var.tags
  image_tag_mutability = var.image_tag_mutability
  force_delete         = var.repository_force_delete

  encryption_configuration {
    encryption_type = var.encryption_type
    kms_key         = var.kms_key
  }

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  dynamic "timeouts" {
    for_each = var.timeouts
    content {
      delete = lookup(timeouts.value.delete, null)
    }
  }
}

resource "aws_ecr_lifecycle_policy" "private" {
  count      = var.enable && var.enable_private_ecr ? 1 : 0
  repository = join("", aws_ecr_repository.this[*].name)

  policy = <<EOF
{
  "rules": [
    {
      "rulePriority": 1,
      "description": "Remove untagged images",
      "selection": {
        "tagStatus": "untagged",
        "countType": "imageCountMoreThan",
        "countNumber": ${var.max_untagged_image_count}
      },
      "action": {
        "type": "expire"
      }
    },
    {
      "rulePriority": 2,
      "description": "Rotate images when reach ${var.max_image_count} images stored",
      "selection": {
        "tagStatus": "any",
        "countType": "imageCountMoreThan",
        "countNumber": ${var.max_image_count}
      },
      "action": {
        "type": "expire"
      }
    }
  ]
}
EOF
}

################################################################################
# Public Repository
################################################################################
resource "aws_ecrpublic_repository" "this" {
  count = var.enable && var.enable_public_ecr ? 1 : 0

  repository_name = var.repository_name

  dynamic "catalog_data" {
    for_each = length(var.public_repository_catalog_data) > 0 ? [var.public_repository_catalog_data] : []

    content {
      about_text        = try(catalog_data.value.about_text, null)
      architectures     = try(catalog_data.value.architectures, null)
      description       = try(catalog_data.value.description, null)
      logo_image_blob   = try(catalog_data.value.logo_image_blob, null)
      operating_systems = try(catalog_data.value.operating_systems, null)
      usage_text        = try(catalog_data.value.usage_text, null)
    }
  }
  tags = var.tags
}

################################################################################
# Private ECR IAM Policies
################################################################################
data "aws_iam_policy_document" "resource_readonly_access_private" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "ReadonlyAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_readonly_access
    }

    actions = [
      "ecr:GetRegistryPolicy",
      "ecr:DescribeImageScanFindings",
      "ecr:GetLifecyclePolicyPreview",
      "ecr:GetDownloadUrlForLayer",
      "ecr:DescribeRegistry",
      "ecr:DescribePullThroughCacheRules",
      "ecr:DescribeImageReplicationStatus",
      "ecr:GetAuthorizationToken",
      "ecr:ListTagsForResource",
      "ecr:ListImages",
      "ecr:BatchGetRepositoryScanningConfiguration",
      "ecr:GetRegistryScanningConfiguration",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetRepositoryPolicy",
      "ecr:GetLifecyclePolicy",
    ]
  }
}

data "aws_iam_policy_document" "resource_full_access_private" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "FullAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_full_access
    }

    actions = [
      "ecr:*"
    ]
  }
}

data "aws_iam_policy_document" "resource_private" {
  count                     = var.enable ? 1 : 0
  source_policy_documents   = [local.principals_readonly_access_non_empty ? join("", data.aws_iam_policy_document.resource_readonly_access_private[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
  override_policy_documents = [local.principals_full_access_non_empty ? join("", data.aws_iam_policy_document.resource_full_access_private[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
}

resource "aws_ecr_repository_policy" "private" {
  count      = var.enable && local.ecr_need_policy && var.enable_private_ecr ? 1 : 0
  repository = join("", aws_ecr_repository.this[*].name)
  policy     = join("", data.aws_iam_policy_document.resource_private[*].json)
}

################################################################################
# Public ECR IAM Policies
################################################################################
data "aws_iam_policy_document" "resource_readonly_access_public" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "ReadonlyAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_readonly_access
    }

    actions = [
      "ecr-public:DescribeImageTags",
      "ecr-public:DescribeImages",
      "ecr-public:DescribeRepositories",
      "ecr-public:GetAuthorizationToken",
      "ecr-public:DescribeRegistries",
      "ecr-public:GetRepositoryCatalogData",
      "ecr-public:GetRegistryCatalogData",
      "ecr-public:ListTagsForResource",
      "ecr-public:GetRepositoryPolicy",
      "ecr-public:BatchCheckLayerAvailability",
    ]
  }
}

data "aws_iam_policy_document" "resource_full_access_public" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "FullAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_full_access
    }

    actions = [
      "ecr-public:*"
    ]
  }
}


data "aws_iam_policy_document" "resource_public" {
  count                     = var.enable ? 1 : 0
  source_policy_documents   = [local.principals_readonly_access_non_empty ? join("", data.aws_iam_policy_document.resource_readonly_access_public[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
  override_policy_documents = [local.principals_full_access_non_empty ? join("", data.aws_iam_policy_document.resource_full_access_public[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
}

resource "aws_ecr_repository_policy" "public" {
  count      = var.enable && local.ecr_need_policy && var.enable_public_ecr ? 1 : 0
  repository = join("", aws_ecrpublic_repository.this[*].repository_name)
  policy     = join("", data.aws_iam_policy_document.resource_public[*].json)
}

data "aws_iam_policy_document" "empty" {
  count = var.enable ? 1 : 0
}

// File: outputs.tf
output "registry_id" {
  value       = try(aws_ecr_repository.this[0].registry_id, aws_ecrpublic_repository.this[0].registry_id, null)
  description = "Registry ID."
}

output "registry_url" {
  value       = try(aws_ecr_repository.this[0].repository_url, aws_ecrpublic_repository.this[0].repository_uri, null)
  description = "Registry URL."
}

output "repository_name" {
  value       = join("", aws_ecr_repository.this[*].name)
  description = "Registry name."
}

output "arn" {
  value       = try(aws_ecr_repository.this[0].arn, aws_ecrpublic_repository.this[0].arn, null)
  description = "Registry ARN."
}

// File: variables.tf
variable "enable" {
  type        = bool
  default     = true
  description = "Set to false to prevent the module from creating any resources."
}

variable "repository_name" {
  type        = string
  default     = ""
  description = <<-EOT
The name to use for the repository.
The repository name may be specified on its own (such as `nginx-web-app`) or it can be prepended with a namespace to group the repository into a category (such as `project-a/nginx-web-app`).
If you don't specify a name, CFNlong generates a unique physical ID and uses that ID for the repository name. For more information, see Name type.
The repository name must start with a letter and can only contain lowercase letters, numbers, hyphens, underscores, and forward slashes.
If you specify a name, you cannot perform updates that require replacement of this resource.
You can perform updates that require no or some interruption.
If you must replace the resource, specify a new name.
  EOT
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags map for resources"
}

variable "enable_private_ecr" {
  type        = bool
  default     = false
  description = "Set to false to prevent the module from creating any resources."
}

variable "max_image_count" {
  type        = number
  default     = 10
  description = "How many Docker Image versions AWS ECR will store."
}

variable "max_untagged_image_count" {
  type        = number
  default     = 1
  description = "How many Untagged Docker Image versions AWS ECR will store."
}

variable "principals_readonly_access" {
  type        = list(any)
  default     = []
  description = "Principal ARN to provide with readonly access to the ECR."
}

variable "principals_full_access" {
  type        = list(any)
  description = "Principal ARN to provide with full access to the ECR."
  default     = []
}

variable "scan_on_push" {
  type        = bool
  description = "Indicates whether images are scanned after being pushed to the repository (true) or not scanned (false)."
  default     = true
}

variable "image_tag_mutability" {
  type        = string
  default     = "IMMUTABLE"
  description = "The tag mutability setting for the repository."
}

variable "repository_force_delete" {
  type        = bool
  default     = false
  description = "If `true`, will delete the repository even if it contains images. Defaults to `false`"
}

variable "encryption_type" {
  type        = string
  default     = "KMS"
  description = "The encryption type for the repository. Must be one of: `KMS` or `AES256`. Defaults to `AES256`"
}

variable "kms_key" {
  type        = string
  default     = null
  description = "The ARN of the KMS key to use when encryption_type is `KMS`. If not specified, uses the default AWS managed key for ECR"
}

# Timeouts
variable "timeouts" {
  type        = map(any)
  default     = {}
  description = "Timeouts map."
}

# Public Repository
variable "enable_public_ecr" {
  type        = bool
  default     = false
  description = "Set to false to prevent the module from creating any resources."
}

variable "public_repository_catalog_data" {
  description = "Catalog data configuration for the repository"
  type        = any
  default     = {}
}

// File: versions.tf
terraform {
  required_providers {

    aws = {
      source  = "hashicorp/aws"
      version = ">= 2.0.0"
    }
  }

  required_version = ">= 0.14"
}

// File: main.tf
provider "aws" {
  region="us-east-1"

}

#testing
#Generating of VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support = true

  tags={
    Name="development-be-vpc"
  }
}

#Generating of a Public Subnet
resource "aws_subnet" "public_subnet" {

  vpc_id = aws_vpc.main.id
  cidr_block = var.subnet_public_cidrs
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = true


  tags={
    Name="development-be-public-subnet"
  }
}

#Generating of Private Subnet
resource "aws_subnet" "private_subnet" {

  vpc_id = aws_vpc.main.id
  cidr_block = var.subnet_private_cidrs
   availability_zone = "us-east-1b"

  tags={
    Name="development-be-private-subnet"
  }
}

#Generating of public Route Table
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "development-be-public-rt"
  }

}

#Association of Route Table with Public Subnet 
resource "aws_route_table_association" "public_subnets_asso" {

  subnet_id = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id

}

#Generating Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags={
    Name="development-be-ig"
  }

}

#Generating of SSH and HTTP Secuirty Group
resource "aws_security_group" "sg_grp" {
  vpc_id = aws_vpc.main.id
  name   = "http_access"
  description = "sg for backend development"

  #This is For SSH
  ingress {
    description = "Allow SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  #This is For Http
  ingress {
    description = "Http Acess"
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name= "development-be-sg"
  }

}

// File: output.tf
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public_subnet.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private_subnet.id
}

// File: variable.tf
variable "vpc_cidr" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}


variable "subnet_public_cidrs" {
  type=string
  description = "Public Subnet CIDR values"
  default = "10.0.1.0/24"

}

variable "subnet_private_cidrs" {
  type=string
  description = "Private Subnet CIDR values"
  default =  "10.0.2.0/24" 


}

variable "availability_zone" {
  description = "Availability Zone for the development environment"
  type        = string
  default     = "us-east-1a"  # Update as needed
}

// File: acm_certificate.tf
#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate" {
  count = var.enable_acm_certificate && !var.enable_acm_certificate_private_ca && !var.enable_import_existing_certificate ? 1 : 0

  domain_name       = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
  validation_method = upper(var.acm_certificate_validation_method)

  subject_alternative_names = var.acm_certificate_subject_alternative_names

  dynamic "options" {
    iterator = options
    for_each = var.acm_certificate_options

    content {
      certificate_transparency_logging_preference = lookup(options.value, "certificate_transparency_logging_preference", null)
    }
  }

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate for private CA
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate_private_ca" {
  count = var.enable_acm_certificate_private_ca && !var.enable_acm_certificate && !var.enable_import_existing_certificate ? 1 : 0

  domain_name               = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
  certificate_authority_arn = var.acm_certificate_certificate_authority_arn

  subject_alternative_names = var.acm_certificate_subject_alternative_names

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate for exististing certificate
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate_exist" {
  count = var.enable_import_existing_certificate && !var.enable_acm_certificate && !var.enable_acm_certificate_private_ca ? 1 : 0

  private_key       = var.acm_certificate_private_key
  certificate_body  = var.acm_certificate_certificate_body
  certificate_chain = var.acm_certificate_certificate_chain

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acm_certificate_validation.tf
#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate validation
#---------------------------------------------------
resource "aws_acm_certificate_validation" "acm_certificate_validation" {
  count = var.enable_acm_certificate_validation ? 1 : 0

  certificate_arn = var.acm_certificate_validation_certificate_arn

  validation_record_fqdns = var.acm_certificate_validation_record_fqdns

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.acm_certificate_validation_timeouts)) > 0 ? [var.acm_certificate_validation_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acmpca_certificate_authority.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (ACM PCA Certificate Authorities)
#---------------------------------------------------
resource "aws_acmpca_certificate_authority" "acmpca_certificate_authority" {
  count = var.enable_acmpca_certificate_authority ? 1 : 0

  enabled = var.acmpca_certificate_authority_enabled

  permanent_deletion_time_in_days = var.acmpca_certificate_authority_permanent_deletion_time_in_days

  dynamic "certificate_authority_configuration" {
    iterator = certificate_authority_configuration
    for_each = length(keys(var.acmpca_certificate_authority_certificate_authority_configuration)) > 0 ? [var.acmpca_certificate_authority_certificate_authority_configuration] : []

    content {
      key_algorithm     = lookup(certificate_authority_configuration.value, "key_algorithm", null)
      signing_algorithm = lookup(certificate_authority_configuration.value, "signing_algorithm", null)

      dynamic "subject" {
        iterator = subject
        for_each = length(keys(lookup(certificate_authority_configuration.value, "subject", {}))) > 0 ? [lookup(certificate_authority_configuration.value, "subject", {})] : []

        content {
          common_name                  = lookup(subject.value, "common_name", null)
          country                      = lookup(subject.value, "country", null)
          distinguished_name_qualifier = lookup(subject.value, "distinguished_name_qualifier", null)
          generation_qualifier         = lookup(subject.value, "generation_qualifier", null)
          given_name                   = lookup(subject.value, "given_name", null)
          initials                     = lookup(subject.value, "initials", null)
          locality                     = lookup(subject.value, "locality", null)
          organization                 = lookup(subject.value, "organization", null)
          organizational_unit          = lookup(subject.value, "organizational_unit", null)
          pseudonym                    = lookup(subject.value, "pseudonym", null)
          state                        = lookup(subject.value, "state", null)
          surname                      = lookup(subject.value, "surname", null)
          title                        = lookup(subject.value, "title", null)
        }
      }
    }
  }

  dynamic "revocation_configuration" {
    iterator = revocation_configuration
    for_each = length(keys(var.acmpca_certificate_authority_revocation_configuration)) > 0 ? [var.acmpca_certificate_authority_revocation_configuration] : []

    content {
      dynamic "crl_configuration" {
        iterator = crl_configuration
        for_each = length(keys(lookup(revocation_configuration.value, "crl_configuration", {}))) > 0 ? [lookup(revocation_configuration.value, "crl_configuration", {})] : []

        content {
          expiration_in_days = lookup(crl_configuration.value, "expiration_in_days", null)

          custom_cname   = lookup(crl_configuration.value, "custom_cname", null)
          enabled        = lookup(crl_configuration.value, "enabled", null)
          s3_bucket_name = lookup(crl_configuration.value, "s3_bucket_name", null)
        }
      }
    }
  }

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.acmpca_certificate_authority_timeouts)) > 0 ? [var.acmpca_certificate_authority_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
    }
  }

  tags = merge(
    {
      Name = var.acmpca_certificate_authority_name != "" ? var.acmpca_certificate_authority_name : "${lower(var.name)}-acmpca-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

