# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_permission

// File: acmpca_policy.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (policy)
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_policy

// File: outputs.tf
#---------------------------------------------------
# acm certificate
#---------------------------------------------------
output "aws_acm_certificate_id" {
  description = "The ARN of the certificate"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.id,
    aws_acm_certificate.acm_certificate_private_ca.*.id,
    aws_acm_certificate.acm_certificate_exist.*.id,
    [""]),
  0)
}

output "aws_acm_certificate_arn" {
  description = "The ARN of the certificate"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.arn,
    aws_acm_certificate.acm_certificate_private_ca.*.arn,
    aws_acm_certificate.acm_certificate_exist.*.arn,
    [""]),
  0)
}

output "aws_acm_certificate_domain_name" {
  description = "The domain name for which the certificate is issued"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.domain_name,
    aws_acm_certificate.acm_certificate_private_ca.*.domain_name,
    aws_acm_certificate.acm_certificate_exist.*.domain_name,
    [""]),
  0)
}

output "aws_acm_certificate_domain_validation_options" {
  description = "A list of attributes to feed into other resources to complete certificate validation. Can have more than one element, e.g. if SANs are defined. Only set if DNS-validation was used"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.domain_validation_options,
    aws_acm_certificate.acm_certificate_private_ca.*.domain_validation_options,
    aws_acm_certificate.acm_certificate_exist.*.domain_validation_options,
    [""]),
  0)
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate validation
#---------------------------------------------------
output "acm_certificate_validation_id" {
  description = "The time at which the certificate was issued"
  value       = element(concat(aws_acm_certificate_validation.acm_certificate_validation.*.id, [""]), 0)
}

#---------------------------------------------------
# acmpca
#---------------------------------------------------
output "acmpca_certificate_authority_id" {
  description = "Amazon Resource Name (ARN) of the certificate authority."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.id, [""]), 0)
}

output "acmpca_certificate_authority_arn" {
  description = "Amazon Resource Name (ARN) of the certificate authority."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.arn, [""]), 0)
}

output "acmpca_certificate_authority_certificate" {
  description = "Base64-encoded certificate authority (CA) certificate. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.certificate, [""]), 0)
}

output "acmpca_certificate_authority_certificate_chain" {
  description = "Base64-encoded certificate chain that includes any intermediate certificates and chains up to root on-premises certificate that you used to sign your private CA certificate. The chain does not include your private CA certificate. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.certificate_chain, [""]), 0)
}

output "acmpca_certificate_authority_certificate_signing_request" {
  description = "The base64 PEM-encoded certificate signing request (CSR) for your private CA certificate."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.certificate_signing_request, [""]), 0)
}

output "acmpca_certificate_authority_not_after" {
  description = "Date and time after which the certificate authority is not valid. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.not_after, [""]), 0)
}

output "acmpca_certificate_authority_not_before" {
  description = "Date and time before which the certificate authority is not valid. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.not_before, [""]), 0)
}

output "acmpca_certificate_authority_serial" {
  description = "Serial number of the certificate authority. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.serial, [""]), 0)
}

output "acmpca_certificate_authority_status" {
  description = "Status of the certificate authority."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.status, [""]), 0)
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "Add additional tags"
  default     = {}
}

#-----------------------------------------------------------
# ACM
#-----------------------------------------------------------
variable "enable_acm_certificate" {
  description = "Enable acm certificate usage"
  default     = false
}

variable "acm_certificate_domain_name" {
  description = "(Required) A domain name for which the certificate should be issued"
  default     = ""
}

variable "acm_certificate_validation_method" {
  description = "(Required) Which method to use for validation. DNS or EMAIL are valid, NONE can be used for certificates that were imported into ACM and then into Terraform."
  default     = "DNS"
}

variable "acm_certificate_subject_alternative_names" {
  description = "(Optional) A list of domains that should be SANs in the issued certificate"
  default     = []
}

variable "acm_certificate_options" {
  description = "(Optional) Configuration block used to set certificate options."
  default     = []
}

variable "enable_import_existing_certificate" {
  description = "Enable import existing certificate usage"
  default     = false
}

variable "acm_certificate_private_key" {
  description = "(Required) The certificate's PEM-formatted private key"
  default     = ""
}

variable "acm_certificate_certificate_body" {
  description = "(Required) The certificate's PEM-formatted public key"
  default     = ""
}

variable "acm_certificate_certificate_chain" {
  description = "(Optional) The certificate's PEM-formatted chain"
  default     = null
}

variable "enable_acm_certificate_private_ca" {
  description = "Enable acm certificate private CA usage"
  default     = false
}

variable "acm_certificate_certificate_authority_arn" {
  description = "ARN of an ACMPCA"
  default     = null
}

#-----------------------------------------------------------
# acm_certificate_validation
#-----------------------------------------------------------
variable "enable_acm_certificate_validation" {
  description = "Enable to use acm certificate validation"
  default     = false
}

variable "acm_certificate_validation_certificate_arn" {
  description = "(Required) The ARN of the certificate that is being validated."
  default     = ""
}

variable "acm_certificate_validation_record_fqdns" {
  description = "(Optional) List of FQDNs that implement the validation. Only valid for DNS validation method ACM certificates. If this is set, the resource can implement additional sanity checks and has an explicit dependency on the resource that is implementing the validation"
  default     = null
}

variable "acm_certificate_validation_timeouts" {
  description = "Set timeouts for acm certificate validation"
  default     = {}
}

#-----------------------------------------------------------
# acmpca_certificate_authority
#-----------------------------------------------------------
variable "enable_acmpca_certificate_authority" {
  description = "Enable to use acmpca certificate authority"
  default     = false
}

variable "acmpca_certificate_authority_name" {
  description = "Set cert name for acmpca"
  default     = ""
}

variable "acmpca_certificate_authority_enabled" {
  description = "(Optional) Whether the certificate authority is enabled or disabled. Defaults to true."
  default     = true
}

variable "acmpca_certificate_authority_certificate_authority_configuration" {
  description = "(Required) Nested argument containing algorithms and certificate subject information."
  default     = {}
}

variable "acmpca_certificate_authority_permanent_deletion_time_in_days" {
  description = "(Optional) The number of days to make a CA restorable after it has been deleted, must be between 7 to 30 days, with default to 30 days."
  default     = null
}

variable "acmpca_certificate_authority_revocation_configuration" {
  description = "(Optional) Nested argument containing revocation configuration."
  default     = {}
}

variable "acmpca_certificate_authority_timeouts" {
  description = "Set timeouts for acmpca"
  default     = {}
}

// File: main.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

data "aws_caller_identity" "current" {}

################################################################################
# Topic
################################################################################

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = var.use_name_prefix ? null : var.name
  name_prefix = var.use_name_prefix ? var.name : null

  application_failure_feedback_role_arn    = try(var.application_feedback.failure_role_arn, null)
  application_success_feedback_role_arn    = try(var.application_feedback.success_role_arn, null)
  application_success_feedback_sample_rate = try(var.application_feedback.success_sample_rate, null)

  content_based_deduplication = var.content_based_deduplication
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config

  firehose_failure_feedback_role_arn    = try(var.firehose_feedback.failure_role_arn, null)
  firehose_success_feedback_role_arn    = try(var.firehose_feedback.success_role_arn, null)
  firehose_success_feedback_sample_rate = try(var.firehose_feedback.success_sample_rate, null)

  http_failure_feedback_role_arn    = try(var.http_feedback.failure_role_arn, null)
  http_success_feedback_role_arn    = try(var.http_feedback.success_role_arn, null)
  http_success_feedback_sample_rate = try(var.http_feedback.success_sample_rate, null)

  kms_master_key_id = var.kms_master_key_id

  lambda_failure_feedback_role_arn    = try(var.lambda_feedback.failure_role_arn, null)
  lambda_success_feedback_role_arn    = try(var.lambda_feedback.success_role_arn, null)
  lambda_success_feedback_sample_rate = try(var.lambda_feedback.success_sample_rate, null)

  policy = var.create_topic_policy ? null : var.topic_policy

  sqs_failure_feedback_role_arn    = try(var.sqs_feedback.failure_role_arn, null)
  sqs_success_feedback_role_arn    = try(var.sqs_feedback.success_role_arn, null)
  sqs_success_feedback_sample_rate = try(var.sqs_feedback.success_sample_rate, null)

  tags = var.tags
}

################################################################################
# Topic Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid = "__default_statement_ID"
      actions = [
        "sns:AddPermission",
        "sns:DeleteTopic",
        "sns:GetTopicAttributes",
        "sns:ListSubscriptionsByTopic",
        "sns:Publish",
        "sns:Receive",
        "sns:RemovePermission",
        "sns:SetTopicAttributes",
        "sns:Subscribe",
      ]
      effect    = "Allow"
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        values   = [data.aws_caller_identity.current.account_id]
        variable = "AWS:SourceOwner"
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid         = try(statement.value.sid, statement.key)
      actions     = try(statement.value.actions, null)
      not_actions = try(statement.value.not_actions, null)
      effect      = try(statement.value.effect, null)
      # This avoids the chicken vs the egg scenario since its embedded and can reference the topic
      resources     = try(statement.value.resources, [aws_sns_topic.this[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Subscription(s)
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = { for k, v in var.subscriptions : k => v if var.create && var.create_subscription }

  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  delivery_policy                 = try(each.value.delivery_policy, null)
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = try(each.value.endpoint_auto_confirms, null)
  filter_policy                   = try(each.value.filter_policy, null)
  filter_policy_scope             = try(each.value.filter_policy_scope, null)
  protocol                        = each.value.protocol
  raw_message_delivery            = try(each.value.raw_message_delivery, null)
  redrive_policy                  = try(each.value.redrive_policy, null)
  subscription_role_arn           = try(each.value.subscription_role_arn, null)
  topic_arn                       = aws_sns_topic.this[0].arn
}

################################################################################
# Data Protection Policy
################################################################################

resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

// File: outputs.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

################################################################################
# Topic
################################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic, as a more obvious property (clone of id)"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS Account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

################################################################################
# Subscription(s)
################################################################################

output "subscriptions" {
  description = "Map of subscriptions created and their attributes"
  value       = aws_sns_topic_subscription.this
}

// File: variables.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

variable "create" {
  description = "Determines whether resources will be created (affects all resources)"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Topic
################################################################################

variable "name" {
  description = "The name of the SNS topic to create"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether `name` is used as a prefix"
  type        = bool
  default     = false
}

variable "application_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # application_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "content_based_deduplication" {
  description = "Boolean indicating whether or not to enable content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "The SNS delivery policy"
  type        = string
  default     = null
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

variable "firehose_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # firehose_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "http_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # http_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK"
  type        = string
  default     = null
}

variable "lambda_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # lambda_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "topic_policy" {
  description = "An externally created fully-formed AWS policy as JSON"
  type        = string
  default     = null
}

variable "sqs_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # sqs_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "signature_version" {
  description = "If SignatureVersion should be 1 (SHA1) or 2 (SHA256). The signature version corresponds to the hashing algorithm used while creating the signature of the notifications, subscription confirmations, or unsubscribe confirmation messages sent by Amazon SNS."
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: PassThrough, Active."
  type        = string
  default     = null
}

################################################################################
# Topic Policy
################################################################################

variable "create_topic_policy" {
  description = "Determines whether an SNS topic policy is created"
  type        = bool
  default     = true
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. In merging, statements with non-blank `sid`s will override statements with the same `sid`"
  type        = list(string)
  default     = []
}

variable "enable_default_topic_policy" {
  description = "Specifies whether to enable the default topic policy. Defaults to `true`"
  type        = bool
  default     = true
}

variable "topic_policy_statements" {
  description = "A map of IAM policy [statements](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/data-sources/iam_policy_document#statement) for custom permission usage"
  type        = any
  default     = {}
}

################################################################################
# Subscription(s)
################################################################################

variable "create_subscription" {
  description = "Determines whether an SNS subscription is created"
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "A map of subscription definitions to create"
  type        = any
  default     = {}
}

################################################################################
# Data Protection Policy
################################################################################

variable "data_protection_policy" {
  description = "A map of data protection policy statements"
  type        = string
  default     = null
}

// File: versions.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.62"
    }
  }
}

// File: locals.tf
locals {
  create_account = var.name != null && var.email != null ? true : false
}

// File: main.tf
resource "aws_organizations_organization" "main" {
  count                         = var.create_organization ? 1 : 0
  aws_service_access_principals = var.aws_service_access_principals
  feature_set                   = var.feature_set
  enabled_policy_types          = var.enabled_policy_types
}

resource "aws_organizations_account" "main" {
  count                      = local.create_account ? 1 : 0
  name                       = var.name
  email                      = var.email
  close_on_deletion          = var.close_on_deletion
  create_govcloud            = var.create_govcloud
  iam_user_access_to_billing = var.iam_user_access_to_billing
  parent_id                  = var.parent_id
  role_name                  = var.role_name
  tags                       = var.tags

  lifecycle {
    ignore_changes = [role_name]
  }
}

resource "aws_organizations_delegated_administrator" "main" {
  count             = var.make_delegated_administrator ? 1 : 0
  account_id        = aws_organizations_account.main[0].id
  service_principal = var.administrator_service_principal
  depends_on        = [aws_organizations_organization.main]
}

resource "aws_organizations_organizational_unit" "main" {
  count     = var.ou_name != null ? 1 : 0
  name      = var.ou_name
  parent_id = var.ou_parent_id
  tags      = var.tags
}

// File: outputs.tf
output "arn" {
  value       = aws_organizations_account.main.*.arn
  description = "The ARN for this account."
}

output "govcloud_id" {
  value       = aws_organizations_account.main.*.govcloud_id
  description = "ID for a GovCloud account created with the account."
}

output "id" {
  value       = aws_organizations_account.main.*.id
  description = "The AWS account id"
}

output "tags_all" {
  value       = aws_organizations_account.main.*.tags_all
  description = "A map of tags assigned to the resource"
}

output "administrator_account_id" {
  value       = aws_organizations_delegated_administrator.main.*.id
  description = "The unique identifier (ID) of the delegated administrator."
}

output "administrator_arn" {
  value       = aws_organizations_delegated_administrator.main.*.arn
  description = "The Amazon Resource Name (ARN) of the delegated administrator's account."
}

output "administrator_delegation_enabled_date" {
  value       = aws_organizations_delegated_administrator.main.*.delegation_enabled_date
  description = "The date when the account was made a delegated administrator."
}

output "administrator_email" {
  value       = aws_organizations_delegated_administrator.main.*.email
  description = "The email address that is associated with the delegated administrator's AWS account."
}

output "administrator_joined_method" {
  value       = aws_organizations_delegated_administrator.main.*.joined_method
  description = "The method by which the delegated administrator's account joined the organization."
}

output "administrator_joined_timestamp" {
  value       = aws_organizations_delegated_administrator.main.*.joined_timestamp
  description = "The date when the delegated administrator's account became a part of the organization."
}

output "administrator_name" {
  value       = aws_organizations_delegated_administrator.main.*.name
