// File: versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.33.0"
    }
  }
}

// File: kms_alias.tf
#---------------------------------------------------
# AWS KMS alias
#---------------------------------------------------
resource "aws_kms_alias" "kms_alias" {
  count = var.enable_kms_alias ? 1 : 0

  name          = var.kms_alias_name
  name_prefix   = var.kms_alias_name_prefix
  target_key_id = var.kms_alias_target_key_id != "" ? var.kms_alias_target_key_id : (var.enable_kms_key ? element(concat(aws_kms_key.kms_key.*.key_id, [""]), 0) : null)

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_kms_key.kms_key
  ]
}

// File: kms_ciphertext.tf
#---------------------------------------------------
# KSM ciphertext
#---------------------------------------------------
resource "aws_kms_ciphertext" "kms_ciphertext" {
  count = var.enable_kms_ciphertext ? 1 : 0

  key_id    = var.kms_ciphertext_key_id != "" ? var.kms_ciphertext_key_id : (var.enable_kms_key ? element(aws_kms_key.kms_key.*.key_id, 0) : null)
  plaintext = var.kms_ciphertext_plaintext

  context = var.kms_ciphertext_context

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: kms_external_key.tf
#---------------------------------------------------
# KSM external key
#---------------------------------------------------
resource "aws_kms_external_key" "kms_external_key" {
  count = var.enable_kms_external_key ? 1 : 0

  description             = var.kms_external_key_description
  enabled                 = var.kms_external_key_enabled
  policy                  = var.kms_external_key_policy
  valid_to                = var.kms_external_key_valid_to
  deletion_window_in_days = var.kms_external_key_deletion_window_in_days
  key_material_base64     = var.kms_external_key_key_material_base64

  tags = merge(
    {
      Name = var.kms_external_key_name != "" ? var.kms_external_key_name : "${lower(var.name)}-kms-external-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: kms_grant.tf
#---------------------------------------------------
# KSM grant
#---------------------------------------------------
resource "aws_kms_grant" "kms_grant" {
  count = var.enable_kms_grant ? 1 : 0

  name              = var.kms_grant_name != "" ? var.kms_grant_name : "${var.name}-kms-grant-${var.environment}"
  key_id            = var.kms_grant_key_id != "" ? var.kms_grant_key_id : (var.enable_kms_key ? element(aws_kms_key.kms_key.*.key_id, 0) : null)
  grantee_principal = var.kms_grant_grantee_principal
  operations        = var.kms_grant_operations

  retiring_principal    = var.kms_grant_retiring_principal
  grant_creation_tokens = var.kms_grant_grant_creation_tokens
  retire_on_delete      = var.kms_grant_retire_on_delete

  dynamic "constraints" {
    iterator = constraints
    for_each = var.kms_grant_constraints

    content {
      encryption_context_equals = lookup(constraints.value, "encryption_context_equals", null)
      encryption_context_subset = lookup(constraints.value, "encryption_context_subset", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_kms_key.kms_key
  ]
}

// File: kms_key.tf
#---------------------------------------------------
# AWS KMS key
#---------------------------------------------------
resource "aws_kms_key" "kms_key" {
  count = var.enable_kms_key ? 1 : 0

  description             = var.kms_key_description
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  key_usage               = upper(var.kms_key_key_usage)

  is_enabled               = var.kms_key_is_enabled
  policy                   = var.kms_key_policy
  enable_key_rotation      = var.kms_key_enable_key_rotation
  customer_master_key_spec = var.kms_key_customer_master_key_spec

  tags = merge(
    {
      Name = var.kms_key_name != "" ? var.kms_key_name : "${lower(var.name)}-kms-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: outputs.tf
#---------------------------------------------------
# AWS KMS key
#---------------------------------------------------
output "kms_key_arn" {
  description = "The globally unique identifier for the key."
  value       = element(concat(aws_kms_key.kms_key.*.arn, [""]), 0)
}

output "kms_key_id" {
  description = "The globally unique identifier for the key."
  value       = element(concat(aws_kms_key.kms_key.*.key_id, [""]), 0)
}

#---------------------------------------------------
# AWS KMS alias
#---------------------------------------------------
output "kms_alias_id" {
  description = "ID of KMS alias"
  value       = element(concat(aws_kms_alias.kms_alias.*.id, [""]), 0)
}

output "kms_alias_arn" {
  description = "The Amazon Resource Name (ARN) of the key alias."
  value       = element(concat(aws_kms_alias.kms_alias.*.arn, [""]), 0)
}

output "kms_alias_target_key_arn" {
  description = "The Amazon Resource Name (ARN) of the target key identifier."
  value       = element(concat(aws_kms_alias.kms_alias.*.target_key_arn, [""]), 0)
}

#---------------------------------------------------
# KSM grant
#---------------------------------------------------
output "kms_grant_id" {
  description = "ID of KMS grant"
  value       = element(concat(aws_kms_grant.kms_grant.*.id, [""]), 0)
}

output "kms_grant_grant_id" {
  description = "The unique identifier for the grant."
  value       = element(concat(aws_kms_grant.kms_grant.*.grant_id, [""]), 0)
}

output "kms_grant_token" {
  description = "The grant token for the created grant. For more information, see Grant Tokens."
  value       = element(concat(aws_kms_grant.kms_grant.*.grant_token, [""]), 0)
}

#---------------------------------------------------
# KSM external key
#---------------------------------------------------
output "kms_external_key_id" {
  description = "The unique identifier for the key."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.id, [""]), 0)
}

output "kms_external_key_arn" {
  description = "The Amazon Resource Name (ARN) of the key."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.arn, [""]), 0)
}

output "kms_external_key_expiration_model" {
  description = "Whether the key material expires. Empty when pending key material import, otherwise KEY_MATERIAL_EXPIRES or KEY_MATERIAL_DOES_NOT_EXPIRE."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.expiration_model, [""]), 0)
}

output "kms_external_key_state" {
  description = "The state of the CMK."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.key_state, [""]), 0)
}

output "kms_external_key_usage" {
