}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks."
  type        = map(string)
  default     = {}
}

#-----------------------------------------------------------
# KMS key
#-----------------------------------------------------------
variable "enable_kms_key" {
  description = "Allow to create kms_key"
  default     = false
}

variable "kms_key_name" {
  description = "Name for KMS"
  default     = ""
}

variable "kms_key_deletion_window_in_days" {
  description = "Duration in days after which the key is deleted after destruction of the resource, must be between 7 and 30 days. Defaults to 30 days."
  default     = null
}

variable "kms_key_description" {
  description = "The description of the key as viewed in AWS console."
  default     = "This key is used to encrypt <___> AWS service"
}

variable "kms_key_key_usage" {
  description = "Specifies the intended use of the key. Defaults to ENCRYPT_DECRYPT, and only symmetric encryption and decryption are supported"
  default     = "ENCRYPT_DECRYPT"
}

variable "kms_key_is_enabled" {
  description = "Specifies whether the key is enabled. Defaults to true."
  default     = true
}

variable "kms_key_enable_key_rotation" {
  description = "Specifies whether key rotation is enabled. Defaults to false."
  default     = false
}

variable "kms_key_policy" {
  description = "Set policy"
  default     = ""
}

variable "kms_key_customer_master_key_spec" {
  description = "(Optional) Specifies whether the key contains a symmetric key or an asymmetric key pair and the encryption algorithms or signing algorithms that the key supports. Valid values: SYMMETRIC_DEFAULT, RSA_2048, RSA_3072, RSA_4096, ECC_NIST_P256, ECC_NIST_P384, ECC_NIST_P521, or ECC_SECG_P256K1. Defaults to SYMMETRIC_DEFAULT. For help with choosing a key spec, see the AWS KMS Developer Guide."
  default     = null
}

#-----------------------------------------------------------
# KMS alias
#-----------------------------------------------------------
variable "enable_kms_alias" {
  description = "Allow to create kms_alias"
  default     = false
}

variable "kms_alias_name" {
  description = "(Optional) The display name of the alias. The name must start with the word 'alias' followed by a forward slash (alias/)"
  default     = null
}

variable "kms_alias_name_prefix" {
  description = "(Optional) Creates an unique alias beginning with the specified prefix. The name must start with the word 'alias' followed by a forward slash (alias/). Conflicts with name."
  default     = null
}

variable "kms_alias_target_key_id" {
  description = "(Required) Identifier for the key for which the alias is for, can be either an ARN or key_id."
  default     = ""
}

#---------------------------------------------------
# KSM grant
#---------------------------------------------------
variable "enable_kms_grant" {
  description = "Enable kms grant usage"
  default     = false
}

variable "kms_grant_name" {
  description = "(Optional, Forces new resources) A friendly name for identifying the grant."
  default     = ""
}

variable "kms_grant_key_id" {
  description = "The unique identifier for the customer master key (CMK) that the grant applies to. Specify the key ID or the Amazon Resource Name (ARN) of the CMK. To specify a CMK in a different AWS account, you must use the key ARN."
  default     = ""
}

variable "kms_grant_grantee_principal" {
  description = "(Required, Forces new resources) The principal that is given permission to perform the operations that the grant permits in ARN format. Note that due to eventual consistency issues around IAM principals, terraform's state may not always be refreshed to reflect what is true in AWS."
  default     = null
}

variable "kms_grant_operations" {
  description = "(Required, Forces new resources) A list of operations that the grant permits. The permitted values are: Decrypt, Encrypt, GenerateDataKey, GenerateDataKeyWithoutPlaintext, ReEncryptFrom, ReEncryptTo, CreateGrant, RetireGrant, DescribeKey"
  default     = []
}

variable "kms_grant_retiring_principal" {
  description = "(Optional, Forces new resources) The principal that is given permission to retire the grant by using RetireGrant operation in ARN format. Note that due to eventual consistency issues around IAM principals, terraform's state may not always be refreshed to reflect what is true in AWS."
  default     = null
}

variable "kms_grant_grant_creation_tokens" {
  description = "(Optional, Forces new resources) A list of grant tokens to be used when creating the grant. See Grant Tokens for more information about grant tokens."
  default     = null
}

variable "kms_grant_retire_on_delete" {
  description = "(Defaults to false, Forces new resources) If set to false (the default) the grants will be revoked upon deletion, and if set to true the grants will try to be retired upon deletion. Note that retiring grants requires special permissions, hence why we default to revoking grants. See RetireGrant for more information."
  default     = null
}

variable "kms_grant_constraints" {
  description = "(Optional, Forces new resources) A structure that you can use to allow certain operations in the grant only when the desired encryption context is present. For more information about encryption context, see Encryption Context."
  default     = []
}

#---------------------------------------------------
# KSM external key
#---------------------------------------------------
variable "enable_kms_external_key" {
  description = "Enable kms external key usage"
  default     = false
}

variable "kms_external_key_name" {
  description = "Set name for external key"
  default     = ""
}

variable "kms_external_key_description" {
  description = "(Optional) Description of the key."
  default     = null
}

variable "kms_external_key_deletion_window_in_days" {
  description = "(Optional) Duration in days after which the key is deleted after destruction of the resource. Must be between 7 and 30 days. Defaults to 30."
  default     = null
}

variable "kms_external_key_enabled" {
  description = "(Optional) Specifies whether the key is enabled. Keys pending import can only be false. Imported keys default to true unless expired."
  default     = null
}

variable "kms_external_key_key_material_base64" {
  description = "(Optional) Base64 encoded 256-bit symmetric encryption key material to import. The CMK is permanently associated with this key material. The same key material can be reimported, but you cannot import different key material."
  default     = null
}

variable "kms_external_key_policy" {
  description = "(Optional) A key policy JSON document. If you do not provide a key policy, AWS KMS attaches a default key policy to the CMK."
  default     = null
}

variable "kms_external_key_valid_to" {
  description = "(Optional) Time at which the imported key material expires. When the key material expires, AWS KMS deletes the key material and the CMK becomes unusable. If not specified, key material does not expire. Valid values: RFC3339 time string (YYYY-MM-DDTHH:MM:SSZ)"
  default     = null
}

#---------------------------------------------------
# KSM ciphertext
#---------------------------------------------------
variable "enable_kms_ciphertext" {
  description = "Enable kms ciphertext usage"
  default     = false
}

variable "kms_ciphertext_key_id" {
  description = "Globally unique key ID for the customer master key."
  default     = ""
}

variable "kms_ciphertext_plaintext" {
  description = "(Required) Data to be encrypted. Note that this may show up in logs, and it will be stored in the state file."
  default     = null
}

variable "kms_ciphertext_context" {
  description = "(Optional) An optional mapping that makes up the encryption context."
  default     = null
}

// File: main.tf
################################################################################
# Athena workgroups
################################################################################

resource "aws_athena_workgroup" "this" {
  for_each = {
    for k, v in var.workgroups :
    v.name => v if var.create
  }
  name          = each.value.name
  description   = each.value.description
  state         = each.value.enabled ? "ENABLED" : "DISABLED"
  tags          = var.tags
  force_destroy = each.value.force_destroy

  dynamic "configuration" {
    for_each = each.value.configuration != null ? [1] : []
    content {
      bytes_scanned_cutoff_per_query     = each.value.configuration.bytes_scanned_cutoff_per_query
      enforce_workgroup_configuration    = each.value.configuration.enforce_workgroup_configuration
      execution_role                     = each.value.configuration.execution_role
      publish_cloudwatch_metrics_enabled = each.value.configuration.publish_cloudwatch_metrics_enabled
      requester_pays_enabled             = each.value.configuration.requester_pays_enabled
      result_configuration {
        dynamic "encryption_configuration" {
          for_each = each.value.configuration.encryption_configuration != null ? [1] : []
          content {
            encryption_option = each.value.configuration.encryption_configuration.encryption_option
            kms_key_arn       = each.value.configuration.encryption_configuration.kms_key_arn
          }
        }
        dynamic "acl_configuration" {
          for_each = each.value.configuration.s3_acl_option != null ? [1] : []
          content {
            s3_acl_option = each.value.configuration.s3_acl_option
          }
        }
        expected_bucket_owner = each.value.configuration.expected_bucket_owner
        output_location       = each.value.configuration.output_location
      }
      engine_version {
        selected_engine_version = each.value.configuration.selected_engine_version
      }
    }
  }
}

################################################################################
# Athena databases
################################################################################

resource "aws_athena_database" "this" {
  for_each = {
    for k, v in var.databases :
    v.name => v if var.create
  }
  name                  = each.value.name
  bucket                = each.value.bucket
  comment               = each.value.description
  expected_bucket_owner = each.value.expected_bucket_owner
  force_destroy         = each.value.force_destroy
  properties            = each.value.properties

  dynamic "encryption_configuration" {
    for_each = each.value.encryption_enabled ? [1] : []
    content {
      encryption_option = each.value.encryption_option
      kms_key           = each.value.encryption_kms_key
    }
  }

  dynamic "acl_configuration" {
    for_each = each.value.s3_acl_option != null ? [1] : []
    content {
      s3_acl_option = each.value.s3_acl_option
    }
  }
}

################################################################################
# Athena named queries
################################################################################

resource "aws_athena_named_query" "this" {
  for_each = {
    for k, v in var.named_queries :
    v.name => v if var.create
  }
  name        = each.value.name
  database    = try(aws_athena_database.this[each.value.database].id, each.value.database)
  query       = each.value.query
  workgroup   = each.value.workgroup != null ? try(aws_athena_workgroup.this[each.value.workgroup].id, each.value.workgroup) : null
  description = each.value.description
}

################################################################################
# Athena data catalogs
################################################################################
resource "aws_athena_data_catalog" "this" {
  for_each = {
    for k, v in var.data_catalogs :
    v.name => v if var.create
  }
  name        = each.value.name
  type        = each.value.type
  parameters  = each.value.parameters
  description = each.value.description
  tags        = var.tags
}

// File: outputs.tf
################################################################################
# Athena workgroups
################################################################################

output "workgroups_arns" {
  description = "Map of Athena workgroups ARNs"
  value = try({
    for workgroup in var.workgroups : workgroup.name =>
    aws_athena_workgroup.this[workgroup.name].arn
  }, null)
}

################################################################################
# Athena databases
################################################################################

output "databases_ids" {
  description = "Map of Athena databases IDs"
  value = try({
    for database in var.databases : database.name =>
    aws_athena_database.this[database.name].id
  }, null)
}

################################################################################
# Athena named queries
################################################################################

output "named_queries_ids" {
  description = "Map of Athena named queries IDs"
  value = try({
    for query in var.named_queries : query.name =>
    aws_athena_named_query.this[query.name].id
  }, null)
}

################################################################################
# Athena data catalogs
################################################################################

output "data_catalogs_ids" {
  description = "Map of Athena data catalogs IDs"
  value = try({
    for dat_catalog in var.data_catalogs : dat_catalog.name =>
    aws_athena_data_catalog.this[dat_catalog.name].id
  }, null)
}

output "data_catalogs_arns" {
  description = "Map of Athena data catalogs ARNs"
  value = try({
    for dat_catalog in var.data_catalogs : dat_catalog.name =>
    aws_athena_data_catalog.this[dat_catalog.name].arn
  }, null)
}

// File: variables.tf
variable "create" {
  description = "Controls if resources should be created (affects nearly all resources)"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Athena workgroups
################################################################################
variable "workgroups" {
  description = "List of Athena workgroups"
  type = list(object({
    name          = string                                          # Name of the workgroup
    description   = optional(string)                                # Description of the workgroup
    enabled       = optional(bool, true)                            # State of the workgroup
    force_destroy = optional(bool)                                  # Option to delete the workgroup and its contents even if the workgroup contains any named queries
    configuration = optional(object({                               # Configuration block with various settings for the workgroup
      bytes_scanned_cutoff_per_query     = optional(number)         # Integer for the upper data usage limit (cutoff) for the amount of bytes a single query in a workgroup is allowed to scan
      enforce_workgroup_configuration    = optional(bool, true)     # Boolean whether the settings for the workgroup override client-side settings
      selected_engine_version            = optional(string, "AUTO") # Requested engine version
      execution_role                     = optional(string)         # Role used in a notebook session for accessing the user's resources
      publish_cloudwatch_metrics_enabled = optional(bool, true)     # Boolean whether Amazon CloudWatch metrics are enabled for the workgroup
      encryption_configuration = optional(object({
        encryption_option = string           # Whether Amazon S3 server-side encryption with Amazon S3-managed keys (SSE_S3), server-side encryption with KMS-managed keys (SSE_KMS), or client-side encryption with KMS-managed keys (CSE_KMS) is used
        kms_key_arn       = optional(string) # For SSE_KMS and CSE_KMS, this is the KMS key ARN
      }), null)
      s3_acl_option          = optional(string, null) # Amazon S3 canned ACL that Athena should specify when storing query results. Valid value is BUCKET_OWNER_FULL_CONTROL
      expected_bucket_owner  = optional(string)       # AWS account ID that you expect to be the owner of the Amazon S3 bucket
      output_location        = optional(string)       # Location in Amazon S3 where your query results are stored, such as s3://path/to/query/bucket/
      requester_pays_enabled = optional(bool)         # If set to true , allows members assigned to a workgroup to reference Amazon S3 Requester Pays buckets in queries
    }), null)
  }))
  default = []
}

################################################################################
# Athena databases
################################################################################

variable "databases" {
  description = "List of Athena databases"
  type = list(object({
    bucket                = string                 # Name of S3 bucket to save the results of the query execution
    name                  = string                 # Name of the database to create
    s3_acl_option         = optional(string, null) # Amazon S3 canned ACL that Athena should specify when storing query results. Valid value is BUCKET_OWNER_FULL_CONTROL
    description           = optional(string)       # Description of the database
    encryption_enabled    = optional(bool, false)  # Whether the encryption is enabled
    encryption_option     = optional(string)       # Type of key; one of SSE_S3, SSE_KMS, CSE_KMS (Required when encryption is enabled)
    encryption_kms_key    = optional(string)       # KMS key ARN or ID; required for key types SSE_KMS and CSE_KMS
    expected_bucket_owner = optional(string)       # AWS account ID that you expect to be the owner of the Amazon S3 bucket
    force_destroy         = optional(bool)         # Boolean that indicates all tables should be deleted from the database so that the database can be destroyed without error
    properties            = optional(map(string))  # Key-value map of custom metadata properties for the database definition
  }))
  default = []
}

################################################################################
# Athena named queries
################################################################################

variable "named_queries" {
  description = "List of Athena named queries"
  type = list(object({
    name        = string           # Plain language name for the query. Maximum length of 128
    database    = string           # Database to which the query belongs
    query       = string           # Text of the query itself. In other words, all query statements. Maximum length of 262144
    workgroup   = optional(string) # Workgroup to which the query belongs
    description = optional(string) # Brief explanation of the query. Maximum length of 1024
  }))
  default = []
}

################################################################################
# Athena data catalogs
################################################################################

variable "data_catalogs" {
  description = "List of Athena data catalogs"
  type = list(object({
    name        = string      # Name of the data catalog
    type        = string      # Type of data catalog: LAMBDA for a federated catalog, GLUE for AWS Glue Catalog, or HIVE for an external hive metastore
    parameters  = map(string) # Key value pairs that specifies the Lambda function or functions to use for the data catalog
    description = string      # Description of the data catalog
  }))
  default = []
}

// File: versions.tf
terraform {
  required_version = ">= 1.2.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.1.0"
    }
  }
}

// File: codebuild_project.tf
#---------------------------------------------------
# AWS Codebuild project
#---------------------------------------------------
resource "aws_codebuild_project" "codebuild_project" {
  count = var.enable_codebuild_project ? 1 : 0

  name         = var.codebuild_project_name != "" ? lower(var.codebuild_project_name) : "${lower(var.name)}-codebuild-project-${lower(var.environment)}"
  service_role = var.codebuild_project_service_role

  description    = var.codebuild_project_description
  badge_enabled  = var.codebuild_project_badge_enabled
  build_timeout  = var.codebuild_project_build_timeout
  queued_timeout = var.codebuild_project_queued_timeout
  encryption_key = var.codebuild_project_encryption_key
  source_version = var.codebuild_project_source_version

  dynamic "artifacts" {
    iterator = artifacts
    for_each = var.codebuild_project_artifacts

    content {
      type = lookup(artifacts.value, "type", null)

      artifact_identifier    = lookup(artifacts.value, "artifact_identifier", null)
      encryption_disabled    = lookup(artifacts.value, "encryption_disabled", null)
      override_artifact_name = lookup(artifacts.value, "override_artifact_name", null)
      location               = lookup(artifacts.value, "location", null)
      name                   = lookup(artifacts.value, "name", null)
      namespace_type         = lookup(artifacts.value, "namespace_type", null)
      packaging              = lookup(artifacts.value, "packaging", null)
      path                   = lookup(artifacts.value, "path", null)
    }
  }

  dynamic "source" {
    iterator = source
    for_each = length(var.codebuild_project_source) > 0 ? [var.codebuild_project_source] : []

    content {
      type = lookup(source.value, "type", null)

      insecure_ssl        = lookup(source.value, "insecure_ssl", null)
      location            = lookup(source.value, "location", null)
      report_build_status = lookup(source.value, "report_build_status", null)
      buildspec           = lookup(source.value, "buildspec", null)
      git_clone_depth     = lookup(source.value, "git_clone_depth", null)

      dynamic "auth" {
        iterator = auth
        for_each = length(keys(lookup(source.value, "auth", {}))) > 0 ? [lookup(source.value, "auth", {})] : []

        content {
          type     = lookup(auth.value, "type", null)
          resource = lookup(auth.value, "resource", null)
        }
      }

      dynamic "git_submodules_config" {
        iterator = git_submodules_config
        for_each = length(keys(lookup(source.value, "git_submodules_config", {}))) > 0 ? [lookup(source.value, "git_submodules_config", {})] : []

        content {
          fetch_submodules = lookup(git_submodules_config.value, "fetch_submodules", null)
        }
      }
    }
  }

  dynamic "environment" {
    iterator = environment
    for_each = length(var.codebuild_project_environment) > 0 ? [var.codebuild_project_environment] : []

    content {
      compute_type = lookup(environment.value, "compute_type", null)
      image        = lookup(environment.value, "image", null)
      type         = lookup(environment.value, "type", null)

      image_pull_credentials_type = lookup(environment.value, "image_pull_credentials_type", null)
      privileged_mode             = lookup(environment.value, "privileged_mode", null)
      certificate                 = lookup(environment.value, "certificate", null)

      dynamic "registry_credential" {
        iterator = regcred
        for_each = length(keys(lookup(environment.value, "registry_credential", {}))) > 0 ? [lookup(environment.value, "registry_credential", {})] : []

        content {
          credential          = lookup(regcred.value, "credential", null)
          credential_provider = lookup(regcred.value, "credential_provider", null)
        }
      }

      dynamic "environment_variable" {
        iterator = envvar
        for_each = length(keys(lookup(environment.value, "environment_variable", {}))) > 0 ? [lookup(environment.value, "environment_variable", {})] : []

        content {
          name  = lookup(envvar.value, "name", null)
          value = lookup(envvar.value, "value", null)
          type  = lookup(envvar.value, "type", null)
        }
      }
    }
  }

  dynamic "cache" {
    iterator = cache
    for_each = var.codebuild_project_cache

    content {
      type  = lookup(cache.value, "type", null)
      modes = lookup(cache.value, "modes", null)

      location = lookup(cache.value, "location", null)
    }
  }

  dynamic "logs_config" {
    iterator = logsconfig
    for_each = var.codebuild_project_logs_config

    content {
      dynamic "cloudwatch_logs" {
        iterator = cloudwatch_logs
        for_each = length(keys(lookup(logsconfig.value, "cloudwatch_logs", {}))) > 0 ? [lookup(logsconfig.value, "cloudwatch_logs", {})] : []

        content {
          status      = lookup(cloudwatch_logs.value, "status", null)
          group_name  = lookup(cloudwatch_logs.value, "group_name", null)
          stream_name = lookup(cloudwatch_logs.value, "stream_name", null)
        }
      }

      dynamic "s3_logs" {
        iterator = s3_logs
        for_each = length(keys(lookup(logsconfig.value, "s3_logs", {}))) > 0 ? [lookup(logsconfig.value, "s3_logs", {})] : []

        content {
          status              = lookup(s3_logs.value, "status", null)
          location            = lookup(s3_logs.value, "location", null)
          encryption_disabled = lookup(s3_logs.value, "status", null)
        }
      }
    }
  }

  dynamic "vpc_config" {
    iterator = vpcconfig
    for_each = var.codebuild_project_vpc_config

    content {
      vpc_id             = lookup(vpcconfig.value, "vpc_id", null)
      security_group_ids = lookup(vpcconfig.value, "security_group_ids", null)
      subnets            = lookup(vpcconfig.value, "subnets", null)
    }
  }

  dynamic "secondary_artifacts" {
    iterator = secartifacts
    for_each = var.codebuild_project_secondary_artifacts

    content {
      type                = lookup(secartifacts.value, "type", null)
      artifact_identifier = lookup(secartifacts.value, "artifact_identifier", null)

      encryption_disabled    = lookup(secartifacts.value, "encryption_disabled", null)
      override_artifact_name = lookup(secartifacts.value, "override_artifact_name", null)
      location               = lookup(secartifacts.value, "location", null)
      name                   = lookup(secartifacts.value, "name", null)
      namespace_type         = lookup(secartifacts.value, "namespace_type", null)
      packaging              = lookup(secartifacts.value, "packaging", null)
      path                   = lookup(secartifacts.value, "path", null)
    }
  }

  dynamic "secondary_sources" {
    iterator = secsources
    for_each = var.codebuild_project_secondary_sources

    content {
      type              = lookup(secsources.value, "type", null)
      source_identifier = lookup(secsources.value, "source_identifier", null)

      buildspec           = lookup(secsources.value, "buildspec", null)
      git_clone_depth     = lookup(secsources.value, "git_clone_depth", null)
      insecure_ssl        = lookup(secsources.value, "insecure_ssl", null)
      location            = lookup(secsources.value, "location", null)
      report_build_status = lookup(secsources.value, "report_build_status", null)

      dynamic "auth" {
        iterator = auth
        for_each = length(keys(lookup(secsources.value, "auth", {}))) > 0 ? [lookup(secsources.value, "auth", {})] : []

        content {
          type     = lookup(auth.value, "type", null)
          resource = lookup(auth.value, "resource", null)
        }
      }

      dynamic "git_submodules_config" {
        iterator = git_submodules_config
        for_each = length(keys(lookup(secsources.value, "git_submodules_config", {}))) > 0 ? [lookup(secsources.value, "git_submodules_config", {})] : []

        content {
          fetch_submodules = lookup(git_submodules_config.value, "fetch_submodules", null)
        }
      }
    }
  }

  tags = merge(
    {
      Name = var.codebuild_project_name != "" ? lower(var.codebuild_project_name) : "${lower(var.name)}-codebuild-project-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: codebuild_report_group.tf
#---------------------------------------------------
# AWS Codebuild report group
#---------------------------------------------------
resource "aws_codebuild_report_group" "codebuild_report_group" {
  count = var.enable_codebuild_report_group ? length(var.codebuild_report_group_stack) : 0

  name = lookup(var.codebuild_report_group_stack[count.index], "name", "${var.name}-codebuild-report-group-${count.index + 1}-${var.environment}")
  type = lookup(var.codebuild_report_group_stack[count.index], "type", null)

  //delete_reports = lookup(var.codebuild_report_group_stack[count.index], "delete_reports", null)

  dynamic "export_config" {
    iterator = export_config
    for_each = length(keys(lookup(var.codebuild_report_group_stack[count.index], "export_config", {}))) > 0 ? [lookup(var.codebuild_report_group_stack[count.index], "export_config", {})] : []

    content {
      type = lookup(export_config.value, "type", null)

      dynamic "s3_destination" {
        iterator = s3_destination
        for_each = length(keys(lookup(export_config.value, "s3_destination", {}))) > 0 ? [lookup(export_config.value, "s3_destination", {})] : []

        content {
          bucket              = lookup(s3_destination.value, "bucket", null)
          encryption_disabled = lookup(s3_destination.value, "encryption_disabled", null)

          encryption_key = lookup(s3_destination.value, "encryption_key", null)
          packaging      = lookup(s3_destination.value, "packaging", null)
          path           = lookup(s3_destination.value, "path", null)
        }
      }
    }
  }

  tags = merge(
    {
      Name = lookup(var.codebuild_report_group_stack[count.index], "name", "${var.name}-codebuild-report-group-${count.index + 1}-${var.environment}")
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: codebuild_resource_policy.tf
#---------------------------------------------------
# AWS Codebuild resource policy
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/codebuild_resource_policy

// File: codebuild_source_credential.tf
#---------------------------------------------------
# AWS Codebuild source credential
#---------------------------------------------------
resource "aws_codebuild_source_credential" "codebuild_source_credential" {
  count = var.enable_codebuild_source_credential ? 1 : 0

  auth_type   = upper(var.codebuild_source_credential_auth_type)
  server_type = upper(var.codebuild_source_credential_server_type)
  token       = var.codebuild_source_credential_token

  user_name = var.codebuild_source_credential_user_name

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: codebuild_webhook.tf
#---------------------------------------------------
# AWS Codebuild webhook
#---------------------------------------------------
resource "aws_codebuild_webhook" "codebuild_webhook" {
  count = var.enable_codebuild_webhook ? 1 : 0

  project_name = var.codebuild_webhook_project_name != "" && !var.enable_codebuild_project ? var.codebuild_webhook_project_name : element(concat(aws_codebuild_project.codebuild_project.*.name, [""]), 0)

  branch_filter = var.codebuild_webhook_branch_filter

  dynamic "filter_group" {
    iterator = filter_group
    for_each = var.codebuild_webhook_filter_group
    content {

      dynamic "filter" {
        iterator = filter
        for_each = length(keys(lookup(filter_group.value, "filter", {}))) > 0 ? [lookup(filter_group.value, "filter", {})] : []

        content {
          type    = lookup(filter.value, "type", null)
          pattern = lookup(filter.value, "pattern", null)

          exclude_matched_pattern = lookup(filter.value, "exclude_matched_pattern", null)
        }
      }
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_codebuild_project.codebuild_project
  ]
}

// File: outputs.tf
#---------------------------------------------------
# AWS Codebuild project
#---------------------------------------------------
output "codebuild_project_id" {
  description = "The name (if imported via name) or ARN (if created via Terraform or imported via ARN) of the CodeBuild project."
  value       = element(concat(aws_codebuild_project.codebuild_project.*.id, [""]), 0)
}

output "codebuild_project_arn" {
  description = "The ARN of the CodeBuild project."
  value       = element(concat(aws_codebuild_project.codebuild_project.*.arn, [""]), 0)
}

output "codebuild_project_badge_url" {
  description = "The URL of the build badge when badge_enabled is enabled."
  value       = element(concat(aws_codebuild_project.codebuild_project.*.badge_url, [""]), 0)
}

#---------------------------------------------------
# AWS Codebuild source credential
#---------------------------------------------------
output "codebuild_source_credential_id" {
  description = "The ARN of Source Credential."
  value       = element(concat(aws_codebuild_source_credential.codebuild_source_credential.*.id, [""]), 0)
}

output "codebuild_source_credential_arn" {
  description = "The ARN of Source Credential."
  value       = element(concat(aws_codebuild_source_credential.codebuild_source_credential.*.arn, [""]), 0)
}

#---------------------------------------------------
# AWS Codebuild webhook
#---------------------------------------------------
output "codebuild_webhook_id" {
  description = "The name of the build project."
  value       = element(concat(aws_codebuild_webhook.codebuild_webhook.*.id, [""]), 0)
}

output "codebuild_webhook_payload_url" {
  description = "The CodeBuild endpoint where webhook events are sent."
  value       = element(concat(aws_codebuild_webhook.codebuild_webhook.*.payload_url, [""]), 0)
}

output "codebuild_webhook_secret" {
  description = "The secret token of the associated repository. Not returned by the CodeBuild API for all source types."
  value       = element(concat(aws_codebuild_webhook.codebuild_webhook.*.secret, [""]), 0)
}

output "codebuild_webhook_url" {
  description = "The URL to the webhook."
  value       = element(concat(aws_codebuild_webhook.codebuild_webhook.*.url, [""]), 0)
}

#---------------------------------------------------
# AWS Codebuild report group
#---------------------------------------------------
output "codebuild_report_group_id" {
  description = "The ARN of Report Group."
  value       = element(concat(aws_codebuild_report_group.codebuild_report_group.*.id, [""]), 0)
}

output "codebuild_report_group_arn" {
  description = "The ARN of Report Group."
  value       = element(concat(aws_codebuild_report_group.codebuild_report_group.*.arn, [""]), 0)
}

output "codebuild_report_group_created" {
  description = "The date and time this Report Group was created."
  value       = element(concat(aws_codebuild_report_group.codebuild_report_group.*.created, [""]), 0)
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks. Each element should have keys named key, value, etc."
  type        = map(string)
  default     = {}
}

#---------------------------------------------------
# AWS Codebuild project
#---------------------------------------------------
variable "enable_codebuild_project" {
  description = "Enable codebuild project usage"
  default     = false
}

variable "codebuild_project_name" {
  description = "Set name for CodeBuild project"
  default     = ""
}

variable "codebuild_project_service_role" {
  description = "(Required) The Amazon Resource Name (ARN) of the AWS Identity and Access Management (IAM) role that enables AWS CodeBuild to interact with dependent AWS services on behalf of the AWS account."
  default     = null
}

variable "codebuild_project_environment" {
  description = "(Required) Configuration block for environment."
  default     = {}
}

variable "codebuild_project_source" {
  description = "(Required) Configuration block for source."
  default     = {}
}

variable "codebuild_project_artifacts" {
  description = "(Required) Configuration block for artifacts."
  default     = {}
}

variable "codebuild_project_cache" {
  description = "(Optional) Information about the cache storage for the project."
  default     = []
}

variable "codebuild_project_logs_config" {
  description = "(Optional) Configuration for the builds to store log data to S3 or CloudWatch."
  default     = []
}

variable "codebuild_project_vpc_config" {
  description = "(Optional) Configuration for the builds to run inside a VPC."
  default     = []
}

variable "codebuild_project_secondary_artifacts" {
  description = "(Optional) A set of secondary artifacts to be used inside the build."
  default     = []
}

variable "codebuild_project_secondary_sources" {
  description = "(Optional) A set of secondary sources to be used inside the build."
  default     = []
}

variable "codebuild_project_description" {
  description = "(Optional) A short description of the project."
  default     = null
}

variable "codebuild_project_badge_enabled" {
  description = "(Optional) Generates a publicly-accessible URL for the projects build badge. Available as badge_url attribute when enabled."
  default     = null
}

variable "codebuild_project_build_timeout" {
  description = "(Optional) How long in minutes, from 5 to 480 (8 hours), for AWS CodeBuild to wait until timing out any related build that does not get marked as completed. The default is 60 minutes."
  default     = null
}

variable "codebuild_project_queued_timeout" {
  description = "(Optional) How long in minutes, from 5 to 480 (8 hours), a build is allowed to be queued before it times out. The default is 8 hours."
  default     = null
}

variable "codebuild_project_encryption_key" {
  description = "(Optional) The AWS Key Management Service (AWS KMS) customer master key (CMK) to be used for encrypting the build project's build output artifacts."
  default     = null
}

variable "codebuild_project_source_version" {
  description = "(Optional) A version of the build input to be built for this project. If not specified, the latest version is used."
  default     = null
}

#---------------------------------------------------
# AWS Codebuild source credential
#---------------------------------------------------
variable "enable_codebuild_source_credential" {
  description = "Enable codebuild source credential usage"
  default     = false
}

variable "codebuild_source_credential_auth_type" {
  description = "(Required) The type of authentication used to connect to a GitHub, GitHub Enterprise, or Bitbucket repository. An OAUTH connection is not supported by the API. Ex: PERSONAL_ACCESS_TOKEN"
  default     = null
}

variable "codebuild_source_credential_server_type" {
  description = "(Required) The source provider used for this project. Ex: GITHUB"
  default     = null
}

variable "codebuild_source_credential_token" {
  description = "(Required) For GitHub or GitHub Enterprise, this is the personal access token. For Bitbucket, this is the app password."
  default     = null
}

variable "codebuild_source_credential_user_name" {
  description = "(Optional) The Bitbucket username when the authType is BASIC_AUTH. This parameter is not valid for other types of source providers or connections."
  default     = null
}

#---------------------------------------------------
# AWS Codebuild webhook
#---------------------------------------------------
variable "enable_codebuild_webhook" {
  description = "Enable codebuild webhook usage"
  default     = false
}

variable "codebuild_webhook_project_name" {
  description = "The name of the build project."
  default     = ""
}

variable "codebuild_webhook_branch_filter" {
  description = "(Optional) A regular expression used to determine which branches get built. Default is all branches are built. It is recommended to use filter_group over branch_filter."
  default     = null
}

variable "codebuild_webhook_filter_group" {
  description = "(Optional) Information about the webhook's trigger"
  default     = []
}

#---------------------------------------------------
# AWS Codebuild report group
#---------------------------------------------------
variable "enable_codebuild_report_group" {
  description = "Enable codebuild report group usage"
  default     = false
}

variable "codebuild_report_group_stack" {
  description = "Set properties for codebuild report group"
  default     = []
}

// File: data.tf
data "aws_region" "current" {}

# get list of available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  region               = "eu-central-1"
  vpc_cidr             = "10.14.0.0/16"
  public_subnet_count  = 3
  private_subnet_count = 3
}

// File: terraform.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = local.region

  default_tags {
    tags = var.default_tags
  }
}

// File: variables.tf
variable "default_tags" {
  type        = map(string)
  description = "Map of default tags to apply to resources"

  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

// File: vpc.tf
# Main VPC
resource "aws_vpc" "eks_main" {
  cidr_block           = local.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "eks_public_subnet" {
  # 10.14.0.0/16 -> [10.14.0.0/20, 10.14.16.0/20, 10.14.32.0/20]
  count                   = local.public_subnet_count
  vpc_id                  = aws_vpc.eks_main.id
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.eks_main.cidr_block, 4, count.index)

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-${data.aws_availability_zones.available.names[count.index]}"
  }
}

# Public Route Table
resource "aws_route_table" "eks_public_rt" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-route-table"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "eks_igw" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-internet-gateway"
  }
}

# Public Routes
resource "aws_route" "eks_public_internet_access" {
  route_table_id         = aws_route_table.eks_public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.eks_igw.id
  depends_on             = [aws_route_table.eks_public_rt]
}

# Public Subnet Route Associations
resource "aws_route_table_association" "eks_public_rta" {
  count          = local.public_subnet_count
  subnet_id      = element(aws_subnet.eks_public_subnet.*.id, count.index)
  route_table_id = aws_route_table.eks_public_rt.id
}

# Private Subnet
resource "aws_subnet" "eks_private_subnet" {
  # 10.14.0.0/16 -> [10.14.48.0/20, 10.14.64.0/20, 10.14.80.0/20]
  count             = local.private_subnet_count
  vpc_id            = aws_vpc.eks_main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.eks_main.cidr_block, 4, count.index + local.public_subnet_count)

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-${data.aws_availability_zones.available.names[count.index]}"
  }
}

# Private Route Table
resource "aws_route_table" "eks_private_rt" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-route-table"
  }
}

# The NAT Elastic IP
resource "aws_eip" "eks_nat_eip" {
  domain = "vpc"

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat-eip"
  }
}

# The NAT Gateway
resource "aws_nat_gateway" "eks_nat" {
  allocation_id = aws_eip.eks_nat_eip.id
  subnet_id     = aws_subnet.eks_public_subnet.0.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat"
  }

  depends_on = [aws_eip.eks_nat_eip, aws_internet_gateway.eks_igw]
}

# Private Routes
resource "aws_route" "eks_private_internet_access" {
  route_table_id         = aws_route_table.eks_private_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.eks_nat.id
  depends_on             = [aws_route_table.eks_private_rt]
}

# Private Subnet Route Associations
resource "aws_route_table_association" "eks_private_rta" {
  count          = local.private_subnet_count
  subnet_id      = element(aws_subnet.eks_private_subnet.*.id, count.index)
  route_table_id = aws_route_table.eks_private_rt.id
}

// File: main.tf
locals {
  attach_policy = var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy
}

resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix

  # hack when `null` value can't be used (eg, from terragrunt, https://github.com/gruntwork-io/terragrunt/pull/1367)
  acl = var.acl != "null" ? var.acl : null

  tags                = var.tags
  force_destroy       = var.force_destroy
  acceleration_status = var.acceleration_status
  request_payer       = var.request_payer

  dynamic "website" {
    for_each = length(keys(var.website)) == 0 ? [] : [var.website]

    content {
      index_document           = lookup(website.value, "index_document", null)
      error_document           = lookup(website.value, "error_document", null)
      redirect_all_requests_to = lookup(website.value, "redirect_all_requests_to", null)
      routing_rules            = lookup(website.value, "routing_rules", null)
    }
  }

  dynamic "cors_rule" {
    for_each = try(jsondecode(var.cors_rule), var.cors_rule)

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }

  dynamic "versioning" {
    for_each = length(keys(var.versioning)) == 0 ? [] : [var.versioning]

    content {
      enabled    = lookup(versioning.value, "enabled", null)
      mfa_delete = lookup(versioning.value, "mfa_delete", null)
    }
  }

  dynamic "logging" {
    for_each = length(keys(var.logging)) == 0 ? [] : [var.logging]

    content {
      target_bucket = logging.value.target_bucket
      target_prefix = lookup(logging.value, "target_prefix", null)
    }
  }

  dynamic "grant" {
    for_each = try(jsondecode(var.grant), var.grant)

    content {
      id          = lookup(grant.value, "id", null)
      type        = grant.value.type
      permissions = grant.value.permissions
      uri         = lookup(grant.value, "uri", null)
    }
  }

  dynamic "lifecycle_rule" {
    for_each = try(jsondecode(var.lifecycle_rule), var.lifecycle_rule)

    content {
      id                                     = lookup(lifecycle_rule.value, "id", null)
      prefix                                 = lookup(lifecycle_rule.value, "prefix", null)
      tags                                   = lookup(lifecycle_rule.value, "tags", null)
      abort_incomplete_multipart_upload_days = lookup(lifecycle_rule.value, "abort_incomplete_multipart_upload_days", null)
      enabled                                = lifecycle_rule.value.enabled

      # Max 1 block - expiration
      dynamic "expiration" {
        for_each = length(keys(lookup(lifecycle_rule.value, "expiration", {}))) == 0 ? [] : [lookup(lifecycle_rule.value, "expiration", {})]

        content {
          date                         = lookup(expiration.value, "date", null)
          days                         = lookup(expiration.value, "days", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      # Several blocks - transition
      dynamic "transition" {
        for_each = lookup(lifecycle_rule.value, "transition", [])

        content {
          date          = lookup(transition.value, "date", null)
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      # Max 1 block - noncurrent_version_expiration
      dynamic "noncurrent_version_expiration" {
        for_each = length(keys(lookup(lifecycle_rule.value, "noncurrent_version_expiration", {}))) == 0 ? [] : [lookup(lifecycle_rule.value, "noncurrent_version_expiration", {})]

        content {
          days = lookup(noncurrent_version_expiration.value, "days", null)
        }
      }

      # Several blocks - noncurrent_version_transition
      dynamic "noncurrent_version_transition" {
        for_each = lookup(lifecycle_rule.value, "noncurrent_version_transition", [])

        content {
          days          = lookup(noncurrent_version_transition.value, "days", null)
          storage_class = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  # Max 1 block - replication_configuration
  dynamic "replication_configuration" {
    for_each = length(keys(var.replication_configuration)) == 0 ? [] : [var.replication_configuration]

    content {
      role = replication_configuration.value.role

      dynamic "rules" {
        for_each = replication_configuration.value.rules

        content {
          id                               = lookup(rules.value, "id", null)
          priority                         = lookup(rules.value, "priority", null)
          prefix                           = lookup(rules.value, "prefix", null)
          delete_marker_replication_status = lookup(rules.value, "delete_marker_replication_status", null)
          status                           = rules.value.status

          dynamic "destination" {
            for_each = length(keys(lookup(rules.value, "destination", {}))) == 0 ? [] : [lookup(rules.value, "destination", {})]

            content {
              bucket             = destination.value.bucket
              storage_class      = lookup(destination.value, "storage_class", null)
              replica_kms_key_id = lookup(destination.value, "replica_kms_key_id", null)
              account_id         = lookup(destination.value, "account_id", null)

              dynamic "access_control_translation" {
                for_each = length(keys(lookup(destination.value, "access_control_translation", {}))) == 0 ? [] : [lookup(destination.value, "access_control_translation", {})]

                content {
                  owner = access_control_translation.value.owner
                }
              }
            }
          }

          dynamic "source_selection_criteria" {
            for_each = length(keys(lookup(rules.value, "source_selection_criteria", {}))) == 0 ? [] : [lookup(rules.value, "source_selection_criteria", {})]

            content {

              dynamic "sse_kms_encrypted_objects" {
                for_each = length(keys(lookup(source_selection_criteria.value, "sse_kms_encrypted_objects", {}))) == 0 ? [] : [lookup(source_selection_criteria.value, "sse_kms_encrypted_objects", {})]

                content {

                  enabled = sse_kms_encrypted_objects.value.enabled
                }
              }
            }
          }

          # Send empty map if `filter` is an empty map or absent entirely
          dynamic "filter" {
            for_each = length(keys(lookup(rules.value, "filter", {}))) == 0 ? [{}] : []

            content {}
          }

          # Send `filter` if it is present and has at least one field
          dynamic "filter" {
            for_each = length(keys(lookup(rules.value, "filter", {}))) != 0 ? [lookup(rules.value, "filter", {})] : []

            content {
              prefix = lookup(filter.value, "prefix", null)
              tags   = lookup(filter.value, "tags", null)
            }
          }

        }
      }
    }
  }

  # Max 1 block - server_side_encryption_configuration
  dynamic "server_side_encryption_configuration" {
    for_each = length(keys(var.server_side_encryption_configuration)) == 0 ? [] : [var.server_side_encryption_configuration]

    content {

      dynamic "rule" {
        for_each = length(keys(lookup(server_side_encryption_configuration.value, "rule", {}))) == 0 ? [] : [lookup(server_side_encryption_configuration.value, "rule", {})]

        content {
          bucket_key_enabled = lookup(rule.value, "bucket_key_enabled", null)

          dynamic "apply_server_side_encryption_by_default" {
            for_each = length(keys(lookup(rule.value, "apply_server_side_encryption_by_default", {}))) == 0 ? [] : [
            lookup(rule.value, "apply_server_side_encryption_by_default", {})]

            content {
              sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
              kms_master_key_id = lookup(apply_server_side_encryption_by_default.value, "kms_master_key_id", null)
            }
          }
        }
      }
    }
  }

  # Max 1 block - object_lock_configuration
  dynamic "object_lock_configuration" {
    for_each = length(keys(var.object_lock_configuration)) == 0 ? [] : [var.object_lock_configuration]

    content {
      object_lock_enabled = object_lock_configuration.value.object_lock_enabled

      dynamic "rule" {
        for_each = length(keys(lookup(object_lock_configuration.value, "rule", {}))) == 0 ? [] : [lookup(object_lock_configuration.value, "rule", {})]

        content {
          default_retention {
            mode  = lookup(lookup(rule.value, "default_retention", {}), "mode")
            days  = lookup(lookup(rule.value, "default_retention", {}), "days", null)
            years = lookup(lookup(rule.value, "default_retention", {}), "years", null)
          }
        }
      }
    }
  }

}

resource "aws_s3_bucket_policy" "this" {
  count = var.create_bucket && local.attach_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

data "aws_iam_policy_document" "combined" {
  count = var.create_bucket && local.attach_policy ? 1 : 0

  source_policy_documents = compact([
    var.attach_elb_log_delivery_policy ? data.aws_iam_policy_document.elb_log_delivery[0].json : "",
    var.attach_lb_log_delivery_policy ? data.aws_iam_policy_document.lb_log_delivery[0].json : "",
    var.attach_deny_insecure_transport_policy ? data.aws_iam_policy_document.deny_insecure_transport[0].json : "",
    var.attach_policy ? var.policy : ""
  ])
}

# AWS Load Balancer access log delivery policy
data "aws_elb_service_account" "this" {
  count = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0
}

data "aws_iam_policy_document" "elb_log_delivery" {
  count = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0

  statement {
    sid = ""

    principals {
      type        = "AWS"
      identifiers = data.aws_elb_service_account.this.*.arn
    }

    effect = "Allow"

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.this[0].arn}/*",
    ]
  }
}

# ALB/NLB

data "aws_iam_policy_document" "lb_log_delivery" {
  count = var.create_bucket && var.attach_lb_log_delivery_policy ? 1 : 0

  statement {
    sid = "AWSLogDeliveryWrite"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    effect = "Allow"

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid = "AWSLogDeliveryAclCheck"

    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    actions = [
      "s3:GetBucketAcl",
    ]

    resources = [
      aws_s3_bucket.this[0].arn,
    ]

  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = var.create_bucket && var.attach_deny_insecure_transport_policy ? 1 : 0

  statement {
    sid    = "denyInsecureTransport"
    effect = "Deny"

    actions = [
      "s3:*",
    ]

    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values = [
        "false"
      ]
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket && var.attach_public_policy ? 1 : 0

  # Chain resources (s3_bucket -> s3_bucket_policy -> s3_bucket_public_access_block)
  # to prevent "A conflicting conditional operation is currently in progress against this resource."
  # Ref: https://github.com/hashicorp/terraform-provider-aws/issues/7628

  bucket = local.attach_policy ? aws_s3_bucket_policy.this[0].id : aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = local.attach_policy ? aws_s3_bucket_policy.this[0].id : aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  # This `depends_on` is to prevent "A conflicting conditional operation is currently in progress against this resource."
  depends_on = [
    aws_s3_bucket_policy.this,
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket.this
  ]
}

// File: outputs.tf
output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = element(concat(aws_s3_bucket_policy.this.*.id, aws_s3_bucket.this.*.id, [""]), 0)
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket. Will be of format arn:aws:s3:::bucketname."
  value       = element(concat(aws_s3_bucket.this.*.arn, [""]), 0)
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name. Will be of format bucketname.s3.amazonaws.com."
  value       = element(concat(aws_s3_bucket.this.*.bucket_domain_name, [""]), 0)
}

output "s3_bucket_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name. The bucket domain name including the region name, please refer here for format. Note: The AWS CloudFront allows specifying S3 region-specific endpoint when creating S3 origin, it will prevent redirect issues from CloudFront to S3 Origin URL."
  value       = element(concat(aws_s3_bucket.this.*.bucket_regional_domain_name, [""]), 0)
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = element(concat(aws_s3_bucket.this.*.hosted_zone_id, [""]), 0)
}

output "s3_bucket_region" {
  description = "The AWS region this bucket resides in."
  value       = element(concat(aws_s3_bucket.this.*.region, [""]), 0)
}

output "s3_bucket_website_endpoint" {
  description = "The website endpoint, if the bucket is configured with a website. If not, this will be an empty string."
  value       = element(concat(aws_s3_bucket.this.*.website_endpoint, [""]), 0)
}

output "s3_bucket_website_domain" {
  description = "The domain of the website endpoint, if the bucket is configured with a website. If not, this will be an empty string. This is used to create Route 53 alias records. "
  value       = element(concat(aws_s3_bucket.this.*.website_domain, [""]), 0)
}

// File: variables.tf
variable "create_bucket" {
  description = "Controls if S3 bucket should be created"
  type        = bool
  default     = true
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ELB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ALB/NLB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if S3 bucket should have deny non-SSL transport policy attached"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Controls if S3 bucket should have bucket policy attached (set to `true` to use value of `policy` as bucket policy)"
  type        = bool
  default     = false
}

variable "attach_public_policy" {
  description = "Controls if a user defined public bucket policy will be attached (set to `false` to allow upstream to apply defaults to the bucket)"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "(Optional, Forces new resource) The name of the bucket. If omitted, Terraform will assign a random, unique name."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "(Optional, Forces new resource) Creates a unique bucket name beginning with the specified prefix. Conflicts with bucket."
  type        = string
  default     = null
}

variable "acl" {
  description = "(Optional) The canned ACL to apply. Defaults to 'private'. Conflicts with `grant`"
  type        = string
  default     = "private"
}

variable "policy" {
  description = "(Optional) A valid bucket policy JSON document. Note that if the policy document is not specific enough (but still valid), Terraform may view the policy as constantly changing in a terraform plan. In this case, please make sure you use the verbose/specific version of the policy. For more information about building AWS IAM policy documents with Terraform, see the AWS IAM Policy Document Guide."
  type        = string
  default     = null
}

variable "tags" {
  description = "(Optional) A mapping of tags to assign to the bucket."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "(Optional, Default:false ) A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error. These objects are not recoverable."
  type        = bool
  default     = false
}

variable "acceleration_status" {
  description = "(Optional) Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "(Optional) Specifies who should bear the cost of Amazon S3 data transfer. Can be either BucketOwner or Requester. By default, the owner of the S3 bucket would incur the costs of any data transfer. See Requester Pays Buckets developer guide for more information."
  type        = string
  default     = null
}

variable "website" {
  description = "Map containing static web-site hosting or redirect configuration."
  type        = map(string)
  default     = {}
}

variable "cors_rule" {
  description = "List of maps containing rules for Cross-Origin Resource Sharing."
  type        = any
  default     = []
}

variable "versioning" {
  description = "Map containing versioning configuration."
  type        = map(string)
  default     = {}
}

variable "logging" {
  description = "Map containing access bucket logging configuration."
  type        = map(string)
  default     = {}
}

variable "grant" {
  description = "An ACL policy grant. Conflicts with `acl`"
  type        = any
  default     = []
}

variable "lifecycle_rule" {
  description = "List of maps containing configuration of object lifecycle management."
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map containing cross-region replication configuration."
  type        = any
  default     = {}
}

variable "server_side_encryption_configuration" {
  description = "Map containing server-side encryption configuration."
  type        = any
  default     = {}
}

variable "object_lock_configuration" {
  description = "Map containing S3 object locking configuration."
  type        = any
  default     = {}
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = false
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = false
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = false
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = false
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerPreferred or ObjectWriter. 'BucketOwnerPreferred': Objects uploaded to the bucket change ownership to the bucket owner if the objects are uploaded with the bucket-owner-full-control canned ACL. 'ObjectWriter': The uploading account will own the object if the object is uploaded with the bucket-owner-full-control canned ACL."
  type        = string
  default     = "ObjectWriter"
}

// File: versions.tf
terraform {
  required_version = ">= 0.12.31"

  required_providers {
    aws = ">= 3.50"
  }
}

// File: main.tf
###############
# VPC Section #
###############

# VPCs

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  awsAz1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  awsAz2 = var.awsAz2 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
}
resource "aws_vpc" "vpcMain" {
  cidr_block = var.vpcMainCidr
  tags = {
