// File: main.tf
## managed container image registry service

# security/policy
resource "aws_iam_policy" "read" {
  name        = format("%s-ecr-read", local.name)
  description = format("Allow to read images from the ECR")
  path        = "/"
  policy = jsonencode({
    Statement = [{
      Action = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
        "ecr:DescribeRepositories",
        "ecr:GetAuthorizationToken",
        "ecr:GetDownloadUrlForLayer",
        "ecr:ListImages",
      ]
      Effect   = "Allow"
      Resource = [aws_ecr_repository.repo.arn]
    }]
    Version = "2012-10-17"
  })
}

resource "aws_iam_policy" "write" {
  name        = format("%s-ecr-write", local.name)
  description = format("Allow to push and write images to the ECR")
  path        = "/"
  policy = jsonencode({
    Statement = [{
      Action = [
        "ecr:PutImage",
        "ecr:UploadLayerPart",
        "ecr:InitiateLayerUpload",
        "ecr:CompleteLayerUpload",
      ]
      Effect   = "Allow"
      Resource = [aws_ecr_repository.repo.arn]
    }]
    Version = "2012-10-17"
  })
}

data "aws_caller_identity" "current" {}

resource "aws_ecr_repository_policy" "repo" {
  repository = aws_ecr_repository.repo.name
  policy = jsonencode({
    Statement = [{
      Sid = "AllowCrossAccountAccess"
      Action = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
        "ecr:DescribeRepositories",
        "ecr:GetAuthorizationToken",
        "ecr:GetDownloadUrlForLayer",
        "ecr:GetRepositoryPolicy",
        "ecr:ListImages",
      ]
      Effect = "Allow"
      Principal = {
        AWS = flatten([
          data.aws_caller_identity.current.account_id,
          var.trusted_accounts,
        ])
      }
    }]
    Version = "2012-10-17"
  })
}

resource "aws_ecr_lifecycle_policy" "repo" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.repo.name
  policy     = var.lifecycle_policy == null ? jsonencode(local.default_lifecycle_policy) : var.lifecycle_policy
}

resource "aws_ecr_repository" "repo" {
  name = local.repo
  tags = merge(var.tags, local.default-tags)

  image_tag_mutability = var.image_tag_mutability
  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }
}

// File: outputs.tf
output "name" {
  description = "A name of generated ECR repository"
  value       = aws_ecr_repository.repo.id
}

output "arn" {
  description = "An ARN of generated ECR repository"
  value       = aws_ecr_repository.repo.arn
}

output "url" {
  description = "A URL of generated ECR repository"
  value       = aws_ecr_repository.repo.repository_url
}

output "policy_arns" {
  description = "A map of IAM polices to allow access this ECR repository. If you want to make an IAM role or instance-profile has permissions to manage this repository, please attach the `poliy_arn` of this output on your side."
  value       = zipmap(["read", "write"], [aws_iam_policy.read.arn, aws_iam_policy.write.arn])
}

// File: variables.tf
### security
variable "trusted_accounts" {
  description = "A list of AWS Account IDs you want to allow them access to the ECR repository"
  type        = list(string)
  default     = []
}

variable "image_tag_mutability" {
  description = "The tag mutability setting for the repository. Must be one of: MUTABLE or IMMUTABLE. Defaults to MUTABLE."
  type        = string
  default     = "MUTABLE"
}

variable "scan_on_push" {
  description = "Indicates whether images are scanned after being pushed to the repository (true) or not scanned (false)."
  type        = bool
  default     = false
}

variable "lifecycle_policy" {
  description = "Lifecycle policy JSON document"
  type        = string
  default     = null
}

variable "namespace" {
  description = "Namespace of container image repository"
  type        = string
  default     = ""
}

### description
variable "name" {
  description = "Name of container image repository"
  type        = string
  default     = null
}

### tags
