// File: output.tf
output "all_groups_names" {
  value = [aws_iam_group.administrators.name,aws_iam_group.developpers.name,aws_iam_group.prod_users.name]
}

// File: password_policy.tf
#############################
# PASSWORD POLICY BEGINNING
#############################

resource "aws_iam_account_password_policy" "password_policy" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_numbers                = var.require_numbers
  require_uppercase_characters   = var.require_uppercase_characters
  require_symbols                = var.require_symbols
}

#############################
# PASSWORD POLICY END
#############################

// File: variables.tf
variable "allow_users_to_change_password" {
  type        = bool
  default     = true
  description = "Whether to allow users to change their own password"
}

variable "hard_expiry" {
  type        = string
  default     = false
  description = "Whether users are prevented from setting a new password after their password"
}

variable "max_password_age" {
  type        = number
  default     = 90
  description = "The number of days that an user password is valid."
}

variable "minimum_password_length" {
  type        = number
  default     = 14
  description = "Minimum length to require for user passwords."
}

variable "password_reuse_prevention" {
  type        = number
  default     = 24
  description = "The number of previous passwords that users are prevented from reusing."
}

variable "require_lowercase_characters" {
  type        = bool
  default     = true
  description = "Whether to require lowercase characters for user passwords."
}

variable "require_numbers" {
  type        = bool
  default     = true
  description = "Whether to require numbers for user passwords."
}

variable "require_symbols" {
  type        = bool
  default     = true
  description = "Whether to require symbols for user passwords."
}

variable "require_uppercase_characters" {
  type        = bool
  default     = true
  description = "Whether to require uppercase characters for user passwords."
}

variable "tags" {
  description = "A mapping of tags to iam resources."
  default     = { Automation = "Terraform" }
  type        = map(string)
}

// File: main.tf
###########
# Defaults
##########

terraform {
  required_version = ">= 0.13"

}
# ---------------------------------------------------------------------------------------------------------------------
# Set the AWS REGION
# ---------------------------------------------------------------------------------------------------------------------

provider "aws" {
  region = var.region
}

######
# Collect data
######

data "aws_availability_zones" "available" {
  state = "available"
}


######
# VPC
######
resource "aws_vpc" "main" {
  cidr_block                       = var.cidr
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support

  tags = {
    Terraform = "true"
    Name      = "${var.name}_vpc"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${var.region}.s3"

  tags = {
    Terraform = "true"
    Name      = "${var.name}_vpc_endpoint"
  }
}

resource "aws_vpc_endpoint_route_table_association" "private_A" {
  count = 2

  route_table_id  = aws_route_table.private_A[count.index].id
  vpc_endpoint_id = aws_vpc_endpoint.s3.id
}

