// File: main.tf
locals {
  tags = {
    terraform = true
  }
}

resource "null_resource" "previous" {}

resource "time_sleep" "wait_60_seconds" {
  count      = var.create_syn_canary ? 1 : 0
  depends_on = [null_resource.previous]

  create_duration = "60s"
}

resource "aws_cloudwatch_dashboard" "cw_dashboard" {
  count          = var.create_dashboard ? 1 : 0
  dashboard_name = var.dashboard_name
  dashboard_body = var.dashboard_body

}

resource "aws_cloudwatch_composite_alarm" "composite_alarm" {
  count             = var.create_composite_alarm ? 1 : 0
  actions_enabled = var.com_actions_enabled
  alarm_description = var.com_alarm_description
  alarm_name        = "${var.com_alarm_name}-comp"
  alarm_actions = var.com_alarm_actions
  alarm_rule    = var.com_alarm_rule


  depends_on = [
    aws_cloudwatch_metric_alarm.default_dynamic,
    aws_cloudwatch_metric_alarm.defalut
  ]


}


#Module      : CLOUDWATCH METRIC ALARM
#Description : Terraform module creates Cloudwatch Alarm on AWS for monitoriing AWS services.
resource "aws_cloudwatch_metric_alarm" "defalut" {
  count = var.enabled_basic ? 1 : 0

  alarm_name                = var.alarm_name
  alarm_description         = var.alarm_description
  comparison_operator       = var.comparison_operator
  evaluation_periods        = var.evaluation_periods
  metric_name               = var.metric_name
  namespace                 = var.namespace
  period                    = var.period
  statistic                 = var.statistic
  threshold                 = var.threshold
  treat_missing_data        = var.treat_missing_data
  alarm_actions             = var.alarm_actions
  actions_enabled           = var.actions_enabled
  insufficient_data_actions = var.insufficient_data_actions
  ok_actions                = var.ok_actions
  dimensions                = var.dimensions
  tags                      = merge(local.tags )

}
resource "aws_cloudwatch_metric_alarm" "default_dynamic" {  
  for_each = var.enabled_dynamic ? var.alarm_list : {}


  alarm_name                = each.value.alarm_name
  alarm_description         = each.value.alarm_description
  comparison_operator       = each.value.comparison_operator
  evaluation_periods        = each.value.evaluation_periods
  metric_name               = each.value.metric_name
  namespace                 = each.value.namespace
  period                    = each.value.period
  statistic                 = each.value.statistic
  threshold                 = each.value.threshold
  treat_missing_data        = each.value.treat_missing_data
  alarm_actions             = length(each.value.alarm_actions) == 0 ? [] : each.value.alarm_actions
  actions_enabled           = each.value.actions_enabled
  insufficient_data_actions = each.value.insufficient_data_actions
  ok_actions                = each.value.ok_actions
  dimensions                = each.value.dimensions
  tags                      = merge(local.tags )

}

resource "aws_cloudwatch_metric_alarm" "expression" {
  count = var.create_metric_alarm_expression ? 1 : 0

  alarm_name                = var.alarm_name
  alarm_description         = var.alarm_description
  comparison_operator       = var.comparison_operator
  evaluation_periods        = var.evaluation_periods
  threshold                 = var.threshold
  treat_missing_data        = var.treat_missing_data
  alarm_actions             = var.alarm_actions
  actions_enabled           = var.actions_enabled
  insufficient_data_actions = var.insufficient_data_actions
  ok_actions                = var.ok_actions
  tags                      = merge(local.tags )
  dynamic "metric_query" {
    for_each = var.query_expressions
    content {
      id          = metric_query.value["id"]
      expression  = metric_query.value["expression"]
      label       = metric_query.value["label"]
      return_data = metric_query.value["return_data"]
    }
  }

  dynamic "metric_query" {
    for_each = var.query_metrics
    content {
      id          = metric_query.value["id"]
      return_data = metric_query.value["return_data"]
      metric {
       metric_name = metric_query.value["metric_name"]
       namespace   = metric_query.value["namespace"]
       period      = metric_query.value["period"]
       stat        = metric_query.value["stat"]
       unit        = metric_query.value["unit"]
       dimensions  = metric_query.value["dimensions"]
      }
    }
  }
  threshold_metric_id = var.threshold_metric_id

}


resource "aws_synthetics_canary" "canary_watch_service" {
  count                = var.create_syn_canary ? 1 : 0
  name                 = var.syn_canary_name
  artifact_s3_location = "s3://${var.syn_s3_canary_bucket_name}/canary/${var.syn_canary_name}"
  execution_role_arn   = var.syn_role_arn
  handler              = var.syn_handler
  s3_bucket            = var.syn_s3_canary_file_bucket_name
  s3_key               = var.syn_s3_key_file
  s3_version           = var.syn_s3_version
  start_canary         = var.syn_start_canary
  #zip_file             = "${var.zip_file}"
  runtime_version      = var.syn_runtime_version
  delete_lambda        = var.syn_delete_lambda

  success_retention_period = var.syn_success_retention_period

  run_config {
    active_tracing     = var.syn_rc_active_tracing
    timeout_in_seconds = var.syn_rc_timeout_in_seconds
    memory_in_mb = var.syn_rc_memory_in_mb
    environment_variables = var.syn_rc_environment_variables

  }


  schedule {
    expression = "rate(${var.syn_sch_expression} ${var.syn_sch_expression == 1 ? "minute" : "minutes"})"
    duration_in_seconds = var.syn_sch_duration_in_seconds

  }

  depends_on = [time_sleep.wait_60_seconds]
}

resource "aws_cloudwatch_log_group" "log_group" {
  count             = var.create_log_group ? 1 : 0
  name              = var.log_group_name
  retention_in_days = var.retention_days
}


resource "aws_cloudwatch_log_stream" "log_stream" {
  count          = var.create_log_group ? 1 : 0
  name           = var.log_stream_name
  log_group_name = aws_cloudwatch_log_group.log_group[count.index].name

  depends_on = [
    aws_cloudwatch_log_group.log_group
  ]

}

// File: outputs.tf
output "cloudwatch_metric_alarm_arn" {
  description = "The ARN of the Cloudwatch metric alarm."
  value       = try(aws_cloudwatch_metric_alarm.default_dynamic[0].arn, "")
}

output "cloudwatch_metric_alarm_id" {
  description = "The ID of the Cloudwatch metric alarm."
  value       = try(aws_cloudwatch_metric_alarm.default_dynamic[0].id, "")
}

output "log_group_arn" {
  description = "The Amazon Resource Name (ARN) specifying the log group."
  #value       = aws_cloudwatch_log_group.log_group.*.arn
  value = element(concat(aws_cloudwatch_log_group.log_group.*.arn, [""]), 0)
}

output "log_group_name" {
  description = "The name of the log group."
  #value       = aws_cloudwatch_log_group.log_group.*.name
  value = element(concat(aws_cloudwatch_log_group.log_group.*.name, [""]), 0)
}

// File: variables.tf
#Module      : CLOUDWATCH METRIC ALARM
#Description : Provides a CloudWatch Metric Alarm resource.

variable "enabled_basic" {
  type        = bool
  default     = false
  description = "Create a specific alarm, if true."
}

variable "alarm_name" {
  type        = string
  default     = ""
  description = "The descriptive name for the alarm."
}

variable "alarm_description" {
  type        = string
  default     = ""
  description = "The description for the alarm."
}

variable "comparison_operator" {
  type        = string
  description = "The arithmetic operation to use when comparing the specified Statistic and Threshold."
  default     = "GreaterThanOrEqualToThreshold"
  sensitive   = true
}

variable "evaluation_periods" {
  type        = number
  default    = "60"
  description = "The number of periods over which data is compared to the specified threshold."
}

variable "metric_name" {
  type        = string
  default     = "CPUUtilization"
  description = "The name for the alarm's associated metric."
}

variable "namespace" {
  type        = string
  default     = "AWS/EC2"
  description = "The namespace for the alarm's associated metric."
  sensitive   = true
}

variable "period" {
  type        = number
  default     = 120
  description = "The period in seconds over which the specified statistic is applied."
}

variable "statistic" {
  type        = string
  default     = "Average"
  description = "The statistic to apply to the alarm's associated metric."
}

variable "threshold" {
  type        = number
  default     = 40
  description = "The value against which the specified statistic is compared."
}
variable "treat_missing_data" {
  type        = string
  default     = "missing"
  description = " (Optional) Sets how this alarm is to handle missing data points. The following values are supported: missing, ignore, breaching and notBreaching. Defaults to missing."
}

variable "alarm_actions" {
  type        = list(any)
  default     = []
  description = "The list of actions to execute when this alarm transitions into an ALARM state from any other state."
}

variable "actions_enabled" {
  type        = bool
  default     = true
  description = "Indicates whether or not actions should be executed during any changes to the alarm's state."
}

variable "insufficient_data_actions" {
  type        = list(any)
  default     = []
  description = "The list of actions to execute when this alarm transitions into an INSUFFICIENT_DATA state from any other state."
}

variable "ok_actions" {
  type        = list(any)
  default     = []
  description = "The list of actions to execute when this alarm transitions into an OK state from any other state."
}

variable "instance_id" {
  type        = string
  default     = ""
  description = "The instance ID."
  sensitive   = true
}

variable "dimensions" {
  default     = {}
  description = "Dimensions for metrics."
}


# It will allow the creation of several alarms
variable "enabled_dynamic" {
  type        = bool
  default     = false
  description = "Creates a list of alarms, if true, consider the alarm_list variable."
}

variable "alarm_list" {
  type        = any
  default     = null
  description = <<-EOT
    type = map(object({
        alarm-cpu = {
        alarm_name      = "alarm_cpu"
        alarm_description = "This metric monitors ec2 cpu utilization exceeding 70%"
        comparison_operator = "GreaterThanOrEqualToThreshold"
        evaluation_periods  = "2"
        metric_name = "CPUUtilization"
        namespace = "AWS/EC2"
        period    = "60"
        statistic = "Average"
        # CPU Utilization threshold is set to 10 percent
        threshold         = "70"
        alarm_actions = null
        actions_enabled = null
        insufficient_data_actions = null
        ok_actions = null
        dimensions = {
            InstanceId = "i-082cb76ca0e5b43a7"   OR
            AutoScalingGroupName = "casper-aws-autoscaling"
        }
    }
    }))
    Required configuration for attach rule to Sg
    EOT
}

# A composite alarm

variable "create_composite_alarm" {
  type        = bool
  default     = false
  description = "Create alarm composite."
}
variable "com_actions_enabled" {
  type        = bool
  default     = true
  description = "(Optional, Forces new resource) Indicates whether actions should be executed during any changes to the alarm state of the composite alarm. Defaults to true."
}

variable "com_alarm_description" {
  description = "(Optional) The description for the composite alarm."
  default     = null
  type        = string
}

variable "com_alarm_name" {
  type        = string
  default     = null
  description = "(Required) The name for the composite alarm. This name must be unique within the region."
}

variable "com_alarm_actions" {
  type        = list(any)
  default     = []
  description = "(Optional) The set of actions to execute when this alarm transitions to the ALARM state from any other state. Each action is specified as an ARN. Up to 5 actions are allowed."
}
variable "com_alarm_rule" {
  type        = string
  default     = ""
  description = "(Required) An expression that specifies which other alarms are to be evaluated to determine this composite alarm's state. For syntax, see Creating a Composite Alarm. The maximum length is 10240 characters."
}

# CW dashboard

variable "create_dashboard" {
  type        = bool
  default     = false
  description = "if true, enable create cloudwatch dashboard"
}

variable "dashboard_name" {
  description = "(Required) The name of the dashboard."
  default     = null
  type        = string
}

variable "dashboard_body" {
  type        = string
  default     = null
  description = "(Required) The detailed information about the dashboard, including what widgets are included and their location on the dashboard. You can read more about the body structure in the documentation."
}

###############

# Canary resource

variable "create_syn_canary" {
  type        = bool
  default     = false
  description = "if true, enable create canary test"
}

variable "syn_runtime_version" {
  description = "(Required) Runtime version to use for the canary. Versions change often so consult the Amazon CloudWatch documentation for the latest valid versions. Values include syn-python-selenium-1.0, syn-nodejs-puppeteer-3.0, syn-nodejs-2.2, syn-nodejs-2.1, syn-nodejs-2.0, and syn-1.0."
  default     = null
  type        = string
}
variable "syn_start_canary" {
  type        = bool
  default     = false
  description = "(Optional) Whether to run or stop the canary."
}

variable "syn_s3_key_file" {
  description = "S3 key of your script. Conflicts with zip_file. canary_zip_inline.zip"
  default     = null
  type        = string
}

variable "syn_canary_name" {
  description = "Name to be used on Canary Test created."
  default     = null
  type        = string
}

variable "syn_s3_canary_bucket_name" {
  description = " (Required) Location in Amazon S3 where Synthetics stores artifacts from the test runs of this canary."
  default     = null
  type        = string
}
variable "syn_s3_canary_file_bucket_name" {
  description = " (Optional) Full bucket name which is used if your canary script is located in S3. The bucket must already exist. Specify the full bucket name including s3:// as the start of the bucket name. Conflicts with zip_file - Name to be used on Id bucket for read the code in Zip file."
  default     = null
  type        = string
}
variable "syn_s3_version" {
  description = " (Optional) S3 version ID of your script. Conflicts with zip_file."
  default     = null
  type        = string
}

variable "syn_role_arn" {
  description = "Role ARN for S3 and Canary Connection"
  default     = null
  type        = string
}

variable "syn_handler" {
  description = "(Required) Entry point to use for the source code when running the canary. This value must end with the string .handler"
  default     = null
  type        = string
}

variable "syn_delete_lambda" {
  description = "(Optional) Specifies whether to also delete the Lambda functions and layers used by this canary. The default is false"
  type        = bool
  default     = false
}
variable "syn_success_retention_period" {
  description = "(Optional) Number of days to retain data about successful runs of this canary. If you omit this field, the default of 31 days is used. The valid range is 1 to 455 days."
  type        = number
  default     = 3
}

# Canary resource in run_config

variable "syn_rc_active_tracing" {
  description = "(Optional) Whether this canary is to use active AWS X-Ray tracing when it runs. You can enable active tracing only for canaries that use version syn-nodejs-2.0 or later for their canary runtime."
  type        = bool
  default     = false
}
variable "syn_rc_timeout_in_seconds" {
  description = "(Optional) Number of seconds the canary is allowed to run before it must stop. If you omit this field, the frequency of the canary is used, up to a maximum of 840 (14 minutes)."
  type        = number
  default     = 60
}
variable "syn_rc_memory_in_mb" {
  description = "(Optional) Maximum amount of memory available to the canary while it is running, in MB. The value you specify must be a multiple of 64."
  type        = string
  default     = null
}

variable "syn_rc_environment_variables" {
  description = "(Optional) Map of environment variables that are accessible from the canary during execution. Please see AWS Docs for variables reserved for Lambda."
  type        = map(any)
  default     = null
}

# Canary resource in schedule

variable "syn_sch_expression" {
  description = "(Required) Rate expression or cron expression that defines how often the canary is to run."
  default     = 1
  type        = number
}

variable "syn_sch_duration_in_seconds" {
  description = "(Optional) Duration in seconds, for the canary to continue making regular runs according to the schedule in the Expression value."
  type        = number
  default     = null

}

# Log group

variable "create_log_group" {
  type        = bool
  default     = false
  description = "if true, enable create canary test"
}

variable "retention_days" {
  description = "Days to keep data saved."
  default     = 3
  type        = number
}

variable "log_group_name" {
  description = "Name to be used on Log Group created."
  default     = null
  type        = string
}

variable "log_stream_name" {
  description = "Name to be used on Log Stream created."
  default     = null
  type        = string
}



variable "create_metric_alarm_expression" {
  type        = bool
  default     = false
  description = "Enable alarm with expression."
}

variable "threshold_metric_id" {
  description = "If this is an alarm based on an anomaly detection model, make this value match the ID of the ANOMALY_DETECTION_BAND function."
  type        = string
  default     = null
}

# Enables you to create an alarm based on a metric math expression. You may specify at most 20.

variable "query_expressions" {
  type = any
  default = [{
    id          = "e1"
    expression  = "ANOMALY_DETECTION_BAND(m1)"
    label       = "CPUUtilization (Expected)"
    return_data = "true"
  }]
  description = "values for metric query expression."
}

variable "query_metrics" {
  type = any
  default = [{
    id          = "m1"
    return_data = "true"
    metric_name = "CPUUtilization"
    namespace   = "AWS/EC2"
    period      = "120"
    stat        = "Average"
    unit        = "Count"
    dimensions = {
      InstanceId = "i-abc123"
    }
  }]
  description = "values for metric query metrics."
}

// File: version.tf
terraform {
  required_version = ">= 0.14"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.61.0"
    }
  }
}

// File: main.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.10"
    }
  }
}

provider "aws" {
  region     = var.region
}

// Create Terraform user
resource "aws_iam_user" "user" {
  name = var.username
  force_destroy = true

  tags = {
    ProjectTag = var.project_tag
  }
}

// Create a Terraform group for managing the infrastructure
resource "aws_iam_group" "group" {
  name = var.group_name
}

// Assign Terraform user to the group
resource "aws_iam_group_membership" "membership" {
  name = var.membership_name

  users = [
    aws_iam_user.user.name,
  ]

  group = aws_iam_group.group.name
}

// Provides an IAM access key for the user
resource "aws_iam_access_key" "terraform_access_key" {
  user = aws_iam_user.user.name
}

// Outputs access key ID
output "AWS_ACCESS_KEY_ID" {
  value = aws_iam_access_key.terraform_access_key.id
}

// Outputs secret access key
output "AWS_SECRET_ACCESS_KEY" {
  # sensitive = true
  value = nonsensitive(aws_iam_access_key.terraform_access_key.secret)
}

// File: policies.tf
resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "sts:GetCallerIdentity"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_basic_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

// Create
resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_create_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.create_policy.arn
}

// Read
resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:ImportKeyPair",
          "ec2:DescribeReplaceRootVolumeTasks",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceCreditSpecifications",
          "ec2:DescribeImages",
          "ec2:DescribeVolumes",
          "ec2:DescribeSubnets",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeRouteTables",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeVpcs",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeImportImageTasks",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeTags",
          "ec2:DescribeAddresses"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "read_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.read_policy.arn
}

// Update
resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:ModifyVpc*",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyLocalGatewayRoute",
          "ec2:ModifySecurityGroupRules",
          "ec2:ModifyVolumeAttribute",
          "ec2:ModifyAvailabilityZoneGroup",
          "ec2:ReplaceRouteTableAssociation",
          "ec2:AttachInternetGateway",
          "ec2:AssociateAddress"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "update_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.update_policy.arn
}

// Delete
resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:DeleteKeyPair",
          "ec2:DeleteVpc",
          "ec2:DeleteSubnet",
          "ec2:DeleteInternetGateway",
          "ec2:DetachInternetGateway",
          "ec2:DeleteRouteTable",
          "ec2:DeleteLocalGatewayRouteTableVpcAssociation",
          "ec2:DeleteSecurityGroup",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress",
          "ec2:ReleaseAddress"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_delete_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_instance_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

// Necessary for acessing the terraform backend
resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
        ]
        "Resource" : [
          "*"
          # // TODO: only allow actions on a specific dynamodb table
          # "arn:aws:dynamodb:*:*:table/*",
        ]
      },
      {
        "Effect" : "Allow",
        "Action" : [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        "Resource" : [
          "*"
          # // TODO: only allow actions on a specific s3 bucket
          # "arn:aws:s3:::*"
        ]
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_terraform_backend_access" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

// File: variables.tf
variable "region" {
  type        = string
  default     = "sa-east-1"
}
variable "project_tag" {
  type        = string
  default     = "my-vpn-tag"
}
variable "username" {
  type        = string
  default     = "my_vpn_infra_user"
}
variable "group_name" {
  type        = string
  default     = "my-vpn-infra-group"
}
variable "membership_name" {
  type        = string
  default     = "my-vpn-infra-manager-group"
}
variable "policies_path" {
  type        = string
  default     = "/my_vpn_infra/"
}

// File: main.tf
# VPC Creation
resource "aws_vpc" "main" {
    cidr_block              = "${var.vpc_cidr_block}"
    enable_dns_hostnames    = true
    tags = {
        Name                = "${var.environment}-vpc"
    }
}

# Public Subnet Creation
resource "aws_subnet" "public-subnet-1a" {
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.public_subnet_1a_cidr_block
    availability_zone   = "us-east-1a"


    tags = {
        Name            = "${var.environment}-public-subnet-1a"
    }
}

resource "aws_subnet" "public-subnet-1b" {
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.public_subnet_1b_cidr_block
    availability_zone   = "us-east-1b"
    tags = {
        Name            = "${var.environment}-public-subnet-1b"
    }
}

# Private Subnet Creation
resource "aws_subnet" "private-subnet-1a" {
    count = var.craete_private_subnet ? 1 : 0
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.private_subnet_1a_cidr_block
    availability_zone   = "us-east-1a"
    tags = {
        Name            = "${var.environment}-private-subnet-1a"
    }
}

resource "aws_subnet" "private-subnet-1b" {
    count = var.craete_private_subnet ? 1 : 0
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.private_subnet_1b_cidr_block
    availability_zone   = "us-east-1b"

    tags = {
        Name            = "${var.environment}-private-subnet-1b"
    }

}

# Route Table Creation - Public 
resource "aws_route_table" "public-route-table" {
    vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id

    tags = {
      Name = "${var.environment}-public-route-table"
    }
}

# Route Table Creation - Private
resource "aws_route_table" "private-route-table" {
    count = var.craete_private_subnet ? 1 : 0
    vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id

    tags = {
      Name = "${var.environment}-private-route-table"
    }
}

# Route Table Association - Public

resource "aws_route_table_association" "public-subnet-1a" {
    subnet_id       = aws_subnet.public-subnet-1a.id
    route_table_id  = aws_route_table.public-route-table.id
}

resource "aws_route_table_association" "public-subnet-1b" {
    subnet_id       = aws_subnet.public-subnet-1b.id
    route_table_id  = aws_route_table.public-route-table.id
}

# Route Table Association - Private

resource "aws_route_table_association" "private-subnet-1a" {
    count = var.craete_private_subnet ? 1 : 0
    subnet_id       = aws_subnet.private-subnet-1a[0].id
    route_table_id  = aws_route_table.private-route-table[0].id
}

resource "aws_route_table_association" "private-subnet-1b" {
    count = var.craete_private_subnet ? 1 : 0
    subnet_id       = aws_subnet.private-subnet-1b[0].id
    route_table_id  = aws_route_table.private-route-table[0].id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "elastic-ip-for-nat-gateway" {
    count = var.craete_private_subnet ? 1 : 0
    domain                         = "vpc"
    associate_with_private_ip   = var.private_ip_for_nat_gateway

    tags = {
      Name = "${var.environment}-EIP-for-NAT-Gateway"
    }
}

# Nat Gateway creation
resource "aws_nat_gateway" "nat-gw" {
    count = var.craete_private_subnet ? 1 : 0
    allocation_id   = aws_eip.elastic-ip-for-nat-gateway[0].id
    subnet_id       = aws_subnet.public-subnet-1a.id

    tags = {
      Name = "${var.environment}-NAT-Gateway"
    }

    depends_on = [ aws_eip.elastic-ip-for-nat-gateway ]
}

# Internet Gateway Creation

resource "aws_internet_gateway" "main-igw" {
    vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id

    tags = {
      Name = "${var.environment}-IGW"
    }
}


# Nat Gateway & route table association [ private route]

resource "aws_route" "nat-gw-route" {
    count = var.craete_private_subnet ? 1 : 0
    route_table_id          = aws_route_table.private-route-table[0].id
    nat_gateway_id          = aws_nat_gateway.nat-gw[0].id
    destination_cidr_block  = "0.0.0.0/0"
}

# Public IGW & route table association [ public route]

resource "aws_route" "igw-route" {
    route_table_id          = aws_route_table.public-route-table.id
    gateway_id              = aws_internet_gateway.main-igw.id
    destination_cidr_block  = "0.0.0.0/0"
}

// File: output.tf
output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_cidr_block" {
  value = aws_vpc.main.cidr_block
}

output "public_subnet_1a_id" {
  value = aws_subnet.public-subnet-1a.id
}

output "public_subnet_1b_id" {
  value = aws_subnet.public-subnet-1b.id
}

output "private_subnet_1a_id" {
  value = aws_subnet.private-subnet-1a[*].id
}

output "private_subnet_1b_id" {
  value = aws_subnet.private-subnet-1b[*].id
}

output "private_subnets" {
  value = tolist([aws_subnet.private-subnet-1a[*].id, aws_subnet.private-subnet-1b[*].id])
}

output "public_subnets" {
  value = tolist([aws_subnet.public-subnet-1a.id, aws_subnet.public-subnet-1b.id])
}

