terraform {
  required_version = ">= 0.12"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

// File: _global.tf
data "aws_caller_identity" "current" {}

variable "name_prefix" {
  description = "A prefix that will be used on all named resources."
  type        = string
  default     = "pippi-"

  validation {
    condition     = length(regexall("^[a-zA-Z-]*$", var.name_prefix)) > 0
    error_message = "`name_prefix` must satisfy pattern `^[a-zA-Z-]+$`."
  }
}

variable "default_tags" {
  description = "A map of default tags, that will be applied to all resources applicable."
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = var.name_prefix
  default_tags = merge(var.default_tags, {
    tf-module : "pippi.io/aws-ecr"
    tf-workspace = terraform.workspace
  })

  account_id = data.aws_caller_identity.current.account_id
}

// File: ecr.tf
# kics-scan ignore-block
resource "aws_ecr_repository" "this" {
  for_each = var.private_repositories

  name                 = each.key
  image_tag_mutability = each.value.image_tag_mutability != null ? each.value.image_tag_mutability : "MUTABLE"

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr["private"].arn
  }

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.default_tags, {
    "Name" = each.key
  })
}

resource "aws_ecr_repository_policy" "this" {
  for_each = aws_ecr_repository.this

  repository = each.value.name
  policy     = data.aws_iam_policy_document.private[each.key].json
}

resource "aws_ecrpublic_repository" "this" {
  for_each = var.public_repositories

  repository_name = each.key

  catalog_data {
    about_text        = each.value.about
    architectures     = each.value.architectures
    description       = each.value.description
    logo_image_blob   = each.value.logo_image_blob
    operating_systems = each.value.operating_systems
    usage_text        = each.value.usage_text
  }

  tags = merge(local.default_tags, {
    "Name" = each.key
  })
}

resource "aws_ecrpublic_repository_policy" "this" {
  for_each = aws_ecrpublic_repository.this

  repository_name = each.value.repository_name
  policy          = data.aws_iam_policy_document.public[each.key].json
}

// File: iam.tf
# kics-scan ignore-block
resource "aws_iam_user" "artifact_user" {
  for_each = local.create_iam_users

  name = "${local.name_prefix}${each.key}"
  path = "/artifact/"

  tags = merge(local.default_tags, {
    "Name" = "${local.name_prefix}${each.key}"
  })
}

resource "aws_iam_access_key" "artifact_user" {
  for_each = aws_iam_user.artifact_user

  user = each.value.name
}

# kics-scan ignore-block
resource "aws_iam_user_policy" "artifact_user" {
  for_each = aws_iam_user.artifact_user

  name   = "ECR"
  user   = each.value.name
  policy = try(data.aws_iam_policy_document.artifact_user_private[each.key].json, data.aws_iam_policy_document.artifact_user_public[each.key].json)
}

data "aws_iam_policy_document" "artifact_user_private" {
  for_each = aws_ecr_repository.this

  statement {
    sid       = "AllowECR"
    actions   = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:CompleteLayerUpload",
      "ecr:GetDownloadUrlForLayer",
      "ecr:InitiateLayerUpload",
      "ecr:PutImage",
      "ecr:UploadLayerPart"
    ]
    resources = [
      each.value.arn
    ]
  }

  statement {
    sid       = "AllowECRAuthorization" # needed to login to ecr
    actions   = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "artifact_user_public" {
  for_each = aws_ecrpublic_repository.this

  statement {
    sid       = "AllowECRPublic"
    actions   = [
      "ecr-public:BatchCheckLayerAvailability",
      "ecr-public:BatchGetImage",
      "ecr-public:CompleteLayerUpload",
      "ecr-public:GetDownloadUrlForLayer",
      "ecr-public:InitiateLayerUpload",
      "ecr-public:PutImage",
      "ecr-public:UploadLayerPart",
    ]
    resources = [
      each.value.arn
    ]
  }

  statement {
    sid       = "AllowECRPublicAuthorization" # needed to login to ecr
    actions   = [
      "ecr-public:GetAuthorizationToken",
      "sts:GetServiceBearerToken"
    ]
    resources = ["*"]
  }
}

// File: kms.tf
data "aws_iam_policy_document" "kms" {
  for_each = length(var.private_repositories) > 0 ? toset(["private"]) : []

  statement {
    resources = ["*"]
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.id}:root"]
    }
  }
}

# kics-scan ignore-block
resource "aws_kms_key" "ecr" {
  for_each = data.aws_iam_policy_document.kms

  description         = "KMS CMK used by ecr"
  enable_key_rotation = true
  policy              = each.value.json

  tags = merge(local.default_tags, {
    "Name" = "${local.name_prefix}ecr-kms"
  })
}

// File: main.tf
locals {
  private_repo_pull_arns = { for k, repo in var.private_repositories : k => concat(
    [for index, account in repo.pull_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.pull_role_arns : role]
  ) }

  private_repo_push_arns = { for k, repo in var.private_repositories : k => concat(
    [for index, account in repo.push_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.push_role_arns : role]
  ) }

  public_repo_push_arns = { for k, repo in var.public_repositories : k => concat(
    [for index, account in repo.push_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.push_role_arns : role]
  ) }

  global_pull_account_arns = concat([for ac in var.global_pull_accounts : "arn:aws:iam::${ac}:root"], ["arn:aws:iam::${local.account_id}:root"])
  global_push_account_arns = concat([for ac in var.global_push_accounts : "arn:aws:iam::${ac}:root"], ["arn:aws:iam::${local.account_id}:root"])

  create_iam_users = toset([for k, repo in merge(var.private_repositories, var.public_repositories) : k if repo.create_iam_user])
}

// File: output.tf
output "private_repositories" {
  value       = aws_ecr_repository.this
  description = "List of private ECR repositories"
}

output "public_repositories" {
  value       = aws_ecrpublic_repository.this
  description = "List of public ECR repositories"
}

output "iam_users" {
  value = {
    for key, user in aws_iam_user.artifact_user :
    user.name => {
      user_arn          = user.arn
      access_key_id     = aws_iam_access_key.artifact_user[key].id
      secret_access_key = aws_iam_access_key.artifact_user[key].secret
    }
  }
  sensitive   = true
  description = "List of IAM users"
}

// File: policy.tf
data "aws_iam_policy_document" "private" {
  for_each = var.private_repositories

  statement {
    sid = "PullPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_pull_account_arns, local.private_repo_pull_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImageScanFindings",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetLifecyclePolicy",
      "ecr:GetLifecyclePolicyPreview",
      "ecr:GetRepositoryPolicy",
      "ecr:ListImages",
      "ecr:ListTagsForResource",
    ]
  }

  statement {
    sid = "PushPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_push_account_arns, local.private_repo_push_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]
  }
}

data "aws_iam_policy_document" "public" {
  for_each = var.public_repositories

  statement {
    sid = "PushPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_push_account_arns, local.public_repo_push_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]
  }
}

// File: variables.tf
variable "private_repositories" {
  type = map(object({
    image_tag_mutability = optional(string)
    pull_accounts        = optional(list(string), [])
    pull_role_arns       = optional(list(string), [])
    push_accounts        = optional(list(string), [])
    push_role_arns       = optional(list(string), [])
    create_iam_user      = optional(bool, false)
  }))
  description = "List of private repositories that should be created"
  default     = {}
}

variable "public_repositories" {
  type = map(object({
    about             = optional(string)
    architectures     = optional(list(string))
    description       = optional(string)
    logo_image_blob   = optional(string)
    operating_systems = optional(list(string))
    usage_text        = optional(string)
    push_accounts     = optional(list(string), [])
    push_role_arns    = optional(list(string), [])
    create_iam_user   = optional(bool, false)
  }))
  description = "List of public repositories that should be created"
  default     = {}
}

variable "global_pull_accounts" {
  type        = list(string)
  description = "List of accounts that can pull from all the private repositories"
  default     = []
}

variable "global_push_accounts" {
  type        = list(string)
  description = "List of accounts that can push to all the repositories"
  default     = []
}

// File: version.tf
