# Terraform Provider
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Configure the AWS Provider
provider "aws" {
  region = "ap-south-1"
}

# Define the VPC
resource "aws_vpc" "bjit_vpc" {
  cidr_block       = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = {
    Name = "bjit-vpc"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam"
  }
}

# Define the subnets in three availability zones
variable "availability_zones" {
  default = ["ap-south-1a", "ap-south-1b", "ap-south-1c"]
}
# Define the subnets
resource "aws_subnet" "public_subnet" {
  count             = 3
  vpc_id            = aws_vpc.bjit_vpc.id
  cidr_block        = "10.0.${4 + count.index * 2}.0/24"
  availability_zone = element(var.availability_zones, count.index)
  map_public_ip_on_launch = true
  tags = {
    Name = "bjit-subnet-public-ap-south-${count.index + 1}"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam"
  }
}

resource "aws_subnet" "private_subnet" {
  count             = 3
  vpc_id            = aws_vpc.bjit_vpc.id
  cidr_block        = "10.0.${10 + count.index * 2}.0/24"
  availability_zone = element(var.availability_zones, count.index)
  tags = {
    Name = "bjit-subnet-private-ap-south-${count.index + 1}"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam"
  }
}

# Create VPC endpoints for S3
resource "aws_vpc_endpoint" "bjit_s3_endpoint" {
  vpc_id = aws_vpc.bjit_vpc.id
  service_name = "com.amazonaws.ap-south-1.s3"
  route_table_ids = [for rt in aws_route_table.private_route_table : rt.id]  
  tags = {
    Name = "bjit-s3-endpoint"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

# Define security groups
resource "aws_security_group" "bjit_alb_sg" {
  name = "bjit-api-server-ALB-SG"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.bjit_vpc.id
  tags = {
    Name = "bjit-api-server-ALB"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

resource "aws_security_group_rule" "bjit_alb_http_https" {
  type             = "ingress"
  from_port        = 80
  to_port          = 443
  protocol         = "tcp"
  security_group_id = aws_security_group.bjit_alb_sg.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_security_group" "bjit_rds_sg" {
  name = "bjit-mariaDB-RDS-SG"
  description = "Security group for MariaDB RDS"
  vpc_id      = aws_vpc.bjit_vpc.id
  tags = {
    Name = "bjit-mariaDB-RDS"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

resource "aws_security_group_rule" "bjit_rds_port" {
  type        = "ingress"
  from_port   = 3306
  to_port     = 3306
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/16"]
  security_group_id = aws_security_group.bjit_rds_sg.id
}

resource "aws_security_group" "bjit_redis_sg" {
  name = "bjit-redis-SG"
  description = "Security group for Redis"
  vpc_id      = aws_vpc.bjit_vpc.id
  tags = {
    Name = "bjit-redis-EC"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

resource "aws_security_group_rule" "bjit_redis_port" {
  type        = "ingress"
  from_port   = 6379
  to_port     = 6379
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/16"]
  security_group_id = aws_security_group.bjit_redis_sg.id
}

resource "aws_security_group" "bjit_api_server_sg" {
  name = "bjit-api-server-SG"
  description = "Security group for API Server"
  vpc_id      = aws_vpc.bjit_vpc.id
  tags = {
    Name = "bjit-api-server"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

resource "aws_security_group_rule" "bjit_api_server_ports" {
  type        = "ingress"
  from_port   = 8080
  to_port     = 8080
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/16"]
  security_group_id = aws_security_group.bjit_api_server_sg.id
}

resource "aws_security_group_rule" "bjit_api_server_ssh" {
  type        = "ingress"
  from_port   = 22
  to_port     = 22
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/16"]
  security_group_id = aws_security_group.bjit_api_server_sg.id
}

resource "aws_security_group" "bjit_file_server_sg" {
  name = "bjit-file-server-SG"
  description = "Security group for File Server"
  vpc_id      = aws_vpc.bjit_vpc.id
  tags = {
    Name = "bjit-file-server"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

resource "aws_security_group_rule" "bjit_file_server_ports" {
  type        = "ingress"
  from_port   = 8081
  to_port     = 8081
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/16"]
  security_group_id = aws_security_group.bjit_file_server_sg.id
}

resource "aws_security_group_rule" "bjit_file_server_ssh" {
  type        = "ingress"
  from_port   = 22
  to_port     = 22
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/16"]
  security_group_id = aws_security_group.bjit_file_server_sg.id
}

resource "aws_security_group" "bjit_public_ssh_sg" {
  name = "bjit-public-ssh-SG"
  description = "Security group for Public SSH Access"
  vpc_id      = aws_vpc.bjit_vpc.id
  tags = {
    Name = "bjit-public-ssh"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}
resource "aws_security_group_rule" "bjit_public_ssh" {
  type        = "ingress"
  from_port   = 22
  to_port     = 22
  protocol    = "tcp"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.bjit_public_ssh_sg.id
}

# Create an Internet Gateway
resource "aws_internet_gateway" "bjit_igw" {
  vpc_id = aws_vpc.bjit_vpc.id
   tags = {
    Name = "bjit-igw"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

# Create a public route table
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.bjit_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.bjit_igw.id
  }

  tags = {
    Name = "bjit-rtb-public"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

# Create private route tables for each availability zone
resource "aws_route_table" "private_route_table" {
  count  = 3
  vpc_id = aws_vpc.bjit_vpc.id

  tags = {
    Name = "bjit-rtb-private-${element(var.availability_zones, count.index)}"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}

# Associate public subnet with the public route table
resource "aws_route_table_association" "public_association" {
  count          = 3
  subnet_id      = aws_subnet.public_subnet[count.index].id
  route_table_id = aws_route_table.public_route_table.id
}

# Associate private subnet with their respective private route tables
resource "aws_route_table_association" "private_association" {
  count          = 3
  subnet_id      = aws_subnet.private_subnet[count.index].id
  route_table_id = element(aws_route_table.private_route_table, count.index).id
}
# Add outbound rules to security groups to allow all traffic
resource "aws_security_group_rule" "bjit_alb_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.bjit_alb_sg.id
}

resource "aws_security_group_rule" "bjit_rds_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.bjit_rds_sg.id
}

resource "aws_security_group_rule" "bjit_redis_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.bjit_redis_sg.id
}

resource "aws_security_group_rule" "bjit_api_server_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.bjit_api_server_sg.id
}
resource "aws_security_group_rule" "bjit_file_server_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.bjit_file_server_sg.id
}
resource "aws_security_group_rule" "bjit_public_ssh_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.bjit_public_ssh_sg.id
}

// File: eip.tf
resource "aws_eip" "natgw" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)
  domain = "vpc"

  tags = merge(
    {
      "Name" = "${var.base_name}-natgw-eip-${count.index}"
    },
    var.tags
  )
}

// File: endpoint.tf
data "aws_region" "current" {}

resource "aws_vpc_endpoint" "ecr_api" {
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  vpc_id              = aws_vpc.main.id
//  subnet_ids          = aws_subnet.private.*.id
  subnet_ids          = var.subnet_private_cidrs == null ? aws_subnet.public.*.id : aws_subnet.private.*.id
  security_group_ids  = [aws_security_group.ecr_endpoint.id]
  private_dns_enabled = true

  tags = merge(
    {
      "Name" = "${var.base_name}-ECR-API-Endpoint"
    },
    var.tags
  )
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  vpc_id              = aws_vpc.main.id
//  subnet_ids          = aws_subnet.private.*.id
  subnet_ids          = var.subnet_private_cidrs == null ? aws_subnet.public.*.id : aws_subnet.private.*.id
  security_group_ids  = [aws_security_group.ecr_endpoint.id]
  private_dns_enabled = true

  tags = merge(
    {
      "Name" = "${var.base_name}-ECR-DKR-Endpoint"
    },
    var.tags
  )
}


resource "aws_vpc_endpoint" "s3_public_subnet" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids = [aws_route_table.public.id]

  tags = merge(
    {
      "Name" = "${var.base_name}-S3-Endpoint-public-subnet"
    },
    var.tags
  )
}

resource "aws_vpc_endpoint" "s3_private_subnet" {
  count = var.subnet_private_cidrs == null ? 0 : 1

  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids = aws_route_table.private.*.id

  tags = merge(
  {
    "Name" = "${var.base_name}-S3-Endpoint-private-subnet"
  },
  var.tags
  )
}

# com.amazonaws.Region.logs

// File: internet_gateway.tf
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      "Name" = "${var.base_name}-internet-gateway"
    },
    var.tags
  )
}

// File: nat_gateway.tf
resource "aws_nat_gateway" "ngw" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)

  allocation_id = aws_eip.natgw[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    {
      "Name" = "${var.base_name}-nat-gateway-${count.index}"
    },
    var.tags
  )
}

// File: output.tf
output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_cidr" {
  value = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  value = [
    for subnet in aws_subnet.public :
    subnet.id
  ]
}

output "private_subnet_ids" {
  value = [
    for subnet in aws_subnet.private :
    subnet.id
  ]
}

// File: private_route_table.tf
resource "aws_route_table" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      "Name" = "${var.base_name}-private-route-table-${count.index}"
    },
    var.tags
  )
}

resource "aws_route" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.ngw[count.index].id
}

resource "aws_route_table_association" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

// File: public_route_table.tf
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      "Name" = "${var.base_name}-public-route-table"
    },
    var.tags
  )
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.gw.id
}

resource "aws_route_table_association" "public" {
  count = length(var.subnet_public_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

// File: sg.tf
resource "aws_security_group" "ecr_endpoint" {
  name        = "${var.base_name}-ecr-endpoint-sg"
  vpc_id      = aws_vpc.main.id
  description = "For ECR Endpoint"

  tags = merge(
    {
      "Name" = "${var.base_name}-ecr-endpoint-sg"
    },
    var.tags
  )

  ingress {
    description = "Allow ECR access from subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.subnet_public_cidrs
  }

  egress {
    description = "Allow any"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group_rule" "ecr_endpont_private" {
  count = var.subnet_private_cidrs == null ? 0 : 1

  description = "Allow ECR access from subnets"
  from_port   = 443
  to_port     = 443
  protocol    = "tcp"
  cidr_blocks = var.subnet_private_cidrs
  security_group_id = aws_security_group.ecr_endpoint.id
  type = "ingress"
}

// File: subent.tf
data "aws_availability_zones" "available" {}

resource "aws_subnet" "public" {
  count = length(var.subnet_public_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = merge(
    {
      "Name"                                   = "${var.base_name}-public-subnet-${count.index}"
    },
    var.tags
  )
}

resource "aws_subnet" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = merge(
    {
      "Name"                                   = "${var.base_name}-private-subnet-${count.index}",
    },
    var.tags
  )
}

// File: variables.tf
# common parameter
variable "tags" {
  description = "リソース群に付与する共通タグ"
  type        = map(string)
  default     = {}
}

variable "base_name" {
  description = "作成するリソースに付与する接頭語"
  type        = string
  default     = "benchmark"
}

# module parameter
variable "vpc_cidr" {
  description = "VPCのネットワークアドレス帯"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "パブリックサブネットのアドレス帯"
  type        = list(string)
  default     = ["10.0.1.0/24","10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "プライベートサブネットのアドレス帯"
  type        = list(string)
  default     = null
}

// File: vpc.tf
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = merge(
    {
      "Name"                                   = "${var.base_name}-vpc",
      "kubernetes.io/cluster/${var.base_name}" = "shared"
    },
    var.tags
  )
}

// File: var.tf
#provider
variable "aws_region" {
