}
# pubsub-2
variable "subpub2" {
  type        = string 
  description = "subnet"
  default     = "10.0.2.0/24" 
}
# pvtsub-1
variable "subpvt1" {
  type        = string 
  description = "subnet"
  default     = "10.0.3.0/24" 
}
# pvtsub-2
variable "subpvt2" {
  type        = string 
  description = "subnet"
  default     = "10.0.4.0/24" 
}
# azpub-1
variable "azpub1" {
  type        = string 
  description = "subnet"
  default     = "eu-central-1a" 
}
# azpub-2
variable "az_sub_pub2" {
  type        = string 
  description = "subnet"
