// File: outputs.tf
#---------------------------------------------------
# Route53 zone
#---------------------------------------------------
output "aws_route53_zone_id" {
  description = "The Hosted Zone ID. This can be referenced by zone records."
  value       = element(concat(aws_route53_zone.route53_zone.*.id, [""]), 0)
}

output "aws_route53_zone_zone_id" {
  description = "The Hosted Zone ID. This can be referenced by zone records."
  value       = element(concat(aws_route53_zone.route53_zone.*.zone_id, [""]), 0)
}

output "aws_route53_zone_name_servers" {
  description = "A list of name servers in associated (or default) delegation set. Find more about delegation sets in AWS docs."
  value       = concat(aws_route53_zone.route53_zone.*.name_servers, [""])
}

#---------------------------------------------------
# Route53 record
#---------------------------------------------------
output "route53_record_name" {
  description = "Get route53 record name"
  value       = element(concat(aws_route53_record.route53_record.*.name, [""]), 0)
}

output "route53_record_fqdn" {
  description = "FQDN built using the zone domain and name."
  value       = element(concat(aws_route53_record.route53_record.*.fqdn, [""]), 0)
}

#---------------------------------------------------
# Route53 delegation set
#---------------------------------------------------
output "route53_delegation_set_id" {
  description = "The delegation set ID"
  value       = element(concat(aws_route53_delegation_set.route53_delegation_set.*.id, [""]), 0)
}

output "route53_delegation_set_name_servers" {
  description = "A list of authoritative name servers for the hosted zone (effectively a list of NS records)."
  value       = concat(aws_route53_delegation_set.route53_delegation_set.*.name_servers, [""])
}

#---------------------------------------------------
# Route53 zone association
#---------------------------------------------------
output "route53_zone_association_id" {
  description = "The calculated unique identifier for the association."
  value       = element(concat(aws_route53_zone_association.route53_zone_association.*.id, [""]), 0)
}

output "route53_zone_association_zone_id" {
  description = "The ID of the hosted zone for the association."
  value       = element(concat(aws_route53_zone_association.route53_zone_association.*.zone_id, [""]), 0)
}

output "route53_zone_association_vpc_id" {
  description = "The ID of the VPC for the association."
  value       = element(concat(aws_route53_zone_association.route53_zone_association.*.vpc_id, [""]), 0)
}

output "route53_zone_association_vpc_region" {
  description = "The region in which the VPC identified by vpc_id was created."
  value       = element(concat(aws_route53_zone_association.route53_zone_association.*.vpc_region, [""]), 0)
}

#---------------------------------------------------
# Route53 query log
#---------------------------------------------------
output "route53_query_log_id" {
  description = "The query logging configuration ID"
  value       = element(concat(aws_route53_query_log.route53_query_log.*.id, [""]), 0)
}

#---------------------------------------------------
# Route53 query log
#---------------------------------------------------
output "route53_health_check_id" {
  description = "The query logging configuration ID"
  value       = element(concat(aws_route53_health_check.route53_health_check.*.id, [""]), 0)
}

#---------------------------------------------------
# AWS route53 vpc association authorization
#---------------------------------------------------
output "route53_vpc_association_authorization_id" {
  description = "The calculated unique identifier for the association."
  value       = element(concat(aws_route53_vpc_association_authorization.route53_vpc_association_authorization.*.id, [""]), 0)
}

#---------------------------------------------------
# AWS Route53 key signing key
#---------------------------------------------------
output "route53_key_signing_key_id" {
  description = "Route 53 Hosted Zone identifier and KMS Key identifier, separated by a comma (,)."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.id, [""]), 0)
}

output "route53_key_signing_key_digest_algorithm_mnemonic" {
  description = "A string used to represent the delegation signer digest algorithm. This value must follow the guidelines provided by RFC-8624 Section 3.3."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.digest_algorithm_mnemonic, [""]), 0)
}

output "route53_key_signing_key_digest_algorithm_type" {
  description = "An integer used to represent the delegation signer digest algorithm. This value must follow the guidelines provided by RFC-8624 Section 3.3."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.digest_algorithm_type, [""]), 0)
}

output "route53_key_signing_key_digest_value" {
  description = "A cryptographic digest of a DNSKEY resource record (RR). DNSKEY records are used to publish the public key that resolvers can use to verify DNSSEC signatures that are used to secure certain kinds of information provided by the DNS system."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.digest_value, [""]), 0)
}

output "route53_key_signing_key_dnskey_record" {
  description = "A string that represents a DNSKEY record."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.dnskey_record, [""]), 0)
}

output "route53_key_signing_key_ds_record" {
  description = "A string that represents a delegation signer (DS) record."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.ds_record, [""]), 0)
}

output "route53_key_signing_key_flag" {
  description = "An integer that specifies how the key is used. For key-signing key (KSK), this value is always 257."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.flag, [""]), 0)
}

output "route53_key_signing_key_key_tag" {
  description = "An integer used to identify the DNSSEC record for the domain name. The process used to calculate the value is described in RFC-4034 Appendix B."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.key_tag, [""]), 0)
}

output "route53_key_signing_key_public_key" {
  description = "The public key, represented as a Base64 encoding, as required by RFC-4034 Page 5."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.public_key, [""]), 0)
}

output "route53_key_signing_key_signing_algorithm_mnemonic" {
  description = "A string used to represent the signing algorithm. This value must follow the guidelines provided by RFC-8624 Section 3.1."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.signing_algorithm_mnemonic, [""]), 0)
}

output "route53_key_signing_key_signing_algorithm_type" {
  description = "An integer used to represent the signing algorithm. This value must follow the guidelines provided by RFC-8624 Section 3.1."
  value       = element(concat(aws_route53_key_signing_key.route53_key_signing_key.*.signing_algorithm_type, [""]), 0)
}

// File: route53_delegation_set.tf
#---------------------------------------------------
# AWS Route53 delegation set
#---------------------------------------------------
resource "aws_route53_delegation_set" "route53_delegation_set" {
  count = var.enable_route53_delegation_set ? 1 : 0

  reference_name = var.route53_delegation_set_reference_name

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []

}

// File: route53_health_check.tf
#---------------------------------------------------
# AWS Route53 health check
#---------------------------------------------------
resource "aws_route53_health_check" "route53_health_check" {
  count = var.enable_route53_health_check ? 1 : 0

  type              = var.route53_health_check_type
  failure_threshold = var.route53_health_check_failure_threshold
  request_interval  = var.route53_health_check_request_interval

  # Calculated_route53
  child_health_threshold = var.route53_health_check_child_health_threshold
  child_healthchecks     = var.route53_health_check_child_healthchecks

  # CloudWatch
  cloudwatch_alarm_name           = var.route53_health_check_cloudwatch_alarm_name
  cloudwatch_alarm_region         = var.route53_health_check_cloudwatch_alarm_region
  insufficient_data_health_status = var.route53_health_check_insufficient_data_health_status

  # Other settings
  disabled           = var.route53_health_check_disabled
  fqdn               = var.route53_health_check_fqdn
  reference_name     = var.route53_health_check_reference_name
  port               = var.route53_health_check_port
  ip_address         = var.route53_health_check_ip_address
  resource_path      = var.route53_health_check_resource_path
  measure_latency    = var.route53_health_check_measure_latency
  search_string      = var.route53_health_check_search_string
  invert_healthcheck = var.route53_health_check_invert_healthcheck
  enable_sni         = var.route53_health_check_enable_sni
  regions            = var.route53_health_check_regions

  tags = merge(
    {
      Name = var.route53_health_check_name != "" ? lower(var.route53_health_check_name) : "${lower(var.name)}-route53-hc-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: route53_hosted_zone_dnssec.tf
#---------------------------------------------------
# route53 hosted zone dnssec
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/route53_hosted_zone_dnssec

// File: route53_key_signing_key.tf
#---------------------------------------------------
# AWS Route53 key signing key
#---------------------------------------------------
resource "aws_route53_key_signing_key" "route53_key_signing_key" {
  count = var.enable_route53_key_signing_key ? 1 : 0

  name                       = var.route53_key_signing_key_name != "" ? lower(var.route53_zone_name) : "${lower(var.name)}-route53-key-signing-key-${lower(var.environment)}"
  hosted_zone_id             = var.route53_key_signing_key_hosted_zone_id != "" ? var.route53_key_signing_key_hosted_zone_id : (var.enable_route53_zone ? element(aws_route53_zone.route53_zone.*.id, 0) : null)
  key_management_service_arn = var.route53_key_signing_key_key_management_service_arn

  status = var.route53_key_signing_key_status != null ? upper(var.route53_key_signing_key_status) : null

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: route53_query_log.tf
#---------------------------------------------------
# AWS Route53 query log
#---------------------------------------------------
resource "aws_route53_query_log" "route53_query_log" {
  count = var.enable_route53_query_log ? 1 : 0

  cloudwatch_log_group_arn = var.route53_query_log_cloudwatch_log_group_arn
  zone_id                  = var.route53_query_log_zone_id != "" ? var.route53_query_log_zone_id : (var.enable_route53_zone ? element(aws_route53_zone.route53_zone.*.id, 0) : null)

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_route53_zone.route53_zone
  ]
}

// File: route53_record.tf
#---------------------------------------------------
# AWS Route53 record
#---------------------------------------------------
resource "aws_route53_record" "route53_record" {
  count = var.enable_route53_record ? 1 : 0

  name    = var.route53_record_name
  zone_id = var.route53_record_parent_zone_id != "" && !var.enable_route53_zone ? var.route53_record_parent_zone_id : element(aws_route53_zone.route53_zone.*.id, 0)
  type    = var.route53_record_type
  ttl     = var.route53_record_ttl
  records = var.route53_record_records

  health_check_id                  = var.route53_record_health_check_id != null && !var.enable_route53_health_check ? var.route53_record_health_check_id : element(concat(aws_route53_health_check.route53_health_check.*.id, [""]), 0)
  multivalue_answer_routing_policy = var.route53_record_multivalue_answer_routing_policy
  allow_overwrite                  = var.route53_record_allow_overwrite

  set_identifier = var.route53_record_set_identifier != null ? lower(var.route53_record_set_identifier) : null

  dynamic "failover_routing_policy" {
    iterator = failover_routing_policy
    for_each = var.route53_record_failover_routing_policy

    content {
      type = lookup(failover_routing_policy.value, "type", null)
    }
  }

  dynamic "geolocation_routing_policy" {
    iterator = geolocation_routing_policy
    for_each = var.route53_record_geolocation_routing_policy

    content {
      continent   = lookup(geolocation_routing_policy.value, "continent", null)
      country     = lookup(geolocation_routing_policy.value, "country", null)
      subdivision = lookup(geolocation_routing_policy.value, "subdivision", null)
    }
  }

  dynamic "latency_routing_policy" {
    iterator = latency_routing_policy
    for_each = var.route53_record_latency_routing_policy

    content {
      region = lookup(latency_routing_policy.value, "region", null)
    }
  }

  dynamic "weighted_routing_policy" {
    iterator = weighted_routing_policy
    for_each = var.route53_record_weighted_routing_policy

    content {
      weight = lookup(weighted_routing_policy.value, "weight", null)
    }
  }

  dynamic "alias" {
    iterator = alias
    for_each = var.route53_record_alias

    content {
      name                   = lookup(alias.value, "name", null)
      zone_id                = lookup(alias.value, "zone_id", null)
      evaluate_target_health = lookup(alias.value, "evaluate_target_health", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_route53_zone.route53_zone,
    aws_route53_health_check.route53_health_check
  ]
}

// File: route53_traffic_policy.tf
#---------------------------------------------------
# route53 traffic policy
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/route53_traffic_policy

// File: route53_traffic_policy_instance.tf
#---------------------------------------------------
# route53 traffic policy instance
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/route53_traffic_policy_instance

// File: route53_vpc_association_authorization.tf
#---------------------------------------------------
# AWS route53 vpc association authorization
#---------------------------------------------------
resource "aws_route53_vpc_association_authorization" "route53_vpc_association_authorization" {
  count = var.enable_route53_vpc_association_authorization ? 1 : 0

  zone_id = var.route53_vpc_association_authorization_zone_id
  vpc_id  = var.route53_vpc_association_authorization_vpc_id

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: route53_zone.tf
#---------------------------------------------------
# AWS route53 zone
#---------------------------------------------------
resource "aws_route53_zone" "route53_zone" {
  count = var.enable_route53_zone ? 1 : 0

  name = var.route53_zone_name != "" ? lower(var.route53_zone_name) : "${lower(var.name)}-route53-zone-${lower(var.environment)}"

  comment           = var.route53_zone_comment
  force_destroy     = var.route53_zone_force_destroy
  delegation_set_id = var.route53_zone_delegation_set_id

  dynamic "vpc" {
    iterator = vpc
    for_each = var.route53_zone_vpc

    content {
      vpc_id     = lookup(vpc.value, "vpc_id", null)
      vpc_region = lookup(vpc.value, "vpc_region", null)
    }
  }

  tags = merge(
    {
      Name = var.route53_zone_name != "" ? lower(var.route53_zone_name) : "${lower(var.name)}-route53-zone-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: route53_zone_association.tf
#---------------------------------------------------
# AWS route53 zone association
#---------------------------------------------------
resource "aws_route53_zone_association" "route53_zone_association" {
  count = var.enable_route53_zone_association ? 1 : 0

  zone_id = var.route53_zone_association_zone_id != "" ? var.route53_zone_association_zone_id : (var.enable_route53_zone ? element(aws_route53_zone.route53_zone.*.id, 0) : null)
  vpc_id  = var.route53_zone_association_vpc_id

  vpc_region = var.route53_zone_association_vpc_region

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_route53_zone.route53_zone
  ]
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks."
  type        = map(string)
  default     = {}
}

#---------------------------------------------------
# Route53 zone
#---------------------------------------------------
variable "enable_route53_zone" {
  description = "If true, then create route53 zone"
  default     = false
}

variable "route53_zone_name" {
  description = "Domain name for route53_zone"
  default     = "domain.localdomain"
}

variable "route53_zone_comment" {
  description = "(Optional) A comment for the hosted zone. Defaults to 'Managed by Terraform'."
  default     = null
}

variable "route53_zone_force_destroy" {
  description = "(Optional) Whether to destroy all records (possibly managed outside of Terraform) in the zone when destroying the zone."
  default     = null
}

variable "route53_zone_delegation_set_id" {
  description = "(Optional) The ID of the reusable delegation set whose NS records you want to assign to the hosted zone. Conflicts with vpc and vpc_id as delegation sets can only be used for public zones."
  default     = null
}

variable "route53_zone_vpc" {
  description = "(Optional) Configuration block(s) specifying VPC(s) to associate with a private hosted zone. Conflicts with the delegation_set_id argument in this resource and any aws_route53_zone_association resource specifying the same zone ID."
  default     = []
}

#---------------------------------------------------
# Route53 record
#---------------------------------------------------
variable "enable_route53_record" {
  description = "Enable route53 record usage"
  default     = false
}

variable "route53_record_name" {
  description = "Route53 record name"
  default     = null
}

variable "route53_record_type" {
  description = "The record type. Valid values are A, AAAA, CAA, CNAME, MX, NAPTR, NS, PTR, SOA, SPF, SRV and TXT"
  default     = "A"
}

variable "route53_record_ttl" {
  description = "Route53 record ttl"
  default     = null
}

variable "route53_record_parent_zone_id" {
  description = "Perent Zone ID"
  default     = ""
}

variable "route53_record_alias" {
  description = "(Optional) An alias block. Conflicts with route53_record_ttl & route53_record_records."
  default     = []
}

variable "route53_record_records" {
  description = "(Required for non-alias records) A string list of records. To specify a single record value longer than 255 characters such as a TXT record for DKIM, add \\ inside the Terraform configuration string."
  default     = []
}

variable "route53_record_set_identifier" {
  description = "(Optional) Unique identifier to differentiate records with routing policies from one another. Required if using failover, geolocation, latency, or weighted routing policies documented below."
  default     = null
}

variable "route53_record_weighted_routing_policy" {
  description = "(Optional) A block indicating a weighted routing policy. Conflicts with any other routing policy."
  default     = []
}

variable "route53_record_health_check_id" {
  description = "(Optional) The health check the record should be associated with."
  default     = null
}

variable "route53_record_failover_routing_policy" {
  description = "(Optional) A block indicating the routing behavior when associated health check fails. Conflicts with any other routing policy."
  default     = []
}

variable "route53_record_geolocation_routing_policy" {
  description = "(Optional) A block indicating a routing policy based on the geolocation of the requestor. Conflicts with any other routing policy."
  default     = []
}

variable "route53_record_latency_routing_policy" {
  description = "(Optional) A block indicating a routing policy based on the latency between the requestor and an AWS region. Conflicts with any other routing policy."
  default     = []
}

variable "route53_record_multivalue_answer_routing_policy" {
  description = "(Optional) Set to true to indicate a multivalue answer routing policy. Conflicts with any other routing policy."
  default     = null
}

variable "route53_record_allow_overwrite" {
  description = "(Optional) Allow creation of this record in Terraform to overwrite an existing record, if any. This does not affect the ability to update the record in Terraform and does not prevent other resources within Terraform or manual Route 53 changes outside Terraform from overwriting this record. false by default. This configuration is not recommended for most environments."
  default     = false
}

#---------------------------------------------------
# Route53 HC
#---------------------------------------------------
variable "enable_route53_health_check" {
  description = "Create http route53 health check"
  default     = false
}

variable "route53_health_check_name" {
  description = "Name for route53 HC"
  default     = ""
}

variable "route53_health_check_type" {
  description = "(Required) The protocol to use when performing health checks. Valid values are HTTP, HTTPS, HTTP_STR_MATCH, HTTPS_STR_MATCH, TCP, CALCULATED and CLOUDWATCH_METRIC."
  default     = "HTTP"
}

variable "route53_health_check_failure_threshold" {
  description = "(Required) Failure threshold for http route53 health check"
  default     = null
}

variable "route53_health_check_request_interval" {
  description = "(Required) Request interval for http route53 health check"
  default     = null
}

variable "route53_health_check_fqdn" {
  description = "FQDN for http route53 health check"
  default     = null
}

variable "route53_health_check_port" {
  description = "Port for http route53 health check"
  default     = null
}

variable "route53_health_check_resource_path" {
  description = "(Optional) Resource path for http route53 health check"
  default     = null
}

variable "route53_health_check_measure_latency" {
  description = "(Optional) measure latency for http route53 health check"
  default     = null
}

variable "route53_health_check_child_health_threshold" {
  description = "(Optional) The minimum number of child health checks that must be healthy for Route 53 to consider the parent health check to be healthy. Valid values are integers between 0 and 256, inclusive"
  default     = null
}

variable "route53_health_check_child_healthchecks" {
  description = "(Optional) For a specified parent health check, a list of HealthCheckId values for the associated child health checks."
  default     = null
}

variable "route53_health_check_cloudwatch_alarm_name" {
  description = "(Optional) The name of the CloudWatch alarm."
  default     = null
}

variable "route53_health_check_cloudwatch_alarm_region" {
  description = "(Optional) The CloudWatchRegion that the CloudWatch alarm was created in."
  default     = null
}

variable "route53_health_check_insufficient_data_health_status" {
  description = "(Optional) The status of the health check when CloudWatch has insufficient data about the state of associated alarm. Valid values are Healthy , Unhealthy and LastKnownStatus."
  default     = null
}

variable "route53_health_check_disabled" {
  description = "(Optional) A boolean value that stops Route 53 from performing health checks. "
  default     = null
}

variable "route53_health_check_reference_name" {
  description = "(Optional) This is a reference name used in Caller Reference (helpful for identifying single health_check set amongst others)"
  default     = null
}

variable "route53_health_check_ip_address" {
  description = "(Optional) The IP address of the endpoint to be checked."
  default     = null
}

variable "route53_health_check_search_string" {
  description = "(Optional) String searched in the first 5120 bytes of the response body for check to be considered healthy. Only valid with HTTP_STR_MATCH and HTTPS_STR_MATCH."
  default     = null
}

variable "route53_health_check_invert_healthcheck" {
  description = "(Optional) A boolean value that indicates whether the status of health check should be inverted. For example, if a health check is healthy but Inverted is True , then Route 53 considers the health check to be unhealthy."
  default     = null
}

variable "route53_health_check_enable_sni" {
  description = "(Optional) A boolean value that indicates whether Route53 should send the fqdn to the endpoint when performing the health check. This defaults to AWS' defaults: when the type is 'HTTPS' enable_sni defaults to true, when type is anything else enable_sni defaults to false."
  default     = null
}

variable "route53_health_check_regions" {
  description = "(Optional) A list of AWS regions that you want Amazon Route 53 health checkers to check the specified endpoint from."
  default     = null
}

#---------------------------------------------------
# Route53 delegation set
#---------------------------------------------------
variable "enable_route53_delegation_set" {
  description = "Enable route53 delegation set usage"
  default     = false
}

variable "route53_delegation_set_reference_name" {
  description = "(Optional) This is a reference name used in Caller Reference (helpful for identifying single delegation set amongst others)"
  default     = null
}

#---------------------------------------------------
# Route53 zone association
#---------------------------------------------------
variable "enable_route53_zone_association" {
  description = "Enable route53 zone association"
  default     = false
}

variable "route53_zone_association_zone_id" {
  description = "(Required) The private hosted zone to associate."
  default     = ""
}

variable "route53_zone_association_vpc_id" {
  description = "(Required) The VPC to associate with the private hosted zone."
  default     = ""
}

variable "route53_zone_association_vpc_region" {
  description = "(Optional) The VPC's region. Defaults to the region of the AWS provider."
  default     = ""
}

#---------------------------------------------------
# Route53 query log
#---------------------------------------------------
variable "enable_route53_query_log" {
  description = "Enable route53 query log usage"
  default     = false
}

variable "route53_query_log_cloudwatch_log_group_arn" {
  description = "(Required) CloudWatch log group ARN to send query logs."
  default     = ""
}

variable "route53_query_log_zone_id" {
  description = "(Required) Route53 hosted zone ID to enable query logs."
  default     = ""
}

#---------------------------------------------------
# AWS route53 vpc association authorization
#---------------------------------------------------
variable "enable_route53_vpc_association_authorization" {
  description = "Enable route53 vpc association authorization usage"
  default     = false
}

variable "route53_vpc_association_authorization_zone_id" {
  description = "(Required) The private hosted zone to associate."
  default     = ""
}

variable "route53_vpc_association_authorization_vpc_id" {
  description = "(Required) The VPC to associate with the private hosted zone."
  default     = ""
}

#---------------------------------------------------
# AWS Route53 key signing key
#---------------------------------------------------
variable "enable_route53_key_signing_key" {
  description = "Enable Route53 key signing key usage"
  default     = false
}

variable "route53_key_signing_key_name" {
  description = "Name of the key-signing key (KSK). Must be unique for each key-singing key in the same hosted zone."
  default     = ""
}

variable "route53_key_signing_key_hosted_zone_id" {
  description = "Identifier of the Route 53 Hosted Zone."
  default     = ""
}

variable "route53_key_signing_key_key_management_service_arn" {
  description = "(Required) Amazon Resource Name (ARN) of the Key Management Service (KMS) Key. This must be unique for each key-signing key (KSK) in a single hosted zone. This key must be in the us-east-1 Region and meet certain requirements, which are described in the Route 53 Developer Guide and Route 53 API Reference."
  default     = null
}

variable "route53_key_signing_key_status" {
  description = "(Optional) Status of the key-signing key (KSK). Valid values: ACTIVE, INACTIVE. Defaults to ACTIVE"
  default     = null
}

// File: main.tf
/*
ECS Service
*/

// AWS IAM Linked Role used for ecs service
resource "aws_iam_role" "ecs_service" {
  name               = "ecsServiceRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_service.json
}

// AWS IAM Role Policy used for ecs service
resource "aws_iam_role_policy" "ecs_service" {
  name   = "ecsTaskRolePolicy"
  policy = data.aws_iam_policy_document.ecs_service_policy.json
  role   = aws_iam_role.ecs_service.id
}

// AWS IAM Policy in format JSON for linked role ecs service
data "aws_iam_policy_document" "ecs_service_policy" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "elasticloadbalancing:Describe*",
      "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
      "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
      "ec2:Describe*",
      "ec2:AuthorizeSecurityGroupIngress",
      "ssm:GetParameters",
      "secretsmanager:GetSecretValue",
      "kms:Decrypt",
      "codedeploy:CreateApplication",
      "codedeploy:CreateDeployment",
      "codedeploy:CreateDeploymentGroup",
      "codedeploy:GetApplication",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentGroup",
      "codedeploy:ListApplications",
      "codedeploy:ListDeploymentGroups",
      "codedeploy:ListDeployments",
      "codedeploy:StopDeployment",
      "codedeploy:GetDeploymentTarget",
      "codedeploy:ListDeploymentTargets",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:GetApplicationRevision",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:BatchGetApplicationRevisions",
      "codedeploy:BatchGetDeploymentGroups",
      "codedeploy:BatchGetDeployments",
      "codedeploy:BatchGetApplications",
      "codedeploy:ListApplicationRevisions",
      "codedeploy:ListDeploymentConfigs",
      "codedpeloy:ContinueDeployment",
      "sns:ListTopics",
      "cloudwatch:DescribeAlarms",
      "lambda:ListFunctions",
    ]
  }
}

// AWS IAM Policy in format JSON for linked role ecs task
data "aws_iam_policy_document" "ecs_service" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"

      identifiers = [
        "ecs.amazonaws.com",
        "s3.amazonaws.com",
      ]
    }
  }
}

/*
ECS Execution
*/

// IAM Policy for task execution role
data "aws_iam_policy_document" "ecs_exec" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecs:DescribeTaskDefinition",
      "ecs:ListServices",
      "ecs:DescribeServices",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "secretsmanager:GetSecretValue",
      "kms:Decrypt",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParameterHistory",
      "ssm:GetParametersByPath",
    ]
  }
}

// AWS IAM Role used for ecs task execution
resource "aws_iam_role" "ecs_exec" {
  name               = "ecsExecTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_exec.json
}

// AWS IAM Role Policy used for ecs task execution
resource "aws_iam_role_policy" "ecs_exec" {
  name   = "ecsExecRolePolicy"
  policy = data.aws_iam_policy_document.ecs_exec.json
  role   = aws_iam_role.ecs_exec.id
}

data "aws_iam_policy_document" "additional_permissions_ecs_execution" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices",
    ]
  }

  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = ["s3:*"]
  }
}

// Additional permissions task execution
resource "aws_iam_role_policy" "additional_permissions_ecs_execution" {
  name   = "ecsExecution_additional"
  role   = aws_iam_role.ecs_exec.id
  policy = data.aws_iam_policy_document.additional_permissions_ecs_execution.json
}

/*
ECS Task
*/

// AWS IAM Policy in format JSON for linked role ecs task
data "aws_iam_policy_document" "ecs_task" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"

      identifiers = [
        "ecs-tasks.amazonaws.com",
        "s3.amazonaws.com",
      ]
    }
  }
}

// - IAM role that the Amazon ECS container agent and the Docker daemon can assume
data "aws_iam_policy_document" "ecs_task_exec" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"

      identifiers = [
        "ecs-tasks.amazonaws.com",
        "s3.amazonaws.com",
      ]
    }
  }
}

// AWS IAM Role used for ecs task
