// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks. Each element should have keys named key, value, etc."
  type        = map(string)
  default     = {}
}

#---------------------------------------------------
# AWS EC2 transit gateway
#---------------------------------------------------
variable "enable_transit_gateway" {
  description = "Enable transit gateway"
  default     = false
}

variable "transit_gateway_name" {
  description = "Set name for TGW"
  default     = ""
}

variable "transit_gateway_amazon_side_asn" {
  description = "(Optional) Private Autonomous System Number (ASN) for the Amazon side of a BGP session. The range is 64512 to 65534 for 16-bit ASNs and 4200000000 to 4294967294 for 32-bit ASNs. Default value: 64512."
  default     = 64512
}

variable "transit_gateway_auto_accept_shared_attachments" {
  description = "(Optional) Whether resource attachment requests are automatically accepted. Valid values: disable, enable. Default value: disable"
  default     = "disable"
}

variable "transit_gateway_default_route_table_association" {
  description = "(Optional) Whether resource attachments are automatically associated with the default association route table. Valid values: disable, enable. Default value: enable"
  default     = "enable"
}

variable "transit_gateway_default_route_table_propagation" {
  description = "(Optional) Whether resource attachments automatically propagate routes to the default propagation route table. Valid values: disable, enable. Default value: enable"
  default     = "enable"
}

variable "transit_gateway_description" {
  description = "(Optional) Description of the EC2 Transit Gateway."
  default     = null
}

variable "transit_gateway_dns_support" {
  description = "(Optional) Whether DNS support is enabled. Valid values: disable, enable. Default value: enable"
  default     = "enable"
}

variable "transit_gateway_vpn_ecmp_support" {
  description = "(Optional) Whether VPN Equal Cost Multipath Protocol support is enabled. Valid values: disable, enable. Default value: enable"
  default     = "enable"
}

#---------------------------------------------------
# AWS EC2 transit gateway vpc attachment
#---------------------------------------------------
variable "enable_transit_gateway_vpc_attachment" {
  description = "Enable TGW vpc attachment usage"
  default     = false
}

variable "transit_gateway_vpc_attachment_name" {
  description = "Set name for TGW VPC attachment"
  default     = ""
}

variable "transit_gateway_vpc_attachment_subnet_ids" {
  description = "(Required) Identifiers of EC2 Subnets."
  default     = []
}

variable "transit_gateway_vpc_attachment_transit_gateway_id" {
  description = "Identifier of EC2 Transit Gateway."
  default     = ""
}

variable "transit_gateway_vpc_attachment_vpc_id" {
  description = "(Required) Identifier of EC2 VPC."
  default     = ""
}

variable "transit_gateway_vpc_attachment_appliance_mode_support" {
  description = "(Optional) Whether Appliance Mode support is enabled. If enabled, a traffic flow between a source and destination uses the same Availability Zone for the VPC attachment for the lifetime of that flow. Valid values: disable, enable. Default value: disable."
  default     = "disable"
}

variable "transit_gateway_vpc_attachment_dns_support" {
  description = "(Optional) Whether DNS support is enabled. Valid values: disable, enable. Default value: enable."
  default     = "enable"
}

variable "transit_gateway_vpc_attachment_ipv6_support" {
  description = "(Optional) Whether IPv6 support is enabled. Valid values: disable, enable. Default value: disable."
  default     = "disable"
}

variable "transit_gateway_vpc_attachment_transit_gateway_default_route_table_association" {
  description = "(Optional) Boolean whether the VPC Attachment should be associated with the EC2 Transit Gateway association default route table. This cannot be configured or perform drift detection with Resource Access Manager shared EC2 Transit Gateways. Default value: true"
  default     = true
}

variable "transit_gateway_vpc_attachment_transit_gateway_default_route_table_propagation" {
  description = "(Optional) Boolean whether the VPC Attachment should propagate routes with the EC2 Transit Gateway propagation default route table. This cannot be configured or perform drift detection with Resource Access Manager shared EC2 Transit Gateways. Default value: true"
  default     = true
}

#---------------------------------------------------
# AWS EC2 transit gateway vpc attachment accepter
#---------------------------------------------------
variable "enable_transit_gateway_vpc_attachment_accepter" {
  description = "Enable TGW vpc attachment accepter usage"
  default     = false
}

variable "transit_gateway_vpc_attachment_accepter_name" {
  description = "Set name for TGW VPC attachment acceper"
  default     = ""
}

variable "transit_gateway_vpc_attachment_accepter_transit_gateway_attachment_id" {
  description = "The ID of the EC2 Transit Gateway Attachment to manage."
  default     = ""
}

variable "transit_gateway_vpc_attachment_accepter_transit_gateway_default_route_table_association" {
  description = "(Optional) Boolean whether the VPC Attachment should be associated with the EC2 Transit Gateway association default route table. Default value: true."
  default     = true
}

variable "transit_gateway_vpc_attachment_accepter_transit_gateway_default_route_table_propagation" {
  description = "(Optional) Boolean whether the VPC Attachment should propagate routes with the EC2 Transit Gateway propagation default route table. Default value: true."
  default     = true
}

#---------------------------------------------------
# AWS EC2 transit gateway route table
#---------------------------------------------------
variable "enable_transit_gateway_route_table" {
  description = "Enable TGW route table usage"
  default     = false
}

variable "transit_gateway_route_table_name" {
  description = "Set name for TGV route table"
  default     = ""
}

variable "transit_gateway_route_table_transit_gateway_id" {
  description = "Set an identifier of EC2 Transit Gateway."
  default     = ""
}

#---------------------------------------------------
# AWS EC2 transit gateway route
#---------------------------------------------------
variable "enable_transit_gateway_route" {
  description = "Enable TGW route usage"
  default     = false
}

variable "transit_gateway_route_destination_cidr_blocks" {
  description = "(Required) IPv4 or IPv6 RFC1924 CIDR list used for destination matches. Routing decisions are based on the most specific match."
  default     = ["0.0.0.0/0"]
}

variable "transit_gateway_route_transit_gateway_route_table_id" {
  description = "Set an identifier of EC2 Transit Gateway Route Table."
  default     = ""
}

variable "transit_gateway_route_transit_gateway_attachment_id" {
  description = "(Optional) Identifier of EC2 Transit Gateway Attachment (required if blackhole is set to false)."
  default     = ""
}

variable "transit_gateway_route_blackhole" {
  description = "(Optional) Indicates whether to drop traffic that matches this route (default to false)."
  default     = false
}

#---------------------------------------------------
# AWS EC2 transit gateway route table propagation
#---------------------------------------------------
variable "enable_transit_gateway_route_table_propagation" {
  description = "Enable TGE route table propagation usage"
  default     = false
}

variable "transit_gateway_route_table_propagation_transit_gateway_attachment_id" {
  description = "Set an identifier of EC2 Transit Gateway Attachment."
  default     = ""
}

variable "transit_gateway_route_table_propagation_transit_gateway_route_table_id" {
  description = "Set an identifier of EC2 Transit Gateway Route Table."
  default     = ""
}

#---------------------------------------------------
# AWS EC2 transit gateway route table association
#---------------------------------------------------
variable "enable_transit_gateway_route_table_association" {
  description = "Enable TGW route table association usage"
  default     = false
}

variable "transit_gateway_route_table_association_transit_gateway_attachment_id" {
  description = "Set an identifier of EC2 Transit Gateway Attachment."
  default     = ""
}

variable "transit_gateway_route_table_association_transit_gateway_route_table_id" {
  description = "Set an identifier of EC2 Transit Gateway Route Table."
  default     = ""
}

#---------------------------------------------------
# AWS EC2 transit gateway peering attachment
#---------------------------------------------------
variable "enable_transit_gateway_peering_attachment" {
  description = "Enable TGW peering attachment usage"
  default     = false
}

variable "transit_gateway_peering_attachment_peer_account_id" {
  description = "(Optional) Account ID of EC2 Transit Gateway to peer with. Defaults to the account ID the AWS provider is currently connected to."
  default     = null
}

variable "transit_gateway_peering_attachment_peer_transit_gateway_id" {
  description = "Set an identifier of EC2 Transit Gateway to peer with."
  default     = ""
}

variable "transit_gateway_peering_attachment_name" {
  description = "Set name for TGW peering attachment"
  default     = ""
}

variable "transit_gateway_peering_attachment_peer_region" {
  description = "(Required) Region of EC2 Transit Gateway to peer with."
  default     = null
}

variable "transit_gateway_peering_attachment_transit_gateway_id" {
  description = "(Required) Identifier of EC2 Transit Gateway."
  default     = null
}

#---------------------------------------------------
# AWS EC2 transit gateway peering attachment accepter
#---------------------------------------------------
variable "enable_transit_gateway_peering_attachment_accepter" {
  description = "Enable TGW peering attachment accepter usage"
  default     = false
}

variable "transit_gateway_peering_attachment_accepter_name" {
  description = "Set name for TGW peering attachment accepter"
  default     = ""
}

variable "transit_gateway_peering_attachment_accepter_transit_gateway_attachment_id" {
  description = "The ID of the EC2 Transit Gateway Peering Attachment to manage."
  default     = ""
}

// File: data.tf
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  availability_zone           = data.aws_availability_zones.available.names[0]
  secondary_availability_zone = data.aws_availability_zones.available.names[1]
  vpc_cidr_block              = "10.32.0.0/20"
}

// File: outputs.tf
output "vpc" {
  description = "The dev VPC"
  value       = aws_vpc.dev-vpc
}

output "db_subnet_id_1" {
  description = "The subnet 1 id of the RDS cluster"
  value       = aws_subnet.lambda-rds-db-subnet-1.id
}

output "db_subnet_id_2" {
  description = "The subnet 2 id of the RDS cluster"
  value       = aws_subnet.lambda-rds-db-subnet-2.id
}

output "db_availability_zone" {
  description = "The availability zone id of the RDS cluster"
  value       = local.availability_zone
}

output "db_security_group_id" {
  description = "The security group id of the RDS cluster"
  value       = aws_security_group.postgres-db.id
}

output "bastion_host_subnet_id" {
  description = "The subnet id of the bastion host"
  value       = aws_subnet.lambda-rds-bastion-host-subnet.id
}

output "bastion_host_security_group_id" {
  description = "The security group id of the Bastion Host"
  value       = aws_security_group.bastion-host.id
}

output "lambda_functions_security_group_id" {
  description = "The security group id of the Lambda Functions"
  value       = aws_security_group.lambda-functions.id
}

output "lambda_functions_subnet_id" {
  description = "The subnet id of the Lambda Functions"
  value       = aws_subnet.lambda-rds-dev-lambda-subnet.id
}

// File: routing.tf
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.dev-vpc.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.dev-vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "bastion-host-route-table" {
  subnet_id      = aws_subnet.lambda-rds-bastion-host-subnet.id
  route_table_id = aws_route_table.public.id
}

// File: security_groups.tf
resource "aws_security_group" "postgres-db" {
  description = "RDS PostgreSQL on dev VPC"
  name        = "lambda-rds-dev-postgres-db"
  vpc_id      = aws_vpc.dev-vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = -1
    cidr_blocks = [
      local.vpc_cidr_block,
    ]
  }
}

resource "aws_security_group_rule" "postgres-db-ingress-bastion-rule" {
  security_group_id        = aws_security_group.postgres-db.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  type                     = "ingress"
  source_security_group_id = aws_security_group.bastion-host.id
}

resource "aws_security_group_rule" "postgres-db-ingress-lambda-rule" {
  security_group_id        = aws_security_group.postgres-db.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  type                     = "ingress"
  source_security_group_id = aws_security_group.lambda-functions.id
}

resource "aws_security_group" "lambda-functions" {
  description = "Lambda functions running on the dev VPC"
  name        = "lambda-rds-dev-lambda-functions"
  vpc_id      = aws_vpc.dev-vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = -1
    cidr_blocks = [
      local.vpc_cidr_block,
    ]
  }
}

#tfsec:ignore:aws-ec2-no-public-ingress-sgr
resource "aws_security_group" "bastion-host" {
  description = "Bastion host to access RDS DB"
  name        = "lambda-rds-dev-bastion-host"
  vpc_id      = aws_vpc.dev-vpc.id

  egress {
    from_port       = 0
    to_port         = 0
    protocol        = -1
    security_groups = [
      aws_security_group.postgres-db.id
    ]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
}

// File: subnets.tf
resource "aws_subnet" "lambda-rds-db-subnet-1" {
  vpc_id            = aws_vpc.dev-vpc.id
  availability_zone = local.availability_zone
  cidr_block        = "10.32.0.0/28"

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "lambda-rds-db-subnet-2" {
  vpc_id            = aws_vpc.dev-vpc.id
  availability_zone = local.secondary_availability_zone
  cidr_block        = "10.32.0.16/28"

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "lambda-rds-dev-lambda-subnet" {
  vpc_id            = aws_vpc.dev-vpc.id
  availability_zone = local.availability_zone
  cidr_block        = "10.32.1.0/24"

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

#tfsec:ignore:aws-ec2-no-public-ip-subnet
resource "aws_subnet" "lambda-rds-bastion-host-subnet" {
  vpc_id                  = aws_vpc.dev-vpc.id
  availability_zone       = local.availability_zone
  cidr_block              = "10.32.15.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

// File: vpc.tf
resource "aws_vpc" "dev-vpc" {
  cidr_block           = local.vpc_cidr_block
  enable_dns_hostnames = true

  tags = {
    Name = "lambda-rds-dev"
  }
}

/* Not allow ingress access in the default SG */
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.dev-vpc.id

  egress {
    cidr_blocks = [
      "0.0.0.0/0"
    ]
    from_port = 0
    protocol  = -1
    to_port   = 0
  }

}

/* Manage default NACL
   Allow ingress and egress access */
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.dev-vpc.default_network_acl_id

  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  lifecycle {
    ignore_changes = [subnet_ids]
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

// File: main.tf
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

################################################################################
# Queue
################################################################################

locals {
  name = try(trimsuffix(var.name, ".fifo"), "")
}

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  content_based_deduplication       = var.content_based_deduplication
  deduplication_scope               = var.deduplication_scope
  delay_seconds                     = var.delay_seconds
  fifo_queue                        = var.fifo_queue
  fifo_throughput_limit             = var.fifo_throughput_limit
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  kms_master_key_id                 = var.kms_master_key_id
  max_message_size                  = var.max_message_size
  message_retention_seconds         = var.message_retention_seconds
  name                              = var.use_name_prefix ? null : (var.fifo_queue ? "${local.name}.fifo" : local.name)
  name_prefix                       = var.use_name_prefix ? "${local.name}-" : null
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  sqs_managed_sse_enabled           = var.kms_master_key_id != null ? null : var.sqs_managed_sse_enabled
  visibility_timeout_seconds        = var.visibility_timeout_seconds

  tags = var.tags
}

################################################################################
# Queue Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, [aws_sqs_queue.this[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Re-drive Policy
################################################################################

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && !var.create_dlq && length(var.redrive_policy) > 0 ? 1 : 0

  queue_url      = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode(var.redrive_policy)
}

resource "aws_sqs_queue_redrive_policy" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode(
    merge(
      {
        deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
        maxReceiveCount     = 5
      },
      var.redrive_policy
    )
  )
}

################################################################################
# Dead Letter Queue
################################################################################

locals {
  stripped_dlq_name = try(trimsuffix(var.dlq_name, ".fifo"), "")
  inter_dlq_name    = try(coalesce(local.stripped_dlq_name, "${local.name}-dlq"), "")
  dlq_name          = var.fifo_queue && !var.use_name_prefix ? "${local.inter_dlq_name}.fifo" : local.inter_dlq_name

  dlq_kms_master_key_id       = try(coalesce(var.dlq_kms_master_key_id, var.kms_master_key_id), null)
  dlq_sqs_managed_sse_enabled = coalesce(var.dlq_sqs_managed_sse_enabled, var.sqs_managed_sse_enabled)
}

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  content_based_deduplication = try(coalesce(var.dlq_content_based_deduplication, var.content_based_deduplication), null)
  deduplication_scope         = try(coalesce(var.dlq_deduplication_scope, var.deduplication_scope), null)
  delay_seconds               = try(coalesce(var.dlq_delay_seconds, var.delay_seconds), null)
  # If source queue is FIFO, DLQ must also be FIFO and vice versa
  fifo_queue                        = var.fifo_queue
  fifo_throughput_limit             = var.fifo_throughput_limit
  kms_data_key_reuse_period_seconds = try(coalesce(var.dlq_kms_data_key_reuse_period_seconds, var.kms_data_key_reuse_period_seconds), null)
  kms_master_key_id                 = local.dlq_kms_master_key_id
  max_message_size                  = var.max_message_size
  message_retention_seconds         = try(coalesce(var.dlq_message_retention_seconds, var.message_retention_seconds), null)
  name                              = var.use_name_prefix ? null : local.dlq_name
  name_prefix                       = var.use_name_prefix ? "${local.dlq_name}-" : null
  receive_wait_time_seconds         = try(coalesce(var.dlq_receive_wait_time_seconds, var.receive_wait_time_seconds), null)
  sqs_managed_sse_enabled           = local.dlq_kms_master_key_id != null ? null : local.dlq_sqs_managed_sse_enabled
  visibility_timeout_seconds        = try(coalesce(var.dlq_visibility_timeout_seconds, var.visibility_timeout_seconds), null)

  tags = merge(var.tags, var.dlq_tags)
}

################################################################################
# Queue Policy
################################################################################

data "aws_iam_policy_document" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents   = var.source_dlq_queue_policy_documents
  override_policy_documents = var.override_dlq_queue_policy_documents

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, [aws_sqs_queue.dlq[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = data.aws_iam_policy_document.dlq[0].json
}

################################################################################
# Re-drive Allow Policy
################################################################################

resource "aws_sqs_queue_redrive_allow_policy" "this" {
  count = var.create && !var.create_dlq && length(var.redrive_allow_policy) > 0 ? 1 : 0

  queue_url            = aws_sqs_queue.this[0].url
  redrive_allow_policy = jsonencode(var.redrive_allow_policy)
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  redrive_allow_policy = jsonencode(merge(
    {
      redrivePermission = "byQueue",
      sourceQueueArns   = [aws_sqs_queue.this[0].arn]
    },
    var.dlq_redrive_allow_policy)
  )
}

// File: outputs.tf
################################################################################
# Queue
################################################################################

output "queue_id" {
  description = "The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_arn_static" {
  description = "The ARN of the SQS queue. Use this to avoid cycle errors between resources (e.g., Step Functions)"
  value       = var.create && !var.use_name_prefix ? "arn:aws:sqs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${local.name}" : ""
}

output "queue_url" {
  description = "Same as `queue_id`: The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

################################################################################
# Dead Letter Queue
################################################################################

output "dead_letter_queue_id" {
  description = "The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dead_letter_queue_arn" {
  description = "The ARN of the SQS queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_arn_static" {
  description = "The ARN of the SQS queue. Use this to avoid cycle errors between resources (e.g., Step Functions)"
  value       = var.create && var.create_dlq && !var.use_name_prefix ? "arn:aws:sqs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${local.dlq_name}" : ""
}

output "dead_letter_queue_url" {
  description = "Same as `dead_letter_queue_id`: The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dead_letter_queue_name" {
  description = "The name of the SQS queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

