// File: variables.tf
variable "config" {
  type    = string
  default = "Path to the pipeline configuration file"
}

variable "shared_tags" {
  type        = map(any)
  description = "Additional user defiend resoirce tags"
  default     = {}
}

// File: data.tf
data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

data "aws_iam_policy_document" "logging" {
  count = var.logging_enabled ? 1 : 0

  statement {
    sid    = "AWSTransferLogging"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:CreateLogGroup",
      "logs:PutLogEvents"
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "sftp_user_policy" {
  count = var.create_iam_role ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientRootAccess",
      "elasticfilesystem:ClientRead",
      "elasticfilesystem:ClientExecute",
      "elasticfilesystem:DescribeMountTargets",
      "elasticfilesystem:ClientWrite"
    ]

    resources = [
      aws_efs_file_system.efs.arn
    ]
  }
}

data "aws_iam_policy_document" "assume_role_policy" {
  count = var.logging_enabled ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

// File: efs.tf
resource "aws_efs_file_system" "efs" {
  creation_token                  = var.efs_name
  encrypted                       = var.encrypted
  kms_key_id                      = var.kms_key_id
  performance_mode                = var.performance_mode
  provisioned_throughput_in_mibps = 0
  tags                            = merge({ Name = var.efs_name }, var.tags)
  throughput_mode                 = var.throughput_mode
}

resource "aws_efs_mount_target" "mount_target" {
  for_each        = toset(var.subnets)
  file_system_id  = aws_efs_file_system.efs.id
  subnet_id       = each.value
  security_groups = var.create_efs_security_group ? compact(concat([aws_security_group.efs[0].id], var.security_groups)) : var.security_groups
}

resource "aws_efs_access_point" "user_access_point" {
  for_each = var.enable_user_access_point ? var.sftp_users : {}

  file_system_id = aws_efs_file_system.efs.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }
  root_directory {
    path = each.value.home_directory != null ? format("/%s", each.value.home_directory) : format("/%s", each.key)
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }
  tags = merge({ Name = each.key }, var.tags)
}

resource "aws_efs_access_point" "additional_access_point" {
  for_each = var.additional_access_points

  file_system_id = aws_efs_file_system.efs.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }
  root_directory {
    path = each.value.path
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = each.value.permissions
    }
  }
  tags = merge({ Name = each.key }, var.tags)
}

// File: eip.tf
resource "aws_eip" "eip" {
  count = var.is_public ? length(var.subnets) : 0

  domain = "vpc"

  tags = var.tags
}

// File: iam.tf
resource "aws_iam_role" "sftp_user_role" {
  count = var.create_iam_role ? 1 : 0

  name = "${var.sftp_name}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "sftp_user_policy" {
  count = var.create_iam_role ? 1 : 0

  name   = "${var.sftp_name}-policy"
  path   = "/"
  policy = data.aws_iam_policy_document.sftp_user_policy[count.index].json
}

resource "aws_iam_role_policy_attachment" "sftp_user_policy_attachment" {
  count      = var.create_iam_role ? 1 : 0
  policy_arn = aws_iam_policy.sftp_user_policy[count.index].arn
  role       = aws_iam_role.sftp_user_role[count.index].name
}

resource "aws_iam_policy" "logging" {
  count = var.logging_enabled ? 1 : 0

  name_prefix = "${var.sftp_name}-logging-"
  policy      = join("", data.aws_iam_policy_document.logging[*].json)

  tags = var.tags
}

resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0

  name_prefix         = "${var.sftp_name}-logging-"
  assume_role_policy  = join("", data.aws_iam_policy_document.assume_role_policy[*].json)
  managed_policy_arns = [join("", aws_iam_policy.logging[*].arn)]

  tags = var.tags
}

// File: main.tf
/**
 * # AWS SFTP with EFS Terraform Module
 *
 * This module set up EFS with AWS Transfer Family for accessing AxeTrading server files for managed service customers.
 *
 * # Connect to sftp server: 
 *
 * sftp -i path-to-private-key sftp-username@sftp-server-address
 *
 * # Mounting instructions:
 *
 * Run the following command to install the amazon-efs-utils package: sudo yum install -y amazon-efs-utils
 *
 * sudo mount -t efs -o tls EFS_ID:/ EFS_ID
 *
 * sudo chown -R ec2-user:ec2-user EFS_ID
 *
 * sudo chmod -R 755 EFS_ID
 */

locals {
  role_arn = var.create_iam_role ? aws_iam_role.sftp_user_role[0].arn : var.provided_iam_role_arn
}

# Create AWS Transfer Family SFTP Server
resource "aws_transfer_server" "sftp_server" {
  lifecycle {
    create_before_destroy = true
  }
  identity_provider_type = var.identity_provider_type
  protocols              = ["SFTP"]
  endpoint_type          = var.vpc_id != null ? "VPC" : "PUBLIC"
  security_policy_name   = var.security_policy_name
  domain                 = var.sftp_domain
  logging_role           = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  dynamic "endpoint_details" {
    for_each = var.vpc_id != null ? [1] : []
    content {
      subnet_ids             = var.subnets
      vpc_id                 = var.vpc_id
      security_group_ids     = var.create_sftp_security_group ? compact(concat([aws_security_group.sftp[0].id], var.sftp_security_group_ids)) : var.sftp_security_group_ids
      address_allocation_ids = var.is_public ? aws_eip.eip.*.id : var.eip_ids
    }
  }
  force_destroy = var.identity_provider_type == "SERVICE_MANAGED" ? true : false
  tags          = merge({ Name = var.sftp_name }, var.tags)
}

# Create AWS Transfer Family SFTP User
resource "aws_transfer_user" "sftp_user" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.sftp_server.id
  user_name = each.key

  home_directory_type = var.home_directory_type
  home_directory      = each.value.home_directory != null ? format("/%s/%s", aws_efs_file_system.efs.id, each.value.home_directory) : format("/%s/%s", aws_efs_file_system.efs.id, each.key)

  dynamic "home_directory_mappings" {
    for_each = each.value.restricted ? [true] : []
    content {
      entry  = "/"
      target = "/${aws_efs_file_system.efs.id}/${each.key}"
    }
  }

  posix_profile {
    uid = each.value.uid
    gid = each.value.gid
  }

  role = local.role_arn

  tags = merge({ Name = each.key }, var.tags)

}

### Asociate SFTP User with his ssh public key
resource "aws_transfer_ssh_key" "sftp_ssh_key" {
  for_each  = var.sftp_users
  server_id = aws_transfer_server.sftp_server.id
  user_name = each.key
  body      = each.value.public_key
  depends_on = [
    aws_transfer_user.sftp_user
  ]
}

// File: output.tf
### EFS 
output "efs_file_system_id" {
  description = "EFS ID"
  value       = try(aws_efs_file_system.efs[*].id, "")
}

output "efs_file_system_arn" {
  description = "EFS ARN"
  value       = try(aws_efs_file_system.efs[*].arn, "")
}

output "efs_mount_target_ids" {
  description = "EFS Mount targets"
  value       = try(values(aws_efs_mount_target.mount_target)[*].id, [])

}

output "efs_mount_target_dns_names" {
  description = "EFS Mount targets DNS name"
  value       = try(values(aws_efs_mount_target.mount_target)[*].dns_name, [])
}

### SFTP 
output "sftp_server_arn" {
  description = "SFTP SERVER ARN"
  value       = aws_transfer_server.sftp_server.arn
}

output "sftp_server_id" {
  description = "SFTP SERVER ID"
  value       = aws_transfer_server.sftp_server.id
}

output "sftp_user_usernames" {
  description = "SFTP SERVER USERS"
  value       = [for user in aws_transfer_user.sftp_user : user.user_name]
}

output "sftp_server_endpoint" {
  description = "SFTP SERVER ENDPOINT"
  value       = try(aws_transfer_server.sftp_server.endpoint, "")
}


### IAM
output "iam_role_arn" {
  description = "IAM ROLE ARN used for SFTP users"
  value       = aws_iam_role.sftp_user_role[0].arn
}

### EIP
output "sftp_elastic_ips" {
  description = "Provisioned Elastic IPs"
  value       = var.is_public ? aws_eip.eip.*.id : null
}


# Security Groups

output "sftp_security_group_id" {
  description = "SFTP Security Group ID"
  value       = try(aws_security_group.sftp[0].id, "")
}

output "efs_security_group_id" {
  description = "EFS Security Group ID"
  value       = try(aws_security_group.efs[0].id, "")
}

output "user_access_points" {
  description = "Information about the user-specific EFS access points"
  value = {
    for user, access_point in aws_efs_access_point.user_access_point : user => {
      id             = access_point.id
      arn            = access_point.arn
      file_system_id = access_point.file_system_id
    }
  }
  sensitive = false
}

output "additional_access_points" {
  description = "Information about the general-use EFS access points"
  value = {
    for name, access_point in aws_efs_access_point.additional_access_point : name => {
      id             = access_point.id
      arn            = access_point.arn
      file_system_id = access_point.file_system_id
    }
  }
  sensitive = false
}

// File: security_group_efs.tf
resource "aws_security_group" "efs" {
  count = var.create_efs_security_group ? 1 : 0

  name        = var.efs_security_group_name
  description = "Security Group for EFS Mount"
  vpc_id      = var.vpc_id
  tags        = var.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "efs" {
  for_each = { for k, v in var.efs_security_group_rules : k => v if var.create_efs_security_group }

  # Required
  security_group_id = aws_security_group.efs[0].id
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  type              = each.value.type

  # Optional
  description              = try(each.value.description, null)
  cidr_blocks              = try(each.value.cidr_blocks, null)
  ipv6_cidr_blocks         = try(each.value.ipv6_cidr_blocks, null)
  prefix_list_ids          = try(each.value.prefix_list_ids, [])
  self                     = try(each.value.self, null)
  source_security_group_id = try(each.value.source_security_group_id, null)
}

// File: security_group_sftp.tf
resource "aws_security_group" "sftp" {
  count = var.create_sftp_security_group ? 1 : 0

  name        = var.sftp_security_group_name
  description = "Security Group for SFTP Server"
  vpc_id      = var.vpc_id
  tags        = var.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "this" {
  for_each = { for k, v in var.sftp_security_group_rules : k => v if var.create_sftp_security_group }

  # Required
  security_group_id = aws_security_group.sftp[0].id
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  type              = each.value.type

  # Optional
  description              = try(each.value.description, null)
  cidr_blocks              = try(each.value.cidr_blocks, null)
  ipv6_cidr_blocks         = try(each.value.ipv6_cidr_blocks, null)
  prefix_list_ids          = try(each.value.prefix_list_ids, [])
  self                     = try(each.value.self, null)
  source_security_group_id = try(each.value.source_security_group_id, null)
}

// File: variables.tf
variable "region" {
  type        = string
  description = "AWS Region"
  default     = "eu-west-2"
}

### VPC, AZ, SG
variable "vpc_id" {
  description = "The name of the VPC where you want to create the resources"
  type        = string
  default     = null
}

variable "subnets" {
  description = "A map of subnets to availability zones"
  type        = list(string)
  default     = []
}

variable "efs_security_group_rules" {
  description = "A map of security group rule definitions to add to the security group created"
  type        = map(any)
  default     = {}
}

variable "sftp_security_group_rules" {
  description = "A map of security group rule definitions to add to the security group created"
  type        = map(any)
  default     = {}
}

variable "create_efs_security_group" {
  description = "Determines whether to create security group for EFS Mount"
  type        = bool
  default     = true
}

variable "create_sftp_security_group" {
  description = "Determines whether to create security group for EFS Mount"
  type        = bool
  default     = true
}

variable "efs_security_group_name" {
  type        = string
  description = "Security Group Name"
  default     = ""
}

variable "sftp_security_group_name" {
  type        = string
  description = "Security Group Name"
  default     = ""
}

variable "security_groups" {
  type        = list(string)
  description = "A list of security group ids that should be attached to EFS Mount"
  default     = []
}


### EFS
variable "efs_name" {
  type        = string
  description = "Efs name"
  default     = ""
}

variable "tags" {
  type    = map(string)
  default = {}
}


variable "performance_mode" {
  type        = string
  description = "Efs performance mode"
  default     = "generalPurpose"
}

variable "throughput_mode" {
  type        = string
  description = "Efs throughput mode"
  default     = "bursting"
}

### IAM
variable "create_iam_role" {
  description = "Flag to create an IAM role for SFTP users"
  type        = bool
  default     = true
}

variable "provided_iam_role_arn" {
  type        = string
  description = "The Amazon Resource Name (ARN) of an existing IAM role that should be used by AWS Backups. The ARN should have the format `arn:aws:iam::account-id:role/role-name`. If not provided, a new IAM role will be created."
  default     = ""
  validation {
    condition     = length(var.provided_iam_role_arn) == 0 || can(regex("^arn:aws:iam::[0-9]{12}:role/.*", var.provided_iam_role_arn))
    error_message = "The provided IAM role ARN is not valid. The ARN should have the format `arn:aws:iam::account-id:role/role-name`."
  }
}

### SFTP
variable "sftp_name" {
  description = "The name of the SFTP server"
  default     = ""
}

variable "identity_provider_type" {
  description = "Identity provider type of the SFTP server"
  default     = "SERVICE_MANAGED"
}

variable "endpoint_type" {
  type        = string
  description = "Endpoint type of the SFTP server"
  default     = "PUBLIC"
}

variable "sftp_domain" {
  type        = string
  description = "Domain type of the SFTP server"
  default     = "EFS"
}

variable "home_directory" {
  description = "Home directory type of the SFTP server"
  default     = ""
  type        = string
}

variable "home_directory_type" {
  description = "Home directory type of the SFTP server"
  default     = "PATH"
  type        = string
}

variable "sftp_users" {
  description = "A map of SFTP users to create"
  type = map(object({
    uid            = number
    gid            = number
    public_key     = string
    home_directory = optional(string, null)
    restricted     = optional(bool, false)
  }))
  default = {}

  validation {
    condition = alltrue([
      for _, user in var.sftp_users : user.home_directory == null || substr(user.home_directory, 0, 1) != "/"
    ])
    error_message = "The home_directory for each user must not start with '/'."
  }
}


variable "security_policy_name" {
  type        = string
  description = "Specifies the name of the security policy that is attached to the server. Possible values are TransferSecurityPolicy-2018-11, TransferSecurityPolicy-2020-06, and TransferSecurityPolicy-2023-05. Default value is: TransferSecurityPolicy-2023-05."
  default     = "TransferSecurityPolicy-2023-05"
}

variable "logging_enabled" {
  type        = bool
  description = "Enable logging for the SFTP server - the logs will be stored in CloudWatch"
  default     = false
}

variable "is_public" {
  type        = bool
  description = "Determines whether the SFTP server should be publicly accessible"
  default     = false
}

variable "eip_ids" {
  type        = list(string)
  description = "A list of Elastic IP IDs to associate with the SFTP server"
  default     = []
}

variable "sftp_security_group_ids" {
  type        = list(string)
  description = "A list of security group ids that should be attached to the SFTP server"
  default     = []
}

variable "encrypted" {
  type        = bool
  description = "Whether to enable encryption for the file system. Default is true."
  default     = true
}

variable "kms_key_id" {
  type        = string
  description = "The ARN of the AWS Key Management Service (AWS KMS) customer master key (CMK) to be used to protect the encrypted file system. This parameter is only required if you want to use a non-default CMK. If this parameter is not specified, the default CMK for Amazon EFS is used. This ID can be in one of the following formats: Key ID - A unique identifier of the key, for example 1234abcd-12ab-34cd-56ef-1234567890ab. ARN - An Amazon Resource Name (ARN) for the key, for example arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab. Key alias - A previously created display name for a key, for example alias/projectKey1. Key alias ARN - An ARN for a key alias, for example arn:aws:kms:us-east-2:444455556666:alias/projectKey1. If KmsKeyId is specified, the Encrypted flag must also be set."
  default     = null
}

variable "enable_user_access_point" {
  description = "Determines whether to create access points for each user"
  type        = bool
  default     = false
}

variable "additional_access_points" {
  description = "Configuration for additional, general-use access points"
  type = map(object({
    path        = string
    uid         = number
    gid         = number
    permissions = optional(string, "0755")
  }))
  default = {}
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
  required_version = ">= 1.3.0"
}

// File: aws.tf
##
# (c) 2024 - Cloud Ops Works LLC - https://cloudops.works/
#            On GitHub: https://github.com/cloudopsworks
#            Distributed Under Apache v2.0 License
#
data "aws_region" "current" {}

// File: locals-vars.tf
##
# (c) 2024 - Cloud Ops Works LLC - https://cloudops.works/
#            On GitHub: https://github.com/cloudopsworks
#            Distributed Under Apache v2.0 License
#
module "tags" {
  source  = "cloudopsworks/tags/local"
  version = "1.0.9"

  env = {
    organization_name = var.org.organization_name
    org_unit_name     = var.org.organization_unit
    environment_name  = var.org.environment_name
    environment_type  = var.org.environment_type
  }
}

// File: locals.tf
##
# (c) 2024 - Cloud Ops Works LLC - https://cloudops.works/
#            On GitHub: https://github.com/cloudopsworks
#            Distributed Under Apache v2.0 License
#
locals {
  region_arr        = split("-", data.aws_region.current.name)
  region            = format("%s%s%s", lower(local.region_arr[0]), lower(substr(local.region_arr[1], 0, 2)), lower(local.region_arr[2]))
  system_name       = format("%s-%s-%s-%s-%s", lower(var.org.organization_unit), lower(var.org.environment_name), lower(var.org.environment_type), var.spoke_def, local.region)
  system_name_short = format("%s-%s-%s-%s-%s", substr(lower(var.org.organization_unit), 0, 3), substr(lower(var.org.environment_name), 0, 3), substr(lower(var.org.environment_type), 0, 4), var.spoke_def, local.region)
  all_tags          = merge(module.tags.locals.common_tags, var.extra_tags)
}

// File: main.tf
##
# (c) 2024 - Cloud Ops Works LLC - https://cloudops.works/
#            On GitHub: https://github.com/cloudopsworks
#            Distributed Under Apache v2.0 License
#

locals {
  private_zones = {
    for k, v in var.zones : k => {
      domain_name = v.domain_name
      comment     = v.comment
      tags        = v.tags
      vpc = {
        vpc_id     = var.vpc_id
        vpc_region = data.aws_region.current.name
      }
    } if try(v.private, false) == true
  }
  public_zones = {
    for k, v in var.zones : k => {
      domain_name = v.domain_name
      comment     = v.comment
      tags        = v.tags
    } if try(v.private, false) != true
  }

  all_zones = merge(local.private_zones, local.public_zones)
}

resource "aws_route53_zone" "this" {
  for_each          = { for k, v in local.all_zones : k => v }
  name              = lookup(each.value, "domain_name", each.key)
  comment           = lookup(each.value, "comment", null)
  force_destroy     = lookup(each.value, "force_destroy", false)
  delegation_set_id = lookup(each.value, "delegation_set_id", null)

  dynamic "vpc" {
    for_each = try(tolist(lookup(each.value, "vpc", [])), [lookup(each.value, "vpc", {})])

    content {
      vpc_id     = vpc.value.vpc_id
      vpc_region = lookup(vpc.value, "vpc_region", null)
    }
  }

  tags = merge(
    lookup(each.value, "tags", {}),
    local.all_tags
  )
  lifecycle {
    ignore_changes = [
      vpc,
    ]
  }
}

resource "aws_route53_vpc_association_authorization" "vpc_association" {
  for_each = {
    for k, v in local.private_zones :
    k => v
    if var.dns_vpc.vpc_id != ""
  }
  vpc_id     = var.dns_vpc.vpc_id
  vpc_region = var.dns_vpc.vpc_region
  zone_id    = aws_route53_zone.this[each.key].zone_id
}

resource "aws_route53_zone_association" "vpc_association" {
  for_each = var.association_zone_ids
  vpc_id   = var.vpc_id
  zone_id  = each.value
}

// File: outputs.tf
##
# (c) 2024 - Cloud Ops Works LLC - https://cloudops.works/
#            On GitHub: https://github.com/cloudopsworks
#            Distributed Under Apache v2.0 License
#

output "zones" {
  value = {
    for v in aws_route53_zone.this :
    v.name => {
      id           = v.zone_id
      arn          = v.arn
      name         = v.name
      name_servers = v.name_servers
    }
  }
}

output "resolver_rules" {
  value = {
    inbound = {
      for rr in aws_route53_resolver_rule.inbound_rules :
      rr.name => {
        id                   = rr.id
        arn                  = rr.arn
        domain_name          = rr.domain_name
        rule_type            = rr.rule_type
        resolver_endpoint_id = rr.resolver_endpoint_id
        target_ip            = rr.target_ip
      }
    }
  }
}

output "custom_resolver_rules" {
  value = {
    inbound = {
      for rr in aws_route53_resolver_rule.custom_inbound_rules :
      rr.name => {
        id                   = rr.id
        arn                  = rr.arn
        domain_name          = rr.domain_name
        rule_type            = rr.rule_type
        resolver_endpoint_id = rr.resolver_endpoint_id
        target_ip            = rr.target_ip
      }
    }
  }
}

output "resolver_rules_associations" {
  value = {
    for rra in aws_route53_resolver_rule_association.inbound_rules :
    rra.name => {
      id               = rra.id
      resolver_rule_id = rra.resolver_rule_id
      vpc_id           = rra.vpc_id
    }
  }
}

output "resolver_endpoints" {
  value = {
    inbound = {
      for re in module.resolver_endpoint_in :
      re.route53_resolver_endpoint_id => {
        id                  = re.route53_resolver_endpoint_id
        arn                 = re.route53_resolver_endpoint_arn
        host_vpc_id         = re.route53_resolver_endpoint_host_vpc_id
        security_groups_ids = re.route53_resolver_endpoint_security_group_ids
        ip_addresses        = re.route53_resolver_endpoint_ip_addresses
      }
    }
    outbound = {
      for re in module.resolver_endpoint_out :
      re.route53_resolver_endpoint_id => {
        id                  = re.route53_resolver_endpoint_id
        arn                 = re.route53_resolver_endpoint_arn
        host_vpc_id         = re.route53_resolver_endpoint_host_vpc_id
        security_groups_ids = re.route53_resolver_endpoint_security_group_ids
        ip_addresses        = re.route53_resolver_endpoint_ip_addresses
      }
    }
  }
}

output "ram" {
  value = {
    custom_rules_resource_shares = {
      for rs in aws_ram_resource_share.custom_inbound_rules :
      rs.name => {
        id                        = rs.id
        arn                       = rs.arn
        allow_external_principals = rs.allow_external_principals
      }
    }
    custom_rules_principal_associations = {
      for pa in aws_ram_principal_association.custom_inbound_rules :
      pa.id => {
        principal          = pa.principal
        resource_share_arn = pa.resource_share_arn
      }
    }
    resource_shares = {
      for rs in aws_ram_resource_share.inbound_rules :
      rs.name => {
        id                        = rs.id
        arn                       = rs.arn
        allow_external_principals = rs.allow_external_principals
      }
    }
    resource_associations = {
      for ra in aws_ram_resource_association.inbound_rules :
      ra.id => {
        resource_arn       = ra.resource_arn
        resource_share_arn = ra.resource_share_arn
      }
    }
    principal_associations = {
      for pa in aws_ram_principal_association.inbound_rules :
      pa.id => {
        principal          = pa.principal
        resource_share_arn = pa.resource_share_arn
      }
    }
  }
}

output "dns_vpc" {
  value = {
    vpc_id         = var.vpc_id
    vpc_region     = data.aws_region.current.id
    vpc_cidr_block = var.vpc_cidr_block
    subnet_ids     = var.subnet_ids
  }
}

output "vpc_association_auth" {
  value = {
    for k, v in local.private_zones :
    k => {
      id         = aws_route53_vpc_association_authorization.vpc_association[k].id
      zone_id    = aws_route53_vpc_association_authorization.vpc_association[k].zone_id
      vpc_id     = aws_route53_vpc_association_authorization.vpc_association[k].vpc_id
      vpc_region = aws_route53_vpc_association_authorization.vpc_association[k].vpc_region
    }
    if var.dns_vpc.vpc_id != ""
  }
}

// File: ram.tf
##
# (c) 2024 - Cloud Ops Works LLC - https://cloudops.works/
#            On GitHub: https://github.com/cloudopsworks
#            Distributed Under Apache v2.0 License
#

# Inbound rules sharing
resource "aws_ram_resource_share" "inbound_rules" {
  for_each                  = local.hub_resolver_zones
  name                      = aws_route53_resolver_rule.inbound_rules[each.key].name
  allow_external_principals = var.ram.allow_external_principals
  tags = merge(
    {
      Name = "rslvr-${replace(each.value, ".", "-")}-${local.system_name}"
    },
    local.all_tags
  )
}

resource "aws_ram_resource_association" "inbound_rules" {
  for_each           = local.hub_resolver_zones
  resource_arn       = aws_route53_resolver_rule.inbound_rules[each.key].arn
  resource_share_arn = aws_ram_resource_share.inbound_rules[each.key].arn
}

resource "aws_ram_principal_association" "inbound_rules" {
  for_each = merge([for p in var.ram.principals :
    { for d in local.hub_resolver_zones : "${d}-${p}" => {
      domain_name = d
      principal   = p
      }
    }
  ]...)
  principal          = each.value.principal
  resource_share_arn = aws_ram_resource_share.inbound_rules[each.value.domain_name].arn
}

# Custom inbound rules sharing
resource "aws_ram_resource_share" "custom_inbound_rules" {
  for_each                  = local.custom_resolver_rules
  name                      = aws_route53_resolver_rule.custom_inbound_rules[each.key].name
  allow_external_principals = var.ram.allow_external_principals
  tags = merge(
    {
      Name = "rslvr-${replace(each.key, ".", "-")}-${local.system_name}"
    },
    local.all_tags
  )
}

resource "aws_ram_resource_association" "custom_inbound_rules" {
  for_each           = local.custom_resolver_rules
  resource_arn       = aws_route53_resolver_rule.custom_inbound_rules[each.key].arn
  resource_share_arn = aws_ram_resource_share.custom_inbound_rules[each.key].arn
}

resource "aws_ram_principal_association" "custom_inbound_rules" {
  for_each = merge([for p in var.ram.principals :
    { for k, v in local.custom_resolver_rules : "${k}-${p}" => {
      rule_name = k
      principal = p
      }
    }
  ]...)
  principal          = each.value.principal
  resource_share_arn = aws_ram_resource_share.custom_inbound_rules[each.value.rule_name].arn
}


resource "aws_ram_resource_share_accepter" "inbound_rules" {
  for_each = {
    for k, v in var.shared.ram_shares :
    k => v
    if var.ram.enabled
  }
  share_arn = each.value.arn
}

// File: resolvers.tf
##
# (c) 2024 - Cloud Ops Works LLC - https://cloudops.works/
#            On GitHub: https://github.com/cloudopsworks
#            Distributed Under Apache v2.0 License
#
locals {
  custom_resolver_rules = {
    for k, v in var.custom_resolver_rules :
    k => v
    if var.is_hub == true
  }
  hub_resolver_zones = toset([
    for k, v in local.private_zones :
    v.domain_name
    if var.is_hub == true
  ])
}

# Resolve the inbound domain with inbound resolver through te outbound resolver
resource "aws_route53_resolver_rule" "inbound_rules" {
  depends_on           = [module.resolver_endpoint_out]
  for_each             = local.hub_resolver_zones
  name                 = "rslvr-rr-in-${replace(lower(each.key), ".", "-")}-${local.system_name}"
  domain_name          = lower(each.value)
  rule_type            = "FORWARD"
  resolver_endpoint_id = module.resolver_endpoint_out[0].route53_resolver_endpoint_id
  dynamic "target_ip" {
    for_each = module.resolver_endpoint_in[0].route53_resolver_endpoint_ip_addresses
    content {
      ip = target_ip.value.ip
    }
  }
  tags = local.all_tags
}

# Resolve custom rules into inbound resolver
resource "aws_route53_resolver_rule" "custom_inbound_rules" {
  depends_on           = [module.resolver_endpoint_out]
  for_each             = local.custom_resolver_rules
  name                 = "rslvr-rr-in-${replace(each.key, ".", "-")}-${local.system_name}"
  domain_name          = lower(each.value.domain_name)
  rule_type            = "FORWARD"
  resolver_endpoint_id = module.resolver_endpoint_out[0].route53_resolver_endpoint_id
  dynamic "target_ip" {
    for_each = module.resolver_endpoint_in[0].route53_resolver_endpoint_ip_addresses
    content {
      ip = target_ip.value.ip
    }
  }
  tags = local.all_tags
}


resource "aws_route53_resolver_rule_association" "inbound_rules" {
  depends_on       = [aws_ram_resource_association.inbound_rules, aws_ram_resource_share_accepter.inbound_rules]
  for_each         = var.shared.resolver_rules
  name             = "rra-${replace(lower(try(each.value.domain_name, each.value.rule_name)), ".", "-")}-${var.vpc_id}-${local.system_name_short}"
  resolver_rule_id = each.value.id
  vpc_id           = var.vpc_id
}

module "resolver_endpoint_in" {
  count      = var.is_hub ? 1 : 0
  depends_on = [aws_route53_zone.this]
  source     = "terraform-aws-modules/route53/aws//modules/resolver-endpoints"
  version    = "~> 3.0"

  create              = true
  name                = "rslvr-in-${local.system_name}"
  direction           = "INBOUND"
  subnet_ids          = var.subnet_ids
  vpc_id              = var.vpc_id
  protocols           = ["DoH", "Do53"]
  tags                = local.all_tags
  security_group_name = "rslvr-in-${local.system_name}-sg"
  security_group_ingress_cidr_blocks = [
    var.vpc_cidr_block
  ]
  security_group_tags = local.all_tags
}

module "resolver_endpoint_out" {
  count      = var.is_hub ? 1 : 0
  depends_on = [aws_route53_zone.this]
  source     = "terraform-aws-modules/route53/aws//modules/resolver-endpoints"
  version    = "~> 3.0"

  create              = true
  name                = "rslvr-out-${local.system_name}"
  direction           = "OUTBOUND"
  subnet_ids          = var.subnet_ids
  vpc_id              = var.vpc_id
  protocols           = ["DoH", "Do53"]
  tags                = local.all_tags
  security_group_name = "rslvr-out-${local.system_name}-sg"
  security_group_ingress_cidr_blocks = [
    var.vpc_cidr_block
  ]
  security_group_tags = local.all_tags
}

// File: variables.tf
##
