// File: near-files.tf
######## Files Table (name=near-files)
resource "aws_dynamodb_table" "near-files" {
  name           = "near-files"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "walletId"
  range_key      = "fileId"
  stream_enabled = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
