    projection_type    = "ALL"
  }

  global_secondary_index {
    name               = "ownerId-fileId-index"
    hash_key           = "ownerId"
    range_key          = "fileId"
    projection_type    = "ALL"
  }

  tags = {
    Name        = "near-files"
    Environment = var.environment
  }

   lifecycle {
    prevent_destroy = true
    }  
}

