// File: near-storage.tf
######## Files Table (name=near-storage)
resource "aws_dynamodb_table" "near-storage" {
  name           = "near-storage"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "pk"
  range_key      = "sk"
  stream_enabled = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "pk1"
    type = "S"
  }

  attribute {
    name = "sk1"
    type = "S"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  global_secondary_index {
    name               = "GSI1"
    hash_key           = "pk1"
    range_key          = "sk1"
    projection_type    = "ALL"
  }

  tags = {
    Name        = "near-storage"
    Environment = var.environment
  }

   lifecycle {
    prevent_destroy = true
    }  
}

