  value       = aws_dynamodb_table.near-storage.name
}

resource "aws_ssm_parameter" "near-storage-ddb-stream-arn" {
  name        = "/file-service/dynamodb/storage/streamArn"
  type        = "String"
  value       = aws_dynamodb_table.near-storage.stream_arn
}

