// File: variables.tf
variable "environment" {
  default     = "dev"

  type = string
  description = "The name of the environment."
}

// File: ec2_ecs_cluster.tf
resource "aws_autoscaling_group" "default" {
  name = local.name

  min_size         = 2
  max_size         = 2
  desired_capacity = 2

  vpc_zone_identifier = [aws_subnet.public.id]

  tag {
    key                 = "Name"
    value               = local.name
    propagate_at_launch = true
  }

  mixed_instances_policy {
    launch_template {
      launch_template_specification {
        launch_template_id = aws_launch_template.default.id
        version            = aws_launch_template.default.latest_version
      }

      override {
        instance_requirements {
          accelerator_count {
            max = 0
          }

          vcpu_count {
            max = 4
          }

          memory_mib {
            max = 16 * 1024
          }

          memory_gib_per_vcpu {
            max = 4
          }


          spot_max_price_percentage_over_lowest_price = 100
        }
      }
    }
    instances_distribution {
      on_demand_percentage_above_base_capacity = 0
      spot_allocation_strategy                 = "price-capacity-optimized"

      spot_instance_pools = 0
    }
  }

  instance_refresh {
    strategy = "Rolling"
    preferences {
      min_healthy_percentage = 0
      instance_warmup        = 0
    }
  }
}

resource "aws_key_pair" "default" {
  public_key = var.public_key
}

resource "aws_launch_template" "default" {
  name = local.name

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2.name
  }

  image_id      = data.aws_ssm_parameter.ecs_amazon_linux_2.value
  instance_type = "t3a.medium" # supports 3 ENIs
  key_name      = aws_key_pair.default.key_name

  monitoring {
    enabled = true
  }

  vpc_security_group_ids = [aws_security_group.ec2.id]

  user_data = base64encode(<<EOF
#!/bin/bash
echo "ECS_CLUSTER=${local.name}" >> /etc/ecs/ecs.config
EOF
  )

  tag_specifications {
    resource_type = "volume"
    tags = {
      Name = local.name
    }
  }

}

data "aws_ssm_parameter" "ecs_amazon_linux_2" {
  name = "/aws/service/ecs/optimized-ami/amazon-linux-2/recommended/image_id"
}

resource "aws_security_group" "ec2" {
  vpc_id = aws_vpc.default.id
  name   = "${local.name}-ec2"
}

resource "aws_security_group_rule" "ec2_egress_all" {
  security_group_id = aws_security_group.ec2.id

  type = "egress"

  from_port = 0
  to_port   = 0
  protocol  = "-1"

  cidr_blocks = ["0.0.0.0/0"]
  description = "allows EC2 hosts to make egress calls"
}

resource "aws_security_group_rule" "ec2_ingress_ssh" {
  security_group_id = aws_security_group.ec2.id

  type = "ingress"

  from_port = 22
  to_port   = 22
  protocol  = "tcp"

  cidr_blocks = [var.admin_cidr]
  description = "allows ssh from admin_cidr"
}

data "aws_iam_policy_document" "ec2_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "ec2" {
  name               = "${local.name}-instance-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume.json
}

resource "aws_iam_policy_attachment" "ec2_ecs" {
  name       = "${local.name}-ec2"
  roles      = [aws_iam_role.ec2.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_policy_attachment" "ec2_ssm" {
  name       = "${local.name}-ec2"
  roles      = [aws_iam_role.ec2.name]
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "${aws_iam_role.ec2.name}-instance-profile"
  role = aws_iam_role.ec2.name
}

data "aws_iam_policy_document" "policy_describe" {
  statement {
    effect = "Allow"
    actions = ["ec2:DescribeImages"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ec2_policy_describe" {
  policy = data.aws_iam_policy_document.policy_describe.json
  role   = aws_iam_role.ec2.name
}

// File: fis_api_fault.tf
resource "aws_fis_experiment_template" "api_fault" {
  description = "api_fault"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  action {
    action_id   = "aws:fis:inject-api-internal-error"
    name        = "ApiFault"
    start_after = []

    parameter {
      key   = "duration"
      value = "PT3M"
    }
    parameter {
      key   = "operations"
      value = "DescribeImages"
    }
    parameter {
      key   = "percentage"
      value = "75"
    }
    parameter {
      key   = "service"
      value = "ec2"
    }

    target {
      key   = "Roles"
      value = "hello-fis"
    }
  }


  target {
    name = "hello-fis"
    resource_arns = [
      aws_iam_role.ec2.arn,
    ]
    resource_type  = "aws:iam:role"
    selection_mode = "ALL"
  }



}

// File: fis_ebs_pause.tf
resource "aws_fis_experiment_template" "ebs_pause" {
  description = "ebs_pause"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  action {
    name      = "EbsPause"
    action_id = "aws:ebs:pause-volume-io"

    target {
      key   = "Volumes"
      value = local.name
    }

    parameter {
      key   = "duration"
      value = "PT1M"
    }
  }

  target {
    name           = local.name
    resource_type  = "aws:ec2:ebs-volume"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = "Name"
      value = local.name
    }

    parameters = {
      availabilityZoneIdentifier = "us-east-1a"
    }

  }
}

// File: fis_ec2_cpu_stress.tf
resource "aws_fis_experiment_template" "cpu_stress" {
  description = "cpu_stress"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  action {
    name      = "CpuStress"
    action_id = "aws:ssm:send-command"

    parameter {
      key   = "documentArn"
      value = "arn:aws:ssm:us-east-1::document/AWSFIS-Run-CPU-Stress"
    }

    parameter {
      key = "documentParameters"
      value = jsonencode(
        {
          DurationSeconds     = "60"
          InstallDependencies = "True"
        }
      )
    }
    parameter {
      key   = "duration"
      value = "PT1M"
    }


    target {
      key   = "Instances"
      value = local.name
    }
  }

  target {
    name           = local.name
    resource_type  = "aws:ec2:instance"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = "Name"
      value = local.name
    }
  }
}

