    selection_mode = "COUNT(1)"


    resource_tag {
      key   = "Name"
      value = local.name
    }
  }
}

// File: iam_fis.tf
data "aws_iam_policy_document" "role_assume_fis" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["fis.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:aws:fis:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:experiment/*"]
    }
  }
}

resource "aws_iam_role" "fis" {
  name               = local.name
  assume_role_policy = data.aws_iam_policy_document.role_assume_fis.json
}

data "aws_iam_policy_document" "fis_fault_injection" {
  statement {
    effect = "Allow"
    actions = [
      "fis:InjectApiInternalError",
      "fis:InjectApiThrottleError",
      "fis:InjectApiUnavailableError",
    ]
    resources = ["arn:*:fis:*:*:experiment/*"]
  }
}


resource "aws_iam_role_policy" "fis_fault_injection" {
  policy = data.aws_iam_policy_document.fis_fault_injection.json
  role   = aws_iam_role.fis.id
}

data "aws_iam_policy_document" "fis_logs" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogDelivery" # TODO: more fine-grained?
    ]
    resources = ["*"]
  }
}


resource "aws_iam_role_policy" "fis_logs" {
  policy = data.aws_iam_policy_document.fis_logs.json
  role   = aws_iam_role.fis.id
}

# managed policy - TODO - use customer defined?
resource "aws_iam_role_policy_attachment" "fis_ec2_managed" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFaultInjectionSimulatorEC2Access"
  role       = aws_iam_role.fis.name
}

resource "aws_iam_role_policy_attachment" "fis_managed_network" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFaultInjectionSimulatorNetworkAccess"
  role       = aws_iam_role.fis.name
}

data "aws_iam_policy_document" "fis_ebs" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeVolumes",
      "ec2:PauseVolumeIO",
    ]
    resources = ["*"]
  }

}


resource "aws_iam_role_policy" "fis_ebs" {
  policy = data.aws_iam_policy_document.fis_ebs.json
  role   = aws_iam_role.fis.id
}

// File: main.tf
provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Name       = "hello-fis"
      Repository = "https://github.com/ericdahl/hello-fis"
    }
  }
}

data "aws_default_tags" "default" {}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  name = data.aws_default_tags.default.tags["Name"]
}

resource "aws_s3_bucket" "fis_logs" {

  force_destroy = true
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.bucket
  policy = data.aws_iam_policy_document.bucket_policy_fis_logs.json
}

data "aws_iam_policy_document" "bucket_policy_fis_logs" {
  statement {
    sid    = "AWSLogDeliveryAclCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.fis_logs.arn]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:aws:logs:us-east-1:${data.aws_caller_identity.current.account_id}:*"]
    }
  }

  statement {
    sid    = "AWSLogDeliveryWrite"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.fis_logs.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:aws:logs:us-east-1:${data.aws_caller_identity.current.account_id}:*"]
    }
  }
}

// File: outputs.tf
output "log_bucket" {
  value = aws_s3_bucket.fis_logs.bucket
}

// File: variables.tf
variable "admin_cidr" {
  default = "10.0.0.0/16"
}
variable "public_key" {
  default = "ssh-rsa  benchmark-generated"
}

// File: vpc.tf
# extremely minimal VPC for demo
resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"

  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.default.id
  availability_zone       = "us-east-1a"
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "default" {
  vpc_id = aws_vpc.default.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.default.id
}

resource "aws_route_table_association" "public" {
  route_table_id = aws_route_table.public.id
  subnet_id      = aws_subnet.public.id
}

resource "aws_route" "public_igw" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.default.id
}

// File: main.tf
locals {
  len_public_subnets  = max(length(var.public_subnets), length(var.public_subnet_ipv6_prefixes))
  len_private_subnets = max(length(var.private_subnets), length(var.private_subnet_ipv6_prefixes))

  max_subnet_length = max(
    local.len_private_subnets,
    local.len_public_subnets,
  )

  # Use `local.vpc_id` to give a hint to Terraform that subnets should be deleted before secondary CIDR blocks can be free!
  vpc_id = try(aws_vpc_ipv4_cidr_block_association.this[0].vpc_id, aws_vpc.this[0].id, "")

  create_vpc = var.create_vpc
}

################################################################################
# VPC
################################################################################

#already defined in aws_flow_log
#tfsec:ignore:aws-ec2-require-vpc-flow-logs-for-all-vpcs
resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block          = var.use_ipam_pool ? null : var.cidr
  ipv4_ipam_pool_id   = var.ipv4_ipam_pool_id
  ipv4_netmask_length = var.ipv4_netmask_length

  assign_generated_ipv6_cidr_block     = var.enable_ipv6 && !var.use_ipam_pool ? true : null
  ipv6_cidr_block                      = var.ipv6_cidr
  ipv6_ipam_pool_id                    = var.ipv6_ipam_pool_id
  ipv6_netmask_length                  = var.ipv6_netmask_length
  ipv6_cidr_block_network_border_group = var.ipv6_cidr_block_network_border_group

  instance_tenancy                     = var.instance_tenancy
  enable_dns_hostnames                 = var.enable_dns_hostnames
  enable_dns_support                   = var.enable_dns_support
  enable_network_address_usage_metrics = var.enable_network_address_usage_metrics

  tags = var.tags
}

resource "aws_vpc_ipv4_cidr_block_association" "this" {
  count = local.create_vpc && length(var.secondary_cidr_blocks) > 0 ? length(var.secondary_cidr_blocks) : 0

  # Do not turn this into `local.vpc_id`
  vpc_id = aws_vpc.this[0].id

  cidr_block = element(var.secondary_cidr_blocks, count.index)
}

################################################################################
# DHCP Options Set
################################################################################

resource "aws_vpc_dhcp_options" "this" {
  count = local.create_vpc && var.create_dhcp_options ? 1 : 0

  domain_name          = var.dhcp_options_domain_name
  domain_name_servers  = var.dhcp_options_domain_name_servers
  ntp_servers          = var.dhcp_options_ntp_servers
  netbios_name_servers = var.dhcp_options_netbios_name_servers
  netbios_node_type    = var.dhcp_options_netbios_node_type

  tags = var.dhcp_options_tags
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = local.create_vpc && var.enable_dhcp_options_association ? 1 : 0

  vpc_id          = local.vpc_id
  dhcp_options_id = var.create_dhcp_options ? aws_vpc_dhcp_options.this[0].id : var.dhcp_options_id
}

################################################################################
# Publiс Subnets
################################################################################

resource "aws_subnet" "public" {
  for_each = var.public_subnets

  assign_ipv6_address_on_creation                = each.value.assign_ipv6_address_on_creation
  cidr_block                                     = each.key
  availability_zone                              = each.value.az
  enable_dns64                                   = each.value.enable_dns64
  enable_resource_name_dns_aaaa_record_on_launch = each.value.enable_resource_name_dns_aaaa_record_on_launch
  enable_resource_name_dns_a_record_on_launch    = each.value.enable_resource_name_dns_a_record_on_launch
  ipv6_cidr_block                                = each.value.ipv6_cidr_block != "" ? each.value.ipv6_cidr_block : null
  ipv6_native                                    = each.value.ipv6_native
  map_public_ip_on_launch                        = each.value.map_public_ip_on_launch
  private_dns_hostname_type_on_launch            = each.value.private_dns_hostname_type_on_launch
  vpc_id                                         = local.vpc_id

  tags = each.value.tags
}

resource "aws_route_table" "public" {
  for_each = var.public_route_tables
  vpc_id   = local.vpc_id

  tags = try(each.value.tags, null)
}

locals {
  flattened_public_route_table_associations = merge([
    for rt_name, rt_details in var.public_route_tables : {
      for subnet_cidr, assoc in rt_details.associations : "${subnet_cidr}-${rt_name}" => {
        subnet_cidr = subnet_cidr
        route_table = rt_name
      }
    }
  ]...)
}

resource "aws_route_table_association" "public" {
  for_each = local.flattened_public_route_table_associations

  subnet_id      = aws_subnet.public[each.value.subnet_cidr].id
  route_table_id = aws_route_table.public[each.value.route_table].id
}

locals {
  flattened_public_route_table_routes = merge([
    for rt_name, rt_details in var.public_route_tables : {
      for route_name, route in rt_details.routes : route_name => {
        destination_cidr_block      = try(route.destination_cidr_block, null)
        destination_ipv6_cidr_block = try(route.destination_ipv6_cidr_block, null)
        igw                         = try(route.igw, null)
        route_table                 = rt_name
      }
    }
  ]...)
}

resource "aws_route" "public" {
  for_each = local.flattened_public_route_table_routes

  route_table_id              = aws_route_table.public[each.value.route_table].id
  destination_cidr_block      = each.value.destination_cidr_block != "" ? each.value.destination_cidr_block : null
  destination_ipv6_cidr_block = each.value.destination_ipv6_cidr_block != "" ? each.value.destination_ipv6_cidr_block : null
  gateway_id                  = lookup(each.value, "igw", null) != null ? aws_internet_gateway.this[0].id : null

}

locals {

  ingress_rules = flatten([
    for acl, details in var.aws_network_acls :
    [for k, v in details.ingress_rules : {
      acl_key     = acl,
      rule_key    = k,
      rule_values = v
    }]
  ])

  egress_rules = flatten([
    for acl, details in var.aws_network_acls :
    [for k, v in details.egress_rules : {
      acl_key     = acl,
      rule_key    = k,
      rule_values = v
    }]
  ])
}

resource "aws_network_acl" "this" {
  for_each = var.aws_network_acls

  vpc_id     = local.vpc_id
  subnet_ids = [for cidr in each.value.subnet_ids : (try(aws_subnet.private[cidr].id, aws_subnet.public[cidr].id))]
  tags       = each.value.tags
}

resource "aws_network_acl_rule" "ingress" {
  for_each = { for rule in local.ingress_rules : "${rule.acl_key}_${rule.rule_key}" => rule }

  network_acl_id = aws_network_acl.this[each.value.acl_key].id

  egress      = false
  rule_number = each.value.rule_values.rule_number
  rule_action = each.value.rule_values.rule_action
  from_port   = lookup(each.value.rule_values, "from_port", null)
  to_port     = lookup(each.value.rule_values, "to_port", null)
  protocol    = each.value.rule_values.protocol
  cidr_block  = lookup(each.value.rule_values, "cidr_block", null)
}

resource "aws_network_acl_rule" "egress" {
  for_each = { for rule in local.egress_rules : "${rule.acl_key}_${rule.rule_key}" => rule }

  network_acl_id = aws_network_acl.this[each.value.acl_key].id

  egress      = true
  rule_number = each.value.rule_values.rule_number
  rule_action = each.value.rule_values.rule_action
  from_port   = lookup(each.value.rule_values, "from_port", null)
  to_port     = lookup(each.value.rule_values, "to_port", null)
  protocol    = each.value.rule_values.protocol
  cidr_block  = lookup(each.value.rule_values, "cidr_block", null)
}

################################################################################
# Private Subnets
################################################################################

locals {
  create_private_subnets = local.create_vpc && local.len_private_subnets > 0
}

resource "aws_subnet" "private" {
  for_each = var.private_subnets

  assign_ipv6_address_on_creation                = each.value.assign_ipv6_address_on_creation
  cidr_block                                     = each.key
  availability_zone                              = each.value.az
  enable_dns64                                   = each.value.enable_dns64
  enable_resource_name_dns_aaaa_record_on_launch = each.value.enable_resource_name_dns_aaaa_record_on_launch
  enable_resource_name_dns_a_record_on_launch    = each.value.enable_resource_name_dns_a_record_on_launch
  ipv6_cidr_block                                = each.value.ipv6_cidr_block != "" ? each.value.ipv6_cidr_block : null
  ipv6_native                                    = each.value.ipv6_native
  private_dns_hostname_type_on_launch            = each.value.private_dns_hostname_type_on_launch
  map_public_ip_on_launch                        = each.value.map_public_ip_on_launch
  vpc_id                                         = local.vpc_id

  tags = each.value.tags
}

resource "aws_route_table" "private" {
  for_each = var.private_route_tables
  vpc_id   = local.vpc_id

  tags = try(each.value.tags, null)
}

locals {
  flattened_private_route_table_associations = merge([
    for rt_name, rt_details in var.private_route_tables : {
      for subnet_cidr, assoc in rt_details.associations : "${subnet_cidr}-${rt_name}" => {
        subnet_cidr = subnet_cidr
        route_table = rt_name
      }
    }
  ]...)
}

resource "aws_route_table_association" "private" {
  for_each = local.flattened_private_route_table_associations

  subnet_id      = aws_subnet.private[each.value.subnet_cidr].id
  route_table_id = aws_route_table.private[each.value.route_table].id
}

locals {
  flattened_private_route_table_routes = merge([
    for rt_name, rt_details in var.private_route_tables : {
      for route_name, route in rt_details.routes : route_name => {
        destination_cidr_block      = try(route.destination_cidr_block, null)
        destination_ipv6_cidr_block = try(route.destination_ipv6_cidr_block, null)
        nat_gateway_name            = try(route.nat_gateway_name, null)
        route_table                 = rt_name
      }
    }
  ]...)
}

resource "aws_route" "private" {
  for_each = local.flattened_private_route_table_routes

  route_table_id              = aws_route_table.private[each.value.route_table].id
  destination_cidr_block      = lookup(each.value, "destination_cidr_block", null) != null ? each.value.destination_cidr_block : null
  destination_ipv6_cidr_block = lookup(each.value, "destination_ipv6_cidr_block", null) != null ? each.value.destination_ipv6_cidr_block : null
  nat_gateway_id              = lookup(each.value, "nat_gateway_name", null) != null ? aws_nat_gateway.this[each.value.nat_gateway_name].id : null
}


################################################################################
# Private Network ACLs
################################################################################

locals {
  create_private_network_acl = local.create_private_subnets && var.private_dedicated_network_acl
}

resource "aws_network_acl" "private" {
  count = local.create_private_network_acl ? 1 : 0

  vpc_id     = local.vpc_id
  subnet_ids = aws_subnet.private[*].id

  tags = var.private_acl_tags
}

resource "aws_network_acl_rule" "private_inbound" {
  count = local.create_private_network_acl ? length(var.private_inbound_acl_rules) : 0

  network_acl_id = aws_network_acl.private[0].id

  egress          = false
  rule_number     = var.private_inbound_acl_rules[count.index]["rule_number"]
  rule_action     = var.private_inbound_acl_rules[count.index]["rule_action"]
  from_port       = lookup(var.private_inbound_acl_rules[count.index], "from_port", null)
  to_port         = lookup(var.private_inbound_acl_rules[count.index], "to_port", null)
  icmp_code       = lookup(var.private_inbound_acl_rules[count.index], "icmp_code", null)
  icmp_type       = lookup(var.private_inbound_acl_rules[count.index], "icmp_type", null)
  protocol        = var.private_inbound_acl_rules[count.index]["protocol"]
  cidr_block      = lookup(var.private_inbound_acl_rules[count.index], "cidr_block", null)
  ipv6_cidr_block = lookup(var.private_inbound_acl_rules[count.index], "ipv6_cidr_block", null)
}

resource "aws_network_acl_rule" "private_outbound" {
  count = local.create_private_network_acl ? length(var.private_outbound_acl_rules) : 0

  network_acl_id = aws_network_acl.private[0].id

  egress          = true
  rule_number     = var.private_outbound_acl_rules[count.index]["rule_number"]
  rule_action     = var.private_outbound_acl_rules[count.index]["rule_action"]
  from_port       = lookup(var.private_outbound_acl_rules[count.index], "from_port", null)
  to_port         = lookup(var.private_outbound_acl_rules[count.index], "to_port", null)
  icmp_code       = lookup(var.private_outbound_acl_rules[count.index], "icmp_code", null)
  icmp_type       = lookup(var.private_outbound_acl_rules[count.index], "icmp_type", null)
  protocol        = var.private_outbound_acl_rules[count.index]["protocol"]
  cidr_block      = lookup(var.private_outbound_acl_rules[count.index], "cidr_block", null)
  ipv6_cidr_block = lookup(var.private_outbound_acl_rules[count.index], "ipv6_cidr_block", null)
}


################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "this" {
  count = var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = var.igw_tags
}

resource "aws_egress_only_internet_gateway" "this" {
  count = local.create_vpc && var.create_egress_only_igw && var.enable_ipv6 && local.max_subnet_length > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = var.igw_tags
}

################################################################################
# NAT Gateway
################################################################################
resource "aws_nat_gateway" "this" {
  for_each = var.nat_gateways

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.value.subnet_cidr].id
  tags          = each.value.tags

  depends_on = [aws_internet_gateway.this]
}

resource "aws_eip" "nat" {
  for_each = var.nat_gateways

  domain = "vpc"
  tags   = each.value.eip_tags

  depends_on = [aws_internet_gateway.this]
}

################################################################################
# Default VPC
################################################################################

resource "aws_default_security_group" "this" {
  count = local.create_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  dynamic "ingress" {
    for_each = var.default_security_group_ingress
    content {
      self             = lookup(ingress.value, "self", null)
      cidr_blocks      = compact(split(",", lookup(ingress.value, "cidr_blocks", "")))
      ipv6_cidr_blocks = compact(split(",", lookup(ingress.value, "ipv6_cidr_blocks", "")))
      prefix_list_ids  = compact(split(",", lookup(ingress.value, "prefix_list_ids", "")))
      security_groups  = compact(split(",", lookup(ingress.value, "security_groups", "")))
      description      = lookup(ingress.value, "description", null)
      from_port        = lookup(ingress.value, "from_port", 0)
      to_port          = lookup(ingress.value, "to_port", 0)
      protocol         = lookup(ingress.value, "protocol", "-1")
    }
  }

  dynamic "egress" {
    for_each = var.default_security_group_egress
    content {
      self             = lookup(egress.value, "self", null)
      cidr_blocks      = compact(split(",", lookup(egress.value, "cidr_blocks", "")))
      ipv6_cidr_blocks = compact(split(",", lookup(egress.value, "ipv6_cidr_blocks", "")))
      prefix_list_ids  = compact(split(",", lookup(egress.value, "prefix_list_ids", "")))
      security_groups  = compact(split(",", lookup(egress.value, "security_groups", "")))
      description      = lookup(egress.value, "description", null)
      from_port        = lookup(egress.value, "from_port", 0)
      to_port          = lookup(egress.value, "to_port", 0)
      protocol         = lookup(egress.value, "protocol", "-1")
    }
  }

  tags = var.default_security_group_tags
}

################################################################################
# Default Network ACLs
################################################################################

resource "aws_default_network_acl" "this" {
  count = local.create_vpc && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  # subnet_ids is using lifecycle ignore_changes, so it is not necessary to list
  subnet_ids = null

  dynamic "ingress" {
    for_each = var.default_network_acl_ingress
    content {
      action          = ingress.value.action
      cidr_block      = lookup(ingress.value, "cidr_block", null)
      from_port       = ingress.value.from_port
      icmp_code       = lookup(ingress.value, "icmp_code", null)
      icmp_type       = lookup(ingress.value, "icmp_type", null)
      ipv6_cidr_block = lookup(ingress.value, "ipv6_cidr_block", null)
      protocol        = ingress.value.protocol
      rule_no         = ingress.value.rule_no
      to_port         = ingress.value.to_port
    }
  }
  dynamic "egress" {
    for_each = var.default_network_acl_egress
    content {
      action          = egress.value.action
      cidr_block      = lookup(egress.value, "cidr_block", null)
      from_port       = egress.value.from_port
      icmp_code       = lookup(egress.value, "icmp_code", null)
      icmp_type       = lookup(egress.value, "icmp_type", null)
      ipv6_cidr_block = lookup(egress.value, "ipv6_cidr_block", null)
      protocol        = egress.value.protocol
      rule_no         = egress.value.rule_no
      to_port         = egress.value.to_port
    }
  }

  tags = var.default_network_acl_tags

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

################################################################################
# Default Route
################################################################################

resource "aws_default_route_table" "default" {
  count = local.create_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id
  propagating_vgws       = var.default_route_table_propagating_vgws

  dynamic "route" {
    for_each = var.default_route_table_routes
    content {
      # One of the following destinations must be provided
      cidr_block                 = lookup(route.value, "cidr_block", null)
      ipv6_cidr_block            = lookup(route.value, "ipv6_cidr_block", null)
      destination_prefix_list_id = lookup(route.value, "destination_prefix_list_id", null)

      # One of the following targets must be provided
      # # egress_only_gateway_id    = lookup(route.value, "egress_only_gateway_id", null)
      gateway_id                = lookup(route.value, "gateway_id", null)
      instance_id               = lookup(route.value, "instance_id", null)
      nat_gateway_id            = lookup(route.value, "nat_gateway_id", null)
      network_interface_id      = lookup(route.value, "network_interface_id", null)
      transit_gateway_id        = lookup(route.value, "transit_gateway_id", null)
      vpc_endpoint_id           = lookup(route.value, "vpc_endpoint_id", null)
      vpc_peering_connection_id = lookup(route.value, "vpc_peering_connection_id", null)
    }
  }

  timeouts {
    create = "5m"
    update = "5m"
  }

  tags = var.default_route_table_tags
}

// File: outputs.tf
################################################################################
# VPC
################################################################################

output "vpc_id" {
  description = "The ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_arn" {
  description = "The ARN of the VPC"
  value       = try(aws_vpc.this[0].arn, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

// File: variables.tf
################################################################################
# VPC
################################################################################

variable "create_vpc" {
  description = "Controls if VPC should be created (it affects almost all resources)"
  type        = bool
  default     = true
}

variable "cidr" {
  description = "(Optional) The IPv4 CIDR block for the VPC. CIDR can be explicitly set or it can be derived from IPAM using `ipv4_netmask_length` & `ipv4_ipam_pool_id`"
  type        = string
  default     = "10.0.0.0/16"
}

variable "secondary_cidr_blocks" {
  description = "List of secondary CIDR blocks to associate with the VPC to extend the IP Address pool"
  type        = list(string)
  default     = []
}

variable "instance_tenancy" {
  description = "A tenancy option for instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_network_address_usage_metrics" {
  description = "Determines whether network address usage metrics are enabled for the VPC"
  type        = bool
  default     = null
}

variable "use_ipam_pool" {
  description = "Determines whether IPAM pool is used for CIDR allocation"
  type        = bool
  default     = false
}

variable "ipv4_ipam_pool_id" {
  description = "(Optional) The ID of an IPv4 IPAM pool you want to use for allocating this VPC's CIDR"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "(Optional) The netmask length of the IPv4 CIDR you want to allocate to this VPC. Requires specifying a ipv4_ipam_pool_id"
  type        = number
  default     = null
}

variable "enable_ipv6" {
  description = "Requests an Amazon-provided IPv6 CIDR block with a /56 prefix length for the VPC. You cannot specify the range of IP addresses, or the size of the CIDR block"
  type        = bool
  default     = false
}

variable "ipv6_cidr" {
  description = "(Optional) IPv6 CIDR block to request from an IPAM Pool. Can be set explicitly or derived from IPAM using `ipv6_netmask_length`"
  type        = string
  default     = null
}

variable "ipv6_ipam_pool_id" {
  description = "(Optional) IPAM Pool ID for a IPv6 pool. Conflicts with `assign_generated_ipv6_cidr_block`"
  type        = string
  default     = null
}

variable "ipv6_netmask_length" {
  description = "(Optional) Netmask length to request from IPAM Pool. Conflicts with `ipv6_cidr_block`. This can be omitted if IPAM pool as a `allocation_default_netmask_length` set. Valid values: `56`"
  type        = number
  default     = null
}

variable "ipv6_cidr_block_network_border_group" {
  description = "By default when an IPv6 CIDR is assigned to a VPC a default ipv6_cidr_block_network_border_group will be set to the region of the VPC. This can be changed to restrict advertisement of public addresses to specific Network Border Groups such as LocalZones"
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

variable "aws_network_acls" {
  description = "A map of network ACLs to associate with the VPC"
  type        = map(any)
  default     = {}
}


################################################################################
# DHCP Options Set
################################################################################

variable "create_dhcp_options" {
  description = "Should be true if you want to specify a DHCP options set with a custom domain name, DNS servers, NTP servers, netbios servers, and/or netbios server type"
  type        = bool
  default     = false
}

variable "dhcp_options_domain_name" {
  description = "Specifies DNS name for DHCP options set (requires enable_dhcp_options set to true)"
  type        = string
  default     = ""
}

variable "dhcp_options_domain_name_servers" {
  description = "Specify a list of DNS server addresses for DHCP options set, default to AWS provided (requires enable_dhcp_options set to true)"
  type        = list(string)
  default     = ["AmazonProvidedDNS"]
}

variable "dhcp_options_ntp_servers" {
  description = "Specify a list of NTP servers for DHCP options set (requires enable_dhcp_options set to true)"
  type        = list(string)
  default     = []
}

variable "dhcp_options_netbios_name_servers" {
  description = "Specify a list of netbios servers for DHCP options set (requires enable_dhcp_options set to true)"
  type        = list(string)
  default     = []
}

variable "dhcp_options_netbios_node_type" {
  description = "Specify netbios node_type for DHCP options set (requires enable_dhcp_options set to true)"
  type        = string
  default     = ""
}

variable "dhcp_options_tags" {
  description = "Additional tags for the DHCP option set (requires enable_dhcp_options set to true)"
  type        = map(string)
  default     = {}
}

variable "enable_dhcp_options_association" {
  description = "Should be true if you want to associate a DHCP Options Set to the VPC"
  type        = bool
  default     = false
}

################################################################################
# Publiс Subnets
################################################################################

variable "public_subnets" {
  description = "Information about the public subnets to be created"
  type        = any
  default     = {}
}

variable "public_subnet_ipv6_prefixes" {
  description = "Assigns IPv6 public subnet id based on the Amazon provided /56 prefix base 10 integer (0-256). Must be of equal length to the corresponding IPv4 subnet list"
  type        = list(string)
  default     = []
}

variable "public_route_tables" {
  description = "Information about the public route tables to be created"
  type        = map(any)
  default     = {}
}

################################################################################
# Private Subnets
################################################################################

variable "private_subnets" {
  description = "Information about the private subnets to be created"
  type        = any
  default     = {}
}

variable "private_subnet_ipv6_prefixes" {
  description = "Assigns IPv6 private subnet id based on the Amazon provided /56 prefix base 10 integer (0-256). Must be of equal length to the corresponding IPv4 subnet list"
  type        = list(string)
  default     = []
}

variable "private_route_tables" {
  description = "Information about the private route tables to be created"
  type = map(object({
    associations = optional(map(bool), {})
    tags         = optional(map(string), {})
    routes = optional(map(object({
      destination_cidr_block = string
      nat_gateway_name       = string
    })), {})
  }))
  default = {}
}



################################################################################
# Private Network ACLs
################################################################################

variable "private_dedicated_network_acl" {
  description = "Whether to use dedicated network ACL (not default) and custom rules for private subnets"
  type        = bool
  default     = false
}

variable "private_inbound_acl_rules" {
  description = "Private subnets inbound network ACLs"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "private_outbound_acl_rules" {
  description = "Private subnets outbound network ACLs"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "private_acl_tags" {
  description = "Additional tags for the private subnets network ACL"
  type        = map(string)
  default     = {}
}

################################################################################
# Internet Gateway
################################################################################

variable "create_igw" {
  description = "Controls if an Internet Gateway is created for public subnets and the related routes that connect them"
  type        = bool
  default     = true
}

variable "create_egress_only_igw" {
  description = "Controls if an Egress Only Internet Gateway is created and its related routes"
