      is_public         = false
    },
    {
      name              = "sn-app-A-private"
      availability_zone = "us-east-1a"
      is_public         = false
    },
    {
      name              = "sn-web-A-public"
      availability_zone = "us-east-1a"
      is_public         = true
    },
    {
      name              = "sn-reserved-B-private"
      availability_zone = "us-east-1b"
      is_public         = false
    },
    {
