// File: waf_byte_match_set.tf
#---------------------------------------------------
# AWS WAF byte match set
#---------------------------------------------------
resource "aws_waf_byte_match_set" "waf_byte_match_set" {
  count = var.enable_waf_byte_match_set ? 1 : 0

  name = var.waf_byte_match_set_name != "" ? lower(var.waf_byte_match_set_name) : "${lower(var.name)}-byte-match-set-${lower(var.environment)}"

  dynamic "byte_match_tuples" {
    iterator = byte_match_tuples
    for_each = var.waf_byte_match_set_byte_match_tuples

    content {
      text_transformation   = lookup(byte_match_tuples.value, "text_transformation", null)
      target_string         = lookup(byte_match_tuples.value, "target_string", null)
      positional_constraint = lookup(byte_match_tuples.value, "positional_constraint", null)

      field_to_match {
        type = lookup(byte_match_tuples.value, "type", null)
        data = lookup(byte_match_tuples.value, "data", null)
      }
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: waf_geo_match_set.tf
#---------------------------------------------------
# AWS WAF geo match set
#---------------------------------------------------
resource "aws_waf_geo_match_set" "waf_geo_match_set" {
  count = var.enable_waf_geo_match_set ? 1 : 0

  name = var.waf_geo_match_set_name != "" ? lower(var.waf_geo_match_set_name) : "${lower(var.name)}-geo-match-set-${lower(var.environment)}"

  dynamic "geo_match_constraint" {
    iterator = geo_match_constraint
    for_each = var.waf_geo_match_set_geo_match_constraint

    content {
      type  = lookup(geo_match_constraint.value, "type", null)
      value = lookup(geo_match_constraint.value, "value", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: waf_ipset.tf
#---------------------------------------------------
# AWS WAF ipset
#---------------------------------------------------
resource "aws_waf_ipset" "waf_ipset" {
  count = var.enable_waf_ipset ? 1 : 0

  name = var.waf_ipset_name != "" ? lower(var.waf_ipset_name) : "${lower(var.name)}-waf-ipset-${lower(var.environment)}"

  dynamic "ip_set_descriptors" {
    iterator = ip_set_descriptors
    for_each = length(var.waf_ipset_ip_set_descriptors) > 0 ? [var.waf_ipset_ip_set_descriptors] : []

    content {
      type  = lookup(ip_set_descriptors.value, "type", null)
      value = lookup(ip_set_descriptors.value, "value", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: waf_rate_based_rule.tf
#---------------------------------------------------
# AWS WAF rate based rule
#---------------------------------------------------
resource "aws_waf_rate_based_rule" "waf_rate_based_rule" {
  count = var.enable_waf_rate_based_rule ? 1 : 0

  name        = var.waf_rate_based_rule_name != "" ? lower(var.waf_rate_based_rule_name) : "${lower(var.name)}-rate-based-rule-${lower(var.environment)}"
  metric_name = var.waf_rate_based_rule_metric_name

  rate_key   = upper(var.waf_rate_based_rule_rate_key)
  rate_limit = var.waf_rate_based_rule_rate_limit

  dynamic "predicates" {
    iterator = predicates
    for_each = var.waf_rate_based_rule_predicates

    content {
      data_id = lookup(predicates.value, "data_id", element(concat(aws_waf_ipset.waf_ipset.*.id, [""]), 0))
      negated = lookup(predicates.value, "negated", null)
      type    = lookup(predicates.value, "type", null)
    }
  }

  tags = merge(
    {
      Name = var.waf_rate_based_rule_name != "" ? lower(var.waf_rate_based_rule_name) : "${lower(var.name)}-rate-based-rule-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_waf_ipset.waf_ipset
  ]
}

// File: waf_regex_match_set.tf
#---------------------------------------------------
# AWS WAF regex match set
#---------------------------------------------------
resource "aws_waf_regex_match_set" "waf_regex_match_set" {
  count = var.enable_waf_regex_match_set ? 1 : 0

  name = var.waf_regex_match_set_name != "" ? lower(var.waf_regex_match_set_name) : "${lower(var.name)}-regex-match-set-${lower(var.environment)}"

  dynamic "regex_match_tuple" {
    iterator = regex_match_tuple
    for_each = var.waf_regex_match_set_regex_match_tuple

    content {
      field_to_match {
        data = lookup(regex_match_tuple.value, "data", null)
        type = lookup(regex_match_tuple.value, "type", null)
      }

      regex_pattern_set_id = lookup(regex_match_tuple.value, "regex_pattern_set_id", element(concat(aws_waf_regex_pattern_set.waf_regex_pattern_set.*.id, [""]), 0))
      text_transformation  = lookup(regex_match_tuple.value, "text_transformation", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_waf_regex_pattern_set.waf_regex_pattern_set
  ]
}

// File: waf_regex_pattern_set.tf
#---------------------------------------------------
# AWS WAF regex pattern set
#---------------------------------------------------
resource "aws_waf_regex_pattern_set" "waf_regex_pattern_set" {
  count = var.enable_waf_regex_pattern_set ? 1 : 0

  name                  = var.waf_regex_pattern_set_name != "" ? lower(var.waf_regex_pattern_set_name) : "${lower(var.name)}-regex-pattern-set-${lower(var.environment)}"
  regex_pattern_strings = var.waf_regex_pattern_set_regex_pattern_strings

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: waf_rule.tf
#---------------------------------------------------
# AWS WAF rule
#---------------------------------------------------
resource "aws_waf_rule" "waf_rule" {
  count = var.enable_waf_rule ? 1 : 0

  name        = var.waf_rule_name != "" ? lower(var.waf_rule_name) : "${lower(var.name)}-${var.waf_rule_metric_name}-rule-${lower(var.environment)}"
  metric_name = var.waf_rule_metric_name

  dynamic "predicates" {
    iterator = predicates
    for_each = var.waf_rule_predicates

    content {
      data_id = lookup(predicates.value, "data_id", element(concat(aws_waf_ipset.waf_ipset.*.id, [""]), 0))
      negated = lookup(predicates.value, "negated", null)
      type    = lookup(predicates.value, "type", null)
    }
  }

  tags = merge(
    {
      Name = var.waf_rule_name != "" ? lower(var.waf_rule_name) : "${lower(var.name)}-${var.waf_rule_metric_name}-rule-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_waf_ipset.waf_ipset
  ]
}

// File: waf_rule_group.tf
#---------------------------------------------------
# AWS WAF rule group
#---------------------------------------------------
resource "aws_waf_rule_group" "waf_rule_group" {
  count = var.enable_waf_rule_group ? 1 : 0

  name        = var.waf_rule_group_name != "" ? lower(var.waf_rule_group_name) : "${lower(var.name)}-waf-rule-group-${lower(var.environment)}"
  metric_name = var.waf_rule_group_metric_name

  dynamic "activated_rule" {
    iterator = activated_rule
    for_each = var.waf_rule_group_activated_rule

    content {
      action {
        type = lookup(activated_rule.value, "action_type", null)
      }

      priority = lookup(activated_rule.value, "priority", null)
      rule_id  = lookup(activated_rule.value, "rule_id", element(concat(aws_waf_rule.waf_rule.*.id, [""]), 0))
      type     = lookup(activated_rule.value, "type", null)
    }
  }

  tags = merge(
    {
      Name = var.waf_rule_group_name != "" ? lower(var.waf_rule_group_name) : "${lower(var.name)}-waf-rule-group-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_waf_rule.waf_rule
  ]
}

// File: waf_size_constraint_set.tf
#---------------------------------------------------
# AWS WAF size constraint set
#---------------------------------------------------
resource "aws_waf_size_constraint_set" "waf_size_constraint_set" {
  count = var.enable_waf_size_constraint_set ? 1 : 0

  name = var.waf_size_constraint_set_name != "" ? lower(var.waf_size_constraint_set_name) : "${lower(var.name)}-size-constraint-set-${lower(var.environment)}"

  dynamic "size_constraints" {
    iterator = size_constraints
    for_each = var.waf_size_constraint_set_size_constraints

    content {
      field_to_match {
        type = lookup(size_constraints.value, "type", null)
        data = lookup(size_constraints.value, "data", null)
      }

      text_transformation = lookup(size_constraints.value, "text_transformation", null)
      comparison_operator = lookup(size_constraints.value, "comparison_operator", null)
      size                = lookup(size_constraints.value, "size", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: waf_sql_injection_match_set.tf
#---------------------------------------------------
# AWS WAF sql injection match set
