// File: data.tf
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "sns_topic_policy" {
  version = "2012-10-17"

  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = ["*"]
  }
}
data "aws_iam_role" "execution_role" {
  name       = aws_iam_role.canary_execution_role.name
  depends_on = [aws_iam_role.canary_execution_role]
}

// File: locals.tf
locals {
  kms_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid       = "AllowCloudWatchToAccessTheKey",
        Effect    = "Allow",
        Principal = { Service = "cloudwatch.amazonaws.com" },
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
          "kms:UpdateKeyPolicy",
        ],
        Resource = "*",
      },
      {
        Sid       = "AllowKeyOwnerToUpdate",
        Effect    = "Allow",
        Principal = { AWS = data.aws_caller_identity.current.account_id },
        Action    = "kms:*",
        Resource  = "*",
      },
    ],
  })
  canaries_with_vpc = {
    for canary_key, canary in var.canaries_with_vpc : canary_key => merge(canary, {
      zip_file   = canary.zip_file != null ? canary.zip_file : null
      s3_bucket  = canary.zip_file == null && canary.s3_details != null ? canary.s3_details.s3_bucket : null
      s3_key     = canary.zip_file == null && canary.s3_details != null ? canary.s3_details.s3_key : null
      s3_version = canary.zip_file == null && canary.s3_details != null ? canary.s3_details.s3_version : null
    })
  }
}

// File: main.tf
resource "random_pet" "iam_role_name" {
  length    = 2
  separator = "-"
}
resource "aws_iam_role" "canary_execution_role" {
  name = "${random_pet.iam_role_name.id}-canary"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = {
        Service = "lambda.amazonaws.com"
      },
      Action = "sts:AssumeRole"
    }]
  })
}
resource "aws_iam_policy" "canary_execution_policy" {
  name        = "${random_pet.iam_role_name.id}-canary-policy"
  description = "Policy for executing canaries"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = [
          "s3:*",
          "s3-object-lambda:*",
          "cloudwatch:PutMetricData",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ],
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "canary_execution_attachment" {
  role       = aws_iam_role.canary_execution_role.name
  policy_arn = aws_iam_policy.canary_execution_policy.arn
}

/////////////////--KMS-KEY----//////////////////////////////
module "kms" {
  source                  = "sourcefuse/arc-kms/aws"
  version                 = "0.0.4"
  enabled                 = var.enabled
  deletion_window_in_days = var.deletion_window_in_days
  enable_key_rotation     = var.enable_key_rotation
  alias                   = var.kms_key_alias
  tags                    = var.tags
  policy                  = var.custom_kms_policy != "" ? var.custom_kms_policy : local.kms_policy
}

/////////////////--SNS----//////////////////////////////

resource "aws_sns_topic" "this" {
  name              = var.sns_topic_name
  kms_master_key_id = var.enabled ? module.kms.key_arn : null
  tags              = var.tags
}

resource "aws_sns_topic_policy" "this" {
  arn    = aws_sns_topic.this.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic_subscription" "this" {
  topic_arn = aws_sns_topic.this.arn
  protocol  = var.protocol
  endpoint  = var.endpoint
}
resource "aws_synthetics_canary" "dynamic_canaries_with_vpc" {
  for_each = local.canaries_with_vpc

  name                     = each.value.name
  artifact_s3_location     = "s3://${aws_s3_bucket.artifcats_bucket.id}/"
  execution_role_arn       = data.aws_iam_role.execution_role.arn
  handler                  = each.value.handler
  runtime_version          = each.value.runtime_version
  start_canary             = each.value.start_canary
  failure_retention_period = each.value.failure_retention_period
  success_retention_period = each.value.success_retention_period

  schedule {
    expression = each.value.schedule_expression
  }

  vpc_config {
    subnet_ids         = var.subnet_ids
    security_group_ids = var.security_group_ids
  }

  run_config {
    timeout_in_seconds    = 120
    environment_variables = each.value.environment_variables
  }

  # Conditional attributes
  zip_file   = each.value.zip_file
  s3_bucket  = each.value.s3_bucket
  s3_key     = each.value.s3_key
  s3_version = each.value.s3_version

  depends_on = [aws_s3_bucket.artifcats_bucket]
  tags       = var.tags
}

resource "aws_cloudwatch_metric_alarm" "fail_alarm" {
  for_each = var.canaries_with_vpc

  alarm_name          = "${each.value.name}-fail-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = "1"
  metric_name         = "Failed"
  namespace           = "CloudWatchSynthetics"
  period              = "60"
  statistic           = "Sum"
  threshold           = "1"
  actions_enabled     = true

  dimensions = {
    CanaryName = each.value.name
  }

  alarm_actions     = [aws_sns_topic.this.arn]
  alarm_description = "Canary is down: ${each.value.name}"
  tags              = var.tags
  depends_on        = [aws_sns_topic.this]
}

resource "aws_cloudwatch_metric_alarm" "success_alarm" {
  for_each            = var.cloudwatch_metric_alarms_enabled ? var.canaries_with_vpc : {}
  alarm_name          = "${each.value.name}-success-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = "60"
  statistic           = "Average"
  threshold           = "90"
  actions_enabled     = true

  dimensions = {
    CanaryName = each.value.name
  }
  ok_actions        = [aws_sns_topic.this.arn]
  alarm_description = "Canary is up: ${each.value.name}"
  tags              = var.tags
  depends_on        = [aws_sns_topic.this]
}
////////////////// s3 ////////////////////////

resource "aws_s3_bucket" "artifcats_bucket" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy
  tags          = var.tags
}

resource "aws_s3_bucket_public_access_block" "public_access_block" {
  bucket = aws_s3_bucket.artifcats_bucket.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}
resource "aws_s3_bucket_server_side_encryption_configuration" "ssm" {
  bucket = aws_s3_bucket.artifcats_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = module.kms.key_arn
      sse_algorithm     = var.sse_algorithm
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}
resource "aws_s3_bucket_versioning" "versioning" {
  bucket = aws_s3_bucket.artifcats_bucket.id
  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}
resource "aws_s3_bucket_cors_configuration" "cors" {
  bucket = aws_s3_bucket.artifcats_bucket.id

  dynamic "cors_rule" {
    for_each = var.cors_configuration
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

// File: outputs.tf
output "canary_arns" {
  value       = { for idx, canary in aws_synthetics_canary.dynamic_canaries_with_vpc : canary.name => canary.arn }
  description = "ARNs of all canaries created"
}

// File: provider.tf
terraform {
  required_version = "~> 1.7"

  required_providers {
    aws = {
      version = ">= 4.0, < 6.0"
      source  = "hashicorp/aws"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "2.4.2"
    }
    random = {
      source  = "hashicorp/random"
      version = "3.6.2"
    }
  }
}

provider "aws" {
  region = var.region
}

// File: variables.tf
variable "region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region"
}
variable "enabled" {
  description = "Whether the KMS module is enabled. If true, a custom KMS key will be used for encryption. If false, the default AWS managed KMS key will be used."
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias for the custom KMS key (if enabled)."
  type        = string
  default     = "alias/benchmark-canary-key"
}

variable "protocol" {
  description = "The protocol for the SNS subscription endpoint."
  type        = string
  default     = "email"
}

variable "endpoint" {
  description = "The endpoint for the SNS subscription."
  type        = string
  default     = "nobody@example.com"
}

///////// KMS //////////////////

variable "deletion_window_in_days" {
  type        = number
  default     = 10
  description = "Duration in days after which the key is deleted after destruction of the resource"
}

variable "enable_key_rotation" {
  type        = bool
  default     = true
  description = "Specifies whether key rotation is enabled"
}

variable "custom_kms_policy" {
  description = "Custom KMS policy to apply if enabled. If not provided, a default policy will be used."
  type        = string
  default     = ""
}
variable "sns_topic_name" {
  description = "Name for the SNS topic."
  type        = string
  default     = "benchmark-canary-topic"
}

variable "canaries_with_vpc" {
  description = "List of canaries with VPC configuration"
  type = map(object({
    name     = string
    handler  = string
    zip_file = string
    s3_details = optional(object({
      s3_bucket  = string
      s3_key     = string
      s3_version = string
    }), null)
    runtime_version          = string
    start_canary             = bool
    failure_retention_period = number
    success_retention_period = number
    schedule_expression      = string
    environment_variables    = map(string)
  }))
  default     = {}
}

variable "subnet_ids" {
  description = "List of subnet IDs where the canary will run"
  type        = list(string)
  default     = [""]
}

variable "security_group_ids" {
  description = "List of security group IDs for the canary"
  type        = list(string)
  default     = [""]
}

variable "tags" {
  description = "Tags to apply to the canary"
  type        = map(string)
  default     = {}
}
################################################################################
## S3
################################################################################

variable "bucket_name" {
  type        = string
  description = "The name of the S3 bucket."
  default     = "benchmark-canary-bucket-tf5x"
}
variable "bucket_key_enabled" {
  type        = bool
  description = "Specifies whether bucket key is enabled."
  default     = false
}
variable "force_destroy" {
  type        = bool
  default     = true
  description = "Specifies whether to force destroy the bucket (and all objects) when the bucket is removed."
}
variable "versioning_enabled" {
  type        = bool
  default     = false
  description = "Enable versioning for the S3 bucket."
}
variable "block_public_acls" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should block public ACLs for this bucket."
}
variable "ignore_public_acls" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
}
variable "block_public_policy" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
}
variable "restrict_public_buckets" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
}
variable "cors_configuration" {
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = list(string)
    max_age_seconds = number
  }))
  default = [
    {
      allowed_headers = ["Authorization"]
      allowed_methods = ["GET", "POST"]
      allowed_origins = ["*"]
      expose_headers  = ["x-amz-server-side-encryption"]
      max_age_seconds = 3000
    }
  ]
  description = "The CORS configuration for the S3 bucket."
}
variable "sse_algorithm" {
  type        = string
  default     = "aws:kms"
  description = "The server-side encryption algorithm to use. Valid values are `AES256` and `aws:kms`"
}
variable "cloudwatch_metric_alarms_enabled" {
  type        = bool
  description = "Boolean flag to enable/disable CloudWatch metrics alarms"
  default     = false
}

// File: main.tf
locals {
  len_public_subnets  = length(var.public_subnets)
  len_private_subnets = length(var.private_subnets)
  len_intra_subnets   = length(var.intra_subnets)
}

################################################################################
# VPC
################################################################################

locals {
  create_vpc = var.create_vpc
}

resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block = var.cidr

  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    { "Name" = var.name },
    var.tags,
    var.vpc_tags,
  )
}

locals {
  vpc_id = try(aws_vpc.this[0].id, null)
}

################################################################################
# Publiс Subnets
################################################################################

locals {
  create_public_subnets = local.create_vpc && local.len_public_subnets > 0
}

resource "aws_subnet" "public" {
  count = local.create_public_subnets ? local.len_public_subnets : 0

  availability_zone       = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) > 0 ? element(var.azs, count.index) : null
  availability_zone_id    = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) == 0 ? element(var.azs, count.index) : null
  cidr_block              = element(concat(var.public_subnets, [""]), count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch
  vpc_id                  = local.vpc_id

  tags = merge(
    {
      Name = try(
        var.public_subnet_names[count.index],
        format("${var.name}-${var.public_subnet_suffix}-%s", element(var.azs, count.index))
      )
    },
    var.tags,
    var.public_subnet_tags,
  )
}

resource "aws_route_table" "public" {
  count = local.create_public_subnets ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    { "Name" = "${var.name}-${var.public_subnet_suffix}" },
    var.tags,
  )
}

resource "aws_route_table_association" "public" {
  count = local.create_public_subnets ? local.len_public_subnets : 0

  subnet_id      = element(aws_subnet.public[*].id, count.index)
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route" "public_internet_gateway" {
  count = local.create_public_subnets && var.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id

  timeouts {
    create = "5m"
  }
}

################################################################################
# Private Subnets
################################################################################

locals {
  create_private_subnets = local.create_vpc && local.len_private_subnets > 0

  # Create NAT gateways if necessary: one for each private subnet that has
  # an associated public subnet.
  natgw_count = (
    local.create_private_subnets && local.create_public_subnets && var.enable_nat_gateway ?
    min(local.len_private_subnets, local.len_public_subnets) : 0
  )
}

resource "aws_subnet" "private" {
  count = local.create_private_subnets ? local.len_private_subnets : 0

  availability_zone    = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) > 0 ? element(var.azs, count.index) : null
  availability_zone_id = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) == 0 ? element(var.azs, count.index) : null
  cidr_block           = element(concat(var.private_subnets, [""]), count.index)
  vpc_id               = local.vpc_id

  tags = merge(
    {
      Name = try(
        var.private_subnet_names[count.index],
        format("${var.name}-${var.private_subnet_suffix}-%s", element(var.azs, count.index))
      )
    },
    var.tags,
    var.private_subnet_tags,
  )
}

# There are as many routing tables as the number of NAT gateways.
resource "aws_route_table" "private" {
  count = local.natgw_count

  vpc_id = local.vpc_id

  tags = merge(
    {
      "Name" = "${var.name}-${var.private_subnet_suffix}"
    },
    var.tags,
  )
}

resource "aws_route_table_association" "private" {
  count = local.create_private_subnets ? local.len_private_subnets : 0

  subnet_id      = element(aws_subnet.private[*].id, count.index)
  route_table_id = element(aws_route_table.private[*].id, count.index)
}

################################################################################
# Intra Subnets
################################################################################

locals {
  create_intra_subnets = local.create_vpc && local.len_intra_subnets > 0
}

resource "aws_subnet" "intra" {
  count = local.create_intra_subnets ? local.len_intra_subnets : 0

  availability_zone    = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) > 0 ? element(var.azs, count.index) : null
  availability_zone_id = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) == 0 ? element(var.azs, count.index) : null
  cidr_block           = element(concat(var.intra_subnets, [""]), count.index)
  vpc_id               = local.vpc_id

  tags = merge(
    {
      Name = try(
        var.intra_subnet_names[count.index],
        format("${var.name}-${var.intra_subnet_suffix}-%s", element(var.azs, count.index))
      )
    },
    var.tags,
    var.intra_subnet_tags,
  )
}

resource "aws_route_table" "intra" {
  count = local.create_intra_subnets ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    { "Name" = "${var.name}-${var.intra_subnet_suffix}" },
    var.tags,
  )
}

resource "aws_route_table_association" "intra" {
  count = local.create_intra_subnets ? local.len_intra_subnets : 0

  subnet_id      = element(aws_subnet.intra[*].id, count.index)
  route_table_id = element(aws_route_table.intra[*].id, 0)
}

################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_public_subnets && var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    { "Name" = var.name },
    var.tags,
    var.igw_tags,
  )
}

################################################################################
# NAT Gateway
################################################################################

locals {
  nat_gateway_ips = try(aws_eip.nat[*].id, [])
}

resource "aws_eip" "nat" {
  count = local.natgw_count

  domain = "vpc"

  tags = merge(
    {
      "Name" = format("${var.name}-%s", element(var.azs, count.index))
    },
    var.tags,
  )
}

resource "aws_nat_gateway" "this" {
  count = local.natgw_count

  allocation_id = element(local.nat_gateway_ips, count.index)
  subnet_id     = element(aws_subnet.public[*].id, count.index)

  tags = merge(
    {
      "Name" = format("${var.name}-%s", element(var.azs, count.index))
    },
    var.tags,
    var.nat_gateway_tags,
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route" "private_nat_gateway" {
  count = local.natgw_count

  route_table_id         = element(aws_route_table.private[*].id, count.index)
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = element(aws_nat_gateway.this[*].id, count.index)

  timeouts {
    create = "5m"
  }
}

// File: outputs.tf
################################################################################
# VPC
################################################################################

output "vpc_id" {
  description = "The ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

################################################################################
# Internet Gateway
################################################################################

output "igw_id" {
  description = "The ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

################################################################################
# Publiс Subnets
################################################################################

output "public_subnet_ids" {
  description = "List of IDs of public subnets"
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidr_blocks" {
  description = "List of CIDR blocks of public subnets"
  value       = compact(aws_subnet.public[*].cidr_block)
}

################################################################################
# Private Subnets
################################################################################

output "private_subnet_ids" {
  description = "List of IDs of private subnets"
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidr_blocks" {
  description = "List of CIDR blocks of private subnets"
  value       = compact(aws_subnet.private[*].cidr_block)
}

################################################################################
# Intra Subnets
################################################################################

output "intra_subnet_ids" {
  description = "List of IDs of intra subnets"
  value       = aws_subnet.intra[*].id
}

output "intra_subnet_cidr_blocks" {
  description = "List of CIDR blocks of intra subnets"
  value       = compact(aws_subnet.intra[*].cidr_block)
}

################################################################################
# NAT Gateway
################################################################################

output "nat_public_ips" {
  description = "List of public Elastic IPs created for AWS NAT Gateway"
  value       = aws_eip.nat[*].public_ip
}

output "natgw_ids" {
  description = "List of NAT Gateway IDs"
  value       = aws_nat_gateway.this[*].id
}

################################################################################
# Static values (arguments)
################################################################################

output "azs" {
  description = "A list of availability zones specified as argument to this module"
  value       = var.azs
}

output "name" {
  description = "The name of the VPC specified as argument to this module"
  value       = var.name
}

// File: variables.tf
