// File: versions.tf
terraform {
  required_version = ">= 1.2.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

// File: _data.tf
data "aws_vpc" "current" {}

data "aws_subnets" "current" {
  tags = {
    "Scheme" = "private"
  }
}

data "aws_route53_zone" "hosted_zones" {
  for_each = { for domain in var.domains : domain.domain => domain }
  name     = each.value.zone_name
}

# Find a certificate that is issued
data "aws_acm_certificate" "certificates" {
  for_each = { for domain in var.domains : domain.domain => domain }
  domain   = each.value.zone_name
  statuses = ["ISSUED"]
}

data "aws_subnets" "private" {

  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.current.id]
  }

  filter {
    name   = "tag:Scheme"
    values = ["private"]
  }
}

// File: _outputs.tf
output "api_gateway_domain_targets" {
  value       = { for domain in var.domains : domain.domain =>
    {
      name = (var.api_type == "http"
        ? try(aws_apigatewayv2_domain_name.domain_name[domain.domain].domain_name_configuration[0].target_domain_name, "")
        : try(aws_api_gateway_domain_name.rest_domain_name[domain.domain].hosted_zone_id, ""))
      zone_id = (var.api_type == "http"
        ? try(aws_apigatewayv2_domain_name.domain_name[domain.domain].domain_name_configuration[0].target_domain_name, "")
        : try(aws_api_gateway_domain_name.rest_domain_name[domain.domain].regional_zone_id, ""))
    }
    if var.create_dns_record && (var.api_type == "http" || var.api_type == "rest")
  }
  description = "Targets for creating DNS records manually"
}

// File: _variables.tf
variable "name" {
  description = "Api Gateway name"
  default     = "benchmark-api"
}

variable "api_type" {
  default     = "http"

  description = "Type of the API. http or rest"
  type        = string
}

variable "api_description" {
  description = "Description for the API"
  type        = string
  default     = ""
}

variable "open_api_file" {
  description = "Path to the open api specification"
  default     = ""
  type        = string
}

variable "target_arn" {
  description = "Target ARN's to the vpc link"
  default     = ""
  type        = string
}

variable "environment_name" {
  description = "Name of the environment"
  default     = ""
  type        = string
}

variable "domains" {
  description = "Domains to be created for the API GATEWAY"
  default     = []
  type = list(object({
    domain            = string
    api_route_mapping = string
    zone_name         = string
  }))
}

variable "create_dns_record" {
  description = "When enabled, creates the route53 record for the custom domain"
  type        = bool
  default     = true
}

variable "routes" {
  description = "Routes to be created in the API"
  default     = []
  type = list(object({
    name             = string
    method           = string
    integration_type = string
    integration_uri  = string
    route_mapping    = string
    path_parameters  = list(string)
    connection_type  = string
  }))

}

variable "create_vpc_link" {
  description = ""
  type        = bool
  default     = false
}

variable "vpc_link_target_id" {
  description = "ARN of the resource to attach for the VPC link load balancer target"
  type        = string
  default     = ""
}

variable "vpc_link_target_port" {
  description = "TCP Port of the resource to attach for the VPC link load balancer target"
  type        = number
  default     = 443
}

variable "create_api_key" {
  description = "Boolean variable that's evaluate the creation of an api key"
  type        = bool
  default     = false
}

variable "tags" {
  default = {}
}

variable "allowed_ips" {
  description = "List of allowed IP's to access the API"
  type        = list(any)
  default     = []
}

variable "custom_authorizers" {
  description = "Custom authorizer variables"
  default     = []
  type = list(object({
    name                          = string
    custom_authorizer_lambda_code = string
  }))

}

// File: api_key.tf
resource "aws_api_gateway_usage_plan" "usage_plan" {
  count = var.create_api_key && var.api_type == "rest" ? 1 : 0
  name  = "${var.environment_name}-${var.name}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest_api[0].id
    stage  = aws_api_gateway_stage.rest_stage[0].stage_name
  }
}

resource "aws_api_gateway_api_key" "api_key" {
  count   = var.create_api_key && var.api_type == "rest" ? 1 : 0
  name    = "${var.environment_name}-${var.name}-api-key"
  enabled = true
}

resource "aws_ssm_parameter" "gateway_api_key" {
  count = var.create_api_key && var.api_type == "rest" ? 1 : 0
  name  = "/${var.environment_name}/${var.name}/api_key"
  type  = "SecureString"
  value = aws_api_gateway_api_key.api_key[0].value
}

resource "aws_api_gateway_usage_plan_key" "api_usage_plan" {
  count         = var.create_api_key && var.api_type == "rest" ? 1 : 0
  key_id        = aws_api_gateway_api_key.api_key[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.usage_plan[0].id
}

// File: auth0_custom_authorizer.tf
resource "aws_api_gateway_authorizer" "rest_authorizer" {
  for_each = { for custom_authorizer in var.custom_authorizers : custom_authorizer.name => custom_authorizer if var.api_type == "rest" }

  name                   = each.value.name
  rest_api_id            = aws_api_gateway_rest_api.rest_api[0].id
  authorizer_uri         = aws_lambda_function.authorizer[each.value.name].invoke_arn
  authorizer_credentials = aws_iam_role.invocation_role[each.value.name].arn
}

resource "aws_iam_role" "invocation_role" {
  for_each           = { for custom_authorizer in var.custom_authorizers : custom_authorizer.name => custom_authorizer if var.api_type == "rest" }
  name               = "api_gateway_auth_invocation-${each.value.name}"
  assume_role_policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Principal": {
                "Service": [
                    "lambda.amazonaws.com",
                    "apigateway.amazonaws.com"
                ]
            },
            "Action": "sts:AssumeRole"
        }
    ]
}
EOF
}

data "aws_iam_policy_document" "invocation_policy" {
  for_each = { for custom_authorizer in var.custom_authorizers : custom_authorizer.name => custom_authorizer if var.api_type == "rest" }
  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = [aws_lambda_function.authorizer[each.value.name].arn]
  }
}

resource "aws_iam_role_policy" "invocation_policy" {
  for_each = { for custom_authorizer in var.custom_authorizers : custom_authorizer.name => custom_authorizer if var.api_type == "rest" }
  name     = "auth-custom-authorizer-${each.value.name}-policy"
  role     = aws_iam_role.invocation_role[each.value.name].id
  policy   = data.aws_iam_policy_document.invocation_policy[each.value.name].json
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda" {
  for_each           = { for custom_authorizer in var.custom_authorizers : custom_authorizer.name => custom_authorizer if var.api_type == "rest" }
  name               = "custom-authorizer-lambda-${each.value.name}-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_lambda_function" "authorizer" {
  for_each         = { for custom_authorizer in var.custom_authorizers : custom_authorizer.name => custom_authorizer if var.api_type == "rest" }
  filename         = each.value.custom_authorizer_lambda_code
  function_name    = "api_gateway_authorizer-${each.value.name}-lambda"
  role             = aws_iam_role.lambda[each.value.name].arn
  handler          = "index.handler"
  source_code_hash = filebase64sha256(each.value.custom_authorizer_lambda_code)
  runtime          = "nodejs16.x"

  environment {
    variables = {
      AUDIENCE = ""
      JWKS_URI = ""
    }
  }
}

// File: domain_mapping.tf
resource "aws_apigatewayv2_domain_name" "domain_name" {
  for_each    = { for domain in var.domains : domain.domain => domain if var.api_type == "http" }
  domain_name = each.value.domain

  domain_name_configuration {
    certificate_arn = data.aws_acm_certificate.certificates[each.value.domain].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

resource "aws_apigatewayv2_api_mapping" "domain_mapping" {
  for_each        = { for domain in var.domains : domain.domain => domain if var.api_type == "http" }
  api_id          = aws_apigatewayv2_api.api[0].id
  domain_name     = aws_apigatewayv2_domain_name.domain_name[each.value.domain].id
  stage           = aws_apigatewayv2_stage.stage[0].id
  api_mapping_key = each.value.api_route_mapping
}

resource "aws_route53_record" "hosted_zone" {
  for_each = { for domain in var.domains : domain.domain => domain if var.api_type == "http" && var.create_dns_record }
  name     = aws_apigatewayv2_domain_name.domain_name[each.value.domain].domain_name
  type     = "A"
  zone_id  = data.aws_route53_zone.hosted_zones[each.value.domain].id

  alias {
    name                   = aws_apigatewayv2_domain_name.domain_name[each.value.domain].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.domain_name[each.value.domain].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_api_gateway_domain_name" "rest_domain_name" {
  for_each                 = { for domain in var.domains : domain.domain => domain if var.api_type == "rest" }
  domain_name              = each.value.domain
  regional_certificate_arn = data.aws_acm_certificate.certificates[each.value.domain].arn

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_base_path_mapping" "rest_api_mapping" {
  for_each    = { for domain in var.domains : domain.domain => domain if var.api_type == "rest" }
  api_id      = aws_api_gateway_rest_api.rest_api[0].id
  domain_name = aws_api_gateway_domain_name.rest_domain_name[each.value.domain].domain_name
  stage_name  = "${var.environment_name}-stage"
  depends_on  = [aws_api_gateway_stage.rest_stage]
}

resource "aws_route53_record" "rest_api_records" {
  for_each = { for domain in var.domains : domain.domain => domain if var.api_type == "rest" && var.create_dns_record }
  name     = aws_api_gateway_domain_name.rest_domain_name[each.value.domain].domain_name
  type     = "A"
  zone_id  = data.aws_route53_zone.hosted_zones[each.value.domain].id

  alias {
    evaluate_target_health = false
    name                   = aws_api_gateway_domain_name.rest_domain_name[each.value.domain].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest_domain_name[each.value.domain].regional_zone_id
  }
}

// File: http_api.tf
resource "aws_apigatewayv2_api" "api" {
  count         = var.api_type == "http" ? 1 : 0
  name          = var.name
  protocol_type = "HTTP"
  description   = try(var.api_description, "")
}

resource "aws_apigatewayv2_stage" "stage" {
  count       = var.api_type == "http" ? 1 : 0
  api_id      = aws_apigatewayv2_api.api[0].id
  name        = "${var.environment_name}-stage"
  auto_deploy = true
}

resource "aws_apigatewayv2_vpc_link" "gateway_vpc_link" {
  count              = var.api_type == "http" && var.create_vpc_link ? 1 : 0
  name               = "${var.environment_name}-${var.name}-vpclink"
  security_group_ids = []
  subnet_ids         = data.aws_subnets.current.ids
  tags               = var.tags
}

resource "aws_apigatewayv2_integration" "http_integration" {
  for_each           = { for integration in var.routes : integration.name => integration if var.api_type == "http" }
  api_id             = aws_apigatewayv2_api.api[0].id
  integration_type   = each.value.integration_type
  integration_method = each.value.integration_method
  integration_uri    = each.value.integration_uri
}
resource "aws_apigatewayv2_route" "integration_route" {
  for_each  = { for integration in var.routes : integration.name => integration if var.api_type == "http" }
  api_id    = aws_apigatewayv2_api.api[0].id
  route_key = "ANY /${each.value.api_route_mapping}"

  target = "integrations/${aws_apigatewayv2_integration.http_integration[each.value.name].id}"
}

// File: rest_api.tf
resource "aws_api_gateway_rest_api" "rest_api" {
  count = var.api_type == "rest" ? 1 : 0
  name  = "${var.environment_name}-${var.name}-api"
  endpoint_configuration {
    types = ["REGIONAL"]
  }

}

resource "aws_api_gateway_deployment" "rest_deployment" {
  count       = var.api_type == "rest" ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id

  triggers = {
    redeployment = sha1(jsonencode(flatten([
      [ for resource in var.routes : try(aws_api_gateway_resource.rest_resource[resource.name], {}) if var.api_type == "rest" && resource.name != "root" ],
      [ for method in var.routes : try(aws_api_gateway_method.rest_method[method.name], {}) if var.api_type == "rest" ],
      [ for integration in var.routes : try(aws_api_gateway_integration.integration[integration.name], {}) if var.api_type == "rest" ]
    ])))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [aws_api_gateway_method.rest_method, aws_api_gateway_integration.integration]
}

resource "aws_api_gateway_stage" "rest_stage" {
  count         = var.api_type == "rest" ? 1 : 0
  deployment_id = aws_api_gateway_deployment.rest_deployment[0].id
  rest_api_id   = aws_api_gateway_rest_api.rest_api[0].id
  stage_name    = "${var.environment_name}-stage"
}


data "aws_iam_policy_document" "ip_resource_policy" {
  count = var.api_type == "rest" && length(var.allowed_ips) > 0 ? 1 : 0
  statement {
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions   = ["execute-api:Invoke"]
    resources = [aws_api_gateway_rest_api.rest_api[0].execution_arn]

    condition {
      test     = "IpAddress"
      variable = "aws:SourceIp"
      values   = var.allowed_ips
    }
  }
}
resource "aws_api_gateway_rest_api_policy" "test" {
  count       = var.api_type == "rest" && length(var.allowed_ips) > 0 ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id
  policy      = data.aws_iam_policy_document.ip_resource_policy[0].json
}

#
#resource "aws_wafv2_web_acl_association" "rest_waf_association" {
#  count       = var.api_type == "rest" && length(var.web_acl_arn) > 0 ? 1 : 0
#  resource_arn  = aws_api_gateway_stage.rest_stage[var.name].arn
#  web_acl_arn   = var.web_acl_arn
#}

resource "aws_api_gateway_resource" "rest_resource" {
  for_each    = { for integration in var.routes : integration.name => integration if var.api_type == "rest" && integration.name != "root" }
  rest_api_id = aws_api_gateway_rest_api.rest_api[0].id
  parent_id   = aws_api_gateway_rest_api.rest_api[0].root_resource_id
  path_part   = each.value.route_mapping
}

resource "aws_api_gateway_method" "rest_method" {
  for_each      = { for integration in var.routes : integration.name => integration if var.api_type == "rest" }
  rest_api_id   = aws_api_gateway_rest_api.rest_api[0].id
  resource_id   = each.value.name == "root" ? aws_api_gateway_rest_api.rest_api[0].root_resource_id : aws_api_gateway_resource.rest_resource[each.value.name].id
  http_method   = each.value.method
  authorization = "NONE"

  request_parameters = { for path_param in try(each.value.path_parameters, []) : "method.request.path.${path_param}" => true }
}

resource "aws_api_gateway_integration" "integration" {
  for_each                = { for route in var.routes : route.name => route if var.api_type == "rest" }
  rest_api_id             = aws_api_gateway_rest_api.rest_api[0].id
  resource_id             = each.value.name == "root" ? aws_api_gateway_rest_api.rest_api[0].root_resource_id : aws_api_gateway_resource.rest_resource[each.value.name].id
  http_method             = each.value.method
  integration_http_method = aws_api_gateway_method.rest_method[each.value.name].http_method
  type                    = each.value.integration_type
  uri                     = each.value.integration_uri
  request_parameters = { for path_param in try(each.value.path_parameters, []) : "integration.request.path.${path_param}" => "method.request.path.${path_param}" }

  connection_type = each.value.connection_type
  connection_id   = var.create_vpc_link ? aws_api_gateway_vpc_link.gateway_vpc_link[0].id : ""
}

resource "aws_lb" "integration_vpc_endpoint" {
  count              = var.api_type == "rest" && var.create_vpc_link ? 1 : 0
  name               = "${var.environment_name}-${var.name}-gw"
  internal           = true
  load_balancer_type = "network"
  subnets            = data.aws_subnets.private.ids
}

resource "aws_api_gateway_vpc_link" "gateway_vpc_link" {
  count       = var.api_type == "rest" && var.create_vpc_link ? 1 : 0
  name        = "${var.environment_name}-${var.name}-vpclink"
  description = "${var.environment_name}-${var.name} API Gateway VPC LINK"
  target_arns = [aws_lb.integration_vpc_endpoint[0].arn]
}

resource "aws_lb_target_group" "vpc_integration_tg" {
  count        = var.api_type == "rest" && var.create_vpc_link ? 1 : 0
  name        = "${var.environment_name}-${var.name}-tg"
  target_type = "alb"
  port        = var.vpc_link_target_port
  protocol    = "TCP"
  vpc_id      = data.aws_vpc.current.id
  health_check {
    matcher  = "200"
    path     = "/"
    protocol = "HTTPS"
  }
}

resource "aws_lb_target_group_attachment" "vpc_integration_tg_attachment" {
  count             = var.api_type == "rest" && var.create_vpc_link ? 1 : 0
  target_group_arn  = aws_lb_target_group.vpc_integration_tg[0].arn
  target_id         = var.vpc_link_target_id
  port              = var.vpc_link_target_port
}

resource "aws_lb_listener" "https" {
  count             = var.api_type == "rest" && var.create_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.integration_vpc_endpoint[0].arn
  port              = var.vpc_link_target_port
  protocol          = "TCP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.vpc_integration_tg[0].arn
  }
}

// File: versions.tf
terraform {
  required_version = ">= 0.13.0"
}

// File: main.tf
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Add this to the top of main.tf
resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = var.bucket_name != "" ? var.bucket_name : "cloudtrail-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_string.suffix.result}"
  force_destroy = var.bucket_force_destroy
}

resource "aws_s3_bucket_versioning" "cloudtrail_bucket_versioning" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = var.enable_s3_bucket_versioning ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_bucket_policy" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck20150319"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_logs.arn
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/${var.cloudtrail_name != "" ? var.cloudtrail_name : "main-trail-${data.aws_region.current.name}-${random_string.suffix.result}"}"
          }
        }
      },
      {
        Sid    = "AWSCloudTrailWrite20150319"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
            "AWS:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/${var.cloudtrail_name != "" ? var.cloudtrail_name : "main-trail-${data.aws_region.current.name}-${random_string.suffix.result}"}"
          }
        }
      } 
    ]
  })
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail logs encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/cloudtrail-${data.aws_region.current.name}-${random_string.suffix.result}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}


resource "aws_kms_key_policy" "cloudtrail" {
  key_id = aws_kms_key.cloudtrail.id
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "Key policy for CloudTrail"
    Statement = concat([
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to encrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:${data.aws_partition.current.partition}:cloudtrail:arn" = "arn:${data.aws_partition.current.partition}:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*"
          }
        }
      },
      {
        Sid    = "Allow CloudWatch Log Group Encrypt"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:${data.aws_partition.current.partition}:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"
          }
        }
      }
    ],
    var.decrypt_role_arn != "" ? [
      {
        Sid    = "AllowRoleToDecryptCloudTrailFiles"
        Effect = "Allow"
        Principal = {
          AWS = var.decrypt_role_arn
        }
        Action   = "kms:Decrypt"
        Resource = aws_kms_key.cloudtrail.arn
        Condition = {
          Null = {
            "kms:EncryptionContext:${data.aws_partition.current.partition}:cloudtrail:arn" = "false"
          }
        }
      }
    ] : [])
  })
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "/aws/cloudtrail/${var.cloudtrail_name != "" ? var.cloudtrail_name : "main-trail-${data.aws_region.current.name}-${random_string.suffix.result}"}"
  retention_in_days = var.log_retention_days
}

resource "aws_iam_role" "cloudwatch_logs_role" {
  name = "cloudwatch-logs-role-${data.aws_region.current.name}-${random_string.suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_logs_policy" {
  name = "cloudwatch-logs-policy-${data.aws_region.current.name}"
  role = aws_iam_role.cloudwatch_logs_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_sns_topic" "cloudtrail_alerts" {
  count = var.create_sns_topic ? 1 : 0
  name  = var.sns_topic_name != "" ? var.sns_topic_name : "cloudtrail-alerts-${data.aws_region.current.name}"
}

resource "aws_sns_topic_policy" "cloudtrail_alerts" {
  count  = var.create_sns_topic ? 1 : 0
  arn    = aws_sns_topic.cloudtrail_alerts[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.cloudtrail_alerts[0].arn
      }
    ]
  })
}

resource "aws_cloudtrail" "main" {
  name                          = var.cloudtrail_name != "" ? var.cloudtrail_name : "main-trail-${data.aws_region.current.name}-${random_string.suffix.result}"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  enable_log_file_validation    = true
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudwatch_logs_role.arn
  is_organization_trail         = var.is_organization_trail
  sns_topic_name                = var.create_sns_topic ? aws_sns_topic.cloudtrail_alerts[0].arn : var.existing_sns_topic_arn

  # Always include management events
  event_selector {
    read_write_type           = var.rw_type
    include_management_events = var.include_management_events

    dynamic "data_resource" {
      for_each = var.data_resources
      content {
        type   = data_resource.value.type
        values = data_resource.value.values
        }
      }
    }

    dynamic "insight_selector" {
      for_each = var.insight_selector
      content {
        insight_type = insight_selector.value.insight_type
      }
  }
}

// File: outputs.tf
output "cloudtrail_id" {
  description = "The name of the trail"
  value       = aws_cloudtrail.main.id
}

output "cloudtrail_arn" {
  description = "The Amazon Resource Name of the trail"
  value       = aws_cloudtrail.main.arn
}

output "s3_bucket_id" {
  description = "The name of the S3 bucket"
  value       = aws_s3_bucket.cloudtrail_logs.id
}

output "s3_bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = aws_s3_bucket.cloudtrail_logs.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encrypting CloudTrail logs"
  value       = aws_kms_key.cloudtrail.arn
}

output "cloudwatch_log_group_arn" {
  description = "The ARN of the CloudWatch log group"
  value       = aws_cloudwatch_log_group.cloudtrail.arn
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic used for CloudTrail notifications"
  value       = var.create_sns_topic ? aws_sns_topic.cloudtrail_alerts[0].arn : var.existing_sns_topic_arn
}

output "kms_key_id" {
  description = "The ID of the KMS key used for encrypting CloudTrail logs"
  value       = aws_kms_key.cloudtrail.key_id
}

// File: variables.tf
variable "bucket_name" {
  description = "The name of the S3 bucket for CloudTrail logs. If empty, a name will be generated."
  type        = string
  default     = ""
}

variable "is_organization_trail" {
  description = "Specifies whether the trail is an AWS Organizations trail. Organization trails log events for the master account and all member accounts. Can only be created in the organization master account."
  type        = bool
  default     = false
}

variable "bucket_force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error"
  type        = bool
  default     = true
}

variable "cloudtrail_name" {
  description = "The name of the CloudTrail. If empty, a name will be generated."
  type        = string
  default     = ""
}

variable "include_global_service_events" {
  description = "Specifies whether the trail is publishing events from global services such as IAM to the log files"
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Specifies whether the trail is created in the current region or in all regions"
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enables logging for the trail"
  type        = bool
  default     = true
}

variable "log_retention_days" {
  description = "Specifies the number of days you want to retain log events in the CloudWatch log group"
  type        = number
  default     = 90
}

variable "create_sns_topic" {
  description = "Specifies whether to create an SNS topic for CloudTrail notifications"
  type        = bool
  default     = false
}

variable "sns_topic_name" {
  description = "The name of the SNS topic to create for CloudTrail notifications. If empty, a name will be generated."
  type        = string
  default     = ""
}

variable "existing_sns_topic_arn" {
  description = "The ARN of an existing SNS topic to use for CloudTrail notifications. Only used if create_sns_topic is false."
  type        = string
  default     = ""
}

variable "enable_s3_bucket_versioning" {
  description = "Enable versioning on the S3 bucket"
  type        = bool
  default     = false
}

variable "decrypt_role_arn" {
  description = "ARN of the IAM role allowed to decrypt CloudTrail log files. If provided, a policy statement will be added to the KMS key to allow decryption."
  type        = string
  default     = ""
}

variable "include_management_events" {
  type    = bool
  default = true
}

variable "data_resource_type" {
  type    = string
  default = "AWS::S3::Object"
}

variable "data_resources" {
  type = list(object({
    type   = string
    values = list(string)
  }))
  default     = []
  description = "List of data resources to log events for. Each object should contain 'type' and 'values' keys."
}

variable "rw_type" {
  description = "Specifies whether to log read-only events, write-only events, or all events for data resources."
  type        = string
  default     = "All"
  validation {
    condition     = contains(["ReadOnly", "WriteOnly", "All"], var.rw_type)
    error_message = "rw_type must be one of ReadOnly, WriteOnly, or All."
  }
}

variable "insight_selector" {
  description = "List of insight types to enable for the trail. Valid values are ApiCallRateInsight and ApiErrorRateInsight."
  type = list(object({
    insight_type = string
  }))
  default = []
  validation {
    condition     = alltrue([for insight in var.insight_selector : contains(["ApiCallRateInsight", "ApiErrorRateInsight"], insight.insight_type)])
    error_message = "Invalid insight type. Allowed values are ApiCallRateInsight and ApiErrorRateInsight."
  }
}

// File: versions.tf
terraform {
  required_version = ">= 0.13.1"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.0"
    }
  }
}

// File: elasticsearch_domain.tf
#---------------------------------------------------
# AWS elasticsearch domain
#---------------------------------------------------
resource "aws_elasticsearch_domain" "elasticsearch_domain" {
  count = var.enable_elasticsearch_domain ? 1 : 0

  domain_name = var.elasticsearch_domain_name != "" ? var.elasticsearch_domain_name : "${lower(var.name)}-es-domain-${lower(var.environment)}"

  elasticsearch_version = var.elasticsearch_domain_elasticsearch_version
  advanced_options      = var.elasticsearch_domain_advanced_options
  access_policies       = var.elasticsearch_domain_access_policies

  dynamic "advanced_security_options" {
    iterator = advanced_security_options
    for_each = length(keys(var.elasticsearch_domain_advanced_security_options)) > 0 ? [var.elasticsearch_domain_advanced_security_options] : []

    content {
      enabled                        = lookup(advanced_security_options.value, "enabled", null)
      internal_user_database_enabled = lookup(advanced_security_options.value, "internal_user_database_enabled", null)

      dynamic "master_user_options" {
        iterator = master_user_options
        for_each = length(keys(lookup(advanced_security_options.value, "master_user_options", {}))) > 0 ? [lookup(advanced_security_options.value, "master_user_options", {})] : []

        content {
          master_user_arn      = lookup(master_user_options.value, "master_user_arn", null)
          master_user_name     = lookup(master_user_options.value, "master_user_name", null)
          master_user_password = lookup(master_user_options.value, "master_user_password", null)
        }
      }

    }
  }

  dynamic "ebs_options" {
    iterator = ebs_options
    for_each = length(keys(var.elasticsearch_domain_ebs_options)) > 0 ? [var.elasticsearch_domain_ebs_options] : []

    content {
      ebs_enabled = lookup(ebs_options.value, "ebs_enabled", null)

      volume_type = lookup(ebs_options.value, "volume_type", null)
      volume_size = lookup(ebs_options.value, "volume_size", null)
      iops        = lookup(ebs_options.value, "iops", null)
    }
  }

  dynamic "encrypt_at_rest" {
    iterator = encrypt_at_rest
    for_each = length(keys(var.elasticsearch_domain_encrypt_at_rest)) > 0 ? [var.elasticsearch_domain_encrypt_at_rest] : []

    content {
      enabled = lookup(encrypt_at_rest.value, "enabled", null)

      kms_key_id = lookup(encrypt_at_rest.value, "kms_key_id", null)
    }
  }

  dynamic "node_to_node_encryption" {
    iterator = node_to_node_encryption
    for_each = length(keys(var.elasticsearch_domain_node_to_node_encryption)) > 0 ? [var.elasticsearch_domain_node_to_node_encryption] : []

    content {
      enabled = lookup(node_to_node_encryption.value, "enabled", null)
    }
  }

  dynamic "cluster_config" {
    iterator = cluster_config
    for_each = var.elasticsearch_domain_cluster_config

    content {
      instance_type            = lookup(cluster_config.value, "instance_type", null)
      instance_count           = lookup(cluster_config.value, "instance_count", null)
      dedicated_master_enabled = lookup(cluster_config.value, "dedicated_master_enabled", null)
      dedicated_master_type    = lookup(cluster_config.value, "dedicated_master_type", null)
      dedicated_master_count   = lookup(cluster_config.value, "dedicated_master_count", null)
      zone_awareness_enabled   = lookup(cluster_config.value, "zone_awareness_enabled", null)
      warm_enabled             = lookup(cluster_config.value, "warm_enabled", null)
      warm_count               = lookup(cluster_config.value, "warm_count", null)
      warm_type                = lookup(cluster_config.value, "warm_type", null)

      dynamic "zone_awareness_config" {
        iterator = zone_awareness_config
        for_each = length(keys(lookup(cluster_config.value, "zone_awareness_config", {}))) > 0 ? [lookup(cluster_config.value, "zone_awareness_config", {})] : []

        content {
          availability_zone_count = lookup(zone_awareness_config.value, "availability_zone_count", null)
        }
      }
    }
  }

  dynamic "vpc_options" {
    iterator = vpc_options
    for_each = length(keys(var.elasticsearch_domain_vpc_options)) > 0 ? [var.elasticsearch_domain_vpc_options] : []

    content {
      subnet_ids = lookup(vpc_options.value, "subnet_ids", null)

      security_group_ids = lookup(vpc_options.value, "security_group_ids", null)
    }
  }

  dynamic "snapshot_options" {
    iterator = snapshot_options
    for_each = length(keys(var.elasticsearch_domain_snapshot_options)) > 0 ? [var.elasticsearch_domain_snapshot_options] : []

    content {
      automated_snapshot_start_hour = lookup(snapshot_options.value, "automated_snapshot_start_hour", null)
    }
  }

  dynamic "log_publishing_options" {
    iterator = log_publishing_options
    for_each = length(keys(var.elasticsearch_domain_log_publishing_options)) > 0 ? [var.elasticsearch_domain_log_publishing_options] : []

    content {
      cloudwatch_log_group_arn = lookup(log_publishing_options.value, "cloudwatch_log_group_arn", null)
      log_type                 = lookup(log_publishing_options.value, "log_type", null)
    }
  }

  dynamic "cognito_options" {
    iterator = cognito_options
    for_each = length(keys(var.elasticsearch_domain_cognito_options)) > 0 ? [var.elasticsearch_domain_cognito_options] : []

    content {
      user_pool_id     = lookup(cognito_options.value, "user_pool_id", null)
      identity_pool_id = lookup(cognito_options.value, "identity_pool_id", null)
      role_arn         = lookup(cognito_options.value, "role_arn", null)

      enabled = lookup(cognito_options.value, "enabled", null)
    }
  }

  dynamic "domain_endpoint_options" {
    iterator = domain_endpoint_options
    for_each = length(keys(var.elasticsearch_domain_domain_endpoint_options)) > 0 ? [var.elasticsearch_domain_domain_endpoint_options] : []

    content {
      enforce_https = lookup(domain_endpoint_options.value, "enforce_https", null)

      tls_security_policy = lookup(domain_endpoint_options.value, "tls_security_policy", null)
    }
  }

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.elasticsearch_domain_timeouts)) > 0 ? [var.elasticsearch_domain_timeouts] : []

    content {
      update = lookup(timeouts.value, "update", null)
    }
  }

  tags = merge(
    {
      Name = var.elasticsearch_domain_name != "" ? var.elasticsearch_domain_name : "${lower(var.name)}-es-domain-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: elasticsearch_domain_policy.tf
#---------------------------------------------------
# AWS elasticsearch domain policy
#---------------------------------------------------
resource "aws_elasticsearch_domain_policy" "elasticsearch_domain_policy" {
  count = var.enable_elasticsearch_domain_policy ? 1 : 0

  domain_name = var.elasticsearch_domain_policy_domain_name != "" ? var.elasticsearch_domain_policy_domain_name : (var.enable_elasticsearch_domain ? aws_elasticsearch_domain.elasticsearch_domain[0].domain_name : null)

  access_policies = var.elasticsearch_domain_policy_access_policies

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_elasticsearch_domain.elasticsearch_domain
  ]
}

