// File: cloudfront.tf
# AWS Managed Caching Policies for CloudFront
data "aws_cloudfront_cache_policy" "cache-none" {
  name = "Managed-CachingDisabled"
}

data "aws_cloudfront_cache_policy" "cache-optimized" {
  name = "Managed-CachingOptimized"
}


resource "aws_cloudfront_distribution" "web" {
  provider = aws.us-east-1
  origin {
    domain_name              = aws_s3_bucket.website.bucket_regional_domain_name
    origin_id                = "S3-OriginID-${aws_s3_bucket.website.id}"
    origin_access_control_id = aws_cloudfront_origin_access_control.web.id
  }

  aliases = local.alias_list

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = var.cloudfront_default_root_object

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    target_origin_id       = "S3-OriginID-${aws_s3_bucket.website.id}"
    cache_policy_id        = data.aws_cloudfront_cache_policy.cache-optimized.id
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
  }

  # because React uses index.html to load the dynamically named content files (css + js), 
  # we'r setting a no cache policy on the index.html file, so that we don't have to wait for 
  # the cache to expire before any updates to our website are viewable in the browser
  ordered_cache_behavior {
    path_pattern           = "/index.html"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    target_origin_id       = "S3-OriginID-${aws_s3_bucket.website.id}"
    cache_policy_id        = data.aws_cloudfront_cache_policy.cache-none.id
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
  }

  price_class = var.cloudfront_price_class

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  # # fall back to the cloudfront_default_certificate if we didn't create a cert for our custom domain
  viewer_certificate {
    acm_certificate_arn            = length(aws_acm_certificate.web) > 0 ? aws_acm_certificate.web[0].arn : null
    ssl_support_method             = length(aws_acm_certificate.web) > 0 ? "sni-only" : null
    minimum_protocol_version       = length(aws_acm_certificate.web) > 0 ? var.cloudfront_minimum_protocol_version : null
    cloudfront_default_certificate = length(aws_acm_certificate.web) > 0 ? null : true
  }

  dynamic "custom_error_response" {
    for_each = var.cloudfront_custom_error_responses
    content {
      error_code            = custom_error_response.value.error_code
      response_code         = custom_error_response.value.response_code
      error_caching_min_ttl = custom_error_response.value.error_caching_min_ttl
      response_page_path    = custom_error_response.value.response_page_path
    }
  }

  wait_for_deployment = false

  depends_on = [
    aws_acm_certificate.web,
    aws_acm_certificate_validation.web
  ]
}

resource "aws_cloudfront_origin_access_control" "web" {
  name                              = aws_s3_bucket.website.id
  description                       = "${aws_s3_bucket.website.id} Origin Access Control"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

// File: dns.tf
resource "aws_acm_certificate" "web" {
  count                     = var.domain_name != "" ? 1 : 0
  provider                  = aws.us-east-1
  domain_name               = var.domain_name
  subject_alternative_names = local.alias_list_certs
  validation_method         = "DNS"

  lifecycle {
    create_before_destroy = true
    precondition {
      condition     = (var.domain_name != "" && var.hostedzone_id != "")
      error_message = "A Hosted Zone ID variable (var.hostedzone_id) must be set if the var.domain_name is set"
    }
  }
}

resource "aws_route53_record" "validation" {
  # Use a conditional expression to check if aws_acm_certificate.this exists.
  # If it does, iterate over its domain_validation_options. Otherwise, provide an empty map.
  for_each = length(aws_acm_certificate.web) > 0 ? {
    for dvo in aws_acm_certificate.web[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 60
  type            = each.value.type
  zone_id         = var.hostedzone_id
}


resource "aws_acm_certificate_validation" "web" {
  count                   = length(aws_acm_certificate.web) > 0 ? 1 : 0
  provider                = aws.us-east-1
  certificate_arn         = aws_acm_certificate.web[0].arn
  validation_record_fqdns = [for record in aws_route53_record.validation : record.fqdn]
}


resource "aws_route53_record" "domain_name_records" {
  for_each = length(local.alias_list) > 0 ? local.alias_list_map : {}

  type    = "A"
  zone_id = var.hostedzone_id
  name    = each.key

  alias {
    name                   = aws_cloudfront_distribution.web.domain_name
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

// File: main.tf
terraform {
  backend "local" {
    path = "tfstate/terraform.tfstate"
  }
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Your target AWS region
provider "aws" {
  region = var.aws_region
  profile = var.aws_profile
  default_tags {
    tags = var.aws_default_tags
  }
}

# Cloudfront needs the us-east-1 region
provider "aws" {
  region = "us-east-1"
  alias  = "us-east-1"
  default_tags {
    tags = var.aws_default_tags
  }
}

resource "random_id" "id" {
  byte_length = 8
}

locals {
  alias_list       = var.domain_name != "" ? (var.domain_name_with_www ? [var.domain_name, "www.${var.domain_name}"] : [var.domain_name]) : []
  alias_list_map   = { for name in local.alias_list : name => name }
  alias_list_certs = var.domain_name != "" ? (var.domain_name_with_www ? ["*.${var.domain_name}"] : []) : []
  s3_bucket_name   = var.s3_bucket_custom_name == "" ? var.domain_name : var.s3_bucket_custom_name
  s3_fallback_name = "webapp-template-${random_id.id.hex}"
  parent_directory = abspath("${dirname(path.module)}/..")
}

// File: outputs.tf
output "acm_certificate_id" {
  value = length(aws_acm_certificate.web) > 0 ? aws_acm_certificate.web[0].id : "cloudfront_default_certificate"
}

output "cloudfront_domain_name" {
  value = aws_cloudfront_distribution.web.domain_name
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.web.id
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.website.arn
}

output "s3_bucket_id" {
  value = aws_s3_bucket.website.id
}

output "web_url" {
  value = format("https://%s", var.domain_name != "" ? var.domain_name : aws_cloudfront_distribution.web.domain_name)
}

// File: s3.tf
# Only CloudFront can read from this bucket, otherwise it's private
data "aws_iam_policy_document" "cfweb" {
  statement {
    sid       = "AllowCloudFrontServicePrincipal"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.website.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.web.arn]
    }

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket" "website" {
  bucket = local.s3_bucket_name == "" ? local.s3_fallback_name : local.s3_bucket_name
}

resource "aws_s3_bucket_policy" "website" {
  bucket = aws_s3_bucket.website.id
  policy = data.aws_iam_policy_document.cfweb.json
}

resource "aws_s3_bucket_versioning" "website" {
  count  = var.s3_bucket_versioning == true ? 1 : 0
  bucket = aws_s3_bucket.website.id
  versioning_configuration {
    status = "Enabled"
  }
}

// File: variables.tf
# Most Commonly Used Variables for Application Configuration
#
variable "domain_name" {
  type        = string
  description = "Domain name for website, used for all resources"
  default     = ""
}

variable "domain_name_with_www" {
  type        = bool
  description = "Add alias 'www.(var.domain_name)' to our CloudFront distribution?"
  default     = false
}

variable "hostedzone_id" {
  type        = string
  description = "Hosted Zone ID for domain name"
  default     = ""
}


# Other AWS Resource Settings Available for Application Fine Tuning
#
variable "aws_default_tags" {
  type        = map(string)
  description = "Tags for all resources"
  default = {
    Terraform = "true"
  }
}

# If not set, Terraform looks for the environment variable "AWS_PROFILE"
# in this project, that env variable is set during the Make build/deploy process. 
# The default AWS_PROFILE value is "default", but can be changed in the .makerc file
variable "aws_profile" {
  type        = string
  description = "AWS profile to use"
  default     = null
}

variable "aws_region" {
  type        = string
  description = "Region for resources"
  default     = "us-west-2"
}

variable "cloudfront_custom_error_responses" {
  type = list(object({
    error_code            = number
    response_code         = number
    error_caching_min_ttl = number
    response_page_path    = string
  }))
  description = "See https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/GeneratingCustomErrorResponses.html"
  default = [
    {
      error_code            = 403
      response_code         = 404
      error_caching_min_ttl = 10
      response_page_path    = "/index.html"
    },
    {
      error_code            = 404
      response_code         = 404
      error_caching_min_ttl = 10
      response_page_path    = "/index.html"
    }
  ]
}

variable "cloudfront_default_root_object" {
  type        = string
  description = "Default root object for cloudfront. Need to also provide custom error response if changing from default"
  default     = "index.html"
}

variable "cloudfront_minimum_protocol_version" {
  type        = string
  description = "The minimum version of the SSL protocol that you want CloudFront to use for HTTPS connections."
  default     = "TLSv1.2_2021"
}

variable "cloudfront_price_class" {
  type        = string
  description = "CloudFront distribution price class"
  default     = "PriceClass_100" # Only US,Canada,Europe
}

variable "s3_bucket_custom_name" {
  type        = string
  description = "Any non-empty string here will replace default name of bucket `var.domain_name`"
  default     = ""
}

variable "s3_bucket_versioning" {
  type        = bool
  description = "Apply versioning to S3 bucket?"
  default     = false
}

