  require_symbols                = var.require_symbols
  require_uppercase_characters   = var.require_uppercase_characters
}

// File: variables.tf
variable "create_account_alias" {
  type        = bool
  default     = false
  description = "Whether to create IAM account alias"
}

variable "account_alias" {
  type        = string
  default     = null
  description = "The account alias"
}

variable "create_account_password_policy" {
  type        = bool
  default     = false
  description = "Whether to create IAM account password policy"
}

variable "allow_users_to_change_password" {
  type        = bool
  default     = true
  description = "Whether to allow users to change their own password"
}

variable "hard_expiry" {
  type        = bool
  default     = null
  description = "Whether users are prevented from setting a new password after their password has expired "
}

variable "max_password_age" {
  type        = number
  default     = null
  description = "The number of days that an user password is valid"
}

variable "minimum_password_length" {
  type        = number
  default     = 6
  description = "Minimum length to require for user passwords"
}

variable "password_reuse_prevention" {
  type        = number
  default     = null
  description = "The number of previous passwords that users are prevented from reusing"
}

variable "require_lowercase_characters" {
  type        = bool
  default     = null
  description = "Whether to require lowercase characters for user passwords"
}

variable "require_numbers" {
  type        = bool
  default     = null
  description = "Whether to require numbers for user passwords"
}

variable "require_symbols" {
  type        = bool
  default     = null
  description = "Whether to require symbols for user passwords"
}

variable "require_uppercase_characters" {
  type        = bool
  default     = null
  description = "Whether to require uppercase characters for user passwords"
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.1"
    }
  }

  required_version = ">= 1.0"
}

// File: inputs.tf
variable "enable_key_rotation" {
  type        = bool
  description = "Enable annual key rotation for KMS keys"
  default     = false
}

variable "cluster_tag" {
  type        = string
  description = "Tag to be used across all resources to namespace clusters."
  default     = "default"
}

variable "machine_roles" {
  type        = map(set(string))
  description = "Map of role name to role policy identifiers"
  default     = {}
}

// File: kms.tf
resource "aws_kms_key" "vault_key" {
  description         = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation = var.enable_key_rotation

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

data "aws_iam_policy_document" "vault_kms_unseal" {
  statement {
    sid       = "VaultKMSUnseal"
    effect    = "Allow"
    resources = [aws_kms_key.vault_key.arn]

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
  }
}

resource "aws_iam_policy" "vault_kms_unseal" {
  name        = "ResinStackKMSUnseal-${var.cluster_tag}"
  description = "Allow unsealing a vault with a KMS key"

  policy = data.aws_iam_policy_document.vault_kms_unseal.json
}

// File: outputs.tf
output "vault_key_id" {
  value       = aws_kms_key.vault_key.id
  description = "ID of the Vault KMS key"
}

output "secretmanager_names" {
  value       = { for key, value in aws_secretsmanager_secret.hashistack_minimal : key => value.name }
  description = "AWS-SM secret names for key resinstack secrets"
}

output "machine_role" {
  value       = { for name, role in aws_iam_role.resinstack_machine_role : name => role.name }
  description = "Map of name to role name for machine roles"
}

output "machine_profile" {
  value       = { for name, profile in aws_iam_instance_profile.machine_profile : name => profile.name }
  description = "Map of name to role ARN for machine profiles"
}

// File: roles.tf
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "resinstack_machine_role" {
  for_each = var.machine_roles

  name                 = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600 * 12

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_role_policy_attachment" "read_tags" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "read-tags") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.read_tags.arn
}

resource "aws_iam_role_policy_attachment" "vault_kms_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "vault-kms") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.vault_kms_unseal.arn
}

resource "aws_iam_role_policy_attachment" "nomad_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "nomad-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.nomad_server_key_access.arn
}

resource "aws_iam_role_policy_attachment" "consul_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "consul-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.consul_server_key_access.arn
}

resource "aws_iam_role_policy_attachment" "vault_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "vault-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.vault_server_key_access.arn
}

resource "aws_iam_role_policy_attachment" "client_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "client-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.client_key_access.arn
}

resource "aws_iam_instance_profile" "machine_profile" {
  for_each = var.machine_roles

  name = "resinstack-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.resinstack_machine_role[each.key].name
}

// File: secrets.tf
resource "aws_secretsmanager_secret" "hashistack_minimal" {
  for_each = toset([
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token",
  ])

  name = "resinstack-${each.value}-${var.cluster_tag}"

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }

}

data "aws_iam_policy_document" "client_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-agent-token"].arn,
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-client-consul-token"].arn,
    ]
  }
}

resource "aws_iam_policy" "client_key_access" {
  name        = "ResinStackClientKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to clients"

  policy = data.aws_iam_policy_document.client_keys.json
}

data "aws_iam_policy_document" "nomad_server_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-agent-token"].arn,
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-server-consul-token"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-vault-token"].arn,
    ]
  }
}

resource "aws_iam_policy" "nomad_server_key_access" {
  name        = "ResinStackNomadServerKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to Nomad servers"

  policy = data.aws_iam_policy_document.nomad_server_keys.json
}

data "aws_iam_policy_document" "consul_server_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
    ]
  }
}

resource "aws_iam_policy" "consul_server_key_access" {
  name        = "ResinStackConsulServerKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to Consul servers"

  policy = data.aws_iam_policy_document.consul_server_keys.json
}

data "aws_iam_policy_document" "vault_server_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["vault-consul-token"].arn,
    ]
  }
}

resource "aws_iam_policy" "vault_server_key_access" {
  name        = "ResinStackVaultServerKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to Vault servers"

  policy = data.aws_iam_policy_document.vault_server_keys.json
}

// File: tags.tf
data "aws_iam_policy_document" "read_tags" {
  statement {
    actions   = ["ec2:DescribeInstances"]
    effect    = "Allow"
    resources = ["*"]
  }
}

resource "aws_iam_policy" "read_tags" {
  name   = "ResinStackReadTags"
  policy = data.aws_iam_policy_document.read_tags.json
}

// File: _1_main.tf
/*
this is a learning project for me

after learning terraform for 2 days - second attempt at building my infrastructure

##################################################### a few notes ######################################################
if you see an empty comment space ie.
# it is usually because the function/resource/variable/etc explains itself
# there is quite a few topics

########################################################################################################################
***************** there are some pretty specific explanations regarding a few of the trickier aspects ******************
#   having said that - there will be a few conventions that carry on throughout the code explanations for these will   #
#                                            declared in this block                                                    #
                                    :: topics are in order of construction ::

_one_ ::  explanation of tagging system can be found in _3_vpc_structure.tf
          tags are used to implement the following properties during terraform construction:
              vpc name
              create one private && public subnet in each available availability zone according to selected region
              name each subnet as follows: (vpc), (region+availability zone), (tag designating public or private subnet)
              dynamically assign ip address ranges to given subnets
              create one private and public route table in vpc
              name each route table following explained conventions






_!_twenty_!_ :: construction zone located in :: _private_route_tables.tf (developer setup enabling)
                                                _vpc_structures.tf
             :: developer setup enabled
************************************************************************************************************************
########################################################################################################################
# portfolio project // blog infrastructure
# @author luis_cortez elluis.codes@gmail.com
# @version 0.02
*/
terraform {
  required_providers {
    aws           = {
      source      = "hashicorp/aws"
      version     = "~> 2.70"
    }
  }
}

# provide default aws cli and region information
provider "aws" {
  region          = var.aws_region
}

// File: _2_local_var_creator.tf
data "aws_region" "us-east-2" {}

locals {
  route_out_cidr = "0.0.0.0/0"
  region_name = "us-east-2"
  region_short_name = lookup(var.region_az_short_names, local.region_name)

  # this carries the local environment variables through the tag system
  default_tags = {
    Environment = lower(var.env_prefix)
  }

  # notice that the last field in the format string is "default" the tag we
  # be using to number our infrastructure names
  vpc_name_tag        = format("%s-%s-%s", upper(var.env_prefix), local.region_short_name, "default")
  public_label        = "elluis_public"
  private_label       = "elluis_private"
  nat_gw_label        = "elluis_nat_gateway"
}

// File: _3_vpc_structure.tf
# vpc construction
resource "aws_vpc" "elluis_vpc" {
  cidr_block                    = var.elluis_vpc_cidr_block
  instance_tenancy              = var.instance_tenancy
  enable_dns_hostnames          = var.enable_dns_hostnames
  enable_dns_support            = var.enable_dns_support
  enable_classiclink            = var.enable_classiclink
}

# internet gateway construction attached to vpc
resource "aws_internet_gateway" "elluis_internet_gateway" {
  # attach to elluis_vpc
  vpc_id                        = aws_vpc.elluis_vpc.id
  # begin collecting naming and counting data for cidr and az assignments
  # by using tag created in _2_local_var_creator.tf
  tags                          = local.default_tags
}
# developer mode switch
# I will only be creating one nat-gateway instead of all nat-gateways
# this nat-gateway will be attached to us-east-2c private subnet
# creates a nat-gateway named after the resource it is attached to
resource "aws_nat_gateway" "elluis_nat_gateway" {
  for_each = var.azs

  allocation_id = lookup(aws_eip.nat_ips, each.key).id
  subnet_id = lookup(aws_subnet.public, each.key).id
  tags = merge(
  local.default_tags,
  {
    Name = format(
    "%s-%s-%s",
    upper(var.env_prefix),
    lookup(var.region_az_short_names, format("%s%s", local.region_name, each.key)),
    local.nat_gw_label
    )
  },
  )
}

# assigns elastic (eip) ip to every nat-gateway to keep db ip address constant
  resource "aws_eip" "nat_ips" {
    for_each = var.azs

    vpc = true
    tags = merge(
    local.default_tags,
    {
      Name = format(
      "%s-%s-%s",
      upper(var.env_prefix),
      lookup(var.region_az_short_names, format("%s%s", local.region_name, each.key)),
      local.nat_gw_label
      )
    }
    )
  }

  # create public subnets in each az
  resource "aws_subnet" "public" {
    #_1_ for every availability zone
    for_each = var.azs
    #_2_ create a new subnet adding 32 to the value
    cidr_block = cidrsubnet(var.elluis_vpc_cidr_block, 8, each.value + 32)
    # assign availability zone        #us-east-2          # a , b, c :: as mapped in our variables
    # following values are assigned to the public az's
    availability_zone = format("%s%s", local.region_name, each.key)
    # us_east_2*
    map_public_ip_on_launch = true
    vpc_id = aws_vpc.elluis_vpc.id

    # name resource according to project name, az, and region
    # merging the tag allows us to carry this information to the next resource
    tags = merge(
    local.default_tags,
    {
      # tags our subnets with the appropriate 'Name'
      # ELLUIS_CODES_LIMITED_NETWORK-us_east_2a-elluis_public
      # ELLUIS_CODES_LIMITED_NETWORK-us_east_2b-elluis_public
      # ELLUIS_CODES_LIMITED_NETWORK-us_east_2c-elluis_public

      # creates our format template - be careful pay attention to commas!
      Name = format("%s-%s-%s", upper(var.env_prefix),
      lookup(var.region_az_short_names,
      # this puts together our us-east2 with a/b/c
      format("%s%s", local.region_name, each.key)),
      # finally attaching our elluis_public tag at the end
      local.public_label)
    }
    )
  }

# create public subnets in each az
resource "aws_subnet" "private" {
  for_each = var.azs
  # ensure that the final value entered in our cidrsubnet does not match our public subnets
  cidr_block                    = cidrsubnet(var.elluis_vpc_cidr_block, 8, each.value)
  availability_zone             = format("%s%s", local.region_name, each.key)
  map_public_ip_on_launch       = true
  vpc_id                        = aws_vpc.elluis_vpc.id

  tags                          = merge(
  local.default_tags,
  {
                                # following values are assigned to the public az's
                                # ELLUIS_CODES_LIMITED_NETWORK-us_east_2a-elluis_private
                                # ELLUIS_CODES_LIMITED_NETWORK-us_east_2b-elluis_private
                                # ELLUIS_CODES_LIMITED_NETWORK-us_east_2c-elluis_private
    Name                        = format("%s-%s-%s", upper(var.env_prefix),   # ELLUIS_CODES_LIMITED_NETWORK
                                lookup(var.region_az_short_names,             # us_east_2
                                format("%s%s", local.region_name, each.key)), # a - b -c
                                local.private_label)                          # elluis_private
  }
  )
}

// File: _4a_public_route_tables.tf
# create public route table
resource "aws_route_table" "public" {
  vpc_id                    = aws_vpc.elluis_vpc.id
  tags                      = merge(
  local.default_tags,
  {
                # it is important to note that this name will not dynamically - we are only spinning up one igw
                # since we will be attaching the internet gateway will be attached to all public subnets located
                # in the region
    Name                    =  format("%s-%s-%s",
                            upper(var.env_prefix),
                            local.region_short_name,
                            local.public_label
    )
  }
  )
}
# create aws public out route from all ports
resource "aws_route" "public_route_out_all" {
  # connect to public route table
  route_table_id = aws_route_table.public.id
  # create out all 0.0.0.0/0 ( passed from _2_ )
  destination_cidr_block    = local.route_out_cidr
  # connect to internet gateway ( created in _3_ )
  gateway_id                = aws_internet_gateway.elluis_internet_gateway.id
}

# create aws public route table association
resource "aws_route_table_association" "public" {
  # for availability availability zone
  for_each                  = var.azs
  # the following two lines associate the subnet with the route table and vice versa
  subnet_id                 = lookup(aws_subnet.public, each.key).id
  route_table_id            = aws_route_table.public.id
}

// File: _4b_private_route_tables.tf
# keeping both the public and private route tables separate is intentional
# keep them separate ! for heavens sake !


# 1_ create public route table
resource "aws_route_table" "private" {
  for_each = var.azs
  vpc_id = aws_vpc.elluis_vpc.id
  tags = merge(
  local.default_tags,
  {
    Name = format(
    "%s-%s-%s",
    upper(var.env_prefix),
    lookup(var.region_az_short_names, format("%s%s", local.region_name, each.key)),
    local.private_label
    )
  }
  )
}
# 2_ creates route for private subnets
resource "aws_route" "private_subnet_route" {
  for_each = var.azs

  destination_cidr_block = local.route_out_cidr
  route_table_id = lookup(aws_route_table.private, each.key).id
  # connecting the nat gateway to the subnet
  # at the moment I am commenting out this call - due to the fact that I do not want to pay nat gateway prices for 3
  # running nat gateways at this stage of development
  # just in-case of uncomment !!!... will still stop you from trying to connect all the nats!
//!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  nat_gateway_id = lookup(aws_nat_gateway.elluis_nat_gateway, each.key).id

  lifecycle {
    ignore_changes = [
      route_table_id,
      nat_gateway_id]
  }
}


# create aws public route table association
resource "aws_route_table_association" "private" {
  # for availability availability zone
  for_each                = var.azs
  # the following two lines associate the subnet with the route table and vice versa
  subnet_id               = lookup(aws_subnet.public, each.key).id
  route_table_id          = aws_route_table.public.id
}

// File: _60_vpc_command_variables.tf
# define main cidr_block
variable "elluis_vpc_cidr_block" {
  description   = "main vpc cidr block"
