terraform {
  required_version = ">= 0.14"
}

// File: main.tf
resource "aws_iam_role" "master" {
  name = "tf-${var.cluster_name}"

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "eks.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = "${aws_iam_role.master.name}"
}

resource "aws_iam_role_policy_attachment" "AmazonEKSServicePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
  role       = "${aws_iam_role.master.name}"
}
resource "aws_iam_role" "node" {
  name = "tf-${var.cluster_name}-node"

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = "${aws_iam_role.node.name}"
}

resource "aws_iam_role_policy_attachment" "AmazonEKS_CNI_Policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = "${aws_iam_role.node.name}"
}

resource "aws_iam_role_policy_attachment" "AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = "${aws_iam_role.node.name}"
}

resource "aws_iam_instance_profile" "node" {
  name = "tf-${var.cluster_name}-node"
  role = "${aws_iam_role.node.name}"
}

resource "aws_iam_role_policy_attachment" "node_autoscaling" {
  policy_arn = aws_iam_policy.node_autoscaling.arn
  role       = aws_iam_role.node.name
}

resource "aws_iam_policy" "node_autoscaling" {
  name_prefix = "eks-worker-autoscaling-${var.cluster_name}"
  description = "EKS worker node autoscaling policy for cluster ${var.cluster_name}"
  policy      = data.aws_iam_policy_document.node_autoscaling.json
}

data "aws_iam_policy_document" "node_autoscaling" {
  statement {
    sid    = "eksWorkerAutoscalingAll"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "eksWorkerAutoscalingOwn"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

// File: outputs.tf
output "master_role_arn" {
  value = aws_iam_role.master.arn
}

output "master_role_id" {
  value = aws_iam_role.master.id
}

output "node_role_arn" {
  value = aws_iam_role.node.arn
}

output "node_role_id" {
  value = aws_iam_role.node.id
}

output "node_instance_profile_name" {
  value = aws_iam_instance_profile.node.name
}

// File: variables.tf
variable "cluster_name" {
  default     = "legion"
  description = "Legion cluster name"
}

// File: versions.tf
terraform {
  required_version = ">= 0.12"
}

// File: main.tf
#----------------------------------------------#
# network-base: main                           #
# ./modules/aws/network-base/main.tf           #
#----------------------------------------------#


resource "aws_vpc" "vpc" {
  cidr_block = var.cidr_range

  tags = {
    Name = var.vpc_tag
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = var.pub_sub_cidr

  tags = {
    Name = var.pub_sub_tag
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = var.priv_sub_cidr

  tags = {
    Name = var.priv_sub_tag
  }
}


resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = var.igw_tag
  }
}

resource "aws_security_group" "sg_webserver" {
  vpc_id = aws_vpc.vpc.id
  name   = join("_", ["webserver-sg", aws_vpc.vpc.id])
  dynamic "ingress" {
    for_each = var.public_rules
    content {
      from_port   = ingress.value["port"]
      to_port     = ingress.value["port"]
      protocol    = ingress.value["porto"]
      cidr_blocks = ingress.value["cidr_blocks"]
    }
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.sg_apache_tag
  }
}

resource "aws_security_group" "sg_rds" {
  vpc_id = aws_vpc.vpc.id
  name   = join("_", ["database-sg", aws_vpc.vpc.id])
  ingress {
    description = "Allow traffic"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    # cidr_blocks = ["10.0.0.0/24"] # replace this with the actual source IP range of your application servers
  }
  #---- UNCOMMENT!!!!!!!!!!!!!!
  # tags = {
  #     Name = var.sg_rds_tag
  # }
}



# ---- Route Table
resource "aws_route_table" "rt_rtb" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  # route {
  #   ipv6_cidr_block        = "::/0"
  #   egress_only_gateway_id = aws_egress_only_internet_gateway.example.id
  # }

  tags = {
    Name = var.rtb_tag
  }
}

resource "aws_route_table_association" "rt_assoc_public" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.rt_rtb.id
}

# resource "aws_route_table_association" "rt_assoc_private" {
#   subnet_id = aws_subnet.private_subnet.id
#   route_table_id = aws_route_table.rt_rtb.id
# }

// File: outputs.tf
#----------------------------------------------#
# network-base: outputs                        #
# ./modules/aws/network-base/outputs.tf        #
#----------------------------------------------#

output "public_subnet_output" {
  description = "public subnet output"
  value       = aws_subnet.public_subnet.id
}

output "private_subnet_output" {
  description = "private subnet output"
  value       = aws_subnet.private_subnet.id
}

output "sg_webserver_output" {
  description = "security group webserver output"
  value       = aws_security_group.sg_webserver.id
}

output "sg_rds_output" {
  description = "security group database output"
  value       = aws_security_group.sg_rds.id
}

