  name  = module.other-label.id
  group = aws_iam_group.other.id
  users = var.other_user_names
}

// File: iam_policies.tf
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "role-trust" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "manage-self" {
  statement {
    sid = "AllowUsersToManageTheirUser"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:DeleteAccessKey",
      "iam:UpdateAccessKey",
      "iam:CreateAccessKey",
      "iam:ChangePassword",
      "iam:DeleteLoginProfile",
      "iam:List*",
      "iam:Get*",
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/&{aws:username}",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    sid = "AllowUsersToDeactivateTheirOwnVirtualMFADevice"

    actions = [
      "iam:DeactivateMFADevice",
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/&{aws:username}",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/&{aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid = "AllowUsersToListMFADevicesandUsersForConsole"

    actions = [
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ListUsers",
    ]

    resources = ["*"]
  }

  statement {
    actions   = ["iam:GetAccountPasswordPolicy"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "assume-role-admin" {
  statement {
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

// File: labels.tf
module "admin-label" {
  source      = "cloudposse/label/null"
  version     = "0.24.1"
  namespace   = var.namespace
  environment = var.environment
  name        = var.admin_name
  tags        = var.tags
  attributes  = var.attributes
}

module "other-label" {
  source      = "cloudposse/label/null"
  version     = "0.24.1"
  namespace   = var.namespace
  environment = var.environment
  name        = var.other_group_name
  tags        = var.tags
  attributes  = var.attributes
}

// File: output.tf
output "group_admin_name" {
  description = "The admin groups name"
  value       = aws_iam_group.admin.name
}

output "group_admin_id" {
  description = "The admin groups ID"
  value       = aws_iam_group.admin.id
}

output "group_admin_arn" {
  description = "The ARN assigned by AWS for the admin group"
  value       = aws_iam_group.admin.arn
}

output "group_admin_path" {
  description = "The path of the admin group in IAM"
  value       = aws_iam_group.admin.path
}

output "group_admin_users" {
  description = "List of IAM User names in the admin group"
  value       = aws_iam_group_membership.admin.*.users
}

output "role_admin_name" {
  description = "The name of the admin role"
  value       = aws_iam_role.admin.name
}

output "role_admin_id" {
  description = "The ID of the admin role"
  value       = aws_iam_role.admin.id
}

output "role_admin_arn" {
  description = "The ARN of the admin role"
  value       = aws_iam_role.admin.arn
}


output "group_other_name" {
  description = "The other groups name"
  value       = aws_iam_group.other.name
}

output "group_other_id" {
  description = "The other groups ID"
  value       = aws_iam_group.other.id
}

output "group_other_arn" {
  description = "The ARN assigned by AWS for the other group"
  value       = aws_iam_group.other.arn
}

output "group_other_path" {
  description = "The path of the other group in IAM"
  value       = aws_iam_group.other.path
}

output "group_other_users" {
  description = "List of IAM User names in the other group"
  value       = aws_iam_group_membership.other.*.users
}

// File: variables.tf
# General Settings
variable "namespace" {
  type        = string
  default     = ""
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'eg' or 'cp'"
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment, e.g. 'prod', 'staging', 'dev', 'pre-prod', 'UAT'"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes (e.g. `1`)"
}

# Assumed Role
variable "admin_name" {
  type        = string
  default     = "admin"
  description = "Name for the admin group and role (e.g. `admin`)"
}

variable "other_group_name" {
  type        = string
  default     = "other"
  description = "Name for the group with non-admin users"
}

variable "admin_user_names" {
  type        = list(any)
  default     = []
  description = "Optional list of IAM user names to add to the admin group"
}

variable "other_user_names" {
  type        = list(any)
  default     = []
  description = "Optional list of IAM user names to setup"
}

// File: verions.tf
terraform {
  required_version = ">= 0.13"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 2.0"
    }
  }
}

// File: network.tf
# RESOURCE: VPC

resource "aws_vpc" "vpc" {
    cidr_block           = "${var.vpc_cidr}"
    enable_dns_hostnames = "${var.vpc_dns_hostnames}"
}


# RESOURCE: INTERNET GATEWAY

resource "aws_internet_gateway" "igw" {
    vpc_id = aws_vpc.vpc.id
}


# RESOURCE: SUBNETS

resource "aws_subnet" "sn_az1_pub" {
    vpc_id                  = aws_vpc.vpc.id
    availability_zone       = "${var.vpc_sn_az1}"
    cidr_block              = "${var.vpc_sn_az1_pub_cidr}"
    map_public_ip_on_launch = "${var.vpc_sn_pub_map_public_ip_on_launch}"
}

resource "aws_subnet" "sn_az2_pub" {
    vpc_id                  = aws_vpc.vpc.id
    availability_zone       = "${var.vpc_sn_az2}"
    cidr_block              = "${var.vpc_sn_az2_pub_cidr}"
    map_public_ip_on_launch = "${var.vpc_sn_pub_map_public_ip_on_launch}"
}

resource "aws_subnet" "sn_az1_priv1" {
    vpc_id                  = aws_vpc.vpc.id
    availability_zone       = "${var.vpc_sn_az1}"
    cidr_block              = "${var.vpc_sn_az1_priv1_cidr}"
}

resource "aws_subnet" "sn_az2_priv1" {
    vpc_id                  = aws_vpc.vpc.id
    availability_zone       = "${var.vpc_sn_az2}"
    cidr_block              = "${var.vpc_sn_az2_priv1_cidr}"
}

resource "aws_subnet" "sn_az1_priv2" {
    vpc_id                  = aws_vpc.vpc.id
    availability_zone       = "${var.vpc_sn_az1}"
    cidr_block              = "${var.vpc_sn_az1_priv2_cidr}"
}

resource "aws_subnet" "sn_az2_priv2" {
    vpc_id                  = aws_vpc.vpc.id
    availability_zone       = "${var.vpc_sn_az2}"
    cidr_block              = "${var.vpc_sn_az2_priv2_cidr}"
}


# RESOURCE: ROUTE TABLES FOR THE SUBNETS

resource "aws_route_table" "rt_pub" {
    vpc_id = aws_vpc.vpc.id
    route {
        cidr_block = "${var.vpc_cidr_all}"
        gateway_id = aws_internet_gateway.igw.id
    }
}

resource "aws_route_table" "rt_priv" {
    vpc_id = aws_vpc.vpc.id
}


# RESOURCE: ROUTE TABLES ASSOCIATION TO SUBNETS

resource "aws_route_table_association" "rt_pub_sn_az1_pub" {
  subnet_id      = aws_subnet.sn_az1_pub.id
  route_table_id = aws_route_table.rt_pub.id
}

resource "aws_route_table_association" "rt_pub_sn_az2_pub" {
  subnet_id      = aws_subnet.sn_az2_pub.id
  route_table_id = aws_route_table.rt_pub.id
}

resource "aws_route_table_association" "rt_priv_sn_az1_priv1" {
  subnet_id      = aws_subnet.sn_az1_priv1.id
  route_table_id = aws_route_table.rt_priv.id
}

resource "aws_route_table_association" "rt_priv_sn_az2_priv1" {
  subnet_id      = aws_subnet.sn_az2_priv1.id
  route_table_id = aws_route_table.rt_priv.id
}

resource "aws_route_table_association" "rt_priv_sn_az1_priv2" {
  subnet_id      = aws_subnet.sn_az1_priv2.id
  route_table_id = aws_route_table.rt_priv.id
}

resource "aws_route_table_association" "rt_priv_sn_az2_priv2" {
  subnet_id      = aws_subnet.sn_az2_priv2.id
  route_table_id = aws_route_table.rt_priv.id
}


# RESOURCE: SECURITY GROUPS

resource "aws_security_group" "vpc_sg_pub" {
    vpc_id = aws_vpc.vpc.id
    egress {
        from_port   = "${var.vpc_sg_port_all}"
        to_port     = "${var.vpc_sg_port_all}"
        protocol    = "${var.vpc_sg_protocol_any}"
        cidr_blocks = ["${var.vpc_cidr_all}"]
    }
    ingress {
        from_port   = "${var.vpc_sg_port_all}"
        to_port     = "${var.vpc_sg_port_all}"
        protocol    = "${var.vpc_sg_protocol_any}"
        cidr_blocks = ["${var.vpc_cidr}"]
    }
    ingress {
        from_port   = "${var.vpc_sg_port_ssh}"
        to_port     = "${var.vpc_sg_port_ssh}"
        protocol    = "${var.vpc_sg_protocol_tcp}"
        cidr_blocks = ["${var.vpc_cidr_all}"]
    }
    ingress {
        from_port   = "${var.vpc_sg_port_http}"
        to_port     = "${var.vpc_sg_port_http}"
        protocol    = "${var.vpc_sg_protocol_tcp}"
        cidr_blocks = ["${var.vpc_cidr_all}"]
    }
}

resource "aws_security_group" "vpc_sg_priv" {
    vpc_id = aws_vpc.vpc.id
    egress {
        from_port   = "${var.vpc_sg_port_all}"
        to_port     = "${var.vpc_sg_port_all}"
        protocol    = "${var.vpc_sg_protocol_any}"
        cidr_blocks = ["${var.vpc_cidr_all}"]
    }
    ingress {
        from_port   = "${var.vpc_sg_port_all}"
        to_port     = "${var.vpc_sg_port_all}"
        protocol    = "${var.vpc_sg_protocol_any}"
        cidr_blocks = ["${var.vpc_cidr}"]
    }
}

// File: output.tf
# NETWORK OUTPUT TO BE REUSED

output "vpc_id" {
    value = "${aws_vpc.vpc.id}"
}

output "vpc_sg_pub_id" {
    value = "${aws_security_group.vpc_sg_pub.id}"
}

output "vpc_sg_priv_id" {
    value = "${aws_security_group.vpc_sg_priv.id}"
}

output "vpc_sn_az1_pub_id" {
    value = "${aws_subnet.sn_az1_pub.id}"
}

output "vpc_sn_az2_pub_id" {
    value = "${aws_subnet.sn_az2_pub.id}"
