// File: variables.tf
variable "project_name" {
  description = "Project name used for resource naming"
  type        = string
  default     = "benchmark"
}

# SCPs

variable "enable_scps" {
  description = "Enable Service Control Policies. Parent toggle - requires AWS Organizations management account."
  type        = bool
  default     = false
}

variable "enable_scp_deny_root_usage" {
  description = "SCP: Block all root user actions in member accounts"
  type        = bool
  default     = true
}

variable "enable_scp_deny_unapproved_regions" {
  description = "SCP: Restrict API calls to approved regions only. Requires allowed_regions to be set."
  type        = bool
  default     = true
}

variable "enable_scp_deny_disable_security" {
  description = "SCP: Block disabling CloudTrail, GuardDuty, Config, Security Hub, Access Analyzer, S3 BPA"
  type        = bool
  default     = true
}

variable "enable_scp_enforce_encryption" {
  description = "SCP: Deny unencrypted RDS/EBS creation and KMS key deletion with < 14 day window"
  type        = bool
  default     = true
}

variable "enable_scp_deny_public_ami" {
  description = "SCP: Block making AMIs public via ModifyImageAttribute"
  type        = bool
  default     = true
}

variable "enable_scp_deny_leave_organization" {
  description = "SCP: Prevent member accounts from leaving the organization"
  type        = bool
  default     = false
}

variable "enable_scp_deny_delete_flow_logs" {
  description = "SCP: Prevent deletion of VPC flow logs"
  type        = bool
  default     = false
}

variable "enable_scp_deny_deactivate_mfa" {
  description = "SCP: Prevent deactivating or deleting MFA devices and creating root access keys"
  type        = bool
  default     = false
}

variable "enable_scp_deny_imdsv1" {
  description = "SCP: Prevent launching EC2 instances without IMDSv2 required and prevent modifying existing instances to disable IMDSv2"
  type        = bool
  default     = false
}

variable "scp_target_ou_ids" {
  description = "List of Organization Unit IDs to attach SCPs to. Can also be the organization root ID (e.g., ou-ab12-cdef3456, r-ab12)."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for id in var.scp_target_ou_ids : can(regex("^(ou-[a-z0-9]{4,32}-[a-z0-9]{8,32}|r-[a-z0-9]{4,32})$", id))])
    error_message = "Each scp_target_ou_ids entry must be a valid OU ID (ou-xxxx-xxxxxxxx) or organization root ID (r-xxxx)."
  }
}

variable "allowed_regions" {
  description = "List of AWS regions allowed by the region-deny SCP. Leave empty to skip region restriction (e.g., us-east-1, eu-west-2)."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for r in var.allowed_regions : can(regex("^[a-z]{2}(-gov)?-(north|south|east|west|central|northeast|southeast|northwest|southwest)-[0-9]+$", r))])
    error_message = "Each allowed_regions entry must be a valid AWS region (e.g., us-east-1, eu-west-2, us-gov-west-1)."
  }
}

# Tag Policies

variable "enable_tag_policies" {
  description = "Enable organization-wide tag policies for consistent tagging"
  type        = bool
  default     = false
}

variable "required_tags" {
  description = "Map of required tag keys and their enforcement configuration"
  type = map(object({
    enforced_values = optional(list(string))
    enforced_for    = optional(list(string))
  }))
  default = {
    Environment = {
      enforced_values = ["dev", "staging", "production"]
      enforced_for    = null
    }
    ManagedBy = {
      enforced_values = ["Terraform"]
      enforced_for    = null
    }
  }
}

# Backup Policies

variable "enable_backup_policies" {
  description = "Enable organization-wide backup policies"
  type        = bool
  default     = false
}

variable "backup_regions" {
  description = "List of AWS regions where backups should run. Leave empty to back up in all regions (e.g., us-east-1, eu-west-2)."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for r in var.backup_regions : can(regex("^[a-z]{2}(-gov)?-(north|south|east|west|central|northeast|southeast|northwest|southwest)-[0-9]+$", r))])
    error_message = "Each backup_regions entry must be a valid AWS region (e.g., us-east-1, eu-west-2, us-gov-west-1)."
  }
}

variable "backup_retention_days" {
  description = "Number of days to retain backups"
  type        = number
  default     = 35

  validation {
    condition     = var.backup_retention_days >= 1
    error_message = "Backup retention must be at least 1 day."
  }
}

# AI Opt-Out

variable "enable_ai_opt_out_policy" {
  description = "Enable AI services opt-out policy to prevent AWS from using content for ML training"
  type        = bool
  default     = false
}

# RAM

variable "enable_ram_org_sharing" {
  description = "Enable AWS RAM sharing within the organization"
  type        = bool
  default     = false
}

// File: nacl.tf
# --------------------------------------------------------------------------------
# public subnet NACL
# --------------------------------------------------------------------------------

resource "aws_network_acl" "public" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = toset(aws_subnet.public.*.id)
  tags       = merge({ "Name" = "${var.vpc_name} Public" }, var.tags)
}

resource "aws_network_acl_rule" "public_ssh_in" {
  count          = length(var.ssh_inbound)
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.ssh_inbound[count.index]
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "public_http_in" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 200
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_https_in" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 210
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ephemeral_in" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 300
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_http_out" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 200
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_https_out" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 210
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ephemeral_out" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 300
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}


# --------------------------------------------------------------------------------
# private subnet NACL
# --------------------------------------------------------------------------------

# we still route 80 & 443 (and ephemeral return routes) out, to allow use of yum etc
# from inside the private subnet, however only allow 80 & 443 incomding from the public subnets
# remeber though that non-local traffic from the 'private' subnets routes through the NAT
# gateway, providing anonymity of the instances from outside

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = toset(aws_subnet.private.*.id)
  tags       = merge({ "Name" = "${var.vpc_name} Private" }, var.tags)
}

resource "aws_network_acl_rule" "private_http_in" {
  count          = local.subnet_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = element(aws_subnet.public.*.cidr_block, count.index)
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_https_in" {
  count          = local.subnet_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = element(aws_subnet.public.*.cidr_block, count.index)
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_ephemeral_in" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 400
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_https_out" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_ephemeral_out_private" {
  count          = local.subnet_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 330 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = element(aws_subnet.private.*.cidr_block, count.index)
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_ephemeral_out" {
  count          = local.subnet_count
  network_acl_id = aws_network_acl.private.id
  rule_number    = 400 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = element(aws_subnet.public.*.cidr_block, count.index)
  from_port      = 1024
  to_port        = 65535
}

