// File: sg.tf
# --------------------------------------------------------------------------------
# default security groups for use on public ec2 instances
# --------------------------------------------------------------------------------

resource "aws_security_group" "public" {
  name        = "${var.vpc_name}_public"
  vpc_id      = aws_vpc.main.id
  description = "Security group for instances in public subnets"
  tags        = merge({ "Name" = "${var.vpc_name} Public" }, var.tags)
}

resource "aws_security_group_rule" "public_ssh_in" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = var.ssh_inbound
}

resource "aws_security_group_rule" "public_http_in" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "public_https_in" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "public_http_out" {
  security_group_id = aws_security_group.public.id
  type              = "egress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "public_https_out" {
  security_group_id = aws_security_group.public.id
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

# --------------------------------------------------------------------------------
# default security groups for use on private ec2 instances
# --------------------------------------------------------------------------------
resource "aws_security_group" "private" {
  name        = "${var.vpc_name}_private"
  vpc_id      = aws_vpc.main.id
  description = "Security group for instances in private subnets"
  tags        = merge({ "Name" = "${var.vpc_name} Private" }, var.tags)
}

resource "aws_security_group_rule" "private_http_in" {
  security_group_id = aws_security_group.private.id
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = aws_subnet.public.*.cidr_block
}

resource "aws_security_group_rule" "private_https_in" {
  security_group_id = aws_security_group.private.id
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = aws_subnet.public.*.cidr_block
}

resource "aws_security_group_rule" "private_https_out" {
  security_group_id = aws_security_group.private.id
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

// File: subnets.tf
# --------------------------------------------------------------------------------
# public subnets
# --------------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count                   = local.subnet_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  cidr_block              = cidrsubnet(var.vpc_cidr, ceil(log(local.subnet_count * 2, 2)), count.index)
  map_public_ip_on_launch = true
  tags                    = merge({ "Name" = "${var.vpc_name} Public" }, var.tags)
}

#
# public instances route out through the internet gateway
#
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = merge({ "Name" = "${var.vpc_name} public" }, var.tags)
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = local.subnet_count

  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}


# --------------------------------------------------------------------------------
# private subnets
# --------------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count                   = local.subnet_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  cidr_block              = cidrsubnet(var.vpc_cidr, ceil(log(local.subnet_count * 2, 2)), local.subnet_count + count.index)
  map_public_ip_on_launch = false
  tags                    = merge({ "Name" = "${var.vpc_name} Private" }, var.tags)
}


# private instances route out via the NAT gateway.
# subnets are implicitly associated with the main route table, so the private subnets don't need to be explicitly associated
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge({ "Name" = "${var.vpc_name} private" }, var.tags)
}

resource "aws_route" "private" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.public.id
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
  depends_on     = [aws_nat_gateway.public, aws_internet_gateway.main]
}

// File: variables.tf
locals {
  # This is used to divide the VPC subnet IP range into 2 * (number of AZ) subranges
  subnet_count = length(data.aws_availability_zones.available.names)
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "vpc_name" {
  type    = string
  default = "benchmark-vpc"
}

variable "ssh_inbound" {
  type    = list(string)
  default = ["10.0.0.0/16"]
}

// File: versions.tf
terraform {
  required_version = ">= 1.7.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.22.0"
    }
  }
}

// File: vpc.tf
# --------------------------------------------------------------------------------
# VPC wide assets
# --------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge({ "Name" = var.vpc_name }, var.tags)
}

# --------------------------------------------------------------------------------
# internet gateway
# --------------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge({ "Name" = var.vpc_name }, var.tags)
}

resource "aws_eip" "igw_ip" {
  domain     = "vpc"
  tags       = merge({ "Name" = "${var.vpc_name} IGW IP" }, var.tags)
  depends_on = [aws_internet_gateway.main]
}

# --------------------------------------------------------------------------------
# NAT
# --------------------------------------------------------------------------------

resource "aws_nat_gateway" "public" {
  allocation_id = aws_eip.igw_ip.id
  subnet_id     = aws_subnet.public[0].id
  tags          = merge({ "Name" = "${var.vpc_name} Public" }, var.tags)
}

# --------------------------------------------------------------------------------
# lookup to find AZ
# --------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

# --------------------------------------------------------------------------------
# control default NACL and security group
# --------------------------------------------------------------------------------
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id
  tags                   = merge({ "Name" = "${var.vpc_name} Default" }, var.tags)
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id
  tags   = merge({ "Name" = "${var.vpc_name} Default" }, var.tags)
}

// File: iam_profile.tf
resource "aws_iam_instance_profile" "examplea" {
  name_prefix = "imagebuilder_"
  role        = aws_iam_role.pike.name
}

resource "aws_iam_role" "pike" {
  name_prefix = "imagebuilder_"
  path        = "/"

  assume_role_policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Action": "sts:AssumeRole",
            "Principal": {
               "Service": "ec2.amazonaws.com"
            },
            "Effect": "Allow",
            "Sid": ""
        }
    ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "builder" {
  role       = aws_iam_role.pike.name
  policy_arn = "arn:aws:iam::aws:policy/AWSImageBuilderFullAccess"
}


output "instance_profile" {
  value = aws_iam_instance_profile.examplea
}

// File: main.tf
/*
IAM role for the Tamr role for an EC2 instance. This role will have iam policies attached to it through
a secondary module (usually aws-emr-tamr-user-policies`module.
(https://github.com/Datatamer/terraform-emr-tamr-policies))
*/
data "aws_iam_policy_document" "instance-assume-role-policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tamr_user_iam_role" {
  name                 = var.aws_role_name
  assume_role_policy   = data.aws_iam_policy_document.instance-assume-role-policy.json
  permissions_boundary = var.permissions_boundary
  tags                 = var.tags
}

resource "aws_iam_instance_profile" "tamr_user_instance_profile" {
  name = var.aws_instance_profile_name
  role = aws_iam_role.tamr_user_iam_role.name
  tags = var.tags
}

// File: outputs.tf
output "tamr_instance_profile_id" {
  value       = aws_iam_instance_profile.tamr_user_instance_profile.id
  description = "ID of the IAM instance profile created"
}

output "tamr_instance_role_name" {
  value       = aws_iam_role.tamr_user_iam_role.id
  description = "ID of the role created"
}

// File: variables.tf
variable "aws_role_name" {
  type        = string
  description = "IAM Role to create"
  default     = "tamr-instance-role"
}

variable "aws_instance_profile_name" {
  type        = string
  description = "IAM Instance Profile to create"
  default     = "tamr-instance-profile"
}

variable "permissions_boundary" {
  type        = string
  description = "ARN of the policy that will be used to set the permissions boundary for the IAM Role"
  default     = null
}

variable "tags" {
  type        = map(string)
  description = "A map of tags to add to all resources."
  default     = {}
}

// File: versions.tf
