// File: main.tf
# ---------------------------------------------------------------------------------------------------------------------
# IAM Role for EC2 instance Packer Builder [read-only access to S3 for software install files]
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_iam_role" "packer-build" {
  name = "${var.environment.resource_name_prefix}-packer-build"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
  tags = {
    Description = "Role for EC2 instance Packer Builder for read-only access to S3 for software install files"
  }
}

resource "aws_iam_policy" "packer-build" {
  name = "${var.environment.resource_name_prefix}-assume-role-packer-files-s3-read"
  description = "Allow assume role in Core account of '${var.packer_s3_bucket_name}' to access software installation files"
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
      {
          "Effect": "Allow",
          "Action": "sts:AssumeRole",
          "Resource": "arn:aws:iam::${var.packer_s3_bucket_account_id}:role/${var.packer_s3_bucket_name}"
      }
  ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "packer-build" {
  role       = aws_iam_role.packer-build.name
  policy_arn = aws_iam_policy.packer-build.arn
}

resource "aws_iam_instance_profile" "packer-build" {
  name = "packer-builder"
  role = aws_iam_role.packer-build.name
}

// File: outputs.tf
# Output values
#
output "packer-builder-profile-name" {
  value = aws_iam_instance_profile.packer-build.name
}

// File: variables.tf
variable "environment" {
  description = "Environment information e.g. account IDs, public/private subnet cidrs"
  type = object({
    name                        = string
    # Environment Account IDs are used for giving permissions to those Accounts for resources such as AMIs
    account_id                  = string
    resource_name_prefix        = string
    # For some environments  (e.g. Core, Customer/production) want to protect against accidental deletion of resources
    resource_deletion_protection  = bool
    default_tags                  = map(string)
  })
  default = {
    name                          = ""
    account_id                    = ""
    resource_name_prefix          = ""
    resource_deletion_protection  = true
    default_tags                  = {}
  }
}
variable "global_default_tags" {
  description = "Global default tags"
  default = {}
  type = map(string)
}
variable "packer_s3_bucket_name" {
  description = ""
  default     = ""
  type        = string
}
variable "packer_s3_bucket_account_id" {
  description = ""
  default     = ""
  type        = string
}

// File: iam_openid_connect_provider.tf
#-----------------------------------------------------------
# IAM openid connect provider
#-----------------------------------------------------------
resource "aws_iam_openid_connect_provider" "iam_openid_connect_provider" {
  count = var.enable_iam_openid_connect_provider ? 1 : 0

  url             = var.iam_openid_connect_provider_url
  client_id_list  = var.iam_openid_connect_provider_client_id_list
  thumbprint_list = var.iam_openid_connect_provider_thumbprint_list

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: iam_saml_provider.tf
#-----------------------------------------------------------
# IAM saml provider
#-----------------------------------------------------------
resource "aws_iam_saml_provider" "iam_saml_provider" {
  count = var.enable_iam_saml_provider ? 1 : 0

  name                   = var.iam_saml_provider_name != "" ? var.iam_saml_provider_name : "${lower(var.name)}-saml-${lower(var.environment)}"
  saml_metadata_document = var.iam_saml_provider_saml_metadata_document

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: outputs.tf
#-----------------------------------------------------------
# IAM access key
#-----------------------------------------------------------
output "iam_openid_connect_provider_id" {
  description = "ID"
  value       = element(concat(aws_iam_openid_connect_provider.iam_openid_connect_provider.*.id, [""], ), 0)
}

output "iam_openid_connect_provider_arn" {
  description = "The ARN assigned by AWS for this provider."
  value       = element(concat(aws_iam_openid_connect_provider.iam_openid_connect_provider.*.arn, [""], ), 0)
}

#-----------------------------------------------------------
# IAM saml provider
#-----------------------------------------------------------
output "iam_saml_provider_arn" {
  description = "The ARN assigned by AWS for this provider."
  value       = element(concat(aws_iam_saml_provider.iam_saml_provider.*.arn, [""], ), 0)
}

output "iam_saml_provider_valid_until" {
  description = "The expiration date and time for the SAML provider in RFC1123 format, e.g. Mon, 02 Jan 2006 15:04:05 MST."
  value       = element(concat(aws_iam_saml_provider.iam_saml_provider.*.valid_until, [""], ), 0)
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

#-----------------------------------------------------------
# IAM openid connect provider
#-----------------------------------------------------------
variable "enable_iam_openid_connect_provider" {
  description = "Enable IAM openID connect provider usage"
  default     = false
}

variable "iam_openid_connect_provider_url" {
  description = "(Required) The URL of the identity provider. Corresponds to the iss claim. Ex: https://accounts.google.com"
  default     = ""
}

variable "iam_openid_connect_provider_client_id_list" {
  description = "(Required) A list of client IDs (also known as audiences). When a mobile or web app registers with an OpenID Connect provider, they establish a value that identifies the application. (This is the value that's sent as the client_id parameter on OAuth requests.)"
  default     = []
}

variable "iam_openid_connect_provider_thumbprint_list" {
  description = "(Required) A list of server certificate thumbprints for the OpenID Connect (OIDC) identity provider's server certificate(s)."
  default     = []
}

#-----------------------------------------------------------
# IAM saml provider
#-----------------------------------------------------------
variable "enable_iam_saml_provider" {
  description = "Enable IAM SAML provider usage"
  default     = false
}

variable "iam_saml_provider_name" {
  description = "The name of the provider to create."
  default     = ""
}

variable "iam_saml_provider_saml_metadata_document" {
  description = "(Required) An XML document generated by an identity provider that supports SAML 2.0."
  default     = ""
}

// File: main.tf
provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = "10.16.0.0/16"

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "presentation" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.16.0.0/24"

  tags = {
    Name = "presentation-subnet"
  }
}

resource "aws_subnet" "application" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.16.1.0/24"

  tags = {
    Name = "application-subnet"
  }
}

resource "aws_subnet" "data" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.16.2.0/24"

  tags = {
    Name = "data-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "presentation" {
  subnet_id = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

resource "aws_route" "internet" {
  route_table_id = aws_route_table.presentation.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

// File: output.tf
output "vpc_id" {
    value = aws_vpc.main.id
}

output "presentation_subnet_id" {
  value = aws_subnet.presentation.id
}

output "application_subnet_id" {
  value = aws_subnet.application.id
}

output "data_subnet_id" {
  value = aws_subnet.data.id
}

// File: variables.tf
variable "aws_region" {
  type = string
  default = "us-east-1"
}

variable "vpc_name" {
  type = string
  default = "three-tier-vpc"
}

// File: main.tf
resource "aws_iam_role" "launch" {
  name = "test_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "servicecatalog.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "launch" {
  name = "ServiceCatalogTerraformLaunchPolicy"
  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Sid" : "LaunchConstraintSC",
        "Effect" : "Allow",
        "Action" : [
          "cloudformation:SetStackPolicy",
          "cloudformation:DescribeStackEvents",
          "cloudformation:CreateStack",
          "cloudformation:DeleteStack",
          "cloudformation:UpdateStack",
          "cloudformation:ValidateTemplate",
          "cloudformation:GetTemplateSummary",
          "cloudformation:DescribeStacks",
          "servicecatalog:*",
          "ec2:*",
          "s3:GetObject",
        ],
        "Resource" : "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "launch" {
  role       = aws_iam_role.launch.name
  policy_arn = aws_iam_policy.launch.arn
}


resource "aws_iam_group" "group1" {
  name = "Group1"
  path = "/terraform/"
}

resource "aws_iam_group_policy_attachment" "group1" {
  group      = aws_iam_group.group1.name
  policy_arn = "arn:aws:iam::aws:policy/AWSServiceCatalogEndUserFullAccess"
}

resource "aws_iam_user" "user1" {
  name          = "User1"
  path          = "/terraform/"
  force_destroy = true
}

resource "aws_iam_user_login_profile" "user1" {
  user                    = aws_iam_user.user1.name
  password_reset_required = false
}

resource "aws_iam_user_group_membership" "user1" {
  user = aws_iam_user.user1.name

  groups = [
    aws_iam_group.group1.name
  ]
}

// File: output.tf
output "launch_role_arn" {
  value = aws_iam_role.launch.arn
}

output "iam_user1_arn" {
  value = aws_iam_user.user1.arn
}

// File: main.tf
data "aws_availability_zones" "available" {}

locals {
  dd_tags = {
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }

  # Limit to a maximum of 3 AZs on that region
  max_azs             = min(3, length(data.aws_availability_zones.available.names))
  private_cidr_offset = 3
  azs_cidrs = {
    for idx, az in slice(data.aws_availability_zones.available.names, 0, local.max_azs) :
    az => {
      public_cidr  = cidrsubnet("10.0.0.0/16", 3, idx),
      private_cidr = cidrsubnet("10.0.0.0/16", 3, idx + local.private_cidr_offset)
    }
  }

  ssm_vpc_endpoint_services = ["ec2messages", "ssmmessages", "ssm"]
}

resource "aws_vpc" "vpc" {
  cidr_block           = var.cidr
  enable_dns_support   = true # required for aws_vpc_endpoint
  enable_dns_hostnames = true # ditto

  tags = merge({ "Name" = var.name }, var.tags, local.dd_tags)
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.vpc.id

  tags = merge({ "Name" = var.name }, var.tags, local.dd_tags)
}

resource "aws_subnet" "public" {
  for_each = local.azs_cidrs

  vpc_id            = aws_vpc.vpc.id
  availability_zone = each.key
  cidr_block        = each.value.public_cidr

  tags = merge({ "Name" = "${var.name}-${each.key}-public" }, var.tags, local.dd_tags)
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge({ "Name" = var.name }, var.tags, local.dd_tags)
}

resource "aws_nat_gateway" "nat_gateway" {
  allocation_id = aws_eip.nat.id
  # NAT gateway are expensive, keep only one until we can remove it entirely
  subnet_id = values(aws_subnet.public)[0].id

  tags = merge({ "Name" = var.name }, var.tags, local.dd_tags)

  depends_on = [aws_internet_gateway.internet_gateway]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.vpc.id

  tags = merge({ "Name" = "${var.name}-public" }, var.tags, local.dd_tags)
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway.id
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  for_each = local.azs_cidrs

  vpc_id            = aws_vpc.vpc.id
  availability_zone = each.key
  cidr_block        = each.value.private_cidr

  tags = merge({ "Name" = "${var.name}-${each.key}-private" }, var.tags, local.dd_tags)
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.vpc.id

  tags = merge({ "Name" = "${var.name}-private" }, var.tags, local.dd_tags)
}

resource "aws_route" "private" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat_gateway.id
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private.id
}

data "aws_vpc_endpoint_service" "s3" {
  service      = "s3"
  service_type = "Gateway"
}

resource "aws_vpc_endpoint" "s3" {
  service_name      = data.aws_vpc_endpoint_service.s3.service_name
  vpc_endpoint_type = data.aws_vpc_endpoint_service.s3.service_type
  vpc_id            = aws_vpc.vpc.id
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = merge(var.tags, local.dd_tags)
}

resource "aws_security_group" "endpoint_sg" {
  name        = "${var.name}-vpc-endpoints"
  description = "VPC endpoint security group"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    description = "TLS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.vpc.cidr_block]
  }

  tags = merge(var.tags, local.dd_tags)

  lifecycle {
    create_before_destroy = true
  }
}

data "aws_vpc_endpoint_service" "lambda" {
  service      = "lambda"
  service_type = "Interface"
}

resource "aws_vpc_endpoint" "lambda" {
  service_name        = data.aws_vpc_endpoint_service.lambda.service_name
  vpc_endpoint_type   = data.aws_vpc_endpoint_service.lambda.service_type
  vpc_id              = aws_vpc.vpc.id
  subnet_ids          = [for s in aws_subnet.private : s.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(var.tags, local.dd_tags)
}

data "aws_vpc_endpoint_service" "ebs" {
  service      = "ebs"
  service_type = "Interface"
}

resource "aws_vpc_endpoint" "ebs" {
  service_name        = data.aws_vpc_endpoint_service.ebs.service_name
  vpc_endpoint_type   = data.aws_vpc_endpoint_service.ebs.service_type
  vpc_id              = aws_vpc.vpc.id
  subnet_ids          = [for s in aws_subnet.private : s.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(var.tags, local.dd_tags)
}

data "aws_vpc_endpoint_service" "ssm" {
  for_each = toset(var.enable_ssm_vpc_endpoint ? local.ssm_vpc_endpoint_services : [])

  service      = each.value
  service_type = "Interface"
}

resource "aws_vpc_endpoint" "ssm" {
  for_each = toset(var.enable_ssm_vpc_endpoint ? local.ssm_vpc_endpoint_services : [])

  service_name        = data.aws_vpc_endpoint_service.ssm[each.value].service_name
  vpc_endpoint_type   = data.aws_vpc_endpoint_service.ssm[each.value].service_type
  vpc_id              = aws_vpc.vpc.id
  subnet_ids          = [for s in aws_subnet.private : s.id]
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.endpoint_sg.id]

  tags = merge(var.tags, local.dd_tags)
}

// File: outputs.tf
output "vpc" {
  description = "The VPC created for the Datadog agentless scanner"
  value       = aws_vpc.vpc
}

output "public_subnets" {
  description = "The public subnets of the created VPC"
  value       = aws_subnet.public
}

output "private_subnets" {
  description = "The private subnets of the created VPC"
  value       = aws_subnet.private
}

output "nap_public_id" {
  description = "The public IP associated with the VPC's NAT"
  value       = aws_eip.nat.public_ip
}

output "routing_ready" {
  description = "Indicates whether routing resources have been successfully provisioned"
  value       = true

  depends_on = [
    aws_route.private,
    aws_route.public
  ]
}

// File: provider.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

// File: variables.tf
variable "name" {
  description = "Name tag, e.g stack"
  type        = string
  default     = "DatatogAgentlessScanner"
}

variable "cidr" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_ssm_vpc_endpoint" {
  description = "Whether to enable AWS SSM VPC endpoint"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of additional tags to add to the instance/volume created"
  type        = map(string)
  default     = {}
}

// File: main.tf
resource "aws_vpc" "default" {
  count      = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  cidr_block = "10.0.0.0/16"
}

locals {
  effective_vpc_id = var.vpc_id != "" ? var.vpc_id : (length(aws_vpc.default) > 0 ? aws_vpc.default[0].id : "")
}

module "labels" {
  source      = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

##-----------------------------------------------------------------------------
## Below resource will deploy new security group in aws.
##-----------------------------------------------------------------------------
resource "aws_security_group" "default" {
  count       = var.enable && var.new_sg ? 1 : 0
  name        = format("%s-sg", module.labels.id)
  vpc_id      = local.effective_vpc_id
  description = var.sg_description
  tags        = module.labels.tags
  lifecycle {
    create_before_destroy = true
  }
}

##-----------------------------------------------------------------------------
## Below data resource is to get details of existing security group in your aws environment.
##-----------------------------------------------------------------------------
data "aws_security_group" "existing" {
  count  = var.enable && var.existing_sg_id != null ? 1 : 0
  id     = var.existing_sg_id
  vpc_id = var.vpc_id
}

##-----------------------------------------------------------------------------
## Below resource will deploy prefix list resource in aws.
##-----------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "prefix_list" {
  count          = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) < 1 ? 1 : 0
  address_family = var.prefix_list_address_family
  max_entries    = var.max_entries
  name           = format("%s-prefix-list", module.labels.id)
  dynamic "entry" {
    for_each = var.entry
    content {
      cidr        = lookup(entry.value, "cidr", null)
      description = lookup(entry.value, "description", null)

    }
  }
}

##-----------------------------------------------------------------------------
## Below resource will deploy ingress security group rules for new security group created from this module.
##-----------------------------------------------------------------------------
# Security group rules with "cidr_blocks", but without "source_security_id" and "self"
resource "aws_security_group_rule" "new_sg_ingress_with_cidr_blocks" {
  for_each          = var.enable ? { for rule in var.new_sg_ingress_rules_with_cidr_blocks : rule.rule_count => rule } : {}
  type              = "ingress"
  from_port         = each.value.from_port
  protocol          = each.value.protocol
  to_port           = each.value.to_port
  security_group_id = join("", aws_security_group.default[*].id)
  cidr_blocks       = lookup(each.value, "cidr_blocks", null)
  ipv6_cidr_blocks  = lookup(each.value, "ipv6_cidr_blocks", null)
  description       = lookup(each.value, "description", null)
}

# Security group rules with "self", but without "source_security_id" and "cidr_blocks"
resource "aws_security_group_rule" "new_sg_ingress_with_self" {
  for_each          = var.enable ? { for rule in var.new_sg_ingress_rules_with_self : rule.rule_count => rule } : {}
  type              = "ingress"
  from_port         = each.value.from_port
  protocol          = each.value.protocol
  to_port           = each.value.to_port
  security_group_id = join("", aws_security_group.default[*].id)
  self              = lookup(each.value, "self", true)
  description       = lookup(each.value, "description", null)
}

# Security group rules with "source_security_id", but without "cidr_blocks" and "self"
resource "aws_security_group_rule" "new_sg_ingress_with_source_sg_id" {
  for_each                 = var.enable ? { for rule in var.new_sg_ingress_rules_with_source_sg_id : rule.rule_count => rule } : {}
  type                     = "ingress"
  from_port                = each.value.from_port
  protocol                 = each.value.protocol
  to_port                  = each.value.to_port
  source_security_group_id = each.value.source_security_group_id
  security_group_id        = join("", aws_security_group.default[*].id)
  description              = lookup(each.value, "description", null)
}

# Security group rules with "prefix_list_ids", but without "cidr_blocks", "self" or "source_security_group_id"
resource "aws_security_group_rule" "new_sg_ingress_with_prefix_list" {
  for_each          = var.enable ? { for rule in var.new_sg_ingress_rules_with_prefix_list : rule.rule_count => rule } : {}
  type              = "ingress"
  from_port         = each.value.from_port
  protocol          = each.value.protocol
  to_port           = each.value.to_port
  security_group_id = join("", aws_security_group.default[*].id)
  prefix_list_ids   = lookup(each.value, "prefix_list_ids", null) == null ? aws_ec2_managed_prefix_list.prefix_list[*].id : lookup(each.value, "prefix_list_ids", null)
  description       = lookup(each.value, "description", null)
}

##-----------------------------------------------------------------------------
## Below resource will deploy ingress security group rules for existing security group.
##-----------------------------------------------------------------------------
# Security group rules with "cidr_blocks", but without "source_security_id" and "self"
resource "aws_security_group_rule" "existing_sg_ingress_cidr_blocks" {
  for_each          = var.enable ? { for rule in var.existing_sg_ingress_rules_with_cidr_blocks : rule.rule_count => rule } : {}
