// File: providers.tf
terraform {
  required_version = ">= 1.6.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.41.0"
    }
  }
}

// File: variables.tf
variable "environment" {
  description = "The environment"
  type        = string
  default     = "dev"
}

variable "create_packer_user" {
  description = "Whether to create the packer user"
  type        = bool
  default     = false
}

variable "create_db_disaster_user" {
  description = "Whether to create the DB disaster recovery user"
  type        = bool
  default     = false
}

variable "create_exports_user" {
  description = "Whether to create the exports user"
  type        = bool
  default     = false
}

variable "exports_bucket_arn" {
  description = "The bucket that will be used for data exports. Needed only when create_exports_users is set to true"
  type        = string
  default     = ""
}

// File: data.tf
data "aws_caller_identity" "current" {}

data "aws_region" "current" {

}

locals {
  health_omics_arn   = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.health_omics_role_name}"
  additional_buckets = var.additional_buckets != null ? var.additional_buckets : []
  buckets            = concat([aws_s3_bucket.output_bucket.arn, "${aws_s3_bucket.output_bucket.arn}/*"], local.additional_buckets)
  ecr_resources = concat(["arn:aws:ecr:${var.region}:${data.aws_caller_identity.current.account_id}:*"], [for account in var.external_ecr_accounts: "arn:aws:ecr:${var.region}:${account}:*"]) 
}


data "aws_iam_policy_document" "health_omics_user_policy" {
  statement {
    sid = "AllowPassRole"
    actions = [
      "iam:PassRole"
    ]

    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["omics.amazonaws.com"]
    }
  }

  statement {
    sid = "AllowOmicsActions"
    actions = [
      "omics:*"
    ]
    resources = ["*"]
  }

  statement {
    sid = "AllowS3ReadOnlyAccess"
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = local.buckets
  }

  statement {
    sid = "AllowReadLogs"
    actions = [
      "logs:DescribeLogStreams",
      "logs:GetLogEvents",
    ]

    resources = [
      "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/omics/*"
    ]
  }
}

data "aws_iam_policy_document" "health_omics_trust_policy" {
  statement {
    sid = "AllowHealthOmicsService"
    actions = [
      "sts:AssumeRole"
    ]

    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
  }
}


data "aws_iam_policy_document" "health_omics_service_policy" {
  statement {
    sid = "AllowS3ReadOnlyAccess"
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = local.buckets
  }
  statement {
    sid = "UploadFilesToS3"
    actions = [
      "s3:PutObject",
    ]

    resources = [
      aws_s3_bucket.output_bucket.arn,
      "${aws_s3_bucket.output_bucket.arn}/*"
    ]
  }

  statement {
    sid = "AllowECRActions"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
    resources = local.ecr_resources

  }

  statement {
    sid = "AllowLogs"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:CreateLogGroup",
      "logs:DescribeLogStreams",
    ]

    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/omics/*"
    ]
  }
}

data "aws_iam_policy_document" "health_omics_ecr_policy" {
  statement {
    sid       = "OmicsWorkflow Access"
    effect    = "Allow"

    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
  }
}

// File: main.tf
provider "aws" {
  region = var.region
}

resource "aws_s3_bucket" "output_bucket" {
  bucket = var.output_bucket_name
  tags = {
    created_by = "terraform"
  }
}

resource "aws_iam_user" "workbench_service_account" {
  name = var.workbench_service_account_name
  tags = {
    created_by = "terraform"
  }
}

resource "aws_iam_user_policy_attachment" "workbench_service_account_policy" {
  user       = aws_iam_user.workbench_service_account.name
  policy_arn = aws_iam_policy.health_omics_user_policy.arn
}

resource "aws_iam_access_key" "workbench_service_account_secret_key" {
  user = aws_iam_user.workbench_service_account.name
}

resource "aws_iam_policy" "health_omics_user_policy" {
  name        = var.health_omics_user_policy_name
  description = "Policy for health omics service"
  policy      = data.aws_iam_policy_document.health_omics_user_policy.json
  tags = {
    created_by = "terraform"
  }

}

resource "aws_iam_policy" "health_omics_service_policy" {
  name        = var.health_omics_service_policy_name
  description = "Policy for health omics service"
  policy      = data.aws_iam_policy_document.health_omics_service_policy.json
  tags = {
    created_by = "terraform"
  }

}

resource "aws_iam_role" "health_omics_role" {
  name               = var.health_omics_role_name
  assume_role_policy = data.aws_iam_policy_document.health_omics_trust_policy.json
  managed_policy_arns = [
    aws_iam_policy.health_omics_service_policy.arn
  ]
  tags = {
    created_by = "terraform"
  }

}

resource "aws_ecr_repository" "ecr_repositories" {
  for_each = var.ecr_repositories
  name     = each.value
}

resource "aws_ecr_repository_policy" "docker_repository_policy" {
  for_each = var.ecr_repositories
  repository = aws_ecr_repository.ecr_repositories[each.key].name
  policy = data.aws_iam_policy_document.health_omics_ecr_policy.json
}

// File: outputs.tf
output "access_key_id" {
  description = "Access key ID for Workbench to use"
  value       = aws_iam_access_key.workbench_service_account_secret_key.id
}

output "secret_access_key" {
  description = "Secret access key for Workbench to use"
  sensitive   = true
  value       = aws_iam_access_key.workbench_service_account_secret_key.secret
}

output "role_arn" {
    description = "ARN of the role used by HealthOmics"
    value       = aws_iam_role.health_omics_role.arn

}

output "output_bucket" {
    description = "The name of the output bucket"
    value       = aws_s3_bucket.output_bucket.bucket
}

output "docker_repositories" {
    description = "The name of the docker repositories"
    value       = [for repo in aws_ecr_repository.ecr_repositories: repo.repository_url]

}

// File: terraform.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.35"
    }
  }
  required_version = "~> 1.3"
}

// File: variables.tf
variable "output_bucket_name" {
  description = "The name of the output bucket"
  type        = string
  nullable    = false
  default     = "tf-benchmark-omics-output-bucket"
}

variable "workbench_service_account_name" {
  description = "The name of the workbench service account"
  type        = string
  default     = "workbench-health-omics"
  nullable    = false

}

variable "force_destroy" {
  description = "Applying the module with this value true allows you to run terraform destroy"
  type        = bool
  default     = false
}

variable "health_omics_role_name" {
  description = "The name of the health omics role"
  type        = string
  default     = "HealthOmicsRole"
  nullable    = false
}

variable "region" {
  description = "The region in which the resources will be created"
  type        = string
  default     = "us-east-1"
  nullable    = false
  validation {
    condition     = contains(["us-east-1", "us-west-2", "ap-southeast-1", "eu-central-1", "eu-west-1", "eu-west-2", "il-central-1"], var.region)
    error_message = "Invalid region"
  }
}
variable "additional_buckets" {
  description = "Additional buckets to add to the policy"
  type        = list(string)
  default     = []
  nullable    = true

}
variable "health_omics_service_policy_name" {
  description = "The name of the health omics service policy"
  type        = string
  default     = "HealthOmicsServicePolicy"
  nullable    = false

}
variable "health_omics_user_policy_name" {
  description = "The name of the health omics user policy"
  type        = string
  default     = "HealthOmicsUserPolicy"
  nullable    = false

}

variable "ecr_repositories" {
  description = "The ecr of docker images to create"
  type        = set(string)
  default     = []
  nullable    = true
}

variable "external_ecr_accounts" {
  description = "The list of external ECR accounts to allow access to the repositories"
  type        = list(string)
  default     = []
  nullable    = true

}

// File: main.tf
resource "aws_ecs_cluster" "dit_paas_cluster" {
  name               = "dit-paas-${var.cluster_name}-cluster"
  tags = {
    Name    = "dit-paas-${var.cluster_name}-cluster"
    Cluster = var.cluster_name
  }
}

// File: variables.tf
variable "aws_region" {
  type        = string
  description = "AWS region"
  default     = "us-east-1"
}

variable "cluster_name" {
  type        = string
  description = "The name of the cluster"
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type        = string
  description = "CIDR network range for the VPC"
  default     = "10.0"
}

variable "default_tags" {
  type        = map(string)
  default     = {}
  description = "Standard tags to add to deployed resources"
}

// File: vpc.tf
locals {
  vpc_tags = {
  }
}

# VPC

resource "aws_vpc" "dit_paas_cluster" {
  cidr_block = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false
  tags = {"Name" = "dit-paas-${var.cluster_name}-cluster-vpc"} 
}


# Private Subnets

resource "aws_subnet" "dit_paas_cluster_private_a" {
  vpc_id = aws_vpc.dit_paas_cluster.id
  cidr_block = "${var.vpc_cidr_network_octets}.0.0/22"
  availability_zone = "${var.aws_region}a"
  tags = merge(
    {
      "Name" = "dit-paas-${var.cluster_name}-private-a",
      "Subnet" = "dit-paas-${var.cluster_name}-private",
      "Subnet_class" = "private",
      "Availability_zone" = "${var.aws_region}a"
      "Cluster" = "dit-paas-${var.cluster_name}"
      "Cluster_name" = var.cluster_name
    },
    var.default_tags,
    local.vpc_tags
  )
}

resource "aws_subnet" "dit_paas_cluster_private_b" {
