resource "aws_key_pair" "key_pair" {
  count      = var.add_ssh_key == true ? 1 : 0
  key_name   = join("-", [local.name_prefix, "ec2-kp"])
  public_key = var.ssh_public_key

  tags = var.tags
}

resource "aws_instance" "ec2_instance" {
  ami               = var.ec2_ami != "" ? var.ec2_ami : data.aws_ami.amazon_linux_2.id
  instance_type     = var.ec2_instance_type
  availability_zone = var.availability_zone

  key_name = var.add_ssh_key == true ? aws_key_pair.key_pair[0].key_name : null

  tags = local.ec2_tags

  iam_instance_profile = aws_iam_instance_profile.iam_instance_profile.name

  network_interface {
    device_index         = 0
    network_interface_id = aws_network_interface.ec2_network_interface.id
  }

  metadata_options {
    http_tokens = var.imds_enabled
  }

  root_block_device {
    encrypted   = var.encrypt_root_volume
    kms_key_id  = var.encrypt_root_volume == true ? var.kms_key_id : null
    volume_size = var.root_volume_size
    tags        = local.volume_tags
  }

  user_data = var.user_data
}

// File: iam_role.tf
# -------------------------------------------------------------------------------------
#
# Copyright (c) 2023, WSO2 LLC. (http://www.wso2.com). All Rights Reserved.
#
# This software is the property of WSO2 LLC. and its suppliers, if any.
# Dissemination of any information or reproduction of any material contained
# herein in any form is strictly forbidden, unless permitted by WSO2 expressly.
# You may not alter or remove any copyright or other notice from copies of this content.
#
# --------------------------------------------------------------------------------------

# Session Manager
# Ignore: AVD-AWS-0057 (https://avd.aquasec.com/misconfig/aws/iam/avd-aws-0057/)
# Reason: This policy provides the permissions to use AWS Session Manager
# AWS Documentation: # Required permissions as per https://docs.aws.amazon.com/systems-manager/latest/userguide/getting-started-add-permissions-to-existing-profile.html
# trivy:ignore:AVD-AWS-0057
resource "aws_iam_policy" "session_manager_policy" {
  count = var.enable_session_manager == true ? 1 : 0
  name  = join("-", [var.project, var.application, var.environment, var.region, "ec2-session-manager-iam-policy"])
  policy = jsonencode({
    Statement = [{
      Action = [
        "ssm:UpdateInstanceInformation",
        "ssmmessages:CreateControlChannel",
        "ssmmessages:CreateDataChannel",
        "ssmmessages:OpenControlChannel",
        "ssmmessages:OpenDataChannel"
      ]
      Effect   = "Allow"
      Resource = "*"
    }]
    Version = "2012-10-17"
  })
}

resource "aws_iam_role" "iam_role" {
  name = join("-", [var.project, var.application, var.environment, var.region, "ec2-iam-role"])

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
      {
          "Effect": "Allow",
          "Principal": {
              "Service": ["ec2.amazonaws.com", "ssm.amazonaws.com"]
          },
          "Action": "sts:AssumeRole"
      }
  ]
}
POLICY
  tags               = var.tags
}


resource "aws_iam_instance_profile" "iam_instance_profile" {
  name = join("-", [var.project, var.application, var.environment, var.region, "ec2-instance-profile"])
  role = aws_iam_role.iam_role.name

  depends_on = [aws_iam_role.iam_role]
}

resource "aws_iam_role_policy_attachment" "instance_connect" {
  count      = var.enable_instance_connect == true ? 1 : 0
  role       = aws_iam_role.iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy_attachment" "session_manager" {
  count      = var.enable_session_manager == true ? 1 : 0
  role       = aws_iam_role.iam_role.name
  policy_arn = aws_iam_policy.session_manager_policy[0].arn
}

// File: locals.tf
# -------------------------------------------------------------------------------------
#
# Copyright (c) 2023, WSO2 LLC. (http://www.wso2.com). All Rights Reserved.
#
# This software is the property of WSO2 LLC. and its suppliers, if any.
# Dissemination of any information or reproduction of any material contained
# herein in any form is strictly forbidden, unless permitted by WSO2 expressly.
# You may not alter or remove any copyright or other notice from copies of this content.
#
# --------------------------------------------------------------------------------------

locals {
  name_prefix = var.availability_zone == null ? join("-", [var.project, var.application, var.environment, var.region]) : join("-", [var.project, var.application, var.environment, var.availability_zone])
  ec2_name    = join("-", [local.name_prefix, "ec2"])
  rt_name     = join("-", [local.name_prefix, "ec2-snet-rt"])
  subnet_name = join("-", [local.name_prefix, "ec2-snet"])
  nic_name    = join("-", [local.name_prefix, "ec2-nic"])
  ip_name     = join("-", [local.name_prefix, "ec2-eip"])
  volume_name = join("-", [local.name_prefix, "ec2-volume"])
  ec2_tags    = merge(var.tags, { Name : local.ec2_name })
  rt_tags     = merge(var.tags, { Name : local.rt_name })
  subnet_tags = merge(var.tags, { Name : local.subnet_name })
  nic_tags    = merge(var.tags, { Name : local.nic_name })
  ip_tags     = merge(var.tags, { Name : local.ip_name })
  volume_tags = merge(var.tags, { Name : local.volume_name })
}

// File: network.tf
# -------------------------------------------------------------------------------------
#
# Copyright (c) 2023, WSO2 LLC. (http://www.wso2.com). All Rights Reserved.
#
# This software is the property of WSO2 LLC. and its suppliers, if any.
# Dissemination of any information or reproduction of any material contained
# herein in any form is strictly forbidden, unless permitted by WSO2 expressly.
# You may not alter or remove any copyright or other notice from copies of this content.
#
# --------------------------------------------------------------------------------------

resource "aws_subnet" "ec2_subnet" {
  count                   = var.use_existing_subnet == true ? 0 : 1
  vpc_id                  = local.effective_ec2_vpc_id
  cidr_block              = var.ec2_subnet_vpc_cidr_block
  availability_zone       = var.availability_zone
  map_public_ip_on_launch = var.ip_address_allocation_method == "Dynamic" && var.ip_type == "Public" ? true : false
  tags                    = local.subnet_tags
}

resource "aws_route_table" "route_table" {
  count = var.use_existing_subnet == true ? 0 : 1

  vpc_id = local.effective_ec2_vpc_id
  tags   = local.rt_tags

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = try(aws_internet_gateway.benchmark[0].id, null)
  }

  dynamic "route" {
    for_each = var.custom_routes
    content {
      cidr_block                = route.value.cidr_block
      carrier_gateway_id        = route.value.ep_type == "carrier_gateway_id" ? route.value.ep_id : null
      core_network_arn          = route.value.ep_type == "core_network_arn" ? route.value.ep_id : null
      egress_only_gateway_id    = route.value.ep_type == "egress_only_gateway_id" ? route.value.egress_only_gateway_id : null
      gateway_id                = route.value.ep_type == "gateway_id" ? route.value.ep_id : null
      local_gateway_id          = route.value.ep_type == "local_gateway_id" ? route.value.ep_id : null
      nat_gateway_id            = route.value.ep_type == "nat_gateway_id" ? route.value.ep_id : null
      network_interface_id      = route.value.ep_type == "network_interface_id" ? route.value.ep_id : null
      transit_gateway_id        = route.value.ep_type == "transit_gateway_id" ? route.value.ep_id : null
      vpc_endpoint_id           = route.value.ep_type == "vpc_endpoint_id" ? route.value.ep_id : null
      vpc_peering_connection_id = route.value.ep_type == "vpc_peering_connection_id" ? route.value.ep_id : null
    }
  }
}

resource "aws_route_table_association" "route_table_association" {
  count          = var.use_existing_subnet == true ? 0 : 1
  subnet_id      = aws_subnet.ec2_subnet[0].id
  route_table_id = aws_route_table.route_table[0].id
}

resource "aws_network_interface" "ec2_network_interface" {
  subnet_id       = var.use_existing_subnet == true ? var.vpc_subnet_id : aws_subnet.ec2_subnet[0].id
  private_ips     = var.ip_address_allocation_method == "Static" ? [var.private_ip] : null
  tags            = local.nic_tags
  security_groups = var.security_group_ids
}

resource "aws_eip" "eip" {
  count                     = var.ip_address_allocation_method == "Static" && var.ip_type == "Public" ? 1 : 0
  network_interface         = aws_network_interface.ec2_network_interface.id
  associate_with_private_ip = var.ip_type == "Static" ? var.private_ip : null
  tags                      = local.ip_tags
}

// File: outputs.tf
# -------------------------------------------------------------------------------------
