# Create External Services: Postgres 14.x DB
resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "daniela-db-subnetgroup"
  subnet_ids = [aws_subnet.publicsub1.id, aws_subnet.privatesub1.id]

  tags = {
    Name = "daniela-db-subnet-group"
  }
}


resource "aws_db_instance" "tfe_db" {
  allocated_storage      = 400
  identifier             = var.db_identifier
  db_name                = var.db_name
  engine                 = "postgres"
  engine_version         = "14.24"
  instance_class         = "db.m5.xlarge"
  username               = var.db_username
  password               = var.db_password
  parameter_group_name   = "default.postgres14"
  skip_final_snapshot    = true
  db_subnet_group_name   = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.securitygp.id]
}

# Create Redis instance
resource "aws_elasticache_subnet_group" "redis_subnet_group" {
  name       = "daniela-redis-subnetgroup"
  subnet_ids = [aws_subnet.publicsub1.id, aws_subnet.privatesub1.id]
}

resource "aws_elasticache_cluster" "tfe_redis" {
  cluster_id           = "daniela-tfe-redis"
  engine               = "redis"
  node_type            = "cache.t3.small"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis7"
  engine_version       = "7.1"
  port                 = 6379
  security_group_ids   = [aws_security_group.securitygp.id]
  subnet_group_name    = aws_elasticache_subnet_group.redis_subnet_group.name
}

// File: outputs.tf
#create outputs for all the data sources for the terraform.tfstate file to get the values with the remote backend
output "cluster_name" {
    value = aws_eks_cluster.k8s_cluster.name
}

output "region" {
  value = var.aws_region
}

output "pg_address" {
  value = aws_db_instance.tfe_db.address
}

output "pg_dbname" {
  value = aws_db_instance.tfe_db.db_name
}

output "pg_user" {
  value = aws_db_instance.tfe_db.username
}

output "pg_password" {
  value = aws_db_instance.tfe_db.password
  sensitive = true
}

output "s3_bucket" {
  value = aws_s3_bucket.s3bucket_data.bucket
}

output "redis_host" {
  value = lookup(aws_elasticache_cluster.tfe_redis.cache_nodes[0], "address", "Redis address not found")
}

output "redis_port" {
  value = lookup(aws_elasticache_cluster.tfe_redis.cache_nodes[0], "port", "Redis port not found")
}

output "kubectl_environment" {
   value = "aws eks update-kubeconfig --region ${var.aws_region} --name ${aws_eks_cluster.k8s_cluster.name}"  
}

// File: provider.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.55.0"
    }
    acme = {
      source  = "vancluever/acme"
      version = "2.23.2"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

